# Windows can show a native "Bad Image" dialog when a helper executable has a
# broken/corrupt image or dependency DLL. The app handles helper failures itself,
# so suppress those OS-level popups and let us repair/report the tool cleanly.
def _suppress_windows_loader_error_dialogs() -> None:
    if os.name != "nt":
        return
    try:
        kernel32 = ctypes.windll.kernel32
        current = int(kernel32.GetErrorMode())
        SEM_FAILCRITICALERRORS = 0x0001
        SEM_NOGPFAULTERRORBOX = 0x0002
        SEM_NOOPENFILEERRORBOX = 0x8000
        kernel32.SetErrorMode(current | SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX | SEM_NOOPENFILEERRORBOX)
    except Exception:
        pass


def _vgmstream_health_check(path: Path | str | None) -> tuple[bool, str]:
    """Confirm that vgmstream-cli can actually start, not merely that the file exists."""
    if not path:
        return False, "vgmstream-cli.exe was not found"
    exe = Path(path)
    try:
        if not exe.is_file():
            return False, f"Executable does not exist: {exe}"
        cp = subprocess.run(
            [os.fspath(exe), "-h"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=8,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except OSError as exc:
        return False, str(exc)
    except subprocess.SubprocessError as exc:
        return False, str(exc)

    # Common Windows loader failures. Compare as unsigned 32-bit values because
    # subprocess returncode representation can vary by Python/Windows version.
    rc = int(cp.returncode)
    unsigned_rc = rc & 0xFFFFFFFF
    fatal_loader_codes = {
        0xC000012F,  # STATUS_INVALID_IMAGE_FORMAT / "Bad Image"
        0xC000007B,  # STATUS_INVALID_IMAGE_FORMAT (wrong architecture/format)
        0xC0000135,  # STATUS_DLL_NOT_FOUND
        0xC0000142,  # STATUS_DLL_INIT_FAILED
    }
    if unsigned_rc in fatal_loader_codes:
        detail = ((cp.stdout or "") + "\n" + (cp.stderr or "")).strip()
        return False, f"Windows loader failure 0x{unsigned_rc:08X}" + (f": {detail[-500:]}" if detail else "")

    output = ((cp.stdout or "") + "\n" + (cp.stderr or "")).lower()
    if "vgmstream" not in output:
        detail = output.strip()
        return False, "vgmstream did not return recognizable help output" + (f": {detail[-500:]}" if detail else "")
    return True, output[-500:]


_suppress_windows_loader_error_dialogs()

