def _cute_dialog(kind: str, title: str, message: str, parent=None, hint: Optional[str] = None, copy_text: Optional[str] = None) -> None:
    """A soft, on-theme modal for warnings/errors; cute without looking like a separate app.
    `hint` shows an optional "How to fix it" line; `copy_text` adds a Copy-details button."""
    if tk is None:
        return

    owner = parent or getattr(tk, "_default_root", None)
    try:

        theme_owner = owner
        palette = None
        for _ in range(8):
            if theme_owner is None:
                break
            palette = getattr(theme_owner, "_theme_colors", None)
            if palette:
                break
            theme_owner = getattr(theme_owner, "master", None)

        palette = palette or {
            "bg": "#fff7fb", "fg": "#332c34", "field": "#fffafd",
            "sel": "#f4d9e7", "accent": "#c25f91", "border": "#e7c6d6",
            "muted": "#756872", "accent_active": "#ab4f80",
            "accent_pressed": "#963f6e",
        }

        bg = palette.get("bg", "#fff7fb")
        field = palette.get("field", "#fffafd")
        fg = palette.get("fg", "#332c34")
        muted = palette.get("muted", "#756872")
        accent = palette.get("accent", "#c25f91")
        border = palette.get("border", "#e7c6d6")
        active = palette.get("accent_active", "#ab4f80")
        sel = palette.get("sel", "#f4d9e7")

        win = tk.Toplevel(owner)
        if owner is not None:
            win.transient(owner)
        win.title(title)
        win.resizable(False, False)
        win.configure(bg=bg)

        titlebar = tk.Frame(win, bg=accent, height=32)
        titlebar.pack(fill="x")
        titlebar.pack_propagate(False)
        tk.Label(
            titlebar, text=f"♡  {title}", anchor="w", bg=accent, fg="#ffffff",
            font=("Segoe UI", 9, "bold"), padx=10
        ).pack(side="left", fill="both", expand=True)
        tk.Button(
            titlebar, text="×", command=win.destroy, relief="flat", borderwidth=0,
            bg=accent, fg="#ffffff", activebackground=active, activeforeground="#ffffff",
            font=("Segoe UI", 12), width=3, cursor="hand2",
        ).pack(side="right", fill="y")

        outer = tk.Frame(win, bg=bg, highlightbackground=border, highlightthickness=1)
        outer.pack(fill="both", expand=True)

        body = tk.Frame(outer, bg=field)
        body.pack(fill="both", expand=True, padx=1, pady=1)

        if kind == "warning":
            marker_text = "!"
        elif kind == "error":
            marker_text = "×"
        else:
            marker_text = "♡"
        marker = tk.Label(
            body, text=marker_text, bg=palette.get("sel", "#f4d9e7"), fg=accent,
            font=("Segoe UI", 13, "bold"), width=3, height=1,
            padx=2, pady=2
        )
        marker.grid(row=0, column=0, rowspan=3, sticky="n", padx=(18, 12), pady=(17, 2))

        if kind == "error":
            heading = "Just a little hiccup ♡"
        elif kind == "warning":
            heading = "Just a heads-up ♡"
        else:
            heading = "All good ♡"
        tk.Label(
            body, text=heading, bg=field, fg=fg, anchor="w",
            font=("Segoe UI", 10, "bold")
        ).grid(row=0, column=1, sticky="ew", padx=(0, 18), pady=(15, 2))

        msg = tk.Label(
            body, text=str(message), bg=field, fg=muted, anchor="nw", justify="left",
            font=("Segoe UI", 9), wraplength=390
        )
        msg.grid(row=1, column=1, sticky="ew", padx=(0, 18), pady=(0, 11))

        if hint:
            tk.Label(
                body, text="♡ " + str(hint), bg=field, fg=accent, anchor="nw", justify="left",
                font=("Segoe UI", 8, "italic"), wraplength=390
            ).grid(row=2, column=1, sticky="ew", padx=(0, 18), pady=(0, 10))

        buttons = tk.Frame(body, bg=field)
        buttons.grid(row=3, column=0, columnspan=2, sticky="ew", padx=18, pady=(0, 14))

        if copy_text:
            def _copyd() -> None:
                try:
                    owner.clipboard_clear(); owner.clipboard_append(str(copy_text))
                except Exception:
                    pass
            tk.Button(
                buttons, text="˅ Copy details", command=_copyd,
                bg=sel, fg=fg, activebackground=border, activeforeground=fg,
                relief="flat", borderwidth=0, padx=12, pady=6,
                font=("Segoe UI", 9), cursor="hand2"
            ).pack(side="left")

        tk.Button(
            buttons, text="Okay ♡", command=win.destroy,
            bg=accent, fg="#ffffff", activebackground=active, activeforeground="#ffffff",
            relief="flat", borderwidth=0, padx=16, pady=6,
            font=("Segoe UI", 9, "bold"), cursor="hand2"
        ).pack(side="right")

        body.columnconfigure(1, weight=1)

        win.update_idletasks()
        width = 470
        height = max(165, min(352, win.winfo_reqheight()))
        if owner is not None and owner.winfo_exists():
            ox = owner.winfo_rootx() + max(0, (owner.winfo_width() - width) // 2)
            oy = owner.winfo_rooty() + max(0, (owner.winfo_height() - height) // 2)
        else:
            ox = max(0, (win.winfo_screenwidth() - width) // 2)
            oy = max(0, (win.winfo_screenheight() - height) // 2)
        win.geometry(f"{width}x{height}+{ox}+{oy}")

        win.bind("<Return>", lambda _e: win.destroy())
        win.bind("<Escape>", lambda _e: win.destroy())
        win.protocol("WM_DELETE_WINDOW", win.destroy)
        win.grab_set()
        win.focus_force()
        win.wait_window()
    except Exception:
        try:
            if kind == "error":
                messagebox.showerror(title, message, parent=owner)
            else:
                messagebox.showwarning(title, message, parent=owner)
        except Exception:
            pass

