def explain_error(exc: BaseException) -> tuple[str, str, Optional[str]]:
    """Translate an exception into a friendly (title, message, fix-hint) triple for users."""
    text = str(exc)
    lower = text.lower()
    if isinstance(exc, ToolNotFound):
        return (
            "A helper tool is missing",
            text,
            "Open the Tool Status menu (More ▾ → Tool Status) and press Re-scan Tools, "
            "or from the More ▾ menu choose Settings to set the missing tool path.",
        )
    if isinstance(exc, ToolExecutionError):
        if (int(getattr(exc, "returncode", 0)) & 0xFFFFFFFF) == 0xC000012F:
            return (
                "vgmstream needs a fresh copy",
                "Windows reported that vgmstream-cli.exe is a bad image (0xC000012F), so the current helper executable or one of its DLLs is not loadable.",
                "The next BNK load repairs vgmstream automatically by downloading a clean official build into the app's private .bnk_wem_tools folder.",
            )
        tool = getattr(exc, "tool", "") or "a helper tool"
        return (
            f"{tool} had a problem",
            text[-500:],
            "This usually means the audio file is unreadable or the helper tool hit a bad "
            "input. Try a different audio file, or re-check the tool in More ▾ → Tool Status.",
        )
    if isinstance(exc, FileNotFoundError):
        return (
            "A file could not be found",
            text,
            "The path may have moved or been renamed. Check the More ▾ → Game folder "
            "target, or copy details and share them for help.",
        )
    if isinstance(exc, PermissionError):
        return (
            "Permission was refused",
            text,
            "Close Brawlhalla, make sure the game files are not set to read-only, and try "
            "running again. The game must be fully closed before sounds are replaced.",
        )
    if "not found" in lower or "missing" in lower:
        return (
            "Something could not be found",
            text,
            "A file the program expected is missing or misnamed. Copy the details and "
            "share them for help if you are not sure what to do.",
        )
    if "denied" in lower or "access" in lower or "locked" in lower:
        return (
            "Access was blocked",
            text,
            "Close Brawlhalla, unblock read-only files, or run the program as administrator "
            "if the game folder is protected.",
        )
    return (
        "Something needs another little try",
        text,
        "Copy the details and share them (Discord is great for this). Meanwhile, check "
        "the More ▾ → Tool Status screen to make sure every helper tool is green.",
    )

