@dataclasses.dataclass(slots=True)
class KitPaths:
    root: Path = DEFAULT_ROOT
    before: Path = dataclasses.field(init=False)
    bnk: Path = dataclasses.field(init=False)
    ffmpeg_master: Path = dataclasses.field(init=False)
    ffmpeg_latest: Path = dataclasses.field(init=False)
    final: Path = dataclasses.field(init=False)
    processed_audio: Path = dataclasses.field(init=False)
    wems: Path = dataclasses.field(init=False)
    unpacker: Path = dataclasses.field(init=False)
    wwise: Path = dataclasses.field(init=False)
    auto_tools: Path = dataclasses.field(init=False)
    wwise_console_override: Optional[Path] = None

    def __post_init__(self) -> None:
        self.root = Path(self.root)
        self.before = self.root / "before"
        self.bnk = self.root / "BNK"
        self.ffmpeg_master = self.root / "FFmpeg-master"
        self.ffmpeg_latest = self.root / "ffmpeg-master-latest-win64-gpl"
        self.final = self.root / "Final"
        self.processed_audio = self.root / "processed audio"
        self.wems = self.root / "wems"
        self.unpacker = self.root / "Wwise-Unpacker-master"
        self.wwise = self.root / "Wwise2025.1.10.9233"
        self.auto_tools = self.root / ".bnk_wem_tools"

    def ensure(self) -> None:
        self.cleanup_generated_bank_artifacts()
        self.cleanup_stale_temporary_work()
        for d in (
            self.bnk,
            self.processed_audio,
            self.wems,
        ):
            d.mkdir(parents=True, exist_ok=True)

    def cleanup_stale_temporary_work(self) -> None:
        for directory in (self.processed_audio / "runs", self.wems / "source_cache"):
            if not directory.is_dir():
                continue
            try:
                for item in list(directory.iterdir()):
                    if item.is_dir():
                        shutil.rmtree(item, ignore_errors=True)
                    elif item.is_file():
                        with contextlib.suppress(OSError):
                            item.unlink()
            except OSError:
                pass

    def cleanup_generated_bank_artifacts(self) -> None:
        # Older versions left persistent BNK backups/results in the package.
        # Remove only files matching the tool's generated naming patterns.
        backup_re = re.compile(r"^.+_\d{8}_\d{6}_[0-9a-f]{6}\.bnk$", re.I)
        generated_final_re = re.compile(r"^.+_replaced\.bnk$", re.I)
        for path in (self.before, self.final):
            if not path.is_dir():
                continue
            try:
                for item in path.iterdir():
                    try:
                        if item.is_file() and (
                            (path == self.before and backup_re.match(item.name))
                            or (path == self.final and generated_final_re.match(item.name))
                        ):
                            item.unlink()
                    except OSError:
                        pass
                try:
                    path.rmdir()
                except OSError:
                    pass
            except OSError:
                pass
        # Keep the persistent undo journal between runs. A new successful run
        # overwrites it; a failed run must not destroy the previous undo point.

@dataclasses.dataclass(slots=True)
class ToolPaths:
    ffmpeg: Optional[Path] = None
    ffprobe: Optional[Path] = None
    yt_dlp: Optional[Path] = None
    deno: Optional[Path] = None
    vgmstream: Optional[Path] = None
    wwiseutil: Optional[Path] = None
    wwise_console: Optional[Path] = None

class ToolNotFound(RuntimeError):
    pass

class ToolExecutionError(RuntimeError):
    def __init__(self, tool: Path | str, command: Sequence[str], returncode: int,
                 stdout: str = "", stderr: str = "") -> None:
        self.tool = str(tool)
        self.command = list(command)
        self.returncode = returncode
        self.stdout = stdout or ""
        self.stderr = stderr or ""
        msg = (
            f"External tool failed (exit {returncode}): {self.tool}\n"
            f"Command: {subprocess.list2cmdline(list(command))}\n"
            f"STDOUT:\n{self.stdout[-4000:]}\nSTDERR:\n{self.stderr[-4000:]}"
        )
        super().__init__(msg)

class EventBus:
    def __init__(self) -> None:
        self._listeners: list[Callable[[str], None]] = []
        self._lock = threading.RLock()

    def subscribe(self, fn: Callable[[str], None]) -> None:
        with self._lock:
            self._listeners.append(fn)

    def emit(self, message: str) -> None:
        with self._lock:
            listeners = list(self._listeners)
        for fn in listeners:
            try:
                fn(message)
            except Exception:
                pass

class UILogHandler(logging.Handler):
    def __init__(self, bus: EventBus) -> None:
        super().__init__()
        self.bus = bus

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.bus.emit(self.format(record))
        except Exception:
            pass

def timestamp() -> str:
    return _dt.datetime.now().strftime("%Y%m%d_%H%M%S")

def safe_name(value: str, max_len: int = 120) -> str:
    value = re.sub(r"[<>:\"/\\|?*\x00-\x1f]", "_", value)
    value = value.strip(" .") or "unnamed"
    return value[:max_len]

