class RunResult:
    args: list[str]
    returncode: int
    stdout: str
    stderr: str
    duration_seconds: float

class PreviewCancelled(RuntimeError):
    pass

class ProcessingCancelled(RuntimeError):
    pass

class Runner:
    def __init__(self, logger: logging.Logger, bus: EventBus, cancel_event: Optional[threading.Event] = None) -> None:
        self.log = logger
        self.bus = bus
        self.cancel_event = cancel_event

    @staticmethod
    def _terminate_process_tree(proc: subprocess.Popen[str], logger: Optional[logging.Logger] = None) -> None:
        """Best-effort termination of a subprocess and any children it spawned."""
        try:
            if proc.poll() is not None:
                return
            if os.name == "nt":
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    check=False,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                    timeout=5,
                )
            else:
                with contextlib.suppress(ProcessLookupError):
                    os.killpg(proc.pid, __import__("signal").SIGTERM)
        except Exception as exc:
            if logger:
                logger.debug("Process-tree termination warning for PID %s: %s", getattr(proc, "pid", "?"), exc)
        finally:
            with contextlib.suppress(Exception):
                proc.terminate()
            try:
                proc.wait(timeout=1.0)
            except Exception:
                with contextlib.suppress(Exception):
                    proc.kill()

    def run(self, args: Sequence[str | os.PathLike[str]], cwd: Optional[Path] = None,
            timeout: Optional[float] = None, check: bool = True,
            env: Optional[dict[str, str]] = None,
            output_callback: Optional[Callable[[str, str], None]] = None) -> RunResult:
        """Run a helper process while optionally forwarding stdout/stderr incrementally.

        The callback is intentionally optional so the normal code path remains lightweight.
        Batch downloads use it with yt-dlp's ``--newline`` mode to surface live progress
        without putting any pipe-reading work on Tk's main thread.
        """
        cmd = [os.fspath(x) for x in args]
        if not cmd or not str(cmd[0]).strip():
            raise ValueError("Cannot execute an empty subprocess command")
        self.log.debug("Running: %s", subprocess.list2cmdline(cmd))
        start = time.perf_counter()

        creationflags = 0
        if os.name == "nt":
            creationflags |= getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
            creationflags |= getattr(subprocess, "CREATE_NO_WINDOW", 0)

        try:
            proc = subprocess.Popen(
                cmd,
                cwd=os.fspath(cwd) if cwd else None,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                env=env,
                shell=False,
                creationflags=creationflags,
                start_new_session=(os.name != "nt"),
            )
        except FileNotFoundError as exc:
            raise ToolNotFound(f"Executable not found: {cmd[0]}") from exc
        except OSError as exc:
            raise ToolExecutionError(cmd[0], cmd, -1, "", str(exc)) from exc

        stdout_parts: list[str] = []
        stderr_parts: list[str] = []
        event_queue: queue.Queue[tuple[str, str]] = queue.Queue()
        readers: list[threading.Thread] = []

        def _reader(stream: Any, kind: str, sink: list[str]) -> None:
            try:
                while True:
                    chunk = stream.readline()
                    if chunk == "":
                        break
                    sink.append(chunk)
                    if output_callback is not None:
                        event_queue.put((kind, chunk.rstrip("\r\n")))
            except Exception as exc:
                self.log.debug("%s reader warning for %s: %s", kind, cmd[0], exc)
            finally:
                with contextlib.suppress(Exception):
                    stream.close()

        if output_callback is not None and proc.stdout is not None and proc.stderr is not None:
            for stream, kind, sink in ((proc.stdout, "stdout", stdout_parts), (proc.stderr, "stderr", stderr_parts)):
                t = threading.Thread(target=_reader, args=(stream, kind, sink),
                                      daemon=True, name=f"runner-{kind}")
                t.start()
                readers.append(t)

        def _drain_events() -> None:
            if output_callback is None:
                return
            while True:
                try:
                    kind, line = event_queue.get_nowait()
                except queue.Empty:
                    break
                try:
                    output_callback(kind, line)
                except Exception as exc:
                    self.log.debug("Live output callback warning: %s", exc)

        deadline = (time.monotonic() + timeout) if timeout is not None else None
        cancelled = False
        timed_out = False
        while True:
            _drain_events()
            if self.cancel_event is not None and self.cancel_event.is_set():
                cancelled = True
                self._terminate_process_tree(proc, self.log)
                break
            if deadline is not None and time.monotonic() >= deadline:
                timed_out = True
                self._terminate_process_tree(proc, self.log)
                break
            if proc.poll() is not None and (not readers or not any(t.is_alive() for t in readers)):
                break
            time.sleep(0.05)

        for t in readers:
            with contextlib.suppress(Exception):
                t.join(timeout=0.75)
        _drain_events()

        if output_callback is None:
            try:
                out, err = proc.communicate(timeout=1.0)
            except Exception:
                out, err = "", ""
            stdout_parts[:] = [out or ""]
            stderr_parts[:] = [err or ""]

        stdout = "".join(stdout_parts)
        stderr = "".join(stderr_parts)
        elapsed = time.perf_counter() - start

        if cancelled:
            raise PreviewCancelled(
                "Preview stopped" if "preview" in str(cmd[0]).lower() else "Operation cancelled"
            )
        if timed_out:
            raise ToolExecutionError(cmd[0], cmd, -9, stdout, stderr)

        result = RunResult(cmd, proc.returncode, stdout, stderr, elapsed)
        if result.stdout:
            self.log.debug("stdout: %s", result.stdout[-8000:])
        if result.stderr:
            self.log.debug("stderr: %s", result.stderr[-8000:])
        if check and proc.returncode != 0:
            raise ToolExecutionError(cmd[0], cmd, proc.returncode, result.stdout, result.stderr)
        return result


def _looks_like_cli_wwiseutil(path: Path | str | None) -> bool:

    if not path:
        return False
    exe = Path(path)
    try:
        if not exe.is_file():
            return False
        cp = subprocess.run(
            [str(exe), "-h"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=4,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        text = ((cp.stdout or "") + "\n" + (cp.stderr or "")).lower()

        if "starting wwiseutil gui" in text:
            return False
        if "unknown options: f, u, o" in text:
            return False

        cli_markers = ("-unpack", "-filepath", "-output", "-replace", "-target")
        return any(marker in text for marker in cli_markers)
    except (OSError, subprocess.SubprocessError, ValueError):
        return False

class ToolLocator:

    TOOL_ENV_VARS = {
        "ffmpeg": ("FFMPEG", "FFMPEG_HOME"),
        "ffprobe": ("FFPROBE", "FFMPEG", "FFMPEG_HOME"),
        "yt_dlp": ("YTDLP", "YT_DLP", "YTDLP_HOME"),
        "deno": ("DENO", "DENO_EXE", "DENO_HOME"),
        "vgmstream": ("VGMSTREAM", "VGMSTREAM_HOME"),
        "wwiseutil": ("WWISEUTIL", "WWISEUTIL_HOME"),
        "wwise_console": ("WWISEROOT", "WWISE", "WWISE_HOME"),
    }

    TOOL_FILENAMES = {
        "ffmpeg": ("ffmpeg.exe",),
        "ffprobe": ("ffprobe.exe",),
        "yt_dlp": ("yt-dlp.exe", "yt-dlp"),
        "deno": ("deno.exe", "deno"),
        "vgmstream": ("vgmstream-cli.exe", "vgmstream-cli"),
        "wwiseutil": ("wwiseutil.exe", "wwiseutil"),
        "wwise_console": ("WwiseConsole.exe", "WwiseConsole"),
    }

    def __init__(self, paths: KitPaths) -> None:
        self.paths = paths

    @staticmethod
    def _which(names: Iterable[str]) -> Optional[Path]:
        for name in names:
            try:
                found = shutil.which(name)
            except Exception:
                found = None
            if found:
                p = Path(found)
                try:
                    if p.is_file():
                        return p.resolve()
                except OSError:
                    pass
        return None

    @staticmethod
    def _vgmstream_usable(path: Path | str | None) -> bool:
        ok, _detail = _vgmstream_health_check(path)
        return ok

    @staticmethod
    def _file(path: Path | str | None) -> Optional[Path]:
        if not path:
            return None
        try:
            p = Path(path).expanduser()
            if p.is_file():
                return p.resolve()
        except (OSError, ValueError):
            pass
        return None

    @classmethod
    def _env_file(cls, names: Iterable[str], filenames: Iterable[str]) -> Optional[Path]:
        wanted = {x.lower() for x in filenames}
        for env_name in names:
            raw = os.environ.get(env_name, "").strip().strip('"')
            if not raw:
                continue
            base = Path(raw)
            direct = cls._file(base)
            if direct and direct.name.lower() in wanted:
                return direct
            for filename in filenames:
                for candidate in (base / filename, base / "bin" / filename, base / "tools" / filename):
                    hit = cls._file(candidate)
                    if hit:
                        return hit
        return None

    @staticmethod
    def _registry_install_dirs() -> list[Path]:

        if os.name != "nt":
            return []
        try:
            import winreg
        except Exception:
            return []
        roots = [
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Audiokinetic"),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Audiokinetic"),
            (winreg.HKEY_CURRENT_USER, r"SOFTWARE\Audiokinetic"),
            (winreg.HKEY_CURRENT_USER, r"SOFTWARE\WOW6432Node\Audiokinetic"),
        ]
        value_names = ("InstallPath", "InstallDir", "Path", "Location", "Root", "InstallLocation")
        found: list[Path] = []
        seen: set[str] = set()
        for hive, subpath in roots:
            try:
                key = winreg.OpenKey(hive, subpath)
            except OSError:
                continue
            try:

                keys = [key]
                try:
                    count = winreg.QueryInfoKey(key)[0]
                    for i in range(count):
                        try:
                            keys.append(winreg.OpenKey(key, winreg.EnumKey(key, i)))
                        except OSError:
                            pass
                except OSError:
                    pass
                for k in keys:
                    try:
                        for value_name in value_names:
                            try:
                                value, _ = winreg.QueryValueEx(k, value_name)
                            except OSError:
                                continue
                            if value:
                                p = Path(str(value))
                                if p.exists():
                                    sk = str(p).lower()
                                    if sk not in seen:
                                        seen.add(sk)
                                        found.append(p)
                    finally:
                        if k is not key:
                            try:
                                winreg.CloseKey(k)
                            except OSError:
                                pass
            finally:
                try:
                    winreg.CloseKey(key)
                except OSError:
                    pass
        return found

    @staticmethod
    def _unique_paths(paths: Iterable[Path]) -> list[Path]:
        out: list[Path] = []
        seen: set[str] = set()
        for p in paths:
            try:
                k = str(Path(p).expanduser().resolve(strict=False)).lower()
            except (OSError, ValueError):
                continue
            if k not in seen:
                seen.add(k)
                out.append(Path(p))
        return out

    @staticmethod
    def _user_search_roots() -> list[Path]:

        roots: list[Path] = []
        home_raw = os.environ.get("USERPROFILE") or os.environ.get("HOME")
        if home_raw:
            home = Path(home_raw)
            roots.extend([
                home / "Downloads",
                home / "Desktop",
                home / "Documents",
                home / "Tools",
            ])
        for raw in (
            os.environ.get("LOCALAPPDATA"),
            os.environ.get("APPDATA"),
            os.environ.get("PROGRAMDATA"),
        ):
            if raw:
                base = Path(raw)
                roots.append(base)
                roots.append(base / "Programs")
                roots.append(base / "Microsoft" / "WinGet" / "Packages")
                roots.append(base / "Audiokinetic")

        try:
            import sysconfig
            scripts = sysconfig.get_path("scripts")
            if scripts:
                roots.append(Path(scripts))
        except Exception:
            pass
        return ToolLocator._unique_paths(roots)

    @staticmethod
    def _where(names: Iterable[str]) -> Optional[Path]:

        if os.name != "nt":
            return None
        for name in names:
            try:
                cp = subprocess.run(
                    ["where.exe", name],
                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                    text=True, timeout=2, check=False,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
            except Exception:
                continue
            for line in (cp.stdout or "").splitlines():
                hit = ToolLocator._file(line.strip().strip('"'))
                if hit:
                    return hit
        return None

    @classmethod
    def _targeted_search(cls, roots: Iterable[Path], filenames: tuple[str, ...],
                         name_hints: tuple[str, ...], max_dirs: int = 1500,
                         walk_all: bool = False, max_depth: int = 4) -> Optional[Path]:

        wanted = {n.lower() for n in filenames}
        hints = tuple(h.lower() for h in name_hints)
        queue_dirs: list[tuple[Path, int]] = []
        seen: set[str] = set()
        for root in roots:
            try:
                if root.is_dir():
                    queue_dirs.append((root, 0))
            except OSError:
                pass
        visited = 0
        while queue_dirs and visited < max_dirs:
            current, depth = queue_dirs.pop(0)
            try:
                key = str(current.resolve(strict=False)).lower()
            except (OSError, ValueError):
                continue
            if key in seen:
                continue
            seen.add(key)
            visited += 1
            try:
                entries = list(os.scandir(current))
            except (OSError, PermissionError):
                continue
            for entry in entries:
                try:
                    if entry.is_file(follow_symlinks=False) and entry.name.lower() in wanted:
                        return Path(entry.path).resolve()
                except OSError:
                    continue
            if depth >= max_depth:
                continue
            for entry in entries:
                try:
                    if not entry.is_dir(follow_symlinks=False):
                        continue
                    name = entry.name.lower()

                    likely = walk_all or any(h in name for h in hints) or name in {"bin", "tools", "authoring", "x64", "release", "scripts"}
                    if likely:
                        queue_dirs.append((Path(entry.path), depth + 1))
                except OSError:
                    continue
        return None

    def locate(self) -> ToolPaths:

        t = ToolPaths()

        override = getattr(self.paths, "wwise_console_override", None)
        if override:
            hit = self._file(Path(override))
            if hit:
                t.wwise_console = hit

        auto = self.paths.auto_tools
        exact: dict[str, list[Path]] = {
            "ffmpeg": [
                self.paths.root / "ffmpeg.exe",
                auto / "ffmpeg.exe",
                auto / "ffmpeg" / "ffmpeg.exe",
                self.paths.ffmpeg_latest / "bin" / "ffmpeg.exe",
                self.paths.ffmpeg_master / "bin" / "ffmpeg.exe",
            ],
            "ffprobe": [
                self.paths.root / "ffprobe.exe",
                auto / "ffprobe.exe",
                auto / "ffmpeg" / "ffprobe.exe",
                self.paths.ffmpeg_latest / "bin" / "ffprobe.exe",
                self.paths.ffmpeg_master / "bin" / "ffprobe.exe",
            ],
            "yt_dlp": [
                self.paths.root / "yt-dlp.exe",
                self.paths.root / "yt-dlp",
                auto / "yt-dlp.exe",
                auto / "yt-dlp" / "yt-dlp.exe",
            ],
            "deno": [
                self.paths.root / "deno.exe",
                auto / "deno.exe",
                auto / "deno" / "deno.exe",
            ],
            "vgmstream": [
                auto / "vgmstream" / "vgmstream-cli.exe",
                auto / "vgmstream-cli.exe",
                self.paths.root / "vgmstream-cli.exe",
                self.paths.root / "vgmstream-cli",
            ],
            "wwiseutil": [
                self.paths.root / "wwiseutil.exe",
                self.paths.unpacker / "wwiseutil.exe",
                self.paths.unpacker / "wwiseutil" / "wwiseutil.exe",
                auto / "wwiseutil.exe",
                auto / "wwiseutil" / "wwiseutil.exe",
            ],
            "wwise_console": [
                self.paths.wwise / "Authoring" / "x64" / "Release" / "bin" / "WwiseConsole.exe",
                self.paths.wwise / "WwiseConsole.exe",
            ],
        }
        for attr, candidates in exact.items():
            for candidate in candidates:
                hit = self._file(candidate)
                if hit:
                    if attr == "wwiseutil" and not _looks_like_cli_wwiseutil(hit):
                        continue
                    if attr == "vgmstream" and not self._vgmstream_usable(hit):
                        continue
                    setattr(t, attr, hit)
                    break

        for attr, env_names in self.TOOL_ENV_VARS.items():
            if getattr(t, attr):
                continue
            hit = (
                self._env_file(env_names, self.TOOL_FILENAMES[attr])
                or self._which(self.TOOL_FILENAMES[attr])
                or self._where(self.TOOL_FILENAMES[attr])
            )
            if attr == "wwiseutil" and hit and not _looks_like_cli_wwiseutil(hit):
                hit = None
            if attr == "vgmstream" and hit and not self._vgmstream_usable(hit):
                hit = None
            setattr(t, attr, hit)

        wwise_roots = [self.paths.wwise]
        for env_name in self.TOOL_ENV_VARS["wwise_console"]:
            raw = os.environ.get(env_name, "").strip().strip('"')
            if raw:
                wwise_roots.append(Path(raw))
        for base in (
            Path(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)")) / "Audiokinetic",
            Path(os.environ.get("PROGRAMFILES", r"C:\Program Files")) / "Audiokinetic",
        ):
            try:
                if base.is_dir():
                    wwise_roots.extend(x for x in base.iterdir() if x.is_dir())
            except OSError:
                pass
        wwise_roots.extend(self._registry_install_dirs())
        for root in self._unique_paths(wwise_roots):
            if t.wwise_console:
                break
            for candidate in (
                root / "Authoring" / "x64" / "Release" / "bin" / "WwiseConsole.exe",
                root / "Authoring" / "x64" / "Release" / "bin" / "WwiseConsole.cmd",
                root / "WwiseConsole.exe",
            ):
                hit = self._file(candidate)
                if hit:
                    t.wwise_console = hit
                    break

        search_roots = self._unique_paths([
            self.paths.root,
            Path(os.environ.get("PROGRAMFILES", r"C:\Program Files")),
            Path(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)")),
            Path(os.environ.get("LOCALAPPDATA", "")),
            Path(os.environ.get("PROGRAMDATA", "")),
            *self._user_search_roots(),
        ])
        specs = (
            ("ffmpeg", ("ffmpeg",), 700),
            ("ffprobe", ("ffmpeg", "ffprobe"), 700),
            ("yt_dlp", ("yt-dlp", "ytdlp", "python", "scripts"), 1000),
            ("deno", ("deno",), 700),
            ("vgmstream", ("vgmstream",), 700),
            ("wwiseutil", ("wwise", "wwiseutil", "unpacker"), 800),
            ("wwise_console", ("wwise", "audiokinetic"), 900),
        )
        for attr, hints, cap in specs:
            if getattr(t, attr):
                continue
            hit = self._targeted_search(search_roots, self.TOOL_FILENAMES[attr], hints, max_dirs=cap)
            if hit:
                if attr == "wwiseutil" and not _looks_like_cli_wwiseutil(hit):
                    continue
                if attr == "vgmstream" and not self._vgmstream_usable(hit):
                    continue
                setattr(t, attr, hit)

        user_roots = self._user_search_roots()
        user_specs = (
            ("ffmpeg", 700),
            ("ffprobe", 700),
            ("yt_dlp", 1400),
            ("deno", 700),
            ("vgmstream", 700),
            ("wwiseutil", 900),
            ("wwise_console", 1200),
        )
        for attr, cap in user_specs:
            if getattr(t, attr):
                continue
            hit = self._targeted_search(
                user_roots, self.TOOL_FILENAMES[attr], (),
                max_dirs=cap, walk_all=True, max_depth=4
            )
            if hit:
                if attr == "wwiseutil" and not _looks_like_cli_wwiseutil(hit):
                    continue
                if attr == "vgmstream" and not self._vgmstream_usable(hit):
                    continue
                setattr(t, attr, hit)

        return t

    def locate_deep(self) -> ToolPaths:

        t = self.locate()
        roots = self._unique_paths([
            self.paths.root,
            Path(os.environ.get("PROGRAMFILES", r"C:\Program Files")),
            Path(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)")),
        ])
        for attr, names in (
            ("ffmpeg", {"ffmpeg.exe"}),
            ("ffprobe", {"ffprobe.exe"}),
            ("yt_dlp", {"yt-dlp.exe"}),
            ("deno", {"deno.exe"}),
            ("vgmstream", {"vgmstream-cli.exe"}),
            ("wwiseutil", {"wwiseutil.exe"}),
            ("wwise_console", {"WwiseConsole.exe"}),
        ):
            if getattr(t, attr):
                continue

            for root in roots:
                try:
                    stack = [root]
                    checked = 0
                    while stack and checked < 25000:
                        current = stack.pop()
                        checked += 1
                        try:
                            for entry in os.scandir(current):
                                try:
                                    if entry.is_file(follow_symlinks=False) and entry.name.lower() in {n.lower() for n in names}:
                                        setattr(t, attr, Path(entry.path).resolve())
                                        stack.clear()
                                        break
                                    if entry.is_dir(follow_symlinks=False):
                                        stack.append(Path(entry.path))
                                except OSError:
                                    continue
                        except (OSError, PermissionError):
                            continue
                        if getattr(t, attr):
                            break
                except OSError:
                    continue
                if getattr(t, attr):
                    break
        return t

    def pretty(self, tools: ToolPaths) -> str:
        rows = []
        for name in ("ffmpeg", "ffprobe", "yt_dlp", "deno", "vgmstream", "wwiseutil", "wwise_console"):
            val = getattr(tools, name)
            rows.append(f"{name:14} = {val or '<not found>'}")
        return "\n".join(rows)

class DependencyInstaller:

    FFMPEG_URL = "https://github.com/GyanD/codexffmpeg/releases/latest/download/ffmpeg-release-essentials.zip"
    YTDLP_URL = "https://github.com/yt-dlp/yt-dlp/releases/latest/download/yt-dlp.exe"
    DENO_URL = "https://github.com/denoland/deno/releases/latest/download/deno-x86_64-pc-windows-msvc.zip"
    DENO_SHA256_URL = DENO_URL + ".sha256sum"
    VGMSTREAM_URL = "https://github.com/vgmstream/vgmstream-releases/releases/download/nightly/vgmstream-win64.zip"
    WWISEUTIL_API = "https://api.github.com/repos/hpxro7/wwiseutil/releases/latest"

    def __init__(self, paths: KitPaths, logger: logging.Logger) -> None:
        self.paths = paths
        self.log = logger
        self.root = self.paths.auto_tools
        self.root.mkdir(parents=True, exist_ok=True)

    @staticmethod
    def _download(url: str, destination: Path, progress=None) -> None:
        destination.parent.mkdir(parents=True, exist_ok=True)
        req = urllib.request.Request(url, headers={"User-Agent": "BNK-WEM-Replacer-Pro/3.5.51"})
        tmp = destination.with_suffix(destination.suffix + ".part")
        if tmp.exists():
            tmp.unlink()
        with urllib.request.urlopen(req, timeout=45) as response, tmp.open("wb") as out:
            total = int(response.headers.get("Content-Length", "0") or 0)
            done = 0
            while True:
                chunk = response.read(1024 * 256)
                if not chunk:
                    break
                out.write(chunk)
                done += len(chunk)
                if progress:
                    progress(done, total)
        tmp.replace(destination)

    @staticmethod
    def _extract_zip(archive: Path, destination: Path, keep_names: set[str] | None = None) -> None:
        destination.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(archive) as zf:
            members = zf.infolist()
            if keep_names is None:
                zf.extractall(destination)
                return
            wanted = {x.lower() for x in keep_names}
            for info in members:
                if info.is_dir():
                    continue
                base = Path(info.filename).name.lower()
                if base in wanted or base.endswith(".dll"):
                    target = destination / base
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with zf.open(info) as src, target.open("wb") as dst:
                        shutil.copyfileobj(src, dst)

    def _install_ffmpeg(self, progress=None) -> Path:
        archive = self.root / "ffmpeg.zip"
        self._download(self.FFMPEG_URL, archive, progress)
        target = self.root / "ffmpeg"
        if target.exists():
            shutil.rmtree(target, ignore_errors=True)
        target.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(archive) as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                parts = Path(info.filename).parts
                name = Path(info.filename).name.lower()
                if "bin" not in [p.lower() for p in parts] or (name not in {"ffmpeg.exe", "ffprobe.exe", "ffplay.exe"} and not name.endswith(".dll")):
                    continue
                if name == "ffplay.exe":
                    continue
                out = target / name
                with zf.open(info) as src, out.open("wb") as dst:
                    shutil.copyfileobj(src, dst)
        archive.unlink(missing_ok=True)
        exe = target / "ffmpeg.exe"
        if not exe.is_file() or not (target / "ffprobe.exe").is_file():
            raise RuntimeError("FFmpeg archive did not contain ffmpeg.exe and ffprobe.exe")
        return exe

    def _install_yt_dlp(self, progress=None) -> Path:
        target = self.root / "yt-dlp.exe"
        self._download(self.YTDLP_URL, target, progress)
        if not target.is_file() or target.stat().st_size < 100000:
            raise RuntimeError("yt-dlp download did not produce a valid executable")
        return target

    def _install_deno(self, progress=None) -> Path:
        """Install a verified official Deno Windows x64 runtime used by yt-dlp's YouTube EJS solver."""
        archive = self.root / "deno-x86_64-pc-windows-msvc.zip"
        self._download(self.DENO_URL, archive, progress)

        req = urllib.request.Request(
            self.DENO_SHA256_URL,
            headers={"User-Agent": "BNK-WEM-Replacer-Pro/4.1", "Accept": "text/plain"},
        )
        with urllib.request.urlopen(req, timeout=20) as response:
            checksum_text = response.read().decode("utf-8", "replace")
        match = re.search(r"\b([0-9a-fA-F]{64})\b", checksum_text)
        if not match:
            archive.unlink(missing_ok=True)
            raise RuntimeError("Could not read Deno release checksum")
        expected = match.group(1).lower()
        actual = hashlib.sha256(archive.read_bytes()).hexdigest().lower()
        if actual != expected:
            archive.unlink(missing_ok=True)
            raise RuntimeError("Deno release checksum verification failed")

        target = self.root / "deno"
        if target.exists():
            shutil.rmtree(target, ignore_errors=True)
        target.mkdir(parents=True, exist_ok=True)
        self._extract_zip(archive, target, keep_names={"deno.exe"})
        archive.unlink(missing_ok=True)
        exe = target / "deno.exe"
        if not exe.is_file() or exe.stat().st_size < 1000000:
            raise RuntimeError("Deno archive did not contain a valid deno.exe")

        # A file existing is not enough: prove Windows can actually start Deno.
        try:
            probe = subprocess.run(
                [os.fspath(exe), "eval", "console.log('cutie-sumo-deno-ok')"],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8,
                check=False,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
        except OSError as exc:
            raise RuntimeError(f"Deno was downloaded but Windows could not launch it: {exc}") from exc
        output = ((probe.stdout or "") + "\n" + (probe.stderr or "")).strip()
        if probe.returncode != 0 or "cutie-sumo-deno-ok" not in output:
            raise RuntimeError(
                "Deno was downloaded but failed its startup self-test."
                + (f"\n{output[-1200:]}" if output else "")
            )
        return exe

    def _install_vgmstream(self, progress=None) -> Path:
        archive = self.root / "vgmstream.zip"
        self._download(self.VGMSTREAM_URL, archive, progress)
        target = self.root / "vgmstream"
        if target.exists():
            shutil.rmtree(target, ignore_errors=True)
        target.mkdir(parents=True, exist_ok=True)
        self._extract_zip(archive, target)
        archive.unlink(missing_ok=True)
        candidates = list(target.rglob("vgmstream-cli.exe"))
        if not candidates:
            raise RuntimeError("vgmstream archive did not contain vgmstream-cli.exe")

        exe = candidates[0]
        if exe.parent != target:
            for child in exe.parent.iterdir():
                dest = target / child.name
                if child.is_file() and not dest.exists():
                    shutil.copy2(child, dest)
        exe = target / "vgmstream-cli.exe"
        ok, detail = _vgmstream_health_check(exe)
        if not ok:
            raise RuntimeError("The downloaded vgmstream build could not start.\n\n" + detail)
        return exe

    def _latest_wwiseutil_asset(self) -> str:
        req = urllib.request.Request(self.WWISEUTIL_API, headers={"User-Agent": "BNK-WEM-Replacer-Pro/3.5.51", "Accept": "application/vnd.github+json"})
        with urllib.request.urlopen(req, timeout=20) as response:
            data = json.loads(response.read().decode("utf-8", "replace"))
        assets = data.get("assets") or []
        candidates = [a for a in assets if str(a.get("browser_download_url", "")).lower().endswith((".zip", ".exe"))]
        for asset in candidates:
            name = str(asset.get("name", "")).lower()
            if "windows" in name or "win" in name or "wwiseutil" in name:
                return str(asset["browser_download_url"])
        if candidates:
            return str(candidates[0]["browser_download_url"])
        raise RuntimeError("Could not find a Windows wwiseutil release asset")

    def _install_wwiseutil(self, progress=None) -> Path:
        url = self._latest_wwiseutil_asset()
        suffix = Path(urllib.parse.urlsplit(url).path).suffix.lower() or ".zip"
        archive = self.root / ("wwiseutil_download" + suffix)
        self._download(url, archive, progress)
        target = self.root / "wwiseutil"
        if target.exists():
            shutil.rmtree(target, ignore_errors=True)
        target.mkdir(parents=True, exist_ok=True)
        if archive.suffix.lower() == ".exe":
            exe = target / "wwiseutil.exe"
            shutil.move(str(archive), str(exe))
            return exe
        self._extract_zip(archive, target)
        archive.unlink(missing_ok=True)
        candidates = list(target.rglob("wwiseutil.exe"))
        if not candidates:
            raise RuntimeError("wwiseutil release did not contain wwiseutil.exe")
        exe = candidates[0]
        if exe.parent != target:
            dest = target / "wwiseutil.exe"
            shutil.copy2(exe, dest)
            exe = dest
        return exe

    def install(self, missing: list[str], progress=None) -> dict[str, Path]:
        installed: dict[str, Path] = {}
        for name in missing:
            if name == "FFmpeg / FFprobe":
                installed["ffmpeg"] = self._install_ffmpeg(progress)
                installed["ffprobe"] = self.root / "ffmpeg" / "ffprobe.exe"
            elif name == "yt-dlp":
                installed["yt_dlp"] = self._install_yt_dlp(progress)
            elif name == "deno":
                installed["deno"] = self._install_deno(progress)
            elif name == "vgmstream":
                installed["vgmstream"] = self._install_vgmstream(progress)
            elif name == "wwiseutil":
                raise RuntimeError("Automatic wwiseutil download is disabled because upstream releases may provide the GUI build instead of the required command-line build.")
        return installed

_LIVE_BNK_STAGING_DIRS: set[Path] = set()

def _cleanup_live_bnk_staging() -> None:
    for path in list(_LIVE_BNK_STAGING_DIRS):
        with contextlib.suppress(OSError):
            shutil.rmtree(path, ignore_errors=True)
    _LIVE_BNK_STAGING_DIRS.clear()

atexit.register(_cleanup_live_bnk_staging)

