META_RE = {
    "sample_rate": re.compile(r"^sample rate:\s*(\d+)\s*Hz", re.I | re.M),
    "channels": re.compile(r"^channels:\s*(\d+)", re.I | re.M),
    "samples": re.compile(r"^stream total samples:\s*(\d+)\s*\(", re.I | re.M),
    "duration": re.compile(r"^stream total samples:\s*\d+\s*\(([^)]+)\s*seconds\)", re.I | re.M),
    "encoding": re.compile(r"^encoding:\s*(.+)$", re.I | re.M),
}

def parse_vgmstream_metadata(text: str) -> dict[str, Any]:
    out: dict[str, Any] = {"sample_rate": 0, "channels": 0, "samples": 0,
                           "duration": 0.0, "encoding": "unknown"}
    m = META_RE["sample_rate"].search(text); out["sample_rate"] = int(m.group(1)) if m else 0
    m = META_RE["channels"].search(text); out["channels"] = int(m.group(1)) if m else 0
    m = META_RE["samples"].search(text); out["samples"] = int(m.group(1)) if m else 0
    m = META_RE["duration"].search(text)
    if m:

        token = m.group(1).strip()
        mm = re.match(r"^(?:(\d+):)?(\d+(?:\.\d+)?)$", token)
        if mm:
            minutes = int(mm.group(1) or 0)
            seconds = float(mm.group(2))
            out["duration"] = minutes * 60.0 + seconds
    m = META_RE["encoding"].search(text); out["encoding"] = m.group(1).strip() if m else "unknown"
    if out["sample_rate"] and out["samples"]:
        out["duration"] = out["samples"] / out["sample_rate"]
    return out

def ffprobe_duration(runner: Runner, ffprobe: Path, source: Path, timeout: float = 120.0) -> float:
    result = runner.run([
        ffprobe, "-v", "error", "-show_entries", "format=duration",
        "-of", "default=noprint_wrappers=1:nokey=1", source
    ], timeout=timeout)
    try:
        val = float(result.stdout.strip())
    except ValueError as exc:
        raise RuntimeError(f"Could not parse FFprobe duration for {source}: {result.stdout!r}") from exc
    if not math.isfinite(val) or val <= 0:
        raise RuntimeError(f"Source has invalid duration: {val}")
    return val

class WwiseUtilAdapter:
    def __init__(self, tool: Path, runner: Runner, logger: logging.Logger) -> None:
        self.tool = tool
        self.runner = runner
        self.log = logger

    def version_help(self) -> str:
        return self.runner.run([self.tool, "-h"], check=False, timeout=30).stdout

    def unpack(self, bank: Path, out_dir: Path, allow_empty: bool = False) -> list[Path]:
        out_dir.mkdir(parents=True, exist_ok=True)
        self.log.info("Unpacking %s", bank)
        try:
            self.runner.run([self.tool, "-unpack", "-filepath", bank, "-output", out_dir], timeout=600)
        except ToolExecutionError as exc:
            combined = f"{exc.stdout}\n{exc.stderr}".lower()

            no_media_markers = (
                "there are no wems stored within this file",
                "no wems stored within this file",
            )
            if allow_empty and any(marker in combined for marker in no_media_markers):
                self.log.info("Skipping %s: bank contains no embedded WEM media", bank)
                return []
            raise
        files = sorted(out_dir.glob("*.wem"), key=lambda p: numeric_stem(p.name))
        if not files:
            if allow_empty:
                self.log.info("Skipping %s: no WEM files were extracted", bank)
                return []
            raise RuntimeError(f"No WEM files were extracted from {bank}")
        return files

    def replace(self, bank: Path, target_dir: Path, output_bank: Path) -> None:
        output_bank.parent.mkdir(parents=True, exist_ok=True)
        self.log.info("Repacking %s -> %s", bank, output_bank)
        self.runner.run([
            self.tool, "-replace", "-filepath", bank, "-target", target_dir, "-output", output_bank
        ], timeout=600)
        if not output_bank.is_file() or output_bank.stat().st_size < 16:
            raise RuntimeError(f"wwiseutil reported success but output bank is missing/empty: {output_bank}")

def numeric_stem(name: str) -> tuple[int, str]:
    stem = Path(name).stem
    try:
        return (int(stem), name)
    except ValueError:
        return (10**18, name.lower())

def make_wem_info_list(
    runner: Runner, vgmstream: Path, bank: Path, wem_files: list[Path], timeout: float,
    progress_callback: Optional[Callable[[int, int, Path], None]] = None,
    cancel_event: Optional[threading.Event] = None, max_workers: Optional[int] = None,
) -> list[WemInfo]:
    """Probe WEM metadata without ever touching the Tk/UI thread.

    ``vgmstream -m`` is a separate process per WEM, so spawning too many probes at once
    can become slower due to disk/process contention. The default is intentionally modest
    and progress is reported as each worker completes.
    """
    if not wem_files:
        return []

    total = len(wem_files)

    def probe(position: int, wem: Path) -> WemInfo:
        if cancel_event is not None and cancel_event.is_set():
            raise ProcessingCancelled("WEM metadata probing cancelled")
        idx = int(wem.stem) if wem.stem.isdigit() else position
        result = runner.run([vgmstream, "-m", wem], timeout=timeout, check=False)
        text = (result.stdout or "") + ("\n" + result.stderr if result.stderr else "")
        meta = parse_vgmstream_metadata(text)
        if result.returncode != 0 or not meta["sample_rate"] or not meta["duration"]:
            logging.getLogger("bnk_replacer").warning(
                "Metadata warning for %s: exit=%s text=%s", wem, result.returncode, text[-1000:]
            )
        return WemInfo(
            bank_path=bank,
            index=idx,
            file_path=wem,
            display_name=wem.name,
            sample_rate=int(meta["sample_rate"]),
            channels=int(meta["channels"]),
            total_samples=int(meta["samples"]),
            duration_seconds=float(meta["duration"]),
            encoding=str(meta["encoding"]),
            metadata_text=text,
        )

    if total == 1:
        info = probe(1, wem_files[0])
        if progress_callback:
            with contextlib.suppress(Exception):
                progress_callback(1, 1, wem_files[0])
        return [info]

    requested = max_workers if max_workers is not None else min(4, max(2, (os.cpu_count() or 4) // 2))
    workers = max(1, min(int(requested), total, 4))
    ordered: list[Optional[WemInfo]] = [None] * total
    completed = 0
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="weminfo") as pool:
        futures = {pool.submit(probe, i, wem): i - 1 for i, wem in enumerate(wem_files, 1)}
        for future in concurrent.futures.as_completed(futures):
            if cancel_event is not None and cancel_event.is_set():
                for pending in futures:
                    pending.cancel()
                raise ProcessingCancelled("WEM metadata probing cancelled")
            position = futures[future]
            info = future.result()
            ordered[position] = info
            completed += 1
            if progress_callback:
                with contextlib.suppress(Exception):
                    progress_callback(completed, total, info.file_path)
    return [info for info in ordered if info is not None]

YOUTUBE_HOSTS = {
    "youtube.com", "www.youtube.com", "m.youtube.com", "youtu.be", "music.youtube.com"
}

def looks_like_url(value: str) -> bool:
    try:
        u = urllib.parse.urlparse(value.strip())
        return u.scheme.lower() in {"http", "https"} and bool(u.netloc)
    except Exception:
        return False

def is_youtube_url(value: str) -> bool:
    if not looks_like_url(value):
        return False
    host = urllib.parse.urlparse(value).hostname or ""
    return host.lower() in YOUTUBE_HOSTS or host.lower().endswith(".youtube.com")

def youtube_playlist_id(value: str) -> str:
    try:
        parsed = urllib.parse.urlparse(value.strip())
        query = urllib.parse.parse_qs(parsed.query)
        return str((query.get("list") or [""])[0]).strip()
    except Exception:
        return ""


def is_youtube_radio_url(value: str) -> bool:
    """Return True for YouTube Mix/radio list IDs (RD/RDMM style dynamic lists)."""
    playlist_id = youtube_playlist_id(value).upper()
    return playlist_id.startswith("RD")


def normalize_youtube_playlist_url(value: str) -> str:
    """Normalize fixed playlists and YouTube Mix URLs for yt-dlp.

    Fixed playlists are reduced to /playlist?list=... so unrelated watch parameters cannot
    interfere with extraction. Dynamic Mix URLs are kept as watch URLs with both ``v=`` and
    ``list=RD...`` because the seed video is part of how YouTube identifies the Mix.
    """
    raw = value.strip().strip('"')
    if not is_youtube_url(raw):
        return raw
    parsed = urllib.parse.urlparse(raw)
    query = urllib.parse.parse_qs(parsed.query)
    playlist_id = str((query.get("list") or [""])[0]).strip()
    if not playlist_id:
        return raw
    if is_youtube_radio_url(raw):
        video_id = str((query.get("v") or query.get("video_id") or [""])[0]).strip()
        if video_id:
            return (
                "https://www.youtube.com/watch?v="
                + urllib.parse.quote(video_id, safe="")
                + "&list="
                + urllib.parse.quote(playlist_id, safe="")
            )
        return "https://www.youtube.com/playlist?list=" + urllib.parse.quote(playlist_id, safe="")
    return "https://www.youtube.com/playlist?list=" + urllib.parse.quote(playlist_id, safe="")


def is_youtube_playlist_url(value: str) -> bool:
    """Return True for fixed YouTube playlists and dynamic YouTube Mix/radio URLs."""
    if not is_youtube_url(value):
        return False
    playlist_id = youtube_playlist_id(value)
    if not playlist_id:
        return False
    try:
        parsed = urllib.parse.urlparse(value.strip())
        path = parsed.path.rstrip("/").lower()
        query = urllib.parse.parse_qs(parsed.query)
        if is_youtube_radio_url(value):
            return bool(path == "/watch" and query.get("v")) or path == "/playlist"
        return path == "/playlist" or bool(query.get("v") or query.get("video_id"))
    except Exception:
        return False

