class SourceManager:
    def __init__(self, tools: ToolPaths, runner: Runner, paths: KitPaths,
                 logger: logging.Logger, options: ProcessOptions, fast_preview: bool = False,
                 progress_callback: Optional[Callable[[str], None]] = None) -> None:
        self.tools = tools
        self.runner = runner
        self.paths = paths
        self.log = logger
        self.options = options
        self.fast_preview = bool(fast_preview)
        self.progress_callback = progress_callback

    def _progress(self, message: str) -> None:
        if self.progress_callback is None:
            return
        try:
            self.progress_callback(str(message))
        except Exception:
            pass

    def materialize(self, raw_source: str, work_dir: Path, source_label: str) -> Path:
        raw_source = raw_source.strip().strip('"')
        work_dir.mkdir(parents=True, exist_ok=True)
        if looks_like_url(raw_source):
            if not self.tools.yt_dlp:
                raise ToolNotFound("A URL was supplied but yt-dlp.exe was not found")
            return self.download_url(raw_source, work_dir, source_label)
        p = Path(os.path.expandvars(os.path.expanduser(raw_source)))
        if not p.is_file():
            raise FileNotFoundError(f"Audio file does not exist: {p}")
        return p.resolve()

                                                                               

                                                                         
    PIPED_API_FALLBACKS = (
        "https://pipedapi.kavin.rocks",
        "https://pipedapi.tokhmi.xyz",
        "https://pipedapi.moomoo.me",
        "https://pipedapi.syncpundit.io",
        "https://api-piped.mha.fi",
        "https://piped-api.garudalinux.org",
        "https://pipedapi.rivo.lol",
        "https://pipedapi.leptons.xyz",
        "https://piped-api.lunar.icu",
        "https://pipedapi.adminforge.de",
        "https://pipedapi.reallyaweso.me",
        "https://pipedapi.private.coffee",
    )

    @staticmethod
    def _youtube_video_id(url: str) -> Optional[str]:
        try:
            parsed = urllib.parse.urlparse(url)
        except Exception:
            return None
        host = parsed.netloc.lower().split(":", 1)[0]
        if host in {"youtu.be", "www.youtu.be"}:
            value = parsed.path.lstrip("/").split("/", 1)[0]
            return value or None
        if host.endswith("youtube.com") or host.endswith("youtube-nocookie.com"):
            qs = urllib.parse.parse_qs(parsed.query)
            value = (qs.get("v") or [None])[0]
            if value:
                return value
            parts = [part for part in parsed.path.split("/") if part]
            if len(parts) >= 2 and parts[0] in {"shorts", "embed", "live"}:
                return parts[1]
        return None

    def _download_via_piped(
        self,
        url: str,
        work_dir: Path,
        label: str,
        progress_callback: Optional[Callable[[float, str], None]] = None,
    ) -> Optional[Path]:
        """Try Piped while reporting real byte-level progress when the server exposes a size."""
        video_id = self._youtube_video_id(url)
        if not video_id:
            return None
        headers = {"User-Agent": "Cutie-Sumo-Sound-Replacer/4.3", "Accept": "application/json"}
        last_error = ""
        for api_base in self.PIPED_API_FALLBACKS:
            endpoint = api_base.rstrip("/") + "/streams/" + urllib.parse.quote(video_id, safe="")
            try:
                if progress_callback:
                    progress_callback(0.0, f"Trying alternate source: {api_base.split('//', 1)[-1]}…")
                req = urllib.request.Request(endpoint, headers=headers)
                with urllib.request.urlopen(req, timeout=min(20, max(8, int(self.options.download_timeout)))) as response:
                    payload = json.loads(response.read().decode("utf-8", "replace"))
                streams = payload.get("audioStreams") or []
                streams = [s for s in streams if isinstance(s, dict) and s.get("url") and not s.get("videoOnly", False)]
                if not streams:
                    last_error = f"{api_base}: no audio streams returned"
                    continue
                streams.sort(key=lambda s: float(s.get("bitrate") or 0), reverse=True)
                stream = streams[0]
                stream_url = str(stream.get("url"))
                fmt = str(stream.get("format") or "").lower()
                mime = str(stream.get("mimeType") or "").lower()
                if "webm" in fmt or "webm" in mime:
                    ext = "webm"
                elif "opus" in fmt or "opus" in mime:
                    ext = "opus"
                else:
                    ext = "m4a"
                target = work_dir / (safe_name(label) + "_piped." + ext)
                stream_req = urllib.request.Request(
                    stream_url,
                    headers={"User-Agent": headers["User-Agent"], "Accept": "*/*"},
                )
                with urllib.request.urlopen(stream_req, timeout=max(30, int(self.options.download_timeout))) as src, target.open("wb") as dst:
                    total_bytes = int(src.headers.get("Content-Length", "0") or 0)
                    done_bytes = 0
                    last_emit = 0.0
                    while True:
                        chunk = src.read(1024 * 1024)
                        if not chunk:
                            break
                        dst.write(chunk)
                        done_bytes += len(chunk)
                        now = time.monotonic()
                        if progress_callback and (now - last_emit >= 0.12 or (total_bytes and done_bytes >= total_bytes)):
                            pct = (done_bytes / total_bytes * 100.0) if total_bytes else -1.0
                            mb = done_bytes / (1024 * 1024)
                            if total_bytes:
                                detail = f"Alternate source • {pct:.0f}% • {mb:.1f} MiB"
                            else:
                                detail = f"Alternate source • {mb:.1f} MiB downloaded"
                            progress_callback(pct, detail)
                            last_emit = now
                if target.is_file() and target.stat().st_size > 4096:
                    if progress_callback:
                        progress_callback(100.0, "Alternate source complete")
                    self.log.info("Downloaded YouTube audio through Piped instance: %s", api_base)
                    return target
                target.unlink(missing_ok=True)
                last_error = f"{api_base}: returned an empty audio stream"
            except Exception as exc:
                last_error = f"{api_base}: {exc}"
                continue
        if last_error:
            self.log.warning("Piped YouTube fallback failed: %s", last_error)
        return None

    def _yt_dlp_download_attempts(
        self, url: str, out_template: Path, *, playlist_mode: bool = False
    ) -> list[list[str | os.PathLike[str]]]:
        """Build isolated yt-dlp attempts for single-video or explicit playlist downloads.

        Every download gets an isolated output directory, ignores user yt-dlp config that
        can unexpectedly alter output/playlist behavior, and has a few resilient retries.
        """
        playlist_flag = "--yes-playlist" if playlist_mode else "--no-playlist"
        base: list[str | os.PathLike[str]] = [
            self.tools.yt_dlp,
            "--ignore-config",
            playlist_flag,
            "-f", "bestaudio/best",
            "--no-part",
            "--restrict-filenames",
            "--newline",
            "--concurrent-fragments", "8",
            "--socket-timeout", "15",
            "--retries", "4",
            "--fragment-retries", "4",
            "--extractor-retries", "3",
            "--retry-sleep", "http:linear=0.75::2",
            "--force-ipv4",
            "-o", out_template,
        ]
        if not is_youtube_url(url):
            return [base + [url]]
        return [
            base + [url],
            base + ["--extractor-args", "youtube:player_client=mweb", url],
            base + ["--extractor-args", "youtube:player_client=web_embedded", url],
            base + ["--extractor-args", "youtube:player_client=android_vr", url],
        ]

    def _yt_dlp_playlist_count_args(self, url: str) -> list[str | os.PathLike[str]]:
        """Build the quickest possible playlist-count request.

        IMPORTANT: this is the editor hot path. It performs one yt-dlp invocation,
        examines only one playlist item, requests no audio, and does not retry with
        alternate player clients. If YouTube/yt-dlp cannot provide playlist_count quickly,
        the UI reports that immediately instead of hanging for several fallback passes.
        """
        runtime_args: list[str | os.PathLike[str]] = []
        runtime = self._youtube_js_runtime_cache or self._find_youtube_js_runtime()
        if runtime:
            runtime_args = ["--js-runtimes", f"deno:{runtime}"]
        return [
            self.tools.yt_dlp,
            "--ignore-config",
            "--remote-components", "ejs:github",
            *runtime_args,
            "--yes-playlist",
            "--flat-playlist",
            "--playlist-end", "1",
            "--print", "%(playlist_count)s",
            "--skip-download",
            "--no-warnings",
            "--quiet",
            "--socket-timeout", "4",
            "--retries", "0",
            "--extractor-retries", "0",
            url,
        ]

    def playlist_count_fast(self, url: str, timeout: float = 8.0) -> int:
        """Get the playlist count with a single fast download-free yt-dlp call."""
        if not self.tools.yt_dlp:
            raise ToolNotFound("yt-dlp.exe was not found")
        if not is_youtube_playlist_url(url):
            raise ValueError("A YouTube playlist URL is required")
        runtime = self._ensure_youtube_js_runtime()
        result = self.runner.run(
            self._yt_dlp_playlist_count_args(url),
            timeout=max(1.0, float(timeout)),
            check=False,
            env=self._youtube_runtime_env(runtime),
        )
        for value in reversed([line.strip() for line in (result.stdout or "").splitlines() if line.strip()]):
            if value.isdigit() and int(value) > 0:
                count = int(value)
                self.log.info("Fast playlist count: %d track(s)", count)
                return count
        detail = ((result.stderr or "") + "\n" + (result.stdout or "")).strip()
        raise RuntimeError(
            "yt-dlp did not return playlist_count during the fast check. "
            f"{detail[-700:]}"
        )

    def _yt_dlp_playlist_entries_args(self, url: str, limit: int, *, embedded: bool = False) -> list[str | os.PathLike[str]]:
        """Build a *lazy* playlist probe that stops as soon as the requested entries arrive.

        ``--lazy-playlist`` is important here: yt-dlp otherwise may try to finish parsing the
        whole playlist before returning the first usable entries. Batch mode only needs the first
        N unique songs, so resolving the entire playlist defeats the purpose of the fast path.
        """
        args: list[str | os.PathLike[str]] = [
            self.tools.yt_dlp,
            "--ignore-config",
            "--yes-playlist",
            "--flat-playlist",
            "--lazy-playlist",
            "--playlist-items", f"1-{max(1, int(limit))}",
            "--print", "%(playlist_index)s\t%(id)s\t%(title)s\t%(webpage_url)s",
            "--skip-download",
            "--no-warnings",
            "--quiet",
            "--socket-timeout", "4",
            "--retries", "0",
            "--fragment-retries", "0",
            "--extractor-retries", "0",
            url,
        ]
        if embedded:
            args[-1:-1] = ["--extractor-args", "youtube:player_client=web_embedded"]
        return args

    @staticmethod
    def _youtube_json_after_marker(html: str, marker: str) -> Any:
        """Extract the JSON object/array immediately following a JS assignment marker."""
        start = html.find(marker)
        if start < 0:
            return None
        pos = start + len(marker)
        while pos < len(html) and html[pos].isspace():
            pos += 1
        if pos >= len(html) or html[pos] not in "[{":
            return None
        opener = html[pos]
        closer = "}" if opener == "{" else "]"
        depth = 0
        in_string = False
        escaped = False
        for i in range(pos, len(html)):
            ch = html[i]
            if in_string:
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == '"':
                    in_string = False
                continue
            if ch == '"':
                in_string = True
                continue
            if ch == opener:
                depth += 1
            elif ch == closer:
                depth -= 1
                if depth == 0:
                    try:
                        return json.loads(html[pos:i + 1])
                    except json.JSONDecodeError:
                        return None
        return None

    @staticmethod
    def _playlist_tracks_from_initial_data(payload: Any, limit: int) -> list[PlaylistTrack]:
        """Pull playlist-video renderers from YouTube page/continuation JSON."""
        tracks: list[PlaylistTrack] = []
        seen: set[tuple[int, str]] = set()
        wanted = max(1, int(limit))

        def text_value(value: Any) -> str:
            if isinstance(value, dict):
                if isinstance(value.get("simpleText"), str):
                    return value["simpleText"]
                runs = value.get("runs")
                if isinstance(runs, list):
                    return "".join(str(r.get("text", "")) for r in runs if isinstance(r, dict))
            return ""

        def add_renderer(renderer: dict[str, Any]) -> None:
            video_id = str(
                renderer.get("videoId")
                or ((renderer.get("navigationEndpoint") or {}).get("watchEndpoint") or {}).get("videoId")
                or ""
            ).strip()
            if not video_id:
                return
            title = text_value(renderer.get("title")) or video_id
            index_text = text_value(renderer.get("index"))
            if not index_text:
                try:
                    index_text = str(
                        ((renderer.get("navigationEndpoint") or {}).get("watchEndpoint") or {}).get("index")
                        or ""
                    )
                except Exception:
                    index_text = ""
            try:
                playlist_index = int(re.search(r"\d+", index_text or "").group(0))
            except Exception:
                playlist_index = len(tracks) + 1
            key = (int(playlist_index), video_id.lower())
            if key in seen:
                return
            seen.add(key)
            tracks.append(PlaylistTrack(
                playlist_index,
                video_id,
                title,
                f"https://www.youtube.com/watch?v={urllib.parse.quote(video_id, safe='')}",
            ))

        def visit(node: Any) -> None:
            if len(tracks) >= wanted:
                return
            if isinstance(node, dict):
                renderer = node.get("playlistVideoRenderer")
                if isinstance(renderer, dict):
                    add_renderer(renderer)
                    if len(tracks) >= wanted:
                        return
                for value in node.values():
                    visit(value)
                    if len(tracks) >= wanted:
                        return
            elif isinstance(node, list):
                for value in node:
                    visit(value)
                    if len(tracks) >= wanted:
                        break

        visit(payload)
        tracks.sort(key=lambda item: (item.playlist_index, item.video_id))
        return tracks[:wanted]

    @staticmethod
    def _youtube_playlist_continuation_token(payload: Any) -> str:
        """Find the playlist's own continuation token in initial or continuation JSON."""
        def token_from_continuation_item(node: Any) -> str:
            if not isinstance(node, dict):
                return ""
            item = node.get("continuationItemRenderer")
            if not isinstance(item, dict):
                return ""
            endpoint = item.get("continuationEndpoint") or {}
            command = endpoint.get("continuationCommand") or {}
            return str(command.get("token") or "").strip()

        def find_in_playlist_renderer(node: Any) -> str:
            if isinstance(node, dict):
                renderer = node.get("playlistVideoListRenderer")
                if isinstance(renderer, dict):
                    contents = renderer.get("contents") or []
                    for item in reversed(contents if isinstance(contents, list) else []):
                        token = token_from_continuation_item(item)
                        if token:
                            return token
                    return ""
                for value in node.values():
                    token = find_in_playlist_renderer(value)
                    if token:
                        return token
            elif isinstance(node, list):
                for value in node:
                    token = find_in_playlist_renderer(value)
                    if token:
                        return token
            return ""

        token = find_in_playlist_renderer(payload)
        if token:
            return token

        # Continuation responses commonly expose the continuation items directly.
        def find_any(node: Any) -> str:
            if isinstance(node, dict):
                token = token_from_continuation_item(node)
                if token:
                    return token
                for value in node.values():
                    token = find_any(value)
                    if token:
                        return token
            elif isinstance(node, list):
                for value in node:
                    token = find_any(value)
                    if token:
                        return token
            return ""

        return find_any(payload)

    @staticmethod
    def _youtube_innertube_config(html: str) -> tuple[str, str]:
        """Extract the public WEB InnerTube API key/client version from YouTube HTML."""
        text = str(html or "")
        key_patterns = (
            r'\"INNERTUBE_API_KEY\"\s*:\s*\"([^\"]+)\"',
            r'INNERTUBE_API_KEY\s*[:=]\s*\"([^\"]+)\"',
        )
        version_patterns = (
            r'\"INNERTUBE_CLIENT_VERSION\"\s*:\s*\"([^\"]+)\"',
            r'\"INNERTUBE_CONTEXT_CLIENT_VERSION\"\s*:\s*\"([^\"]+)\"',
            r'INNERTUBE_CLIENT_VERSION\s*[:=]\s*\"([^\"]+)\"',
        )
        api_key = next((m.group(1) for pat in key_patterns if (m := re.search(pat, text))), "")
        client_version = next((m.group(1) for pat in version_patterns if (m := re.search(pat, text))), "")
        return api_key, client_version

    def _youtube_playlist_continuation_request(
        self, token: str, api_key: str, client_version: str
    ) -> Any:
        """Fetch one public playlist continuation page from YouTube's WEB client."""
        if not token or not api_key:
            raise ValueError("YouTube playlist continuation data is incomplete")
        version = client_version or "2.20260915.01.00"
        endpoint = (
            "https://www.youtube.com/youtubei/v1/browse?key="
            + urllib.parse.quote(api_key, safe="")
            + "&prettyPrint=false"
        )
        body = json.dumps({
            "context": {
                "client": {
                    "clientName": "WEB",
                    "clientVersion": version,
                    "hl": "en",
                    "gl": "US",
                }
            },
            "continuation": token,
        }).encode("utf-8")
        req = urllib.request.Request(
            endpoint,
            data=body,
            method="POST",
            headers={
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36"
                ),
                "Content-Type": "application/json",
                "Accept": "application/json",
                "Origin": "https://www.youtube.com",
                "X-YouTube-Client-Name": "1",
                "X-YouTube-Client-Version": version,
            },
        )
        with urllib.request.urlopen(req, timeout=7.0) as response:
            return json.loads(response.read().decode("utf-8", "replace"))

    PIPED_PLAYLIST_INSTANCES = (
        # Several public Piped APIs are tried in parallel so one dead instance cannot block Batch Mode.
        "https://pipedapi.kavin.rocks",
        "https://pipedapi.leptons.xyz",
        "https://pipedapi.nosebs.ru",
        "https://pipedapi.tokhmi.xyz",
        "https://pipedapi.moomoo.me",
        "https://pipedapi.syncpundit.io",
        "https://api-piped.mha.fi",
        "https://piped-api.garudalinux.org",
        "https://pipedapi.reallyaweso.me",
        "https://api.piped.private.coffee",
    )

    @staticmethod
    def _piped_video_url(raw_url: str) -> str:
        value = str(raw_url or '').strip()
        if value.startswith('/'):
            return 'https://www.youtube.com' + value
        if value.startswith(('http://', 'https://')):
            try:
                parsed = urllib.parse.urlparse(value)
                qs = urllib.parse.parse_qs(parsed.query)
                video_id = (qs.get('v') or [''])[0].strip()
                if video_id:
                    return 'https://www.youtube.com/watch?v=' + urllib.parse.quote(video_id, safe='')
            except Exception:
                pass
            return value
        return ''

    @classmethod
    def _parse_piped_playlist_payload(
        cls, payload: Any, limit: int, start_index: int = 1
    ) -> tuple[str, list[PlaylistTrack], str]:
        """Parse one Piped playlist response into PlaylistTrack objects."""
        if not isinstance(payload, dict):
            return '', [], ''
        title = str(payload.get('name') or payload.get('title') or '').strip()
        nextpage = str(payload.get('nextpage') or '').strip()
        raw_items = payload.get('relatedStreams') or []
        tracks: list[PlaylistTrack] = []
        seen: set[str] = set()
        index = max(1, int(start_index))
        for item in raw_items:
            if len(tracks) >= limit:
                break
            if not isinstance(item, dict):
                continue
            video_url = cls._piped_video_url(str(item.get('url') or item.get('webpageUrl') or ''))
            video_id = cls._youtube_video_id(video_url) if video_url else None
            if not video_id:
                raw_id = str(item.get('videoId') or item.get('id') or '').strip()
                video_id = raw_id or None
                if video_id:
                    video_url = 'https://www.youtube.com/watch?v=' + urllib.parse.quote(video_id, safe='')
            if not video_url:
                continue
            key = (video_id or video_url).lower()
            if key in seen:
                continue
            seen.add(key)
            track_title = str(item.get('title') or video_id or f'Track {index}').strip()
            tracks.append(PlaylistTrack(index, video_id or '', track_title, video_url))
            index += 1
        return title, tracks, nextpage

    def _piped_playlist_entries(self, url: str, limit: int) -> tuple[str, list[PlaylistTrack]]:
        """Resolve playlist entries through multiple Piped APIs without using yt-dlp."""
        playlist_id = youtube_playlist_id(url)
        if not playlist_id:
            raise ValueError('A YouTube playlist URL is required')
        limit = max(1, int(limit))

        def fetch_initial(base: str) -> tuple[str, list[PlaylistTrack], str, str]:
            endpoint = base.rstrip('/') + '/playlists/' + urllib.parse.quote(playlist_id, safe='')
            req = urllib.request.Request(
                endpoint,
                headers={
                    'User-Agent': 'Cutie-Sumo-Sound-Replacer/4.0',
                    'Accept': 'application/json',
                },
            )
            with urllib.request.urlopen(req, timeout=3.5) as response:
                payload = json.loads(response.read().decode('utf-8', 'replace'))
            title, tracks, nextpage = self._parse_piped_playlist_payload(payload, limit)
            if not tracks:
                raise RuntimeError('Piped returned no usable playlist entries')
            return title, tracks, nextpage, base

        pool = concurrent.futures.ThreadPoolExecutor(
            max_workers=min(len(self.PIPED_PLAYLIST_INSTANCES), 8),
            thread_name_prefix='piped-playlist',
        )
        futures = {pool.submit(fetch_initial, base): base for base in self.PIPED_PLAYLIST_INSTANCES}
        errors: list[str] = []
        try:
            for future in concurrent.futures.as_completed(futures):
                try:
                    title, tracks, nextpage, base = future.result()
                    pool.shutdown(wait=False, cancel_futures=True)

                    while len(tracks) < limit and nextpage:
                        endpoint = (
                            base.rstrip('/') + '/nextpage/playlists/'
                            + urllib.parse.quote(playlist_id, safe='')
                        )
                        query = urllib.parse.urlencode({'nextpage': nextpage})
                        req = urllib.request.Request(
                            endpoint + '?' + query,
                            headers={
                                'User-Agent': 'Cutie-Sumo-Sound-Replacer/4.0',
                                'Accept': 'application/json',
                            },
                        )
                        with urllib.request.urlopen(req, timeout=3.5) as response:
                            payload = json.loads(response.read().decode('utf-8', 'replace'))
                        page_title, page_tracks, nextpage = self._parse_piped_playlist_payload(
                            payload, limit - len(tracks), start_index=len(tracks) + 1
                        )
                        if page_title and not title:
                            title = page_title
                        known = {(t.video_id or t.webpage_url).lower() for t in tracks}
                        for track in page_tracks:
                            key = (track.video_id or track.webpage_url).lower()
                            if key in known:
                                continue
                            known.add(key)
                            track.playlist_index = len(tracks) + 1
                            tracks.append(track)
                            if len(tracks) >= limit:
                                break
                        if not page_tracks:
                            break

                    tracks = tracks[:limit]
                    if tracks:
                        self.log.info(
                            'Fast Piped playlist resolver found %d track(s) via %s', len(tracks), base
                        )
                        return title, tracks
                except Exception as exc:
                    errors.append(f'{futures[future]}: {exc}')
        finally:
            with contextlib.suppress(Exception):
                pool.shutdown(wait=False, cancel_futures=True)

        detail = '; '.join(errors[-4:])
        raise RuntimeError(
            'No Piped playlist instance returned usable entries.'
            + (f' {detail[:500]}' if detail else '')
        )

    def _youtube_playlist_page_fast(self, url: str, limit: int) -> tuple[str, list[PlaylistTrack]]:
        """Resolve the full requested playlist prefix, following YouTube continuation pages."""
        playlist_id = youtube_playlist_id(url)
        if not playlist_id:
            raise ValueError("A YouTube playlist URL is required")
        wanted = max(1, int(limit))
        page_url = "https://www.youtube.com/playlist?list=" + urllib.parse.quote(playlist_id, safe="")
        req = urllib.request.Request(
            page_url,
            headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                              "(KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36",
                "Accept-Language": "en-US,en;q=0.9",
                "Accept": "text/html,application/xhtml+xml",
            },
        )
        with urllib.request.urlopen(req, timeout=7.0) as response:
            html = response.read().decode("utf-8", "replace")
        payload = None
        for marker in ("var ytInitialData = ", "ytInitialData = "):
            payload = self._youtube_json_after_marker(html, marker)
            if payload is not None:
                break
        if payload is None:
            raise RuntimeError("YouTube did not return playlist page data.")

        tracks_by_position: dict[int, PlaylistTrack] = {}

        def merge(items: Sequence[PlaylistTrack]) -> int:
            added = 0
            for track in items:
                try:
                    position = int(track.playlist_index)
                except (TypeError, ValueError):
                    continue
                if position < 1 or position > wanted or position in tracks_by_position:
                    continue
                tracks_by_position[position] = track
                added += 1
            return added

        title = ""
        try:
            title = str(payload.get("metadata", {}).get("playlistMetadataRenderer", {}).get("title") or "").strip()
        except Exception:
            pass

        added = merge(self._playlist_tracks_from_initial_data(payload, wanted))
        self.log.info("Batch playlist YouTube page: %d initial track(s), have %d/%d", added, len(tracks_by_position), wanted)

        api_key, client_version = self._youtube_innertube_config(html)
        token = self._youtube_playlist_continuation_token(payload)
        seen_tokens: set[str] = set()
        page_no = 1
        while len(tracks_by_position) < wanted and token and token not in seen_tokens and page_no <= 20:
            seen_tokens.add(token)
            if not api_key:
                raise RuntimeError("YouTube playlist has more entries, but its public continuation API key was not present.")
            continuation_payload = self._youtube_playlist_continuation_request(token, api_key, client_version)
            page_tracks = self._playlist_tracks_from_initial_data(
                continuation_payload, wanted - len(tracks_by_position)
            )
            added = merge(page_tracks)
            self.log.info(
                "Batch playlist YouTube continuation %d: %d new track(s), have %d/%d",
                page_no, added, len(tracks_by_position), wanted,
            )
            token = self._youtube_playlist_continuation_token(continuation_payload)
            page_no += 1
            if not added and not token:
                break

        if not tracks_by_position:
            raise RuntimeError("YouTube returned no playlist entries.")

        tracks = sorted(
            tracks_by_position.values(),
            key=lambda item: (item.playlist_index, item.video_id.lower(), item.title.lower()),
        )
        if len(tracks) < wanted:
            raise RuntimeError(
                f"YouTube page resolver returned only {len(tracks)}/{wanted} usable playlist entries."
            )
        return title, tracks[:wanted]

    def _yt_dlp_playlist_entry_attempts(
        self, url: str, start_index: int, end_index: int
    ) -> list[list[str | os.PathLike[str]]]:
        """Build fast, metadata-only playlist probes.

        Playlist enumeration does NOT need YouTube's JavaScript challenge solver.  In earlier
        versions we launched Deno and allowed remote EJS components for every metadata probe,
        which added avoidable startup/network work.  ``--flat-playlist`` is specifically intended
        for obtaining playlist entries without fully extracting each video.

        The returned commands deliberately disable JS runtimes and remote components for this
        metadata-only stage.  Deno/EJS remains enabled for the actual audio downloads.
        """
        if not self.tools.yt_dlp:
            raise ToolNotFound("yt-dlp.exe was not found")
        start = max(1, int(start_index))
        end = max(start, int(end_index))
        common: list[str | os.PathLike[str]] = [
            self.tools.yt_dlp,
            "--ignore-config",
            "--no-js-runtimes",
            "--no-remote-components",
            "--yes-playlist",
            "--flat-playlist",
            "--playlist-items", f"{start}-{end}",
            "--ignore-errors",
            "--skip-download",
            "--no-warnings",
            "--socket-timeout", "10",
            "--retries", "1",
            "--fragment-retries", "0",
            "--extractor-retries", "1",
            "--print", "%(playlist_index)s\t%(id)s\t%(title)s\t%(webpage_url)s",
        ]
        primary = common + [url]
        # A second client is only a recovery command.  It is never used in parallel with the
        # primary probe, which keeps YouTube load reasonable while still recovering bad metadata
        # responses when the default client gets stuck.
        fallback = common[:-1] + [
            "--print", "%(playlist_index)s\t%(id)s\t%(title)s\t%(webpage_url)s",
            "--extractor-args", "youtube:player_client=android_vr",
            url,
        ]
        return [primary, fallback]

    @staticmethod
    def _playlist_tracks_from_yt_dlp_json(text: str, limit: int) -> list[PlaylistTrack]:
        tracks: list[PlaylistTrack] = []
        seen: set[tuple[int, str]] = set()
        wanted = max(1, int(limit))
        for raw in str(text or "").splitlines():
            raw = raw.strip()
            if not raw or not raw.startswith("{"):
                continue
            try:
                payload = json.loads(raw)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue

            # --dump-json + --flat-playlist normally emits one entry object per line.
            # Some yt-dlp builds may wrap a playlist in an object containing `entries`,
            # so accept that shape too.
            entries = payload.get("entries")
            if isinstance(entries, list):
                candidates = entries
            else:
                candidates = [payload]

            for item in candidates:
                if not isinstance(item, dict):
                    continue
                video_id = str(item.get("id") or item.get("url") or "").strip()
                if video_id.startswith("http://") or video_id.startswith("https://"):
                    parsed = urllib.parse.urlparse(video_id)
                    query = urllib.parse.parse_qs(parsed.query)
                    video_id = str((query.get("v") or [""])[0]).strip()
                if not video_id:
                    continue
                webpage_url = str(item.get("webpage_url") or item.get("original_url") or "").strip()
                if not webpage_url:
                    webpage_url = f"https://www.youtube.com/watch?v={urllib.parse.quote(video_id, safe='')}"
                title = str(item.get("title") or item.get("fulltitle") or video_id).strip() or video_id
                raw_index = item.get("playlist_index")
                try:
                    playlist_index = int(raw_index)
                except (TypeError, ValueError):
                    playlist_index = len(tracks) + 1
                key = (int(playlist_index), (video_id or webpage_url).lower())
                if key in seen:
                    continue
                seen.add(key)
                tracks.append(PlaylistTrack(playlist_index, video_id, title, webpage_url))
                if len(tracks) >= wanted:
                    return tracks
        tracks.sort(key=lambda t: (t.playlist_index, t.video_id.lower()))
        return tracks

    @staticmethod
    def _playlist_tracks_from_output(stdout: str, stderr: str, limit: int) -> list[PlaylistTrack]:
        """Extract playlist tracks from yt-dlp JSON or printed rows.

        yt-dlp can print useful playlist rows before the process exits.  The app must
        therefore be able to parse partial output too, especially when a network
        extractor stalls after emitting the entries we actually need.
        """
        wanted = max(1, int(limit))
        combined = (stdout or "") + "\n" + (stderr or "")

        tracks = SourceManager._playlist_tracks_from_yt_dlp_json(stdout or "", wanted)
        if len(tracks) >= wanted:
            return tracks[:wanted]

        seen = {(int(t.playlist_index), (t.video_id or t.webpage_url).lower()) for t in tracks}
        row_re = re.compile(
            r"^\s*(\d+)\s+([A-Za-z0-9_-]{5,})\s+(.*?)\s+(https?://\S+)\s*$"
        )

        for raw_line in combined.splitlines():
            line = raw_line.strip()
            if not line:
                continue

            # Preferred explicit --print format: index<TAB>id<TAB>title<TAB>url.
            parts = line.split("\t", 3)
            if len(parts) == 4:
                index_text, video_id, title, webpage_url = parts
            else:
                match = row_re.match(line)
                if not match:
                    continue
                index_text, video_id, title, webpage_url = match.groups()

            video_id = str(video_id).strip()
            if not video_id or video_id.lower() in seen:
                continue

            webpage_url = str(webpage_url or "").strip()
            if not webpage_url.startswith(("http://", "https://")):
                webpage_url = (
                    "https://www.youtube.com/watch?v="
                    + urllib.parse.quote(video_id, safe="")
                )

            try:
                playlist_index = int(str(index_text).strip())
            except (TypeError, ValueError):
                playlist_index = len(tracks) + 1

            key = (int(playlist_index), video_id.lower())
            if key in seen:
                continue
            seen.add(key)
            tracks.append(PlaylistTrack(
                playlist_index,
                video_id,
                str(title).strip() or video_id,
                webpage_url,
            ))
            if len(tracks) >= wanted:
                break

        tracks.sort(key=lambda t: (t.playlist_index, t.video_id.lower()))
        return tracks[:wanted]

    def playlist_entries_limited(self, url: str, limit: int, *, allow_partial: bool = False) -> tuple[str, list[PlaylistTrack]]:
        """Resolve the requested playlist prefix without accepting an avoidable partial result.

        Batch mode used to stop after the first yt-dlp timeout, so a 43-song playlist could
        become 35 songs simply because the first metadata process hit its 25-second limit.
        This implementation resumes from the missing playlist indexes until the requested
        prefix is complete or the source genuinely has no more usable entries.
        """
        normalized = normalize_youtube_playlist_url(url)
        if not is_youtube_playlist_url(normalized):
            raise ValueError("A YouTube playlist or Mix URL is required")
        wanted = max(1, int(limit))

        merged: dict[str, PlaylistTrack] = {}
        title = ""
        errors: list[str] = []
        source_exhausted = False

        def add_tracks(items: Sequence[PlaylistTrack]) -> int:
            added = 0
            for item in items:
                key = self._playlist_track_key(item)
                if not key or key in merged:
                    continue
                merged[key] = item
                added += 1
            return added

        # The legacy non-fast path keeps the direct public resolvers as optional fallbacks.
        # Batch mode itself goes straight to resumable yt-dlp probes so it does not spend time
        # on several different HTTP playlist implementations before using the downloader it
        # already needs later.
        if not self.fast_preview:
            for resolver_name, resolver in (
                ("YouTube page", self._youtube_playlist_page_fast),
                ("Piped", self._piped_playlist_entries),
            ):
                if len(merged) >= wanted:
                    break
                try:
                    resolved_title, tracks = resolver(normalized, wanted - len(merged))
                    if resolved_title and not title:
                        title = resolved_title
                    added = add_tracks(tracks)
                    self.log.info(
                        "Batch playlist %s resolver: %d new track(s), have %d/%d",
                        resolver_name, added, len(merged), wanted,
                    )
                except Exception as exc:
                    errors.append(f"{resolver_name}: {exc}")
                    self.log.debug("Batch playlist %s resolver failed: %s", resolver_name, exc)

        def present_indices() -> set[int]:
            return {
                int(track.playlist_index)
                for track in merged.values()
                if 1 <= int(track.playlist_index) <= wanted
            }

        def missing_ranges() -> list[tuple[int, int]]:
            present = present_indices()
            ranges: list[tuple[int, int]] = []
            start: Optional[int] = None
            prev: Optional[int] = None
            for idx in range(1, wanted + 1):
                if idx in present:
                    if start is not None and prev is not None:
                        ranges.append((start, prev))
                    start = None
                    prev = None
                else:
                    if start is None:
                        start = idx
                    prev = idx
            if start is not None and prev is not None:
                ranges.append((start, prev))
            return ranges

        def run_probe(start_index: int, end_index: int, label: str) -> int:
            """Fetch one exact playlist-index range, preserving partial stdout on timeout."""
            nonlocal source_exhausted
            start = max(1, int(start_index))
            end = max(start, int(end_index))
            wanted_here = end - start + 1
            attempts = self._yt_dlp_playlist_entry_attempts(normalized, start, end)
            added_total = 0
            for attempt_no, args in enumerate(attempts, 1):
                try:
                    # Metadata-only playlist discovery explicitly disables JavaScript runtimes
                    # and remote components.  Do not launch/check Deno here; that work belongs to
                    # the later audio-format extraction stage and was a major source of delay.
                    result = self.runner.run(
                        args,
                        timeout=45.0 if attempt_no == 1 else 25.0,
                        check=False,
                    )
                    stdout = result.stdout or ""
                    stderr = result.stderr or ""
                    tracks = self._playlist_tracks_from_output(stdout, stderr, wanted_here)
                    added = add_tracks(tracks)
                    added_total += added
                    if result.returncode == 0 and tracks:
                        positions = sorted({int(t.playlist_index) for t in tracks if int(t.playlist_index) >= start})
                        # A successful request that ends cleanly before the requested upper
                        # bound is the normal signature of a shorter playlist.  Only treat it
                        # as exhaustion when the returned positions are contiguous; this keeps
                        # genuinely missing middle entries eligible for recovery.
                        if positions and positions[-1] < end and positions == list(range(start, positions[-1] + 1)):
                            source_exhausted = True
                            self.log.info(
                                "Batch playlist reached end at playlist index %d (requested through %d)",
                                positions[-1], end,
                            )
                    if result.returncode != 0:
                        detail = ((stderr or "") + "\n" + (stdout or "")).strip()
                        if detail:
                            errors.append(f"yt-dlp {label}, attempt {attempt_no}: {detail[-1200:]}")
                    self.log.info(
                        "Batch playlist yt-dlp %s attempt %d: %d new track(s), have %d/%d%s",
                        label,
                        attempt_no,
                        added,
                        len(merged),
                        wanted,
                        " (partial/timeout, resuming gaps)" if result.returncode != 0 else "",
                    )
                    if len(merged) >= wanted:
                        return added_total
                    if added:
                        # Do not burn the alternate client when the default extractor already
                        # produced usable rows. The next call will target only missing indexes.
                        return added_total
                except ProcessingCancelled:
                    raise
                except ToolExecutionError as exc:
                    stdout = getattr(exc, "stdout", "") or ""
                    stderr = getattr(exc, "stderr", "") or ""
                    tracks = self._playlist_tracks_from_output(stdout, stderr, wanted_here)
                    added = add_tracks(tracks)
                    added_total += added
                    detail = ((stderr or "") + "\n" + (stdout or "")).strip()
                    if detail:
                        errors.append(f"yt-dlp {label}, attempt {attempt_no}: {detail[-1200:]}")
                    self.log.warning(
                        "Batch playlist yt-dlp %s attempt %d timed out/failed after returning %d usable track(s); resuming missing indexes",
                        label,
                        attempt_no,
                        added,
                    )
                    if added:
                        return added_total
                except Exception as exc:
                    errors.append(f"yt-dlp {label}, attempt {attempt_no}: {exc}")
            return added_total

        # Large playlist metadata requests are split into small ranges.  A single 1-72 probe can
        # sit inside YouTube pagination for a long time; smaller ranges finish sooner and make any
        # stalled portion independently recoverable.  The actual audio download remains one yt-dlp
        # playlist session later, so this only affects metadata discovery.
        if self.tools.yt_dlp and len(merged) < wanted:
            chunk_size = 24
            start_index = 1
            while start_index <= wanted and not source_exhausted:
                end_index = min(wanted, start_index + chunk_size - 1)
                run_probe(start_index, end_index, f"initial {start_index}-{end_index}")
                start_index = end_index + 1

        # Resume exact missing playlist positions. This is intentionally enabled for fast
        # preview/batch mode; it is the key fix for the user's 35/43 result.
        no_progress_rounds = 0
        while len(merged) < wanted and not source_exhausted:
            ranges = missing_ranges()
            if not ranges:
                break
            progressed = False
            for start, end in ranges:
                if len(merged) >= wanted:
                    break
                before = len(merged)
                run_probe(start, end, f"resume {start}-{end}")
                if len(merged) > before:
                    progressed = True
            if progressed:
                no_progress_rounds = 0
                continue

            no_progress_rounds += 1
            if no_progress_rounds >= 2:
                # At this point yt-dlp produced no new metadata for any missing position across
                # two complete passes. Treating that as a real source limitation is preferable
                # to endlessly hitting the same dead playlist entries.
                break

        tracks = sorted(
            merged.values(),
            key=lambda t: (t.playlist_index, t.video_id.lower(), t.title.lower()),
        )
        resolved_indices = {
            int(track.playlist_index)
            for track in tracks
            if 1 <= int(track.playlist_index) <= wanted
        }
        missing_indices = [i for i in range(1, wanted + 1) if i not in resolved_indices]

        if len(tracks) < wanted or missing_indices:
            if source_exhausted and tracks:
                self.log.info(
                    "Playlist contains %d usable track occurrence(s); requested prefix was %d, so the source ended normally.",
                    len(tracks), wanted,
                )
                return title, tracks[:wanted]
            if allow_partial and tracks:
                self.log.warning(
                    "Playlist resolver returned a partial result after resumable extraction: %d/%d track(s); missing indexes: %s",
                    len(tracks),
                    wanted,
                    ", ".join(map(str, missing_indices[:40])) if missing_indices else "unknown",
                )
                return title, tracks[:wanted]
            detail = "\n".join(errors[-5:])
            missing_text = (
                " Missing playlist index(es): " + ", ".join(map(str, missing_indices[:40]))
                if missing_indices else ""
            )
            raise RuntimeError(
                f"Only {len(tracks)} unique playlist track(s) could be resolved, but {wanted} were required."
                + missing_text
                + ("\n\n" + detail[-3000:] if detail else "")
            )
        return title, tracks[:wanted]

    # Compatibility aliases. The GUI no longer uses multi-attempt metadata probing.
    def _yt_dlp_playlist_metadata_attempts(self, url: str) -> list[list[str | os.PathLike[str]]]:
        return [self._yt_dlp_playlist_count_args(url)]

    def _yt_dlp_playlist_info_attempts(self, url: str) -> list[list[str | os.PathLike[str]]]:
        return self._yt_dlp_playlist_metadata_attempts(url)

    @staticmethod
    def _parse_playlist_metadata(stdout: str) -> tuple[int, str, list[PlaylistTrack]]:
        """Parse yt-dlp playlist JSON into count/title/track entries."""
        raw = str(stdout or "").strip()
        if not raw:
            return 0, "", []
        try:
            payload = json.loads(raw)
        except json.JSONDecodeError:
            decoder = json.JSONDecoder()
            start = raw.find("{")
            if start < 0:
                start = raw.find("[")
            if start < 0:
                return 0, "", []
            try:
                payload, _ = decoder.raw_decode(raw[start:])
            except json.JSONDecodeError:
                return 0, "", []

        if isinstance(payload, dict):
            entries = payload.get("entries") or []
            declared = payload.get("playlist_count") or payload.get("n_entries") or payload.get("playlist_entries") or len(entries)
            title = str(payload.get("title") or payload.get("playlist_title") or "").strip()
        elif isinstance(payload, list):
            entries = payload
            declared = len(entries)
            title = ""
        else:
            return 0, "", []

        try:
            declared_count = max(0, int(declared or 0))
        except (TypeError, ValueError):
            declared_count = len(entries)

        tracks: list[PlaylistTrack] = []
        seen: set[str] = set()
        fallback_index = 0
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            video_id = str(entry.get("id") or "").strip()
            webpage_url = str(entry.get("webpage_url") or "").strip()
            if not looks_like_url(webpage_url):
                candidate_url = str(entry.get("url") or "").strip()
                webpage_url = candidate_url if looks_like_url(candidate_url) else ""
            if not webpage_url and video_id:
                webpage_url = f"https://www.youtube.com/watch?v={urllib.parse.quote(video_id, safe='')}"
            if not video_id and webpage_url:
                video_id = SourceManager._youtube_video_id(webpage_url) or webpage_url
            if not video_id and not webpage_url:
                continue
            key = video_id or webpage_url
            if key in seen:
                continue
            seen.add(key)
            fallback_index += 1
            try:
                playlist_index = int(entry.get("playlist_index") or fallback_index)
            except (TypeError, ValueError):
                playlist_index = fallback_index
            entry_title = str(entry.get("title") or video_id or f"Track {playlist_index}").strip()
            tracks.append(PlaylistTrack(playlist_index, video_id, entry_title, webpage_url))
        tracks.sort(key=lambda t: (t.playlist_index, t.video_id.lower(), t.title.lower()))
        if declared_count <= 0:
            declared_count = len(tracks)
        return declared_count, title, tracks

    def playlist_metadata(self, url: str) -> tuple[int, str, list[PlaylistTrack]]:
        """Compatibility method: fast count plus only the entries needed by the count."""
        count = self.playlist_count_fast(url)
        title, tracks = self.playlist_entries_limited(url, count)
        return count, title, tracks

    @staticmethod
    def _playlist_source_key(track: PlaylistTrack) -> str:
        """Stable identity for the actual downloadable song, independent of playlist position."""
        source = str(track.video_id or track.webpage_url or track.title).strip().lower()
        return source

    @staticmethod
    def _playlist_track_key(track: PlaylistTrack) -> str:
        """Stable identity for one playlist occurrence.

        Playlist position stays part of the occurrence key so two assignments never accidentally
        share one cache/output path.  Use ``_playlist_source_key`` when the caller specifically
        needs to enforce distinct songs by video/source identity.
        """
        try:
            position = int(track.playlist_index)
        except (TypeError, ValueError):
            position = 0
        source = SourceManager._playlist_source_key(track)
        return f"{position}:{source}"

    @staticmethod
    def _valid_audio_file(path: Optional[Path]) -> bool:
        try:
            return bool(path and path.is_file() and path.stat().st_size > 4096 and path.suffix.lower() in {
                ".m4a", ".webm", ".opus", ".mp3", ".mp4", ".aac", ".wav", ".flac", ".ogg"
            })
        except OSError:
            return False

    _youtube_js_runtime_lock = threading.Lock()
    _youtube_js_runtime_cache: Optional[Path] = None

    @staticmethod
    def _supported_deno_runtime(path: Path) -> bool:
        """Return True only when Deno is new enough and can execute a tiny JS program."""
        try:
            cp = subprocess.run(
                [os.fspath(path), "--version"],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=5,
                check=False,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            match = re.search(r"\bdeno\s+(\d+)\.(\d+)\.(\d+)", (cp.stdout or "") + "\n" + (cp.stderr or ""), re.I)
            if not match or cp.returncode != 0:
                return False
            major, minor = (int(match.group(i)) for i in (1, 2))
            if not (major > 2 or (major == 2 and minor >= 3)):
                return False
            probe = subprocess.run(
                [os.fspath(path), "eval", "console.log('cutie-sumo-deno-ok')"],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8,
                check=False,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            return probe.returncode == 0 and "cutie-sumo-deno-ok" in ((probe.stdout or "") + "\n" + (probe.stderr or ""))
        except (OSError, subprocess.SubprocessError, ValueError):
            return False

    def _youtube_runtime_env(self, runtime: Optional[Path]) -> Optional[dict[str, str]]:
        if runtime is None:
            return None
        env = os.environ.copy()
        parent = str(Path(runtime).resolve().parent)
        current_path = env.get("PATH", "")
        env["PATH"] = parent + (os.pathsep + current_path if current_path else "")
        cache = self.paths.auto_tools / "deno_cache"
        cache.mkdir(parents=True, exist_ok=True)
        env["DENO_DIR"] = str(cache)
        return env

    def _find_youtube_js_runtime(self) -> Optional[Path]:
        """Find a supported JavaScript runtime for yt-dlp's YouTube EJS solver."""
        candidates: list[Path] = []
        for env_name in ("DENO", "DENO_EXE"):
            raw = os.environ.get(env_name, "").strip().strip('"')
            if raw:
                candidates.append(Path(raw))

        roots = [self.paths.root, self.paths.auto_tools, self.paths.auto_tools / "deno", self.paths.root / "tools"]
        if self.tools.yt_dlp:
            ytdlp = Path(self.tools.yt_dlp)
            roots.extend([ytdlp.parent, ytdlp.parent / "deno"])
        for root in roots:
            candidates.extend([root / "deno.exe", root / "deno"])
            # Accept extracted release layouts such as tools\deno-x86_64-pc-windows-msvc\deno.exe.
            try:
                if root.is_dir():
                    for child in root.iterdir():
                        if child.is_dir() and child.name.lower().startswith("deno"):
                            candidates.extend([child / "deno.exe", child / "deno"])
                        elif child.is_file() and child.name.lower().startswith("deno") and child.suffix.lower() == ".exe":
                            candidates.append(child)
            except OSError:
                pass

        for executable in ("deno.exe", "deno"):
            found = shutil.which(executable)
            if found:
                candidates.append(Path(found))

        seen: set[str] = set()
        for candidate in candidates:
            try:
                resolved = candidate.expanduser().resolve()
            except OSError:
                continue
            key = str(resolved).lower()
            if key in seen:
                continue
            seen.add(key)
            if resolved.is_file() and self._supported_deno_runtime(resolved):
                return resolved
        return None

    def _ensure_youtube_js_runtime(self) -> Optional[Path]:
        """Return a launch-tested Deno runtime, repairing/installing it when necessary."""
        cached = self._youtube_js_runtime_cache
        if cached is not None and cached.is_file():
            return cached
        with self._youtube_js_runtime_lock:
            cached = self._youtube_js_runtime_cache
            if cached is not None and cached.is_file():
                return cached
            found = self._find_youtube_js_runtime()
            if found:
                self._youtube_js_runtime_cache = found
                self.log.info("Using launch-tested Deno runtime: %s", found)
                return found
            if os.name != "nt":
                # The application is Windows-only; keep non-Windows self-tests/build-time
                # introspection usable without pretending Deno is installed there.
                return None
            self.log.info("No launch-tested YouTube JavaScript runtime found; installing official Deno runtime…")
            try:
                found = DependencyInstaller(self.paths, self.log)._install_deno()
            except Exception as exc:
                raise RuntimeError(
                    "Could not install or launch the bundled Deno runtime for YouTube."
                    f"\n\n{exc}\n\nThe app will not continue with a broken JavaScript runtime."
                ) from exc
            if not self._supported_deno_runtime(found):
                raise RuntimeError(f"Deno failed its post-install startup test: {found}")
            self._youtube_js_runtime_cache = found
            self.log.info("YouTube JavaScript runtime ready: %s", found)
            self.log.info("Automatic yt-dlp EJS updates are enabled through the official ejs:github remote component.")
            return found

    def _batch_download_args(self, url: str, out_template: Path) -> list[list[str | os.PathLike[str]]]:
        """Build isolated single-video yt-dlp commands with YouTube EJS support."""
        runtime_args: list[str | os.PathLike[str]] = []
        if is_youtube_url(url):
            runtime = self._ensure_youtube_js_runtime()
            if runtime:
                runtime_kind = "deno" if runtime.name.lower().startswith("deno") else "node"
                runtime_args = ["--js-runtimes", f"{runtime_kind}:{runtime}"]
                self.log.debug("Using yt-dlp %s runtime: %s", runtime_kind, runtime)

        base: list[str | os.PathLike[str]] = [
            self.tools.yt_dlp,
            "--ignore-config",
            "--remote-components", "ejs:github",
            *runtime_args,
            "--no-playlist",
            "-f", "bestaudio/best",
            "--no-part",
            "--restrict-filenames",
            "--newline",
            "--concurrent-fragments", "6",
            "--socket-timeout", "15",
            "--retries", "4",
            "--fragment-retries", "4",
            "--extractor-retries", "3",
            "--retry-sleep", "http:linear=0.75::2",
            "--force-ipv4",
            "-o", out_template,
            url,
        ]
        if not is_youtube_url(url):
            return [base]
        # YouTube player clients can differ in availability and CDN authorization.
        # Keep the ordinary client first, then try clients that are useful when a
        # perfectly playable URL returns a CDN 403.
        return [
            base,
            base[:-1] + ["--extractor-args", "youtube:player_client=mweb", url],
            base[:-1] + ["--extractor-args", "youtube:player_client=web_embedded", url],
            base[:-1] + ["--extractor-args", "youtube:player_client=android_vr", url],
        ]

    def _download_playlist_track(
        self,
        track: PlaylistTrack,
        track_number: int,
        total: int,
        work_dir: Path,
        cancel_event: Optional[threading.Event],
        progress: Optional[Callable[[str, int, int], None]] = None,
        track_progress: Optional[Callable[[PlaylistTrack, str, Optional[float], str], None]] = None,
    ) -> PlaylistTrack:
        """Download one exact playlist entry with detailed progress for the live per-track UI."""
        if cancel_event is not None and cancel_event.is_set():
            raise ProcessingCancelled("Batch download cancelled")
        track_dir = work_dir / f"{track.playlist_index:05d}_{safe_name(track.video_id or str(track.playlist_index))}"
        track_dir.mkdir(parents=True, exist_ok=True)
        label = track.title or f"Track {track.playlist_index}"
        out_template = track_dir / f"{safe_name(label, 80)}__{safe_name(track.video_id or str(track.playlist_index), 64)}.%(ext)s"

        def emit(state: str, percent: Optional[float], detail: str) -> None:
            if track_progress is not None:
                with contextlib.suppress(Exception):
                    track_progress(track, state, percent, detail)
            if progress is not None and detail:
                shown = detail
                if percent is not None and percent >= 0:
                    shown = f"{label[:75]} — {percent:.0f}% • {detail}"
                with contextlib.suppress(Exception):
                    progress(shown, 0, total)

        existing = [
            p for p in track_dir.iterdir()
            if p.is_file() and not p.name.endswith(".part") and self._valid_audio_file(p)
        ]
        if existing:
            path = max(existing, key=lambda p: p.stat().st_mtime).resolve()
            emit("cached", 100.0, "Already downloaded")
            return dataclasses.replace(track, path=path)

        errors: list[str] = []
        runner = Runner(self.log, self.runner.bus, cancel_event=cancel_event)
        attempts = self._batch_download_args(track.webpage_url, out_template)
        for attempt_no, args in enumerate(attempts, 1):
            if cancel_event is not None and cancel_event.is_set():
                raise ProcessingCancelled("Batch download cancelled")
            emit("starting" if attempt_no == 1 else "retrying", 0.0, "Starting download…" if attempt_no == 1 else f"Retrying with fallback client {attempt_no - 1}…")

            def live_output(_stream: str, line: str, _attempt: int = attempt_no) -> None:
                text_line = re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", str(line or "")).strip()
                if not text_line:
                    return
                pct_match = re.search(r"(\d+(?:\.\d+)?)%", text_line)
                pct = float(pct_match.group(1)) if pct_match else None
                speed_match = re.search(r"\bat\s+([^\s]+/s)", text_line)
                eta_match = re.search(r"\bETA\s+([^\s]+)", text_line)
                speed = speed_match.group(1) if speed_match else ""
                eta = eta_match.group(1) if eta_match else ""
                if pct is not None:
                    bits = [f"{pct:.0f}%"]
                    if speed:
                        bits.append(speed)
                    if eta:
                        bits.append(f"ETA {eta}")
                    emit("downloading", pct, " • ".join(bits))
                elif "downloading" in text_line.lower() or text_line.lower().startswith("[youtube]") or text_line.lower().startswith("[info]"):
                    emit("starting", None, text_line[-180:])

            try:
                runtime = self._ensure_youtube_js_runtime() if is_youtube_url(track.webpage_url) else None
                result = runner.run(
                    args,
                    timeout=self.options.download_timeout,
                    check=False,
                    output_callback=live_output,
                    env=self._youtube_runtime_env(runtime),
                )
            except ProcessingCancelled:
                raise
            except Exception as exc:
                errors.append(str(exc))
                emit("retrying", None, f"Download process error: {exc}")
                continue

            files = [
                p for p in track_dir.rglob("*")
                if p.is_file() and not p.name.endswith(".part") and self._valid_audio_file(p)
            ]
            if result.returncode == 0 and files:
                path = max(files, key=lambda p: p.stat().st_mtime).resolve()
                emit("ready", 100.0, "Downloaded and ready")
                if progress:
                    progress(f"✓ Downloaded {track_number}/{total} — {label[:75]}", track_number, total)
                return dataclasses.replace(track, path=path)

            detail = ((result.stderr or "") + "\n" + (result.stdout or "")).strip()
            errors.append(detail[-1800:] or f"yt-dlp exited with code {result.returncode}")
            emit("retrying", None, f"Attempt {attempt_no} failed — retrying…")
            if attempt_no < len(attempts):
                self.log.warning("Track %s download attempt %d failed; trying fallback client", track.video_id, attempt_no)

        if is_youtube_url(track.webpage_url):
            emit("alternate", None, "Trying alternate source…")
            try:
                piped = self._download_via_piped(
                    track.webpage_url,
                    track_dir,
                    label,
                    progress_callback=lambda pct, detail: emit(
                        "alternate", (pct if pct >= 0 else None), detail
                    ),
                )
                if piped is not None and self._valid_audio_file(piped):
                    emit("ready", 100.0, "Recovered from alternate source")
                    if progress:
                        progress(
                            f"✓ Recovered {track_number}/{total} via alternate source — {label[:75]}",
                            track_number,
                            total,
                        )
                    return dataclasses.replace(track, path=Path(piped).resolve())
            except ProcessingCancelled:
                raise
            except Exception as exc:
                errors.append(f"Piped fallback: {exc}")

        reason = errors[-1] if errors else "unknown yt-dlp error"
        emit("failed", None, f"Failed: {reason[-220:]}")
        raise RuntimeError(f"Could not download playlist track {track.playlist_index}: {label}\n{reason}")

    def download_playlist_bulk(
        self,
        playlist_url: str,
        tracks: Sequence[PlaylistTrack],
        work_dir: Path,
        cancel_event: Optional[threading.Event] = None,
        progress: Optional[Callable[[str, int, int], None]] = None,
    ) -> list[PlaylistTrack]:
        """Download all selected entries from one playlist in a single yt-dlp session.

        yt-dlp itself handles playlist pagination and YouTube EJS once. The app then maps the
        generated files back to PlaylistTrack objects. Only genuinely missing tracks are retried
        individually, so one bad video cannot restart the entire playlist.
        """
        selected = sorted(list(tracks), key=lambda t: (int(t.playlist_index), t.video_id.lower()))
        if not selected:
            return []
        if not self.tools.yt_dlp or not is_youtube_playlist_url(playlist_url):
            raise ValueError("A valid YouTube playlist and yt-dlp.exe are required for bulk download")
        work_dir.mkdir(parents=True, exist_ok=True)
        bulk_dir = work_dir / "bulk"
        bulk_dir.mkdir(parents=True, exist_ok=True)
        template = bulk_dir / "%(playlist_index)05d__%(id)s.%(ext)s"
        playlist_items = ",".join(str(int(t.playlist_index)) for t in selected)

        runtime = self._ensure_youtube_js_runtime()
        runtime_args: list[str | os.PathLike[str]] = []
        if runtime:
            runtime_args = ["--js-runtimes", f"deno:{runtime}"]

        args: list[str | os.PathLike[str]] = [
            self.tools.yt_dlp,
            "--ignore-config",
            "--remote-components", "ejs:github",
            *runtime_args,
            "--yes-playlist",
            "--playlist-items", playlist_items,
            "--no-overwrites",
            "--no-part",
            "--continue",
            "--ignore-errors",
            "--newline",
            "-f", "bestaudio/best",
            "--socket-timeout", "15",
            "--retries", "2",
            "--fragment-retries", "2",
            "--extractor-retries", "2",
            "--concurrent-fragments", "8",
            "-o", template,
            playlist_url,
        ]
        if progress:
            progress(f"Downloading {len(selected)} playlist track(s) in one yt-dlp session… ♫", 0, len(selected))

        runner = Runner(self.log, self.runner.bus, cancel_event=cancel_event)
        result = runner.run(
            args,
            timeout=max(300.0, float(self.options.download_timeout)),
            check=False,
            env=self._youtube_runtime_env(runtime),
        )

        by_index: dict[int, Path] = {}
        for path in bulk_dir.rglob("*"):
            if not path.is_file() or path.name.endswith(".part") or not self._valid_audio_file(path):
                continue
            match = re.match(r"^(\d+)__", path.name)
            if not match:
                continue
            index = int(match.group(1))
            prior = by_index.get(index)
            if prior is None or path.stat().st_mtime > prior.stat().st_mtime:
                by_index[index] = path.resolve()

        downloaded: list[PlaylistTrack] = []
        missing: list[PlaylistTrack] = []
        for track in selected:
            path = by_index.get(int(track.playlist_index))
            if path is not None and self._valid_audio_file(path):
                downloaded.append(dataclasses.replace(track, path=path))
            else:
                missing.append(track)

        # Recovery is deliberately limited to missing tracks; never restart the playlist.
        for track in missing:
            if cancel_event is not None and cancel_event.is_set():
                raise ProcessingCancelled("Batch playlist download cancelled")
            try:
                recovered = self._download_playlist_track(
                    track, len(downloaded) + 1, len(selected), work_dir, cancel_event, progress
                )
                downloaded.append(recovered)
            except Exception as exc:
                self.log.error("Bulk playlist recovery failed for track %d (%s): %s", track.playlist_index, track.title, exc)

        downloaded.sort(key=lambda t: (int(t.playlist_index), t.video_id.lower()))
        if len(downloaded) < len(selected):
            failed = [str(t.playlist_index) for t in selected if all(int(x.playlist_index) != int(t.playlist_index) for x in downloaded)]
            detail = ((result.stderr or "") + "\n" + (result.stdout or "")).strip()
            raise RuntimeError(
                f"Only {len(downloaded)}/{len(selected)} playlist tracks could be downloaded. "
                f"Failed playlist indexes: {', '.join(failed[:30])}"
                + (f"\n\n{detail[-1500:]}" if detail else "")
            )
        self.log.info("Bulk playlist download complete: %d/%d usable track(s)", len(downloaded), len(selected))
        if progress:
            progress(f"✓ All {len(downloaded)} playlist track(s) downloaded", len(downloaded), len(downloaded))
        return downloaded

    def download_playlist_parallel(
        self,
        tracks: Sequence[PlaylistTrack],
        work_dir: Path,
        workers: Optional[int] = None,
        cancel_event: Optional[threading.Event] = None,
        progress: Optional[Callable[[str, int, int], None]] = None,
        allow_partial: bool = False,
        track_progress: Optional[Callable[[PlaylistTrack, str, Optional[float], str], None]] = None,
    ) -> list[PlaylistTrack] | tuple[list[PlaylistTrack], list[PlaylistDownloadFailure]]:
        """Download playlist tracks independently and in parallel.

        One yt-dlp process per active track gives the UI exact track-level progress and also
        lets independent downloads continue even when one video returns a 403 or another error.
        Each track has its own isolated folder, so no worker can corrupt another track's output.
        """
        selected = sorted(list(tracks), key=lambda t: (int(t.playlist_index), t.video_id.lower(), t.title.lower()))
        if not selected:
            return []
        work_dir.mkdir(parents=True, exist_ok=True)
        total = len(selected)
        if cancel_event is not None and cancel_event.is_set():
            raise ProcessingCancelled("Batch download cancelled")

        results: list[Optional[PlaylistTrack]] = [None] * total
        pending: list[tuple[int, PlaylistTrack]] = []

        def track_key(track: PlaylistTrack) -> str:
            return f"{int(track.playlist_index)}:{track.video_id.lower()}:{track.title.lower()}"

        def track_dir(track: PlaylistTrack) -> Path:
            d = work_dir / f"{int(track.playlist_index):05d}_{safe_name(track.video_id or str(track.playlist_index))}"
            d.mkdir(parents=True, exist_ok=True)
            return d

        def find_cached(track: PlaylistTrack) -> Optional[Path]:
            directory = track_dir(track)
            try:
                existing = [
                    p for p in directory.iterdir()
                    if p.is_file() and not p.name.endswith(".part") and self._valid_audio_file(p)
                ]
            except OSError:
                existing = []
            # Do not search the whole playlist cache by video ID. That old fallback could take
            # a file belonging to another playlist occurrence and silently turn two assignments
            # into one shared download. The track-specific folder is the only automatic cache hit.
            if existing:
                return max(existing, key=lambda p: p.stat().st_mtime).resolve()
            return None

        cached_count = 0
        for index, track in enumerate(selected):
            cached = find_cached(track)
            if cached is not None:
                results[index] = dataclasses.replace(track, path=cached)
                cached_count += 1
                if track_progress:
                    track_progress(track, "cached", 100.0, "Already downloaded")
                if progress:
                    progress(f"✓ Reusing {index + 1}/{total} — {track.title[:75]}", cached_count, total)
            else:
                pending.append((index, track))
                if track_progress:
                    track_progress(track, "queued", 0.0, "Queued")

        if not pending:
            if progress:
                progress(f"✓ All {total}/{total} playlist tracks ready", total, total)
            final = [item for item in results if item is not None]
            return (final, []) if allow_partial else final

        requested_workers = int(workers or getattr(self.options, "download_workers", 8) or 8)
        # TURBO uses a bounded 16-job pool. This keeps slow YouTube entries from holding the
        # whole playlist behind a 12-job queue without creating an unbounded connection burst.
        worker_count = max(1, min(16, requested_workers, len(pending)))
        self.log.info(
            "Starting %d parallel playlist-track downloads (%d pending, %d cached)",
            worker_count, len(pending), cached_count,
        )
        if progress:
            progress(
                f"Downloading {len(pending)} remaining playlist track(s) with {worker_count} parallel jobs… ♫",
                cached_count,
                total,
            )

        completed = cached_count
        completed_lock = threading.Lock()
        failures_by_index: dict[int, PlaylistDownloadFailure] = {}
        runner = Runner(self.log, self.runner.bus, cancel_event=cancel_event)

        def one(index: int, track: PlaylistTrack) -> tuple[int, Optional[PlaylistTrack], Optional[Exception]]:
            try:
                value = self._download_playlist_track(
                    track,
                    index + 1,
                    total,
                    work_dir,
                    cancel_event,
                    progress=progress,
                    track_progress=track_progress,
                )
                return index, value, None
            except ProcessingCancelled:
                raise
            except Exception as exc:
                return index, None, exc

        with concurrent.futures.ThreadPoolExecutor(
            max_workers=worker_count,
            thread_name_prefix="playlist-track",
        ) as executor:
            future_map = {
                executor.submit(one, index, track): (index, track)
                for index, track in pending
            }
            for future in concurrent.futures.as_completed(future_map):
                index, track = future_map[future]
                if cancel_event is not None and cancel_event.is_set():
                    for f in future_map:
                        f.cancel()
                    raise ProcessingCancelled("Batch download cancelled")
                try:
                    result_index, downloaded, exc = future.result()
                except ProcessingCancelled:
                    for f in future_map:
                        f.cancel()
                    raise
                except Exception as exc:
                    result_index, downloaded = index, None
                if downloaded is not None and downloaded.path is not None and self._valid_audio_file(downloaded.path):
                    results[result_index] = downloaded
                    with completed_lock:
                        completed += 1
                        done_now = completed
                    if progress:
                        progress(
                            f"✓ Ready {done_now}/{total} — {track.title[:75]}",
                            done_now,
                            total,
                        )
                else:
                    reason = str(exc or "No usable audio file was produced")
                    failures_by_index[result_index] = PlaylistDownloadFailure(track=track, reason=reason)
                    if track_progress:
                        track_progress(track, "failed", None, reason[-220:])
                    self.log.error(
                        "Playlist track %s (%s) failed: %s",
                        track.playlist_index,
                        track.title,
                        reason,
                    )

        # A late filesystem scan can recover a file written right before a worker exited.
        for index, track in pending:
            if results[index] is not None and self._valid_audio_file(results[index].path):
                continue
            cached = find_cached(track)
            if cached is not None:
                results[index] = dataclasses.replace(track, path=cached)
                failures_by_index.pop(index, None)
                if track_progress:
                    track_progress(track, "ready", 100.0, "Recovered completed file")

        failures = [failures_by_index[i] for i, _track in pending if i in failures_by_index]
        final = [item for item in results if item is not None and item.path is not None and self._valid_audio_file(item.path)]
        if failures:
            if progress:
                progress(
                    f"⚠ {len(failures)} track(s) need your choice; {len(final)}/{total} are ready",
                    len(final),
                    total,
                )
            if allow_partial:
                return final, failures
            failed_lines = "\n".join(f"{f.track.playlist_index}: {f.track.title}" for f in failures[:20])
            raise RuntimeError(
                f"{len(failures)} playlist song(s) could not be prepared.\n\n{failed_lines}"
            )

        if progress:
            progress(f"✓ All {len(final)}/{total} playlist tracks ready", len(final), total)
        return (final, []) if allow_partial else final

    def download_playlist(
        self, url: str, work_dir: Path, label: str = "playlist", expected_count: Optional[int] = None
    ) -> list[PlaylistTrack]:
        """Compatibility shim for legacy callers; the GUI batch path does not use it.

        The new batch workflow performs metadata validation first and then calls
        ``download_playlist_parallel`` directly.  This shim preserves old integrations
        without reinstating the former playlist-wide download-and-scan implementation.
        """
        _, _, tracks = self.playlist_metadata(url)
        if expected_count is not None:
            tracks = tracks[:max(0, int(expected_count))]
        return self.download_playlist_parallel(
            tracks,
            work_dir,
            workers=self.options.download_workers,
            cancel_event=self.runner.cancel_event,
            progress=lambda message, done, total: self._progress(message),
        )

    def download_url(self, url: str, work_dir: Path, label: str) -> Path:
        """Download one source into an isolated cache directory.

        This method is safe to call concurrently for dozens of distinct URLs because every
        caller owns its own ``work_dir``.  yt-dlp gets several retries; YouTube failures then
        fall back to the already-supported Piped resolver before the source is reported dead.
        """
        work_dir.mkdir(parents=True, exist_ok=True)
        name_template = safe_name(label) + "_%(_id)s.%(ext)s"
        out_template = work_dir / name_template
        self.log.info("Downloading %s", url)
        self._progress(f"Downloading {label or 'replacement audio'}… ♫")

        def live_single(_stream: str, line: str) -> None:
            text = str(line or "").strip()
            if not text:
                return
            pct = re.search(r"(\d+(?:\.\d+)?)%", text)
            if pct:
                self._progress(f"Downloading {label or 'replacement audio'}… {float(pct.group(1)):.0f}% ♫")

        attempts = self._yt_dlp_download_attempts(url, out_template)
        errors: list[str] = []
        for index, args in enumerate(attempts, 1):
            # Only remove this source's own failed artifacts.  Bulk downloads never share a
            # directory, so a retry can never delete a neighboring source's completed file.
            for p in work_dir.iterdir():
                if p.is_file() and p.name != "desktop.ini":
                    with contextlib.suppress(OSError):
                        p.unlink()
            try:
                result = self.runner.run(args, timeout=self.options.download_timeout, check=False, output_callback=live_single)
            except ProcessingCancelled:
                raise
            except Exception as exc:
                errors.append(str(exc))
                continue
            if result.returncode == 0:
                files = [
                    p for p in work_dir.iterdir()
                    if p.is_file() and p.name != "desktop.ini" and not p.name.endswith(".part")
                    and self._valid_audio_file(p)
                ]
                if files:
                    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
                    return files[0].resolve()
            detail = ((result.stderr or "") + "\n" + (result.stdout or "")).strip()
            errors.append(detail[-2200:] or f"yt-dlp exited with code {result.returncode}")
            if is_youtube_url(url) and index < len(attempts):
                self.log.warning("YouTube download attempt %d failed; retrying with another player client", index)

        # yt-dlp can lose access to an otherwise playable YouTube video when a specific
        # player client/cookie path is blocked.  Use the app's Piped fallback before giving up.
        if is_youtube_url(url):
            try:
                piped = self._download_via_piped(url, work_dir, label)
                if piped is not None and self._valid_audio_file(piped):
                    return piped.resolve()
            except ProcessingCancelled:
                raise
            except Exception as exc:
                errors.append(f"Piped fallback: {exc}")

        hint = "\n\nSome YouTube videos may be unavailable depending on yt-dlp/YouTube availability." if is_youtube_url(url) else ""
        detail = errors[-1] if errors else "unknown download error"
        raise RuntimeError(f"Could not download {url}.\n{detail[-2600:]}{hint}")


@dataclasses.dataclass
class _URLPrefetchEntry:
    url: str
    cache_dir: Path
    done: threading.Event = dataclasses.field(default_factory=threading.Event)
    cancel: threading.Event = dataclasses.field(default_factory=threading.Event)
    path: Optional[Path] = None
    playlist_tracks: list[PlaylistTrack] = dataclasses.field(default_factory=list)
    error: str = ""


class URLPrefetchManager:
    """Pre-download the current URL source without applying any audio processing."""
    def __init__(self, tools_provider: Callable[[], ToolPaths], paths: KitPaths,
                 logger: logging.Logger, bus: EventBus,
                 status_callback: Optional[Callable[[str], None]] = None) -> None:
        self._tools_provider = tools_provider
        self.paths = paths
        self.log = logger
        self.bus = bus
        self.status_callback = status_callback
        self.root = paths.processed_audio / "url_prefetch"
        self.root.mkdir(parents=True, exist_ok=True)
        self._lock = threading.RLock()
        self._entries: dict[str, _URLPrefetchEntry] = {}
        self._contexts: dict[str, str] = {}

    @staticmethod
    def _key(url: str) -> str:
        return hashlib.sha256(url.strip().encode("utf-8")).hexdigest()[:32]

    @staticmethod
    def _valid(path: Optional[Path]) -> bool:
        try:
            return bool(path and path.is_file() and path.stat().st_size > 4096)
        except OSError:
            return False

    def _cached_path(self, url: str) -> Optional[Path]:
        """Find a completed cached download even if its in-memory entry was retired."""
        cache_dir = self.root / self._key(url)
        try:
            candidates = [
                p for p in cache_dir.iterdir()
                if p.is_file() and p.name != "desktop.ini" and not p.name.endswith(".part")
            ]
        except OSError:
            return None
        valid = [p for p in candidates if self._valid(p)]
        if not valid:
            return None
        valid.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return valid[0]

    def _status(self, message: str) -> None:
        if self.status_callback:
            try:
                self.status_callback(message)
            except Exception:
                pass

    def _remove_files(self, entry: _URLPrefetchEntry) -> None:
        with contextlib.suppress(OSError):
            shutil.rmtree(entry.cache_dir, ignore_errors=True)

    def _start(self, entry: _URLPrefetchEntry, label: str, expected_count: Optional[int] = None) -> None:
        def worker() -> None:
            try:
                entry.cache_dir.mkdir(parents=True, exist_ok=True)
                runner = Runner(self.log, self.bus, cancel_event=entry.cancel)
                opts = ProcessOptions(download_timeout=600.0, install_to_game=False)
                source_manager = SourceManager(
                    self._tools_provider(), runner, self.paths, self.log, opts, fast_preview=True,
                    progress_callback=self._status,
                )
                self.log.info("Prefetching URL source: %s", entry.url)
                if is_youtube_playlist_url(entry.url):
                    tracks = source_manager.download_playlist(entry.url, entry.cache_dir, label, expected_count=expected_count)
                    if entry.cancel.is_set():
                        raise PreviewCancelled("URL playlist prefetch cancelled")
                    if not tracks or any(not self._valid(t.path) for t in tracks):
                        raise RuntimeError("The playlist download completed without a usable audio file for every track")
                    with self._lock:
                        entry.playlist_tracks = tracks
                        entry.path = tracks[0].path
                        entry.error = ""
                    self.log.info("URL playlist prefetch ready: %s -> %d tracks", entry.url, len(tracks))
                    self._status(f"✓ Playlist ready — {len(tracks)} tracks")
                else:
                    path = source_manager.download_url(entry.url, entry.cache_dir, label)
                    if entry.cancel.is_set():
                        raise PreviewCancelled("URL prefetch cancelled")
                    if not self._valid(path):
                        raise RuntimeError("The download completed but did not produce a usable audio file")
                    with self._lock:
                        entry.path = path
                        entry.error = ""
                    self.log.info("URL prefetch ready: %s -> %s", entry.url, path)
                    self._status("✓ Replacement audio is ready")
            except Exception as exc:
                with self._lock:
                    entry.error = str(exc)
                if not entry.cancel.is_set():
                    self.log.error("URL prefetch failed for %s: %s", entry.url, exc)
                    self._status("♡ Could not pre-download the replacement audio")
            finally:
                entry.done.set()
                with self._lock:
                    still_active = self._entries.get(entry.url) is entry
                # Keep successful downloads cached even when the originating UI field
                # has changed or its context has been destroyed. The replacement stage
                # may legitimately request the same URL milliseconds later; deleting a
                # completed file here creates a race where the log shows "prefetch ready"
                # and the actual replacement immediately starts a needless failed download.
                if entry.cancel.is_set():
                    self._remove_files(entry)
                    with self._lock:
                        if self._entries.get(entry.url) is entry:
                            self._entries.pop(entry.url, None)
                elif not still_active:
                    with self._lock:
                        if self._entries.get(entry.url) is entry:
                            self._entries[entry.url] = entry

        threading.Thread(target=worker, daemon=True, name="url-prefetch").start()

    def activate(self, context: str, raw_url: str, label: str) -> None:
        url = raw_url.strip().strip('"')
        with self._lock:
            previous = self._contexts.get(context)
            if previous == url:
                return
            if previous:
                self._contexts.pop(context, None)
                old = self._entries.get(previous)
                if old is not None and previous not in self._contexts.values():
                    old.cancel.set()
                    if old.done.is_set():
                        self._entries.pop(previous, None)
                        self._remove_files(old)
            if not looks_like_url(url):
                return
            self._contexts[context] = url
            if is_youtube_playlist_url(url):
                self._status("Playlist source will be loaded when you press Apply ♡")
                return
            entry = self._entries.get(url)
            if entry is None or entry.cancel.is_set():
                if entry is not None:
                    self._entries.pop(url, None)
                entry = None
            if entry is None:
                entry = _URLPrefetchEntry(url, self.root / self._key(url))
                self._entries[url] = entry
                self._status("♡ Downloading replacement audio in the background…")
                self._start(entry, label)
            elif entry.done.is_set() and self._valid(entry.path):
                self._status("✓ Replacement audio is already downloaded")
            else:
                self._status("♡ Downloading replacement audio in the background…")

    def _cached_playlist_tracks(self, url: str) -> list[PlaylistTrack]:
        manifest = self.root / self._key(url) / "manifest.json"
        try:
            payload = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, ValueError, TypeError):
            return []
        tracks: list[PlaylistTrack] = []
        for item in payload if isinstance(payload, list) else []:
            if not isinstance(item, dict):
                continue
            try:
                idx = int(item.get("playlist_index"))
            except (TypeError, ValueError):
                continue
            path = Path(str(item.get("path") or ""))
            if not self._valid(path):
                return []
            tracks.append(PlaylistTrack(
                idx,
                str(item.get("video_id") or ""),
                str(item.get("title") or f"Track {idx}"),
                str(item.get("webpage_url") or ""),
                path.resolve(),
            ))
        tracks.sort(key=lambda t: t.playlist_index)
        return tracks

    def wait_for_playlist(self, raw_url: str, label: str, expected_count: Optional[int] = None, timeout: float = 900.0) -> list[PlaylistTrack]:
        url = raw_url.strip().strip('"')
        cached = self._cached_playlist_tracks(url)
        cache_satisfies = expected_count is None or len(cached) >= int(expected_count)
        if cached and cache_satisfies:
            chosen = cached if expected_count is None else cached[:int(expected_count)]
            with self._lock:
                entry = self._entries.get(url)
                if entry is not None:
                    entry.playlist_tracks = cached
                    entry.path = cached[0].path if cached else None
                    entry.error = ""
            self.log.info("Using cached YouTube playlist: %s -> %d track(s)%s", url, len(cached),
                          f" (using first {len(chosen)})" if expected_count is not None and len(cached) > len(chosen) else "")
            return chosen

        with self._lock:
            entry = self._entries.get(url)
            needs_restart = (
                entry is None
                or entry.cancel.is_set()
                or (entry.done.is_set() and not entry.playlist_tracks)
                or (expected_count is not None and entry.done.is_set() and len(entry.playlist_tracks) < int(expected_count))
            )
            if needs_restart:
                if entry is not None and entry.cancel.is_set():
                    self._entries.pop(url, None)
                entry = _URLPrefetchEntry(url, self.root / self._key(url))
                self._entries[url] = entry
                self._start(entry, label, expected_count=expected_count)
        if not entry.done.wait(timeout):
            raise RuntimeError("Timed out waiting for the YouTube playlist download")
        with self._lock:
            tracks = list(entry.playlist_tracks)
            error = entry.error
        if tracks and all(self._valid(t.path) for t in tracks):
            if expected_count is None:
                return tracks
            if len(tracks) >= int(expected_count):
                return tracks[:int(expected_count)]
        cached = self._cached_playlist_tracks(url)
        if cached and all(self._valid(t.path) for t in cached):
            if expected_count is None:
                return cached
            if len(cached) >= int(expected_count):
                return cached[:int(expected_count)]
        if tracks:
            return tracks
        cached = self._cached_playlist_tracks(url)
        if cached:
            return cached if expected_count is None else cached[:int(expected_count)]
        raise RuntimeError(error or "The YouTube playlist download failed")

    def wait_for(self, raw_url: str, label: str, timeout: float = 900.0) -> Path:
        url = raw_url.strip().strip('"')
        # First recover a completed file from disk. This makes the replacement stage
        # resilient to a UI-context cleanup racing the background prefetch completion.
        cached = self._cached_path(url)
        if cached is not None:
            with self._lock:
                entry = self._entries.get(url)
                if entry is not None:
                    entry.path = cached
                    entry.error = ""
            self.log.info("Using cached replacement audio: %s -> %s", url, cached)
            return cached

        with self._lock:
            entry = self._entries.get(url)
            if entry is None or entry.cancel.is_set() or (entry.done.is_set() and not self._valid(entry.path)):
                if entry is not None and entry.cancel.is_set():
                    self._entries.pop(url, None)
                entry = _URLPrefetchEntry(url, self.root / self._key(url))
                self._entries[url] = entry
                self._start(entry, label)
        if not entry.done.wait(timeout):
            raise RuntimeError("Timed out waiting for the replacement audio download")
        with self._lock:
            path = entry.path
            error = entry.error
        if self._valid(path):
            return path  # type: ignore[return-value]
        cached = self._cached_path(url)
        if cached is not None:
            self.log.info("Recovered completed replacement audio from cache: %s -> %s", url, cached)
            return cached
        raise RuntimeError(error or "The replacement audio download failed")

    def cleanup_all(self) -> None:
        with self._lock:
            entries = list(self._entries.values())
            self._entries.clear()
            self._contexts.clear()
        for entry in entries:
            entry.cancel.set()
            if entry.done.is_set():
                self._remove_files(entry)

def _require_file(path: Path, description: str, minimum_size: int = 44) -> Path:
    """Validate that a subprocess-produced file exists and is not trivially empty."""
    try:
        if path.is_file() and path.stat().st_size >= minimum_size:
            return path
    except OSError as exc:
        raise RuntimeError(f"Could not validate {description}: {path}: {exc}") from exc
    raise RuntimeError(f"Expected {description} was not produced: {path}")


class AudioProcessor:
    def __init__(self, tools: ToolPaths, runner: Runner, logger: logging.Logger,
                 options: ProcessOptions) -> None:
        self.tools = tools
        self.runner = runner
        self.log = logger
        self.options = options
        self.last_source_duration: Optional[float] = None

    def decode_and_match(self, source: Path, target: WemInfo, work_dir: Path,
                         extra_offset_ms: float = 0.0,
                         source_duration: Optional[float] = None) -> Path:
        """Convert, trim/match, and apply common effects in one FFmpeg pass.

        Older builds decoded to an intermediate WAV, re-read it for offset/cutoff, wrote a
        second WAV for duration matching, and then optionally ran additional FFmpeg passes for
        effects/normalization. That multiplied disk I/O and process startup costs for every WEM.
        This path keeps the same user-facing rules while reducing normal conversion to one FFmpeg
        process. Duration-dependent probing is only used where the requested behavior truly needs it;
        loudness normalization remains a separate pass because it intentionally uses the existing
        peak-detect behavior.
        """
        if not self.tools.ffmpeg:
            raise ToolNotFound("FFmpeg was not found")
        work_dir.mkdir(parents=True, exist_ok=True)
        target_duration = float(target.duration_seconds)
        if target_duration <= 0:
            raise RuntimeError(f"Target WEM {target.display_name} has no usable duration")

        if self.options.combine_original:
            self.last_source_duration = None
            return self._decode_and_combine(source, target, work_dir, extra_offset_ms)

        rate = float(self.options.playback_rate or 1.0)
        if not math.isfinite(rate) or rate <= 0:
            raise ValueError("Playback speed must be greater than 0")
        offset_ms = float(self.options.audio_offset_ms or 0.0) + float(extra_offset_ms or 0.0)
        if offset_ms < 0:
            raise ValueError("Audio start offset cannot be negative")
        cutoff_ms = self.options.source_end_ms
        if cutoff_ms is not None:
            cutoff_ms = float(cutoff_ms)
            if not math.isfinite(cutoff_ms) or cutoff_ms < 0:
                raise ValueError("Audio end cutoff must be 0 or greater")

        # Most replacement modes do not actually need the source duration up front.
        # FFmpeg already knows the source EOF while decoding, and -t/atrim/apad can
        # enforce the requested output boundary in the same pass. Only two cases need
        # an explicit duration calculation: strict "reject if too short", and a
        # non-auto-matched fade-out whose start point must be placed from the end.
        fade_in = max(0.0, float(self.options.fade_in_ms or 0) / 1000.0)
        fade_out = max(0.0, float(self.options.fade_out_ms or 0) / 1000.0)
        needs_source_duration = (
            (bool(self.options.auto_match_duration) and self.options.short_source_policy == "reject")
            or (not bool(self.options.auto_match_duration) and fade_out > 0.0)
        )
        if needs_source_duration:
            if source_duration is None:
                source_duration = (
                    ffprobe_duration(self.runner, self.tools.ffprobe, source)
                    if self.tools.ffprobe else self._ffmpeg_duration(source)
                )
            self.last_source_duration = float(source_duration)
            self.log.info("Source duration %.6fs; target %s duration %.6fs", source_duration, target.display_name, target_duration)
        else:
            self.last_source_duration = None

        sr_arg: list[str] = []
        ch_arg: list[str] = []
        if self.options.sample_rate_policy == "original" and target.sample_rate:
            sr_arg = ["-ar", str(target.sample_rate)]
        elif self.options.sample_rate_policy == "48000":
            sr_arg = ["-ar", "48000"]
        if self.options.channel_policy == "original" and target.channels:
            ch_arg = ["-ac", str(target.channels)]
        elif self.options.channel_policy in {"1", "2"}:
            ch_arg = ["-ac", self.options.channel_policy]

        # Trim coordinates are applied after any atempo filter. An explicit cutoff is
        # an absolute end timestamp; FFmpeg safely clamps it at EOF, so no source
        # duration probe is necessary just to express the cutoff.
        start_s = offset_ms / 1000.0
        cutoff_s = 0.0 if cutoff_ms is None else cutoff_ms / 1000.0

        working_duration: Optional[float] = None
        if source_duration is not None:
            processed_duration = float(source_duration) / rate
            end_s = min(processed_duration, cutoff_s) if cutoff_s > 0.000001 else processed_duration
            if start_s >= end_s - 0.000001:
                raise RuntimeError(
                    "The selected audio range is empty; the start offset must be before the end cutoff/source end"
                )
            working_duration = end_s - start_s

        filters: list[str] = []
        n = rate
        while n > 2.0 + 1e-9:
            filters.append("atempo=2.0"); n /= 2.0
        while n < 0.5 - 1e-9:
            filters.append("atempo=0.5"); n /= 0.5
        if abs(rate - 1.0) > 1e-6:
            filters.append(f"atempo={n:.6f}")

        if start_s > 0.000001 or cutoff_s > 0.000001:
            if cutoff_s > 0.000001:
                # No source-duration probe is required here; atrim's end timestamp is
                # simply bounded by EOF if the source is shorter than the requested end.
                filters.append(f"atrim=start={start_s:.9f}:end={cutoff_s:.9f}")
            else:
                filters.append(f"atrim=start={start_s:.9f}")
            filters.append("asetpts=PTS-STARTPTS")

        output_duration: Optional[float]
        if self.options.auto_match_duration:
            output_duration = target_duration
            if self.options.short_source_policy == "reject":
                assert working_duration is not None
                if working_duration + 1e-6 < target_duration:
                    raise ValueError(
                        f"Replacement audio is too short ({working_duration:.6f}s) for target ({target_duration:.6f}s). Strict mode is enabled."
                    )
            elif self.options.short_source_policy == "silence":
                # apad is harmless when the source is already long; -t below trims
                # the result to the exact target duration either way.
                filters.append(f"apad=whole_dur={target_duration:.9f}")
            elif self.options.short_source_policy == "loop":
                # Loop unconditionally. When the source is longer than the target,
                # -t stops the first pass at target_duration; when it is shorter, the
                # same command seamlessly supplies additional source audio.
                pass
        else:
            output_duration = working_duration

        volume = float(self.options.volume_db or 0.0)
        if abs(volume) > 0.001:
            filters.append(f"volume={volume:.3f}dB")
        if fade_in > 0:
            if output_duration is None:
                filters.append(f"afade=t=in:st=0:d={fade_in:.6f}")
            else:
                filters.append(f"afade=t=in:st=0:d={min(fade_in, output_duration):.6f}")
        if fade_out > 0:
            if output_duration is None:
                raise RuntimeError("Fade-out preparation requires a source duration")
            fade_out = min(fade_out, output_duration / 2.0)
            filters.append(f"afade=t=out:st={max(0.0, output_duration - fade_out):.6f}:d={fade_out:.6f}")

        matched = work_dir / "matched.wav"

        # Playlist replacement is deliberately audio-only. Explicit stream mapping and
        # metadata stripping prevent FFmpeg from probing/copying unrelated streams such
        # as video thumbnails, subtitles, attachments, or container metadata. Keeping
        # each conversion to one codec thread is also important when many FFmpeg
        # processes run concurrently: otherwise 8-16 worker processes can each spawn
        # their own thread pools and spend much of their time fighting for the same CPU.
        cmd: list[str | os.PathLike[str]] = [
            self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
            "-nostdin", "-threads", "1",
        ]
        if self.options.auto_match_duration and self.options.short_source_policy == "loop":
            cmd += ["-stream_loop", "-1"]
        cmd += ["-i", source, "-map", "0:a:0", "-map_metadata", "-1"]
        if filters:
            cmd += ["-filter:a", ",".join(filters)]
        if self.options.auto_match_duration:
            cmd += ["-t", f"{output_duration:.9f}"]
        cmd += ["-vn", "-sn", "-dn", *sr_arg, *ch_arg, "-c:a", "pcm_s16le", matched]
        self.runner.run(cmd, timeout=self.options.tool_timeout)
        _require_file(matched, "matched WAV")

        if self.options.auto_match_duration:
            assert output_duration is not None
            # FFmpeg's PCM -t cutoff is sample-accurate. Re-probing the WAV and then
            # potentially launching another FFmpeg pass added 1-2 extra processes per
            # song without improving the final WEM validation, which already measures
            # the encoded result. Trust the requested sample boundary here and keep the
            # expensive verification at the WEM stage.

        if self.options.normalize_loudness:
            normalized = work_dir / "matched_normalized.wav"
            self._normalize_peak(matched, normalized, target_peak_db=-1.0)
            os.replace(normalized, matched)

        source_text = "unknown (fast path)" if source_duration is None else f"{float(source_duration):.6f}s"
        output_text = "source length" if output_duration is None else f"{float(output_duration):.6f}s"
        self.log.info(
            "Prepared %s in one FFmpeg pass | source %s | output %s | speed %.3fx | offset %.3fms | cutoff %s | codec threads 1",
            target.display_name, source_text, output_text, rate, offset_ms,
            "none" if cutoff_ms in (None, 0, 0.0) else f"{cutoff_ms:.3f}ms absolute",
        )
        return matched

    def _decode_and_combine(self, source: Path, target: WemInfo, work_dir: Path, extra_offset_ms: float = 0.0) -> Path:
        """Mix the original WEM underneath the replacement without forcing the replacement to target length.

        Combine mode is intentionally duration-preserving for the replacement source:
        - the original WEM contributes its natural duration;
        - the replacement keeps its full processed duration when no end cutoff is supplied;
        - an explicit end cutoff still clips the replacement source;
        - the final mix lasts for the longer active stream.

        This is different from normal replacement mode, where auto-match can intentionally
        trim/loop/pad a source to the original WEM duration.
        """
        if not self.tools.vgmstream:
            raise ToolNotFound("vgmstream-cli.exe is required for Combine mode")
        if not self.tools.ffmpeg:
            raise ToolNotFound("ffmpeg.exe is required for Combine mode")
        work_dir.mkdir(parents=True, exist_ok=True)
        target_duration = float(target.duration_seconds)
        if target_duration <= 0:
            raise RuntimeError(f"Target WEM {target.display_name} has no usable duration")
        if not target.file_path.is_file():
            raise FileNotFoundError(f"Original WEM is not available: {target.file_path}")

        # Decode the original and preserve the full original WEM duration.
        original_decoded = work_dir / "original_decoded.wav"
        result = self.runner.run(
            [self.tools.vgmstream, "-o", original_decoded, target.file_path],
            timeout=self.options.tool_timeout,
            check=False,
        )
        if result.returncode != 0 or not original_decoded.is_file() or original_decoded.stat().st_size < 44:
            detail = (result.stderr or result.stdout or "unknown vgmstream error").strip()
            raise RuntimeError(f"Could not decode original WEM {target.display_name}: {detail[-1600:]}")

        original_pcm = work_dir / "original_pcm.wav"
        self.runner.run(
            [
                self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
                "-i", original_decoded, "-vn",
                "-ar", str(target.sample_rate or 48000),
                "-ac", str(target.channels or 2),
                "-t", f"{target_duration:.9f}",
                "-c:a", "pcm_s16le", original_pcm,
            ],
            timeout=self.options.tool_timeout,
        )
        _require_file(original_pcm, "decoded original PCM")

        # Prepare the replacement at the target sample format, but DO NOT duration-match it.
        overlay = work_dir / "overlay_normalized.wav"
        rate = float(self.options.playback_rate or 1.0)
        if not math.isfinite(rate) or rate <= 0:
            raise ValueError("Playback speed must be greater than 0")
        sf: list[str] = []
        n = rate
        while n > 2.0 + 1e-9:
            sf.append("atempo=2.0")
            n /= 2.0
        while n < 0.5 - 1e-9:
            sf.append("atempo=0.5")
            n /= 0.5
        if abs(rate - 1.0) > 1e-6:
            sf.append(f"atempo={n:.6f}")

        self.runner.run(
            [
                self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
                "-i", source, "-vn",
                "-ar", str(target.sample_rate or 48000),
                "-ac", str(target.channels or 2),
                *( ["-filter:a", ",".join(sf)] if sf else [] ),
                "-c:a", "pcm_s16le", overlay,
            ],
            timeout=self.options.tool_timeout,
        )
        _require_file(overlay, "combined replacement WAV")

        overlay_src = overlay
        offset_ms = float(self.options.audio_offset_ms or 0.0) + float(extra_offset_ms or 0.0)
        if offset_ms < 0:
            raise ValueError("Audio start offset cannot be negative")
        cutoff_ms = self.options.source_end_ms
        if cutoff_ms is not None:
            cutoff_ms = float(cutoff_ms)
            if not math.isfinite(cutoff_ms) or cutoff_ms < 0:
                raise ValueError("Audio end cutoff must be 0 or greater")

        if offset_ms > 0.0001 or (cutoff_ms is not None and float(cutoff_ms) > 0.0001):
            overlay_src = work_dir / "overlay_offset.wav"
            offset_s = max(0.0, offset_ms / 1000.0)
            duration_limit: Optional[float] = None
            od = ffprobe_duration(self.runner, self.tools.ffprobe, overlay) if self.tools.ffprobe else self._ffmpeg_duration(overlay)
            cutoff_s = 0.0 if cutoff_ms is None else float(cutoff_ms) / 1000.0
            if cutoff_s > 0.000001:
                if cutoff_s > od:
                    cutoff_s = od
                if offset_s >= cutoff_s - 0.000001:
                    raise ValueError(
                        f"Replacement audio does not contain enough usable audio for the requested offset ({offset_ms:.3f} ms) and end cutoff ({cutoff_s * 1000.0:.3f} ms)."
                    )
                # End cutoff is an absolute source timestamp.
                duration_limit = cutoff_s - offset_s
            elif offset_s >= od - 0.000001:
                raise ValueError(
                    f"Replacement audio does not contain enough usable audio for the requested offset ({offset_ms:.3f} ms)."
                )
            args = [self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error"]
            args += ["-ss", f"{offset_s:.9f}", "-i", overlay]
            if duration_limit is not None:
                args += ["-t", f"{duration_limit:.9f}"]
            args += ["-c:a", "pcm_s16le", overlay_src]
            self.runner.run(args, timeout=self.options.tool_timeout)
            _require_file(overlay_src, "offset/cutoff replacement WAV")

        # Combine mode never uses the original WEM duration as a clipping limit.
        # A replacement shorter than the original is allowed to remain short; the original
        # continues underneath it. A replacement longer than the original remains fully intact.
        overlay_match = work_dir / "overlay_matched.wav"
        self.runner.run(
            [
                self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
                "-i", overlay_src,
                "-c:a", "pcm_s16le", overlay_match,
            ],
            timeout=self.options.tool_timeout,
        )
        _require_file(overlay_match, "combined overlay WAV")

        overlay_duration = ffprobe_duration(self.runner, self.tools.ffprobe, overlay_match) if self.tools.ffprobe else self._ffmpeg_duration(overlay_match)
        if overlay_duration <= 0.000001:
            raise RuntimeError("The replacement overlay produced no usable audio")

        fx: list[str] = []
        gain = float(self.options.overlay_gain_db or self.options.volume_db or 0.0)
        if abs(gain) > 0.001:
            fx.append(f"volume={gain:.3f}dB")
        fi = max(0.0, float(self.options.fade_in_ms or 0) / 1000.0)
        fo = max(0.0, float(self.options.fade_out_ms or 0) / 1000.0)
        if fi > 0:
            fi = min(fi, overlay_duration)
            fx.append(f"afade=t=in:st=0:d={fi:.6f}")
        if fo > 0:
            fo = min(fo, overlay_duration / 2.0)
            fx.append(f"afade=t=out:st={max(0.0, overlay_duration - fo):.6f}:d={fo:.6f}")
        if fx:
            effected = work_dir / "overlay_effects.wav"
            self.runner.run(
                [
                    self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
                    "-i", overlay_match, "-filter:a", ",".join(fx),
                    "-c:a", "pcm_s16le", effected,
                ],
                timeout=self.options.tool_timeout,
            )
            overlay_match = effected
            overlay_duration = ffprobe_duration(self.runner, self.tools.ffprobe, overlay_match) if self.tools.ffprobe else self._ffmpeg_duration(overlay_match)

        if self.options.normalize_loudness:
            normalized = work_dir / "overlay_normalized_safe.wav"
            self._normalize_peak(overlay_match, normalized, target_peak_db=-1.0)
            overlay_match = normalized

        # duration=longest is deliberate and there is NO atrim/-t here.
        # Thus a 5-second replacement over a 1.5-second original produces ~5 seconds.
        combined = work_dir / "matched.wav"
        self.runner.run(
            [
                self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
                "-i", original_pcm,
                "-i", overlay_match,
                "-filter_complex",
                "[0:a][1:a]amix=inputs=2:duration=longest:dropout_transition=0:normalize=1",
                "-ar", str(target.sample_rate or 48000),
                "-ac", str(target.channels or 2),
                "-c:a", "pcm_s16le", combined,
            ],
            timeout=self.options.tool_timeout,
        )
        _require_file(combined, "combined WAV")
        actual = ffprobe_duration(self.runner, self.tools.ffprobe, combined) if self.tools.ffprobe else self._ffmpeg_duration(combined)
        if actual <= 0.000001:
            raise RuntimeError("Combined audio produced no usable duration")
        self.log.info(
            "Combined original WEM + full replacement for %s | original %.6fs | overlay %.6fs | result %.6fs | overlay gain %.3f dB | speed %.3fx",
            target.display_name, target_duration, overlay_duration, actual, gain, rate,
        )
        return combined

    def _normalize_peak(self, wav: Path, output: Path, target_peak_db: float = -1.0) -> None:
        result = self.runner.run([
            self.tools.ffmpeg, "-hide_banner", "-nostats", "-i", wav,
            "-filter:a", "volumedetect", "-f", "null", os.devnull
        ], timeout=self.options.tool_timeout, check=False)
        text = ((result.stderr or "") + "\n" + (result.stdout or ""))
        match = re.search(r"max_volume:\s*([-+]?\d+(?:\.\d+)?)\s*dB", text, re.IGNORECASE)
        if result.returncode != 0 or not match:
            self.log.warning("Could not measure audio level for normalization; leaving audio unchanged: %s", wav)
            shutil.copy2(wav, output)
            return
        try:
            max_db = float(match.group(1))
        except (TypeError, ValueError):
            max_db = float("nan")
        if not math.isfinite(max_db):
            self.log.warning("Audio level measurement was invalid; leaving audio unchanged: %s", wav)
            shutil.copy2(wav, output)
            return
        gain_db = float(target_peak_db) - max_db
        if abs(gain_db) < 0.05:
            shutil.copy2(wav, output)
            return
        self.runner.run([
            self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
            "-i", wav, "-filter:a", f"volume={gain_db:.3f}dB",
            "-c:a", "pcm_s16le", output
        ], timeout=self.options.tool_timeout)

    def _force_exact(self, wav: Path, duration: float) -> None:
        tmp = wav.with_suffix(".exact.wav")
        self.runner.run([
            self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error",
            "-i", wav, "-t", f"{duration:.9f}", "-c:a", "pcm_s16le", tmp
        ], timeout=self.options.tool_timeout)
        os.replace(tmp, wav)

    def _ffmpeg_duration(self, source: Path) -> float:

        result = self.runner.run([
            self.tools.ffmpeg, "-hide_banner", "-i", source
        ], timeout=60, check=False)
        text = result.stderr or result.stdout
        m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", text)
        if not m:
            raise RuntimeError(f"Could not determine duration with FFmpeg for {source}")
        return int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))

class WwiseEncoder:
    def __init__(self, tools: ToolPaths, runner: Runner, root: Path,
                 logger: logging.Logger, options: ProcessOptions) -> None:
        self.tools = tools
        self.runner = runner
        self.root = root
        self.log = logger
        self.options = options

    def encode(self, matched_wav: Path, wem_name: str, output_dir: Path) -> Path:
        if not self.tools.wwise_console:
            raise ToolNotFound("WwiseConsole.exe was not found")
        output_dir.mkdir(parents=True, exist_ok=True)

        project_dir = output_dir / "AudioConversion"
        project = project_dir / "AudioConversion.wproj"
        self._ensure_project(output_dir, project_dir, project)
        wsources = project_dir / "sources.wsources"
        xml_root = matched_wav.parent.as_posix()

        import xml.sax.saxutils as saxutils
        root_attr = saxutils.quoteattr(xml_root)
        src_attr = saxutils.quoteattr(matched_wav.name)
        conv_attr = saxutils.quoteattr(self.options.conversion_preset)
        wsources.write_text(
            '<?xml version="1.0" encoding="utf-8"?>\n'
            f'<ExternalSourcesList SchemaVersion="1" Root={root_attr}>\n'
            f'  <Source Path={src_attr} Conversion={conv_attr}/>'
            '\n</ExternalSourcesList>\n', encoding="utf-8")
        raw_out = output_dir / "wwise_out"

        if raw_out.exists():
            shutil.rmtree(raw_out, ignore_errors=True)
        raw_out.mkdir(parents=True, exist_ok=True)

        command = [
            self.tools.wwise_console, "convert-external-source", project,
            "--source-file", wsources, "--output", raw_out, "--quiet"
        ]
        with _WWISE_CONSOLE_LOCK:
            last_failure: Optional[BaseException] = None
            for attempt in range(1, 4):
                if attempt > 1:
                    with contextlib.suppress(OSError):
                        if raw_out.exists():
                            shutil.rmtree(raw_out, ignore_errors=True)
                    raw_out.mkdir(parents=True, exist_ok=True)
                    time.sleep(0.75 * (attempt - 1))
                try:
                    result = self.runner.run(
                        command, cwd=output_dir, timeout=self.options.tool_timeout, check=False
                    )
                except BaseException as exc:
                    last_failure = exc
                    if attempt < 3:
                        self.log.warning("Wwise conversion attempt %d failed; retrying: %s", attempt, exc)
                        continue
                    raise
                if result.returncode == 0:
                    break
                detail = ((result.stdout or "") + "\n" + (result.stderr or "")).strip()
                transient = (
                    "LMDB_CommitFailed" in detail
                    or "LMDB::Commit" in detail
                    or result.returncode in (0xC0000006, -1073741818)
                )
                failure = ToolExecutionError(self.tools.wwise_console, command, result.returncode, result.stdout, result.stderr)
                if transient and attempt < 3:
                    self.log.warning("Wwise conversion attempt %d hit a transient LMDB/I/O failure; retrying", attempt)
                    last_failure = failure
                    continue
                raise failure
            else:
                if last_failure is not None:
                    raise last_failure
        wem_candidates = list(raw_out.rglob("*.wem"))
        if not wem_candidates:
            raise RuntimeError("WwiseConsole completed but no .wem file was produced")

        same = [p for p in wem_candidates if p.stem.lower() == matched_wav.stem.lower()]
        chosen = sorted(same or wem_candidates, key=lambda p: p.stat().st_mtime, reverse=True)[0]
        final_wem = output_dir / wem_name
        shutil.copy2(chosen, final_wem)
        if not final_wem.is_file() or final_wem.stat().st_size < 16:
            raise RuntimeError(f"Encoded WEM is missing or invalid: {final_wem}")
        return final_wem

    def encode_many(self, jobs: Sequence[tuple[Path, str, Path]], batch_dir: Path) -> dict[str, Path]:
        """Encode several prepared WAVs with ONE WwiseConsole transaction."""
        if not jobs:
            return {}
        if not self.tools.wwise_console:
            raise ToolNotFound("WwiseConsole.exe was not found")

        batch_dir = Path(batch_dir)
        batch_dir.mkdir(parents=True, exist_ok=True)
        project_dir = batch_dir / "AudioConversion"
        project = project_dir / "AudioConversion.wproj"
        self._ensure_project(batch_dir, project_dir, project)

        source_root = batch_dir / "sources"
        raw_out = batch_dir / "wwise_out"
        shutil.rmtree(source_root, ignore_errors=True)
        shutil.rmtree(raw_out, ignore_errors=True)
        source_root.mkdir(parents=True, exist_ok=True)
        raw_out.mkdir(parents=True, exist_ok=True)

        import xml.sax.saxutils as saxutils
        conversion = saxutils.quoteattr(self.options.conversion_preset)
        entries: list[str] = [
            '<?xml version="1.0" encoding="utf-8"?>',
            f'<ExternalSourcesList SchemaVersion="1" Root={saxutils.quoteattr(source_root.as_posix())}>',
        ]
        seen_stems: set[str] = set()
        jobs_with_sources: list[tuple[Path, str, Path, str]] = []

        for index, (matched_wav, wem_name, destination_dir) in enumerate(jobs, 1):
            target_stem = Path(wem_name).stem
            source_name = f"{target_stem}.wav"
            if source_name.lower() in seen_stems:
                source_name = f"{target_stem}_{index:03d}.wav"
            seen_stems.add(source_name.lower())
            src = source_root / source_name
            try:
                os.link(matched_wav, src)
            except OSError:
                shutil.copy2(matched_wav, src)
            entries.append(
                f'  <Source Path={saxutils.quoteattr(source_name)} Conversion={conversion}/>'
            )
            jobs_with_sources.append((matched_wav, wem_name, Path(destination_dir), source_name))

        entries.append("</ExternalSourcesList>")
        wsources = project_dir / "sources.wsources"
        wsources.write_text("\n".join(entries) + "\n", encoding="utf-8")

        command = [
            self.tools.wwise_console, "convert-external-source", project,
            "--source-file", wsources, "--output", raw_out, "--quiet"
        ]
        self.log.info("Encoding %d WEMs in one WwiseConsole transaction…", len(jobs))
        with _WWISE_CONSOLE_LOCK:
            last_failure: Optional[BaseException] = None
            for attempt in range(1, 4):
                if attempt > 1:
                    shutil.rmtree(raw_out, ignore_errors=True)
                    raw_out.mkdir(parents=True, exist_ok=True)
                    time.sleep(0.75 * (attempt - 1))
                try:
                    result = self.runner.run(
                        command, cwd=batch_dir, timeout=self.options.tool_timeout, check=False
                    )
                except BaseException as exc:
                    last_failure = exc
                    if attempt < 3:
                        self.log.warning("Batched Wwise conversion attempt %d failed; retrying: %s", attempt, exc)
                        continue
                    raise
                if result.returncode == 0:
                    break
                detail = ((result.stdout or "") + "\n" + (result.stderr or "")).strip()
                transient = (
                    "LMDB_CommitFailed" in detail
                    or "LMDB::Commit" in detail
                    or result.returncode in (0xC0000006, -1073741818)
                )
                failure = ToolExecutionError(
                    self.tools.wwise_console, command, result.returncode, result.stdout, result.stderr
                )
                if transient and attempt < 3:
                    self.log.warning("Batched Wwise conversion attempt %d hit transient LMDB/I/O failure; retrying", attempt)
                    last_failure = failure
                    continue
                raise failure
            else:
                if last_failure is not None:
                    raise last_failure

        candidates = [p for p in raw_out.rglob("*.wem") if p.is_file()]
        by_stem = {p.stem.lower(): p for p in candidates}
        results: dict[str, Path] = {}
        for _matched_wav, wem_name, destination_dir, source_name in jobs_with_sources:
            candidate = by_stem.get(Path(source_name).stem.lower())
            if candidate is None:
                # Fallback for Wwise variants that rename to the requested target stem.
                candidate = by_stem.get(Path(wem_name).stem.lower())
            if candidate is None:
                raise RuntimeError(f"WwiseConsole produced no WEM for {source_name}")
            final_wem = destination_dir / wem_name
            final_wem.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(candidate, final_wem)
            if not final_wem.is_file() or final_wem.stat().st_size < 16:
                raise RuntimeError(f"Encoded WEM is missing or invalid: {final_wem}")
            results[wem_name] = final_wem.resolve()

        self.log.info("Batched Wwise encoding complete: %d WEM(s)", len(results))
        return results

    def _ensure_project(self, workspace_dir: Path, project_dir: Path, project: Path) -> None:
        if project.exists():
            return

        workspace_dir.mkdir(parents=True, exist_ok=True)
        relative_project = Path(project_dir.name) / project.name
        command = [
            self.tools.wwise_console, "create-new-project", relative_project
        ]
        result = self.runner.run(
            command, cwd=workspace_dir, timeout=180, check=False
        )
        if result.returncode != 0 and not project.exists():
            raise ToolExecutionError(
                self.tools.wwise_console,
                [self.tools.wwise_console, "create-new-project", os.fspath(relative_project)],
                result.returncode, result.stdout, result.stderr
            )
        if not project.exists():
            raise RuntimeError(
                "WwiseConsole did not create the expected project. "
                f"Expected: {project}\n"
                f"Output: {(result.stdout or '').strip()}\n"
                f"Error: {(result.stderr or '').strip()}"
            )

class ArtifactStore:
    def __init__(self, paths: KitPaths, run_id: str, logger: logging.Logger) -> None:
        self.paths = paths
        self.run_id = run_id
        self.log = logger
        self.backup_retention = 1
        self.root = paths.processed_audio / "runs" / run_id
        self.root.mkdir(parents=True, exist_ok=True)

    def bank_stage(self, bank: Path) -> Path:
        d = self.root / safe_name(bank.stem)
        d.mkdir(parents=True, exist_ok=True)
        return d

    def backup_bank(self, bank: Path) -> Path:
        originals = self.root / "originals"
        originals.mkdir(parents=True, exist_ok=True)
        dest = originals / f"{safe_name(bank.stem)}{bank.suffix}"
        shutil.copy2(bank, dest)
        self.log.info("Temporary safety copy created: %s", dest)
        return dest

    def cleanup(self) -> None:

        if self.root.exists():
            shutil.rmtree(self.root, ignore_errors=True)

    def atomic_publish(self, source: Path, destination: Path) -> None:

        destination.parent.mkdir(parents=True, exist_ok=True)
        temp = destination.with_name(destination.name + f".{self.run_id}.tmp")
        try:
            if temp.exists():
                temp.unlink()
            shutil.copy2(source, temp)
            try:
                with open(temp, "r+b") as fh:
                    fh.flush()
                    try:
                        os.fsync(fh.fileno())
                    except OSError as sync_exc:
                        self.log.debug("Filesystem sync warning for %s: %s", temp, sync_exc)
            except OSError as handle_exc:

                self.log.debug("Could not reopen temporary output read/write: %s", handle_exc)
            os.replace(temp, destination)
        except Exception:
            with contextlib.suppress(OSError):
                temp.unlink()
            raise

    def write_json(self, name: str, payload: Any) -> Path:
        path = self.root / safe_name(name)
        if path.suffix.lower() != ".json":
            path = path.with_suffix(".json")
        path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
        return path

@dataclasses.dataclass(slots=True)
class BankMediaEntry:
    index: int
    media_id: int
    offset: int
    length: int
    padding: int
    loop_value: int = -1

@dataclasses.dataclass(slots=True)
class BankSnapshot:
    path: Path
    size: int
    bkhd_length: int
    bkhd_version: int
    bkhd_id: int
    data_payload_offset: int
    data_payload_size: int
    media: list[BankMediaEntry]

def _read_u32(data: bytes, offset: int) -> int:
    if offset < 0 or offset + 4 > len(data):
        raise ValueError(f"Unexpected end of binary data at offset {offset}")
    return struct.unpack_from("<I", data, offset)[0]

def _read_i32(data: bytes, offset: int) -> int:
    if offset < 0 or offset + 4 > len(data):
        raise ValueError(f"Unexpected end of binary data at offset {offset}")
    return struct.unpack_from("<i", data, offset)[0]

def parse_bnk_snapshot(bank: Path) -> BankSnapshot:

    raw = Path(bank).read_bytes()
    if len(raw) < 40:
        raise RuntimeError(f"BNK is too small to be valid: {bank}")
    def _chunk_id_at(offset: int) -> str:
        if offset < 0 or offset + 4 > len(raw):
            return ""
        return raw[offset:offset + 4].decode("ascii", errors="replace")

    chunks: dict[str, tuple[int, int]] = {}
    order: list[str] = []
    pos = 0
    seen_offsets: set[int] = set()
    while pos + 8 <= len(raw):
        if pos in seen_offsets:
            raise RuntimeError(f"BNK parser made no progress at offset {pos}")
        seen_offsets.add(pos)
        name = _chunk_id_at(pos)
        length = _read_u32(raw, pos + 4)
        payload_start = pos + 8
        payload_end = payload_start + length
        if payload_end > len(raw):
            raise RuntimeError(
                f"BNK chunk {name!r} runs beyond EOF: end={payload_end}, size={len(raw)}"
            )
        chunks[name] = (payload_start, length)
        order.append(name)

        next_no_pad = payload_end
        next_pad = payload_end + 1
        id_no_pad = _chunk_id_at(next_no_pad)
        id_pad = _chunk_id_at(next_pad)
        def plausible_chunk_id(chunk_id: str) -> bool:
            return len(chunk_id) == 4 and all(("A" <= c <= "Z") or ("0" <= c <= "9") or c in " ?_" for c in chunk_id)

        if next_no_pad + 8 <= len(raw) and plausible_chunk_id(id_no_pad):
            pos = next_no_pad
        elif next_pad + 8 <= len(raw) and plausible_chunk_id(id_pad):
            pos = next_pad
        else:

            pos = next_no_pad
            if pos >= len(raw):
                break
    for required in ("BKHD", "DIDX", "DATA"):
        if required not in chunks:
            raise RuntimeError(f"BNK is missing required {required} chunk: {bank}")

    bkhd_start, bkhd_len = chunks["BKHD"]
    if bkhd_len < 8:
        raise RuntimeError("BKHD chunk is too short")
    bkhd_version = _read_u32(raw, bkhd_start)
    bkhd_id = _read_u32(raw, bkhd_start + 4)

    didx_start, didx_len = chunks["DIDX"]
    if didx_len % 12 != 0:
        raise RuntimeError(f"DIDX length {didx_len} is not divisible by 12")
    count = didx_len // 12
    data_start, data_len = chunks["DATA"]
    media: list[BankMediaEntry] = []
    ranges: list[tuple[int, int, int]] = []
    for index in range(1, count + 1):
        base = didx_start + (index - 1) * 12
        media_id = _read_u32(raw, base)
        offset = _read_u32(raw, base + 4)
        length = _read_u32(raw, base + 8)
        if offset + length > data_len:
            raise RuntimeError(
                f"DIDX media {index} exceeds DATA: offset={offset} length={length} data={data_len}"
            )
        if length < 12:
            raise RuntimeError(f"DIDX media {index} is implausibly short: {length} bytes")
        media.append(BankMediaEntry(index, media_id, offset, length, 0, -1))
        ranges.append((offset, offset + length, index))
    ranges.sort()
    for previous, current in zip(ranges, ranges[1:], strict=False):
        if current[0] < previous[1]:
            raise RuntimeError(
                f"DIDX media overlap: WEM {previous[2]} ends at {previous[1]}, "
                f"WEM {current[2]} starts at {current[0]}"
            )

    return BankSnapshot(
        path=Path(bank),
        size=len(raw),
        bkhd_length=bkhd_len,
        bkhd_version=bkhd_version,
        bkhd_id=bkhd_id,
        data_payload_offset=data_start,
        data_payload_size=data_len,
        media=media,
    )

def extract_embedded_wems_from_snapshot(snapshot: BankSnapshot) -> dict[int, bytes]:
    raw = snapshot.path.read_bytes()
    result: dict[int, bytes] = {}
    for entry in snapshot.media:
        start = snapshot.data_payload_offset + entry.offset
        result[entry.index] = raw[start:start + entry.length]
    return result

def wem_header_signature(wem_bytes: bytes) -> dict[str, Any]:

    if len(wem_bytes) < 20 or wem_bytes[:4] != b"RIFF" or wem_bytes[8:12] != b"WAVE":
        raise RuntimeError("Replacement media is not a RIFF/WAVE WEM")
    pos = 12
    fmt: Optional[bytes] = None
    data_len: Optional[int] = None
    while pos + 8 <= len(wem_bytes):
        cid = wem_bytes[pos:pos + 4]
        clen = _read_u32(wem_bytes, pos + 4)
        start = pos + 8
        end = start + clen
        if end > len(wem_bytes):
            # Some Wwise-generated WEMs have a stale data-chunk length field even though
            # the physical payload is complete and vgmstream can decode it. Treat the
            # remaining bytes as the data payload; keep strict behavior for structural chunks.
            if cid == b"data" and start < len(wem_bytes):
                data_len = len(wem_bytes) - start
                break
            raise RuntimeError("WEM chunk extends beyond file boundary")
        if cid == b"fmt ":
            fmt = wem_bytes[start:end]
        elif cid == b"data":
            data_len = clen
        pos = end + (clen & 1)
    if fmt is None or len(fmt) < 16:
        raise RuntimeError("WEM is missing a usable fmt chunk")
    format_tag, channels, sample_rate = struct.unpack_from("<HHI", fmt, 0)
    return {
        "format_tag": format_tag,
        "channels": channels,
        "sample_rate": sample_rate,
        "fmt_length": len(fmt),
        "data_length": data_len or 0,
        "size": len(wem_bytes),
    }

def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

class BNKReplacer:
    def __init__(self, paths: KitPaths, tools: ToolPaths, options: ProcessOptions,
                 logger: logging.Logger, bus: EventBus,
                 cancel_event: Optional[threading.Event] = None,
                 progress_callback: Optional[Callable[[str, int, int], None]] = None) -> None:
        self.paths = paths
        self.tools = tools
        self.options = options
        self.log = logger
        self.bus = bus
        self.cancel_event = cancel_event
        self.progress_callback = progress_callback
        self._progress_done = 0
        self._progress_total = 0
        self.runner = Runner(logger, bus, cancel_event=cancel_event)
        if not tools.wwiseutil:
            raise ToolNotFound("wwiseutil.exe not found")
        self.wwiseutil = WwiseUtilAdapter(tools.wwiseutil, self.runner, logger)
        self.source_manager = SourceManager(tools, self.runner, paths, logger, options)
        self.audio = AudioProcessor(tools, self.runner, logger, options)
        self.encoder = WwiseEncoder(tools, self.runner, paths.root, logger, options)
        self._run_source_cache: dict[str, Path] = {}
        self._run_source_cache_dir: Optional[Path] = None

    def _live_game_target(self, source_path: Path) -> Path:
        """Return the live-game path while preserving the source BNK/WEM subdirectory."""
        root = self.options.game_audio_dir.resolve()
        source = source_path.resolve()
        try:
            relative = source.relative_to(root)
        except ValueError:
            # For files selected from elsewhere, keep the existing fallback behavior.
            relative = Path(source.name)
        return root / relative

    def _cancelled(self) -> bool:
        return self.cancel_event is not None and self.cancel_event.is_set()

    def _check_cancel(self) -> None:
        if self._cancelled():
            raise ProcessingCancelled("Replacement cancelled by the user")

    def _ensure_vgmstream_ready(self) -> Path:
        """Return a working vgmstream executable, repairing a broken bundled copy automatically."""
        current = self.tools.vgmstream
        if current:
            ok, _detail = _vgmstream_health_check(current)
            if ok:
                return Path(current)

        with _VGMSTREAM_REPAIR_LOCK:
            # Another load thread may already have repaired it.
            current = self.tools.vgmstream
            if current:
                ok, _detail = _vgmstream_health_check(current)
                if ok:
                    return Path(current)

            discovered = ToolLocator(self.paths).locate().vgmstream
            if discovered:
                ok, _detail = _vgmstream_health_check(discovered)
                if ok:
                    self.tools.vgmstream = discovered
                    self.log.info("Using launch-tested vgmstream: %s", discovered)
                    return discovered

            self.log.warning(
                "The configured vgmstream executable is unavailable or broken; "
                "downloading a clean copy…"
            )
            try:
                repaired = DependencyInstaller(self.paths, self.log)._install_vgmstream()
            except Exception as exc:
                raise RuntimeError(
                    "vgmstream-cli.exe is broken and automatic repair failed.\n\n"
                    f"{exc}"
                ) from exc

            ok, detail = _vgmstream_health_check(repaired)
            if not ok:
                raise RuntimeError(
                    "vgmstream-cli.exe was reinstalled, but Windows still could not start it.\n\n"
                    + detail
                )
            self.tools.vgmstream = repaired
            self.log.info("Repaired vgmstream successfully: %s", repaired)
            return repaired

    def _emit_progress(self, label: str) -> None:
        if self.progress_callback is None:
            return
        try:
            with getattr(self, "_progress_lock", contextlib.nullcontext()):
                self.progress_callback(label, self._progress_done, self._progress_total)
        except Exception:
            pass

    def inspect_bank(
        self, bank: Path, progress_callback: Optional[Callable[[int, int, Path], None]] = None
    ) -> list[WemInfo]:
        """Load a BNK's WEM metadata using disposable temporary staging.

        This internal step exists only to populate the app's sound list. No
        extracted WEMs live only in the OS temporary directory while the bank is loaded.
        """
        bank = bank.resolve()
        if not bank.is_file():
            raise FileNotFoundError(bank)
        stage = Path(tempfile.mkdtemp(prefix="cutie_sumo_bnk_"))
        _LIVE_BNK_STAGING_DIRS.add(stage)
        try:
            vgmstream = self._ensure_vgmstream_ready()
            wem_files = self.wwiseutil.unpack(bank, stage, allow_empty=True)
            if not wem_files:
                _LIVE_BNK_STAGING_DIRS.discard(stage)
                with contextlib.suppress(OSError):
                    shutil.rmtree(stage, ignore_errors=True)
                return []
            # Keep this disposable OS-temp staging alive for as long as the loaded
            # bank is visible. Preview reads the extracted WEM files directly.
            # It must not use TemporaryDirectory here because that would delete the
            # WEMs before the GUI has finished using them.
            return make_wem_info_list(
                self.runner, vgmstream, bank, wem_files, self.options.tool_timeout,
                progress_callback=progress_callback,
            )
        except Exception:
            _LIVE_BNK_STAGING_DIRS.discard(stage)
            with contextlib.suppress(OSError):
                shutil.rmtree(stage, ignore_errors=True)
            raise

    def process(self, selections: list[Selection], output_dir: Optional[Path] = None) -> list[JobRecord]:
        if not selections:
            raise ValueError("No WEM selections supplied")
        run_id = timestamp() + "_" + uuid.uuid4().hex[:6]
        self.paths.ensure()
        store = ArtifactStore(self.paths, run_id, self.log)
        store.backup_retention = max(0, int(self.options.backup_retention))
        self._run_source_cache.clear()
        self._run_source_cache_dir = self.paths.wems / "source_cache" / run_id
        self._run_source_cache_dir.mkdir(parents=True, exist_ok=True)
        grouped: dict[Path, list[Selection]] = {}
        for sel in selections:
            grouped.setdefault(sel.wem.bank_path.resolve(), []).append(sel)
        self._progress_total = len(selections)
        self._progress_done = 0
        self._progress_lock = threading.Lock()
        self._emit_progress("Warming up the cute little mixer… ♪")
        records: list[JobRecord] = []
        try:
            bank_items = list(grouped.items())
            # FFmpeg preparation uses one codec thread per process. Give a single-bank
            # run enough parallel workers to use modern CPUs, but split the same total
            # budget across banks so multi-bank runs do not oversubscribe the machine.
            prep_budget = min(16, max(8, (os.cpu_count() or 8)))
            self._prep_worker_budget = prep_budget
            self._prep_bank_count = max(1, len(bank_items))
            cpu_workers = max(4, min(8, (os.cpu_count() or 4)))
            max_workers = min(cpu_workers, len(bank_items)) if len(bank_items) > 1 else 1
            if max_workers > 1:
                self.log.info("Processing %d banks in parallel with %d workers", len(bank_items), max_workers)
                with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix="bnkproc") as executor:
                    future_to_bank = {
                        executor.submit(self._process_one_bank, store, bank, bank_selections, output_dir): bank
                        for bank, bank_selections in bank_items
                    }
                    for future in concurrent.futures.as_completed(future_to_bank):
                        bank = future_to_bank[future]
                        if self._cancelled():
                            self.log.info("Cancellation requested; cancelling remaining banks")
                            for f in future_to_bank:
                                f.cancel()
                            break
                        try:
                            rec = future.result()
                        except Exception as exc:
                            self.log.error("Bank %s failed: %s", bank.name, exc)
                            rec = JobRecord(
                                run_id=store.run_id,
                                status="failed",
                                started_at=_dt.datetime.now().isoformat(timespec="seconds"),
                                source_bank=str(bank),
                                output_bank="",
                                replacements=len(grouped[bank]),
                                messages=[str(exc), traceback.format_exc()],
                            )
                        records.append(rec)
                        with contextlib.suppress(OSError):
                            shutil.rmtree(store.root / safe_name(bank.stem), ignore_errors=True)
                        if rec.status == "cancelled":
                            for f in future_to_bank:
                                f.cancel()
                            break
            else:
                for bank, bank_selections in bank_items:
                    if self._cancelled():
                        self.log.info("Cancellation requested; stopping before %s", bank.name)
                        break
                    rec = self._process_one_bank(store, bank, bank_selections, output_dir)
                    records.append(rec)
                    with contextlib.suppress(OSError):
                        shutil.rmtree(store.root / safe_name(bank.stem), ignore_errors=True)
                    if rec.status == "cancelled":
                        break
            # Only install runs keep persistent backups; export run paths live in the
            # temporary run workspace and would leave Undo pointing at deleted files.
            if self.options.install_to_game:
                successful = [r for r in records if r.status == "success" and r.backup_path and r.installed_path]
                if successful:
                    journal = self.paths.processed_audio / "last_run.json"
                    payload = {
                        "run_id": run_id,
                        "created_at": _dt.datetime.now().isoformat(timespec="seconds"),
                        "entries": [
                            {
                                "installed_path": r.installed_path,
                                "backup_path": r.backup_path,
                                "installed_sha256": r.installed_sha256,
                                "source_bank": r.source_bank,
                            }
                            for r in successful
                        ],
                    }
                    tmp = journal.with_suffix(".json.tmp")
                    tmp.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
                    tmp.replace(journal)
            UndoManager(self.paths, self.log).prune()
            return records
        finally:
            store.cleanup()
            runs_root = self.paths.processed_audio / "runs"
            if runs_root.is_dir():
                for stale in runs_root.iterdir():
                    if stale.is_dir() and stale.name != run_id:
                        with contextlib.suppress(OSError):
                            shutil.rmtree(stale, ignore_errors=True)
            self.paths.cleanup_generated_bank_artifacts()
            if self._run_source_cache_dir is not None:
                with contextlib.suppress(OSError):
                    shutil.rmtree(self._run_source_cache_dir, ignore_errors=True)
            self._run_source_cache.clear()
            self._run_source_cache_dir = None
            with contextlib.suppress(Exception):
                delattr(self, "_prep_worker_budget")
            with contextlib.suppress(Exception):
                delattr(self, "_prep_bank_count")

    def _process_one_bank(self, store: ArtifactStore, bank: Path, selections: list[Selection], output_dir: Optional[Path]) -> JobRecord:
        rec = JobRecord(
            run_id=store.run_id,
            status="running",
            started_at=_dt.datetime.now().isoformat(timespec="seconds"),
            source_bank=str(bank),
            output_bank="",
            replacements=len(selections),
        )
        stage = store.bank_stage(bank)
        try:

            # Capture the true pre-install fingerprint for the automatic TXT reconstruction recipe.
            rec.original_sha256 = sha256_file(bank)
            game_target_for_backup = self._live_game_target(bank)
            backup_source = game_target_for_backup if self.options.install_to_game and game_target_for_backup.is_file() else bank
            if self.options.backup_inputs and not self.options.install_to_game and backup_source.is_file():
                backup = store.backup_bank(backup_source)
                rec.backup_path = str(backup)
            original_snapshot = parse_bnk_snapshot(bank)

            inspected_dirs = {sel.wem.file_path.parent.resolve() for sel in selections if sel.wem.file_path.is_file()}
            cached_extract: Optional[Path] = None
            if len(inspected_dirs) == 1:
                candidate = next(iter(inspected_dirs))
                candidate_wems = sorted(candidate.glob("*.wem"), key=lambda p: p.name.lower())
                if candidate_wems:
                    cached_extract = candidate

            if cached_extract is not None:
                extract_dir = cached_extract
                self.log.info("Reusing already-loaded WEM extraction for %s: %s", bank.name, extract_dir)
                wem_files = sorted(extract_dir.glob("*.wem"), key=lambda p: p.name.lower())
            else:

                extract_dir = stage / "extracted"
                wem_files = self.wwiseutil.unpack(bank, extract_dir)

            wem_map: dict[int, Path] = {}
            for i, path in enumerate(wem_files, 1):
                key = int(path.stem) if path.stem.isdigit() else i
                wem_map[key] = path
            if not wem_map:
                raise RuntimeError("No WEM files found after extraction")

            replacement_dir = stage / "replacement_wems"
            if replacement_dir.exists():
                shutil.rmtree(replacement_dir, ignore_errors=True)
            shutil.copytree(extract_dir, replacement_dir)

            def prepare_selection_job(position: int, sel: Selection) -> tuple[Selection, dict[str, Any]]:
                self._check_cancel()
                target = sel.wem
                target_file = replacement_dir / target.file_path.name
                if not target_file.exists():
                    raise FileNotFoundError(f"Target WEM is not present in staging: {target_file}")
                self._emit_progress(f"Preparing {position}/{len(selections)}: {target.display_name} — FFmpeg…")
                repl_info = self._process_selection(
                    store, bank, target, sel, stage, position, encode_wem=False
                )
                return sel, repl_info

            prepared_results: list[tuple[Selection, dict[str, Any]]] = []
            prep_budget = max(1, int(getattr(self, "_prep_worker_budget", self.options.max_workers or 8)))
            prep_bank_count = max(1, int(getattr(self, "_prep_bank_count", 1)))
            per_bank_budget = max(1, prep_budget // prep_bank_count)
            configured_limit = max(1, int(self.options.max_workers or prep_budget))
            selection_workers = max(1, min(configured_limit, per_bank_budget, len(selections), 16))
            self.log.info(
                "Preparing %d WEMs in %d parallel FFmpeg worker(s) before one batched Wwise conversion for %s",
                len(selections), selection_workers, bank.name
            )

            if selection_workers == 1:
                prepared_results = [prepare_selection_job(position, sel) for position, sel in enumerate(selections, 1)]
            else:
                with concurrent.futures.ThreadPoolExecutor(
                    max_workers=selection_workers, thread_name_prefix="wemprep"
                ) as executor:
                    future_map = {
                        executor.submit(prepare_selection_job, position, sel): sel
                        for position, sel in enumerate(selections, 1)
                    }
                    first_error: Optional[BaseException] = None
                    for future in concurrent.futures.as_completed(future_map):
                        if self._cancelled():
                            for pending in future_map:
                                pending.cancel()
                            break
                        try:
                            prepared_results.append(future.result())
                        except BaseException as exc:
                            if first_error is None:
                                first_error = exc
                            self.log.error("WEM preparation failed in %s: %s", bank.name, exc)
                    if first_error is not None:
                        raise first_error
                order = {id(sel): pos for pos, sel in enumerate(selections)}
                prepared_results.sort(key=lambda item: order[id(item[0])])

            self._check_cancel()

            batch_jobs: list[tuple[Path, str, Path]] = []
            for sel, repl_info in prepared_results:
                matched_wav = Path(repl_info["matched_wav"])
                if not matched_wav.is_file():
                    raise FileNotFoundError(f"Prepared WAV is missing: {matched_wav}")
                batch_jobs.append((
                    matched_wav,
                    sel.wem.file_path.name,
                    matched_wav.parent.parent / "wem",
                ))

            encoded_map = self.encoder.encode_many(batch_jobs, stage / "batched_wwise")

            for sel, repl_info in prepared_results:
                target = sel.wem
                target_file = replacement_dir / target.file_path.name
                encoded_wem = encoded_map.get(target.file_path.name)
                if encoded_wem is None:
                    raise RuntimeError(f"Batched Wwise conversion did not produce {target.file_path.name}")
                repl_info["encoded_wem"] = str(encoded_wem)
                shutil.copy2(encoded_wem, target_file)
                # The rebuilt-bank verification below validates each selected WEM after
                # repacking. Avoid probing it once here and then again after repacking.
                # When output verification is disabled, retain the old immediate check.
                if not self.options.verify_output:
                    self._verify_wem_duration(encoded_wem, target, sel)
                with contextlib.suppress(OSError):
                    shutil.rmtree(Path(repl_info.get("matched_wav", encoded_wem)).parents[1], ignore_errors=True)
                rec.completed += 1
                rec.replacements_detail.append(repl_info)
                with getattr(self, "_progress_lock", contextlib.nullcontext()):
                    self._progress_done += 1
                self._emit_progress(f"Replaced “{sel.wem.display_name}” in {bank.name} ♡")

            self._check_cancel()
            temp_out = stage / f"{safe_name(bank.stem)}{self.options.output_suffix}{bank.suffix}"
            self.wwiseutil.replace(bank, replacement_dir, temp_out)
            if self.options.verify_output:
                self._verify_bank(temp_out, selections, original_snapshot, replacement_dir)

            if not self.options.install_to_game:
                rec.installed_path = str(temp_out)
                rec.installed_sha256 = sha256_file(temp_out) if temp_out.is_file() else ""
                return rec
            game_target = self._live_game_target(bank)
            if not game_target.parent.exists():
                raise FileNotFoundError(f"Game audio directory does not exist: {game_target.parent}")
            # IMPORTANT: capture the original live file BEFORE replacing it.
            # Creating this copy after os.replace() would back up the new modded file
            # and make Undo appear to work while restoring nothing.
            undo_manager = UndoManager(self.paths, self.log)
            undo_backup = undo_manager.create_backup(store.run_id, game_target, backup_source)
            rec.backup_path = str(undo_backup)
            install_tmp = game_target.with_name(game_target.name + f".{store.run_id}.install.tmp")
            try:
                if install_tmp.exists():
                    install_tmp.unlink()
                shutil.copy2(temp_out, install_tmp)
                with open(install_tmp, "r+b") as fh:
                    fh.flush()
                    try:
                        os.fsync(fh.fileno())
                    except OSError as sync_exc:
                        self.log.debug("Game-install fsync warning: %s", sync_exc)
                os.replace(install_tmp, game_target)
            finally:
                with contextlib.suppress(OSError):
                    install_tmp.unlink()
            rec.installed_path = str(game_target)
            rec.output_bank = str(game_target)
            rec.installed_sha256 = sha256_file(game_target)
            rec.status = "success"
            rec.finished_at = _dt.datetime.now().isoformat(timespec="seconds")
            self.log.info("SUCCESS: %s installed directly to live game file: %s", bank.name, game_target)
            return rec
        except Exception as exc:
            rec.finished_at = _dt.datetime.now().isoformat(timespec="seconds")
            if isinstance(exc, (PreviewCancelled, ProcessingCancelled)) or self._cancelled():
                rec.status = "cancelled"
                rec.failed = 0
                rec.messages.append("Cancelled before this sound group finished; no changes were installed for it.")
                self.log.info("CANCELLED: %s", bank.name)
                return rec
            rec.status = "failed"
            rec.failed = max(0, len(selections) - rec.completed)
            rec.messages.append(str(exc))
            rec.messages.append(traceback.format_exc())
            self.log.error("FAILED: %s: %s", bank, exc)
            return rec

    def _process_selection(self, store: ArtifactStore, bank: Path, target: WemInfo,
                           sel: Selection, stage: Path, position: int,
                           encode_wem: bool = True) -> dict[str, Any]:
        source_work = stage / "sources" / f"{position:03d}_{safe_name(target.display_name)}"
        source_work.mkdir(parents=True, exist_ok=True)
        raw_source = sel.source.strip().strip('"')
        prefetched = sel.local_source_path
        if looks_like_url(raw_source) and prefetched is not None and prefetched.is_file() and prefetched.stat().st_size > 4096:
            source_path = prefetched.resolve()
            self.log.info("Using pre-downloaded source for %s: %s", raw_source, source_path)
        elif is_youtube_url(raw_source) and self._run_source_cache_dir is not None:
            cache_key = hashlib.sha256(raw_source.encode("utf-8")).hexdigest()[:32]
            cached = self._run_source_cache.get(cache_key)
            if cached is not None and cached.is_file() and cached.stat().st_size > 4096:
                source_path = cached
                self.log.info("Reusing downloaded source for %s", raw_source)
            else:
                cache_dir = self._run_source_cache_dir / cache_key
                source_path = self.source_manager.materialize(raw_source, cache_dir, target.display_name)
                self._run_source_cache[cache_key] = source_path
        else:
            source_path = self.source_manager.materialize(raw_source, source_work / "download", target.display_name)
        # decode_and_match performs a source-duration probe only when a duration-dependent
        # feature needs it. Avoiding this unconditional probe saves one process per playlist song.
        source_duration: Optional[float] = None

        selection_options = dataclasses.replace(
            self.options,
            playback_rate=self.options.playback_rate if sel.playback_rate is None else float(sel.playback_rate),
            volume_db=self.options.volume_db if sel.volume_db is None else float(sel.volume_db),
            fade_in_ms=self.options.fade_in_ms if sel.fade_in_ms is None else int(sel.fade_in_ms),
            fade_out_ms=self.options.fade_out_ms if sel.fade_out_ms is None else int(sel.fade_out_ms),
            normalize_loudness=self.options.normalize_loudness if sel.normalize_loudness is None else bool(sel.normalize_loudness),
            combine_original=self.options.combine_original if sel.combine_original is None else bool(sel.combine_original),
            overlay_gain_db=self.options.overlay_gain_db if sel.overlay_gain_db is None else float(sel.overlay_gain_db),
            short_source_policy=self.options.short_source_policy if sel.short_source_policy is None else str(sel.short_source_policy),
            source_end_ms=self.options.source_end_ms if sel.source_end_ms is None else float(sel.source_end_ms),
            auto_match_duration=self.options.auto_match_duration if sel.auto_match_duration is None else bool(sel.auto_match_duration),
        )
        selection_audio = AudioProcessor(self.tools, self.runner, self.log, selection_options)
        matched = selection_audio.decode_and_match(
            source_path, target, source_work / "audio", extra_offset_ms=sel.source_offset_ms
        )
        source_duration = selection_audio.last_source_duration
        wem_out_dir = source_work / "wem"
        encoded = None
        if encode_wem:
            encoded = self.encoder.encode(matched, target.file_path.name, wem_out_dir)

        return {
            "bank": str(bank),
            "wem": target.display_name,
            "wem_index": target.index,
            "original_duration_seconds": target.duration_seconds,
            "original_sample_rate": target.sample_rate,
            "original_channels": target.channels,
            "source": sel.source,
            "source_kind": sel.source_kind,
            "source_playlist_index": sel.source_playlist_index,
            "source_playlist_title": sel.source_playlist_title,
            "source_path": str(source_path),
            "source_duration_seconds": source_duration,
            "source_offset_ms": sel.source_offset_ms,
            "matched_wav": str(matched),
            "encoded_wem": str(encoded) if encoded is not None else "",
            "audit_wem": "(temporary; cleaned after success)",
        }

    def process_loose_wems(self, selections: list[Selection], output_dir: Optional[Path] = None) -> list[JobRecord]:

        if not selections:
            return []
        run_id = timestamp() + "_" + uuid.uuid4().hex[:6]
        store = ArtifactStore(self.paths, run_id, self.log)
        store.backup_retention = max(0, int(self.options.backup_retention))
        records: list[JobRecord] = []
        self.paths.ensure()
        self._progress_total = self._progress_done + len(selections)
        self._emit_progress("Warming up the cute little mixer… ♪")

        for position, selection in enumerate(selections, 1):
            self._check_cancel()
            target = selection.wem
            wem = target.file_path.resolve()
            rec = JobRecord(
                run_id=run_id,
                status="running",
                started_at=_dt.datetime.now().isoformat(timespec="seconds"),
                source_bank=str(wem),
                output_bank="",
                replacements=1,
            )
            stage = store.bank_stage(wem)
            try:
                if not wem.is_file():
                    raise FileNotFoundError(f"Loose WEM is missing: {wem}")
                if self.options.backup_inputs and not self.options.install_to_game:
                    backup = store.backup_bank(wem)
                    rec.backup_path = str(backup)

                repl_info = self._process_selection(store, wem, target, selection, stage, position)
                encoded_wem = Path(repl_info["encoded_wem"])
                self._verify_wem_duration(encoded_wem, target, selection)
                # Reclaim the big intermediate WAV, but keep the encoded WEM until it
                # has been copied out; the whole stage is removed by store.cleanup().
                with contextlib.suppress(OSError):
                    shutil.rmtree(Path(repl_info.get("matched_wav", encoded_wem)).parent, ignore_errors=True)

                temp_out = stage / f"{safe_name(wem.stem)}{self.options.output_suffix}{wem.suffix}"
                shutil.copy2(encoded_wem, temp_out)
                rec.completed = 1
                rec.replacements_detail.append(repl_info)

                if self.options.verify_output:
                    self._verify_wem_duration(temp_out, target, selection)

                if not self.options.install_to_game:
                    rec.installed_path = str(temp_out)
                    rec.installed_sha256 = sha256_file(temp_out) if temp_out.is_file() else ""
                    rec.status = "success"
                    rec.finished_at = _dt.datetime.now().isoformat(timespec="seconds")
                    records.append(rec)
                    with getattr(self, "_progress_lock", contextlib.nullcontext()):
                        self._progress_done += 1
                    self._emit_progress(f"Replaced “{target.display_name}” ♡")
                    continue
                game_target = self._live_game_target(wem)
                if not game_target.parent.exists():
                    raise FileNotFoundError(f"Brawlhalla audio directory does not exist: {game_target.parent}")
                backup_source = game_target if game_target.is_file() else wem
                # Capture the original bytes BEFORE installing the replacement.
                # Otherwise the backup would contain the new modded WEM.
                undo_manager = UndoManager(self.paths, self.log)
                undo_backup = undo_manager.create_backup(run_id, game_target, backup_source)
                rec.backup_path = str(undo_backup)
                install_tmp = game_target.with_name(game_target.name + f".{run_id}.install.tmp")
                try:
                    if install_tmp.exists():
                        install_tmp.unlink()
                    shutil.copy2(temp_out, install_tmp)
                    with open(install_tmp, "r+b") as fh:
                        fh.flush()
                        try:
                            os.fsync(fh.fileno())
                        except OSError as sync_exc:
                            self.log.debug("Loose WEM install fsync warning: %s", sync_exc)
                    os.replace(install_tmp, game_target)
                finally:
                    with contextlib.suppress(OSError):
                        install_tmp.unlink()
                rec.installed_path = str(game_target)
                rec.installed_sha256 = sha256_file(game_target)
                rec.output_bank = str(game_target)
                self.log.info("Installed validated loose WEM directly to live game file: %s", game_target)

                rec.status = "success"
                rec.finished_at = _dt.datetime.now().isoformat(timespec="seconds")
                records.append(rec)
                with getattr(self, "_progress_lock", contextlib.nullcontext()):
                    self._progress_done += 1
                self._emit_progress(f"Replaced “{target.display_name}” ♡")
            except Exception as exc:
                rec.finished_at = _dt.datetime.now().isoformat(timespec="seconds")
                if isinstance(exc, (PreviewCancelled, ProcessingCancelled)) or self._cancelled():
                    rec.status = "cancelled"
                    rec.failed = 0
                    rec.messages.append("Cancelled before this sound finished.")
                    self.log.info("CANCELLED loose WEM: %s", wem)
                else:
                    rec.status = "failed"
                    rec.failed = 1
                    rec.messages.append(str(exc))
                    rec.messages.append(traceback.format_exc())
                    self.log.error("FAILED loose WEM: %s: %s", wem, exc)
                records.append(rec)
                if rec.status == "cancelled":
                    break

        # Only install runs keep persistent backups; export run paths live in the
        # temporary run workspace and would leave Undo pointing at deleted files.
        if self.options.install_to_game:
            successful = [r for r in records if r.status == "success" and r.backup_path and r.installed_path]
            if successful:
                journal = self.paths.processed_audio / "last_run.json"
                payload = {
                    "run_id": run_id,
                    "created_at": _dt.datetime.now().isoformat(timespec="seconds"),
                    "entries": [
                        {
                            "installed_path": r.installed_path,
                            "backup_path": r.backup_path,
                            "installed_sha256": r.installed_sha256,
                            "source_bank": r.source_bank,
                        }
                        for r in successful
                    ],
                }
                tmp = journal.with_suffix(".json.tmp")
                tmp.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
                tmp.replace(journal)
        UndoManager(self.paths, self.log).prune()
        store.cleanup()
        self.paths.cleanup_generated_bank_artifacts()
        return records

    def _verify_wem_duration(self, wem: Path, target: WemInfo, selection: Optional[Selection] = None) -> None:
        raw = wem.read_bytes()
        sig = wem_header_signature(raw)
        if sig["format_tag"] != 0xFFFF:
            raise RuntimeError(
                f"Replacement {target.display_name} is not a Wwise WEM (codec tag {sig['format_tag']:#x})"
            )
        if target.sample_rate and sig["sample_rate"] != target.sample_rate:
            raise RuntimeError(
                f"Replacement {target.display_name} sample-rate mismatch: "
                f"original={target.sample_rate} new={sig['sample_rate']}"
            )
        if target.channels and sig["channels"] != target.channels:
            raise RuntimeError(
                f"Replacement {target.display_name} channel mismatch: "
                f"original={target.channels} new={sig['channels']}"
            )
        result = self.runner.run([self.tools.vgmstream, "-m", wem], timeout=self.options.tool_timeout, check=False)
        meta = parse_vgmstream_metadata((result.stdout or "") + "\n" + (result.stderr or ""))
        if result.returncode != 0 or not meta["duration"]:
            raise RuntimeError(f"Replacement WEM could not be inspected: {wem}")
        combine_mode = bool(selection is not None and selection.combine_original)
        auto_match = False if combine_mode or selection is None or selection.auto_match_duration is None else bool(selection.auto_match_duration)
        if auto_match:
            delta_ms = abs(meta["duration"] - target.duration_seconds) * 1000.0
            if delta_ms > self.options.duration_tolerance_ms:
                raise RuntimeError(
                    f"Replacement WEM duration mismatch for {target.display_name}: "
                    f"original={target.duration_seconds:.6f}s new={meta['duration']:.6f}s delta={delta_ms:.3f}ms"
                )
            if target.total_samples and meta["samples"] and int(meta["samples"]) != int(target.total_samples):
                raise RuntimeError(
                    f"Replacement WEM sample-count mismatch for {target.display_name}: "
                    f"original={target.total_samples} new={meta['samples']}"
                )
        self.log.info(
            "Encoded WEM verified: %s | %d Hz | %d ch | samples=%s | %.6fs",
            wem.name, sig["sample_rate"], sig["channels"], meta["samples"], meta["duration"]
        )

    def _verify_bank(self, bank: Path, selections: list[Selection],
                     original_snapshot: BankSnapshot,
                     replacement_dir: Path) -> None:
        """Fast structural verification of a rebuilt BNK.

        Untouched WEMs are compared directly from the embedded DATA payload, so no
        unpacking or vgmstream process is needed for them. Replaced WEMs still receive
        a real vgmstream decode check, but those independent probes run concurrently.
        """
        if not bank.is_file() or bank.stat().st_size < 32:
            raise RuntimeError(f"Output bank failed basic file validation: {bank}")

        output_snapshot = parse_bnk_snapshot(bank)
        if output_snapshot.bkhd_version != original_snapshot.bkhd_version:
            raise RuntimeError(
                f"Output BKHD version changed unexpectedly: "
                f"{original_snapshot.bkhd_version} -> {output_snapshot.bkhd_version}"
            )
        if output_snapshot.bkhd_id != original_snapshot.bkhd_id:
            raise RuntimeError(
                f"Output BKHD ID changed unexpectedly: "
                f"{original_snapshot.bkhd_id} -> {output_snapshot.bkhd_id}"
            )
        if len(output_snapshot.media) != len(original_snapshot.media):
            raise RuntimeError(
                f"Output WEM count changed: {len(original_snapshot.media)} -> {len(output_snapshot.media)}"
            )

        for before, after in zip(original_snapshot.media, output_snapshot.media, strict=True):
            if before.media_id != after.media_id:
                raise RuntimeError(
                    f"Output media ID changed at WEM {before.index}: "
                    f"{before.media_id} -> {after.media_id}"
                )

        selected_by_index = {sel.wem.index: sel for sel in selections}
        original_media = extract_embedded_wems_from_snapshot(original_snapshot)
        output_media = extract_embedded_wems_from_snapshot(output_snapshot)
        selected_jobs: list[tuple[int, Selection, dict[str, Any], bytes]] = []
        unchanged_count = 0

        for entry in output_snapshot.media:
            actual_bytes = output_media.get(entry.index, b"")
            if not actual_bytes:
                raise RuntimeError(f"Output verification: WEM {entry.index}.wem is missing from DATA")
            sig = wem_header_signature(actual_bytes)
            if sig["format_tag"] != 0xFFFF:
                raise RuntimeError(
                    f"WEM {entry.index} no longer uses Wwise codec tag 0xFFFF: {sig['format_tag']:#x}"
                )

            target_sel = selected_by_index.get(entry.index)
            if target_sel is None:
                original_bytes = original_media.get(entry.index)
                if original_bytes is None:
                    raise RuntimeError(f"Output verification: original WEM {entry.index} is missing")
                if actual_bytes != original_bytes:
                    raise RuntimeError(
                        f"Non-selected WEM {entry.index} changed unexpectedly during repack"
                    )
                unchanged_count += 1
                continue

            if target_sel.wem.sample_rate and sig["sample_rate"] != target_sel.wem.sample_rate:
                raise RuntimeError(
                    f"WEM {entry.index} sample rate mismatch: "
                    f"original={target_sel.wem.sample_rate} new={sig['sample_rate']}"
                )
            if target_sel.wem.channels and sig["channels"] != target_sel.wem.channels:
                raise RuntimeError(
                    f"WEM {entry.index} channel mismatch: "
                    f"original={target_sel.wem.channels} new={sig['channels']}"
                )
            selected_jobs.append((entry.index, target_sel, sig, actual_bytes))

        if selected_jobs:
            verify_workers = min(4, len(selected_jobs))

            def verify_selected(job: tuple[int, Selection, dict[str, Any], bytes]) -> tuple[int, dict[str, Any], dict[str, Any]]:
                index, target_sel, sig, actual_bytes = job
                # Each worker gets its own tiny WEM file so vgmstream processes never
                # contend over the same temporary path.
                temp_dir = Path(tempfile.mkdtemp(prefix=f"bnk_verify_{index}_"))
                try:
                    actual_path = temp_dir / f"selected_{index}.wem"
                    actual_path.write_bytes(actual_bytes)
                    result = self.runner.run(
                        [self.tools.vgmstream, "-m", actual_path],
                        timeout=self.options.tool_timeout,
                        check=False,
                    )
                    text = (result.stdout or "") + "\n" + (result.stderr or "")
                    meta = parse_vgmstream_metadata(text)
                    if result.returncode != 0 or not meta["duration"]:
                        raise RuntimeError(
                            f"Output WEM {index} cannot be decoded by vgmstream: {text[-1500:]}"
                        )
                    combine_mode = bool(target_sel.combine_original)
                    auto_match = False if combine_mode or target_sel.auto_match_duration is None else bool(target_sel.auto_match_duration)
                    if auto_match:
                        delta_ms = abs(meta["duration"] - target_sel.wem.duration_seconds) * 1000.0
                        if delta_ms > self.options.duration_tolerance_ms:
                            raise RuntimeError(
                                f"Output WEM {index} duration mismatch after repack: "
                                f"original={target_sel.wem.duration_seconds:.6f}s "
                                f"new={meta['duration']:.6f}s delta={delta_ms:.3f}ms"
                            )
                        if target_sel.wem.total_samples and meta["samples"] and int(meta["samples"]) != int(target_sel.wem.total_samples):
                            raise RuntimeError(
                                f"Output WEM {index} sample-count mismatch after repack: "
                                f"original={target_sel.wem.total_samples} new={meta['samples']}"
                            )
                    return index, sig, meta
                finally:
                    with contextlib.suppress(OSError):
                        shutil.rmtree(temp_dir, ignore_errors=True)

            with concurrent.futures.ThreadPoolExecutor(
                max_workers=verify_workers, thread_name_prefix="wemverify"
            ) as executor:
                futures = [executor.submit(verify_selected, job) for job in selected_jobs]
                for future in concurrent.futures.as_completed(futures):
                    index, sig, meta = future.result()
                    self.log.info(
                        "Verified replaced WEM %d: %d Hz, %d ch, %.6fs",
                        index, sig["sample_rate"], sig["channels"], meta["duration"]
                    )

        self.log.info(
            "Fast output verification passed for %s: %d selected WEM(s) decoded in %d parallel probe(s), %d untouched WEM(s) byte-verified",
            bank, len(selected_jobs), min(4, len(selected_jobs)) if selected_jobs else 0, unchanged_count
        )

def configure_logging(log_file: Path, bus: Optional[EventBus] = None, verbose: bool = False) -> logging.Logger:
    log_file.parent.mkdir(parents=True, exist_ok=True)
    logger = logging.getLogger("bnk_replacer")
    logger.setLevel(logging.DEBUG)
    logger.handlers.clear()
    formatter = logging.Formatter("%(asctime)s | %(levelname)-8s | %(message)s")
    fh = RotatingFileHandler(log_file, maxBytes=1024 * 1024, backupCount=2, encoding="utf-8")
    fh.setFormatter(formatter); fh.setLevel(logging.DEBUG)
    logger.addHandler(fh)
    if sys.stdout is not None:
        sh = logging.StreamHandler(sys.stdout)
        sh.setFormatter(formatter); sh.setLevel(logging.DEBUG if verbose else logging.INFO)
        logger.addHandler(sh)
    if bus:
        uh = UILogHandler(bus)
        uh.setFormatter(formatter); uh.setLevel(logging.INFO)
        logger.addHandler(uh)
    return logger

_console_owned = {"value": False}
_console_saved = {"out": None, "err": None}

def _console_present() -> bool:
    try:
        if os.name == "nt":
            import ctypes as _ct
            return bool(_ct.windll.kernel32.GetConsoleWindow())
    except Exception:
        pass
    return sys.stdout is not None

def ensure_console_window(logger=None) -> bool:
    try:
        if os.name != "nt":
            return sys.stdout is not None
        import ctypes as _ct
        if not _console_present():
            try:
                _ct.windll.kernel32.AllocConsole()
            except Exception:
                pass
            if not _console_present():
                return False
            _console_owned["value"] = True
            try:
                _console_saved["out"] = sys.stdout
                _console_saved["err"] = sys.stderr
                sys.stdout = open("CONOUT$", "w", buffering=1, encoding="utf-8", errors="replace")
                sys.stderr = open("CONOUT$", "w", buffering=1, encoding="utf-8", errors="replace")
            except Exception:
                pass
        lg = logger if logger is not None else logging.getLogger("bnk_replacer")
        try:
            if not any(getattr(h, "_cutie_console", False) for h in lg.handlers):
                h = logging.StreamHandler(sys.stdout if sys.stdout is not None else sys.stderr)
                h.setFormatter(logging.Formatter("%(asctime)s | %(levelname)-8s | %(message)s"))
                h.setLevel(logging.INFO)
                h._cutie_console = True
                lg.addHandler(h)
        except Exception:
            pass
        return True
    except Exception:
        return False

def release_console_window(logger=None) -> bool:
    try:
        lg = logger if logger is not None else logging.getLogger("bnk_replacer")
        try:
            for h in [x for x in lg.handlers if getattr(x, "_cutie_console", False)]:
                with contextlib.suppress(Exception):
                    lg.removeHandler(h)
        except Exception:
            pass
        if os.name == "nt" and _console_owned["value"]:
            try:
                import ctypes as _ct
                _ct.windll.kernel32.FreeConsole()
            except Exception:
                pass
            _console_owned["value"] = False
            with contextlib.suppress(Exception):
                if sys.stdout is not None:
                    sys.stdout.flush()
            sys.stdout = _console_saved["out"]
            sys.stderr = _console_saved["err"]
        return True
    except Exception:
        return False

def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="BNK_WEM_Replacer_Pro.py",
        description="Batch replace WEM audio inside Wwise BNK files and repack them safely."
    )
    p.add_argument("--root", type=Path, default=DEFAULT_ROOT)
    p.add_argument("--bnk", action="append", type=Path, help="BNK file; repeat option for multiple banks")
    p.add_argument("--select", help="WEM selection expression. Example: 1,3,7")
    p.add_argument("--audio", action="append", help="Replacement source; repeat for separate audio per selected WEM")
    p.add_argument("--same-audio", action="store_true", help="Use one --audio source for every selected WEM")
    p.add_argument("--output", type=Path)
    p.add_argument("--short-source", choices=["loop", "silence", "reject"], default="loop")
    p.add_argument("--tolerance-ms", type=float, default=2.0)
    p.add_argument("--preset", default="Vorbis Quality High")
    p.add_argument("--no-backup", action="store_true")
    p.add_argument("--no-verify", action="store_true")
    p.add_argument("--keep-staging", action="store_true", help="Keep temporary processing files after success")
    p.add_argument("--verbose", action="store_true")
    p.add_argument("--gui", action="store_true")
    p.add_argument("--list-tools", action="store_true")
    p.add_argument("pack", nargs="?", type=Path, help=".cutie mod pack to open after launch (also works via double-click)")
    p.add_argument("--register-cutie", action="store_true", help="Make .cutie files open with this app (current user, no admin needed)")
    p.add_argument("--unregister-cutie", action="store_true", help="Remove the .cutie file association")
    return p

def select_by_expression(infos: list[WemInfo], expression: str) -> list[WemInfo]:
    selected: list[WemInfo] = []
    tokens = [x.strip() for x in expression.split(",") if x.strip()]
    for token in tokens:
        if "-" in token and re.fullmatch(r"\d+\s*-\s*\d+", token):
            a, b = [int(x.strip()) for x in token.split("-", 1)]
            if a > b: a, b = b, a
            for n in range(a, b + 1):
                if 1 <= n <= len(infos):
                    selected.append(infos[n - 1])
        else:
            n = int(token)
            if not (1 <= n <= len(infos)):
                raise ValueError(f"Selection {n} is outside the visible WEM list 1..{len(infos)}")
            selected.append(infos[n - 1])

    out: list[WemInfo] = []
    seen: set[str] = set()
    for x in selected:
        if x.key not in seen:
            out.append(x); seen.add(x.key)
    return out

def run_cli(args: argparse.Namespace) -> int:
    paths = KitPaths(args.root); paths.ensure()
    bus = EventBus()
    log = configure_logging(paths.processed_audio / "bnk_replacer.log", bus, args.verbose)
    tools = ToolLocator(paths).locate()
    print("\n" + APP_NAME + " " + APP_VERSION)
    print("\nDetected tools:\n" + ToolLocator(paths).pretty(tools) + "\n")
    if args.list_tools:
        return 0
    if args.register_cutie:
        print(register_cutie_association())
        return 0
    if args.unregister_cutie:
        unregister_cutie_association()
        print("Removed the .cutie association.")
        return 0
    if args.pack or args.gui or (not args.bnk and tk is not None):
        launch_gui(paths, tools, log, bus, open_pack=args.pack)
        return 0
    if not args.bnk:
        print("No BNK files supplied. Use --gui for interactive mode or --bnk PATH.")
        return 2
    if not tools.wwiseutil or not tools.vgmstream or not tools.ffmpeg or not tools.wwise_console:
        log.error("One or more required tools were not detected; see --list-tools")
        return 3
    options = ProcessOptions(
        short_source_policy=args.short_source,
        duration_tolerance_ms=args.tolerance_ms,
        conversion_preset=args.preset,
        backup_inputs=False,
        verify_output=not args.no_verify,
        keep_staging=args.keep_staging,
    )
    replacer = BNKReplacer(paths, tools, options, log, bus)
    if not args.select:
        print("No --select expression supplied. Select one or more WEMs to continue.")
        return 2

    all_infos: list[WemInfo] = []
    for bank in args.bnk:
        infos = replacer.inspect_bank(bank)
        print(f"\nBNK: {bank}")
        for i, info in enumerate(infos, 1):
            print(f"  {i:4d}. {info.display_name:<24} {info.duration_seconds:10.4f}s  {info.sample_rate}Hz  {info.channels}ch")
        all_infos.extend(infos)
    selected = select_by_expression(all_infos, args.select)
    if not args.audio:
        raise ValueError("Selected WEMs require one or more --audio values")
    if args.same_audio:
        if len(args.audio) != 1:
            raise ValueError("--same-audio requires exactly one --audio argument")
        sources = args.audio * len(selected)
    else:
        if len(args.audio) != len(selected):
            raise ValueError(f"Separate-audio mode needs {len(selected)} --audio values; got {len(args.audio)}")
        sources = args.audio
    selections = []
    for wem, source in zip(selected, sources, strict=True):
        selections.append(Selection(wem=wem, source=source, source_kind="url" if looks_like_url(source) else "file"))
    records = replacer.process(selections, args.output or paths.final)
    print(json.dumps([dataclasses.asdict(r) for r in records], indent=2, ensure_ascii=False))
    return 0 if all(r.status == "success" for r in records) else 4

def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as fh:
        for block in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()

def is_windows_admin() -> bool:
    if os.name != "nt":
        return True
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False

def request_admin_restart() -> bool:

    if os.name != "nt" or is_windows_admin():
        return False
    try:
        import ctypes
        params = subprocess.list2cmdline(sys.argv)
        rc = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, params, None, 1)
        if rc > 32:
            return True
    except Exception:
        return False
    return False

class UndoManager:
    def __init__(self, paths: KitPaths, logger: logging.Logger) -> None:
        self.paths = paths
        self.log = logger
        self.journal = self.paths.processed_audio / "last_run.json"

    def _undo_root(self) -> Path:
        return self.paths.processed_audio / "undo"

    def _backup_path(self, run_id: str, target: Path) -> Path:
        """Return a collision-safe persistent backup path for one installed target."""
        resolved = Path(target).resolve(strict=False)
        token = hashlib.sha256(os.fspath(resolved).lower().encode("utf-8", "replace")).hexdigest()[:16]
        run_root = self._undo_root() / str(run_id)
        run_root.mkdir(parents=True, exist_ok=True)
        return run_root / f"{token}__{safe_name(resolved.name)}"

    def create_backup(self, run_id: str, target: Path, source: Path | None = None) -> Path:
        """Copy the pre-install bytes to persistent Undo storage before replacement."""
        target = Path(target).resolve(strict=False)
        source = Path(source or target).resolve(strict=False)
        if not source.is_file():
            raise FileNotFoundError(f"Cannot create Undo backup; original file is missing: {source}")
        backup = self._backup_path(run_id, target)
        temp = backup.with_name(backup.name + ".tmp")
        try:
            with contextlib.suppress(OSError):
                temp.unlink()
            shutil.copy2(source, temp)
            # Make sure the persistent copy really contains the original bytes.
            if sha256_file(temp) != sha256_file(source):
                raise RuntimeError(f"Undo backup verification failed for {target}")
            os.replace(temp, backup)
        finally:
            with contextlib.suppress(OSError):
                temp.unlink()
        self.log.info("Created persistent Undo backup for %s: %s", target, backup)
        return backup

    def _remove_run_dir(self, run_id: str) -> None:
        run_id = str(run_id or "").strip()
        if not run_id:
            return
        with contextlib.suppress(OSError):
            shutil.rmtree(self._undo_root() / run_id, ignore_errors=True)

    def _write_journal(self, run_id: str, created_at: str, entries: list[dict[str, Any]]) -> None:
        payload = {
            "run_id": run_id,
            "created_at": created_at or _dt.datetime.now().isoformat(timespec="seconds"),
            "entries": entries,
        }
        self.journal.parent.mkdir(parents=True, exist_ok=True)
        temp = self.journal.with_name(self.journal.name + ".tmp")
        temp.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
        os.replace(temp, self.journal)

    def _clear_journal(self) -> None:
        with contextlib.suppress(OSError):
            self.journal.unlink()

    def prune(self) -> None:
        """Delete backups from older runs so undo space only holds the latest install."""
        root = self._undo_root()
        if not root.is_dir():
            return
        keep: set[str] = set()
        with contextlib.suppress(Exception):
            data = self.read()
            run_id = str(data.get("run_id", "")).strip()
            if run_id:
                keep.add(run_id)
        for child in root.iterdir():
            if child.is_dir() and child.name not in keep:
                with contextlib.suppress(OSError):
                    shutil.rmtree(child, ignore_errors=True)
                    self.log.info("Pruned old undo backups: %s", child)

    def read(self) -> dict[str, Any]:
        if not self.journal.is_file():
            raise FileNotFoundError("No undo record exists yet. Make a successful replacement first.")
        try:
            data = json.loads(self.journal.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise RuntimeError(f"The undo record could not be read: {exc}") from exc
        if not isinstance(data, dict) or not isinstance(data.get("entries"), list):
            raise RuntimeError("The undo record is invalid or incomplete.")
        return data

    def _restore_one(self, backup: Path, target: Path) -> None:
        target.parent.mkdir(parents=True, exist_ok=True)
        temp = target.with_name(target.name + ".undo.tmp")
        try:
            if temp.exists():
                temp.unlink()
            shutil.copy2(backup, temp)
            os.replace(temp, target)
        finally:
            with contextlib.suppress(OSError):
                if temp.exists():
                    temp.unlink()

    def undo_last(self, force: bool = False) -> list[str]:
        data = self.read()
        messages: list[str] = []
        entries = data.get("entries", [])
        if not entries:
            raise RuntimeError("The last run contains no successful game installations to undo.")
        remaining: list[dict[str, Any]] = []
        for entry in entries:
            target = Path(entry["installed_path"])
            backup = Path(entry["backup_path"])
            if not backup.is_file():
                messages.append(f"SKIPPED: missing backup {backup}")
                remaining.append(entry)
                continue
            current_hash = sha256_file(target) if target.is_file() else None
            expected_hash = entry.get("installed_sha256")
            if not force and current_hash != expected_hash:
                messages.append(f"SKIPPED: {target} changed after the run; use forced undo to override")
                remaining.append(entry)
                continue
            try:
                self._restore_one(backup, target)
            except OSError as exc:
                messages.append(f"FAILED: {target}: {exc}")
                remaining.append(entry)
                continue
            messages.append(f"RESTORED: {target}")
            with contextlib.suppress(OSError):
                backup.unlink()
            self.log.info("↶ Undo restored %s from %s", target, backup)
        if remaining:
            self._write_journal(data.get("run_id", ""), data.get("created_at", ""), remaining)
        else:
            self._clear_journal()
            self._remove_run_dir(data.get("run_id", ""))
        return messages

def _bank_identity_key(path: Path) -> tuple[int, str]:

    try:
        return (path.stat().st_size, path.name.lower())
    except OSError:
        return (0, path.name.lower())

def is_live_game_bank(path: Path) -> bool:

    name = Path(path).name.lower()
    if not name.endswith(".bnk"):
        return False
    stem = name[:-4]
    blocked = (
        "_backup", ".backup", "-backup", " backup",
        "_replaced", ".replaced", "-replaced", " replaced",
        "_copy", "-copy", " copy", "_duplicate", "-duplicate",
        " (copy)", " (1)", " (2)", " (3)",
    )
    return not any(token in stem for token in blocked)

def find_exact_duplicate_banks(banks: Sequence[Path]) -> tuple[list[Path], dict[str, list[Path]]]:

    by_size: dict[int, list[Path]] = {}
    for bank in banks:
        try:
            by_size.setdefault(bank.stat().st_size, []).append(bank)
        except OSError:
            by_size.setdefault(-1, []).append(bank)

    def preferred(paths: list[Path]) -> Path:
        def score(p: Path) -> tuple[int, int, str]:
            n = p.name.lower()
            copy_markers = (" - copy", "_copy", " (1)", " (2)", " duplicate", "_duplicate")
            marker = 1 if any(m in n for m in copy_markers) else 0
            backup = 1 if not is_live_game_bank(p) else 0
            return (backup, marker, n)
        return sorted(paths, key=score)[0]

    kept: list[Path] = []
    duplicates: dict[str, list[Path]] = {}
    for _, same_size in by_size.items():
        if len(same_size) == 1:
            kept.extend(same_size)
            continue
        hashes: dict[str, list[Path]] = {}
        for path in same_size:
            try:
                digest = sha256_file(path)
            except OSError:
                digest = f"UNREADABLE:{path}"
            hashes.setdefault(digest, []).append(path)
        for digest, group in hashes.items():
            if len(group) == 1 or digest.startswith("UNREADABLE:"):
                kept.extend(group)
                continue
            rep = preferred(group)
            kept.append(rep)
            duplicates[str(rep)] = [p for p in group if p != rep]
    return sorted(kept, key=lambda p: p.name.lower()), duplicates

