def _stem(path: Path) -> str:
    return Path(path).stem

def _normal_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.lower())

def _humanise_bank_name(value: str) -> str:
    value = value.strip(" _-")
    value = re.sub(r"[_\-]+", " ", value)
    value = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", value)
    value = re.sub(r"(?<=[A-Za-z])(?=\d)", " ", value)
    value = re.sub(r"(?<=\d)(?=[A-Za-z])", " ", value)
    return re.sub(r"\s+", " ", value).strip() or "Unknown"

def _category_label(prefix: str, name: str) -> str:
    return _humanise_bank_name(name[len(prefix):])

def categorise_brawlhalla_bnk(path: Path) -> tuple[str, str]:
    name = Path(path).stem
    lower_name = name.lower()

    if lower_name == "vox_announcer":
        return ("Announcer & Voice", "Announcer")
    if lower_name.startswith("vox_"):
        return ("Announcer & Voice", f"Voice: {_category_label('VOX_', name)}")
    if lower_name.startswith("dia_") or lower_name.startswith("voice_"):
        return ("Announcer & Voice", _humanise_bank_name(name.split("_", 1)[1]))

    if name == "MUS_Menu":
        return ("Menu & Lobby Music", "Main Menu")
    if name == "MUS_BTS":
        return ("Menu & Lobby Music", "BTS")
    if name == "MUS_BattlePass":
        return ("Menu & Lobby Music", "Battle Pass 1")

    match = re.fullmatch(r"MUS_BattlePass_S(\d+)", name, flags=re.I)
    if match:
        return ("Menu & Lobby Music", f"Battle Pass {int(match.group(1))}")
    if lower_name.startswith("mus_menu_event_"):
        return ("Menu & Lobby Music", f"Event: {_category_label('MUS_Menu_Event_', name)}")
    if lower_name.startswith("mus_menu_xo_"):
        return ("Menu & Lobby Music", f"Crossover: {_category_label('MUS_Menu_XO_', name)}")
    if lower_name.startswith("mus_menu_"):
        return ("Menu & Lobby Music", _category_label("MUS_Menu_", name))
    if lower_name.startswith("mus_") and not lower_name.startswith("mus_level_"):
        return ("Menu & Lobby Music", _category_label("MUS_", name))

    if name in MAP_BANK_ALIASES:
        return ("Map Music", MAP_BANK_ALIASES[name])
    match = re.fullmatch(r"MUS_Level_0?(\d+)", name, flags=re.I)
    if match:
        return ("Map Music", f"Stage {int(match.group(1))}")
    if lower_name.startswith("mus_level_"):
        return ("Map Music", _category_label("MUS_Level_", name))

    weapon_names = {
        "WEP_Unarmed": "Unarmed",
        "WEP_Axe": "Axe",
        "WEP_Boots": "Battle Boots",
        "WEP_Bow": "Bow",
        "WEP_Cannon": "Cannon",
        "WEP_Chakrams": "Chakrams",
        "WEP_Explosion": "Explosions",
        "WEP_Fists": "Gauntlets",
        "WEP_Greatsword": "Greatsword",
        "WEP_Hammer": "Hammer",
        "WEP_Katar": "Katars",
        "WEP_Orb": "Orb",
        "WEP_Pistol": "Blasters",
        "WEP_RocketLance": "Rocket Lance",
        "WEP_Scythe": "Scythe",
        "WEP_Spear": "Spear",
        "WEP_Sword": "Sword",
    }
    if name in weapon_names:
        return ("Weapon Sounds", weapon_names[name])
    if lower_name.startswith("wep_"):
        return ("Weapon Sounds", _category_label("WEP_", name))

    if lower_name.startswith("spc_"):
        return ("Legend Signatures", f"Sig: {_category_label('SPC_', name)}")

    if name == "PC_Movement":
        return ("Movement & UI", "Movement")
    if name == "PC_Taunt":
        return ("Movement & UI", "Emotes & Taunts")
    if lower_name.startswith("pc_"):
        return ("Movement & UI", _category_label("PC_", name))
    if name == "UI":
        return ("Movement & UI", "UI Sounds")
    if lower_name.startswith("ui_"):
        return ("Movement & UI", _category_label("UI_", name))
    if name == "ENV_Crowd":
        return ("Movement & UI", "Crowd Sounds")

    if lower_name.startswith(("sfx_", "fx_", "snd_", "amb_")):
        prefix = next(prefix for prefix in ("SFX_", "FX_", "SND_", "AMB_") if lower_name.startswith(prefix.lower()))
        return ("Other / Uncategorized", _category_label(prefix, name))
    if lower_name.startswith("env_"):
        return ("Other / Uncategorized", _category_label("ENV_", name))

    for prefix in ("Cutscenes_", "Cinematics_", "Cinematic_", "CIN_"):
        if lower_name.startswith(prefix.lower()):
            return ("Cinematics & Cutscenes", f"Cutscene: {_category_label(prefix, name)}")

    return ("Other / Uncategorized", _humanise_bank_name(name))

def find_brawlhalla_audio_dir(preferred: Optional[Path] = None) -> Path:

    candidates: list[Path] = []
    if preferred:
        candidates.append(Path(preferred))

    for drive in "CDEFGHIJKLMNOPQRSTUVWXYZ":
        candidates.append(Path(f"{drive}:\\Program Files (x86)\\Steam\\steamapps\\common\\Brawlhalla\\audio\\pc"))
        candidates.append(Path(f"{drive}:\\Program Files\\Steam\\steamapps\\common\\Brawlhalla\\audio\\pc"))
        candidates.append(Path(f"{drive}:\\SteamLibrary\\steamapps\\common\\Brawlhalla\\audio\\pc"))
        candidates.append(Path(f"{drive}:\\Steam\\steamapps\\common\\Brawlhalla\\audio\\pc"))

    if os.name == "nt":
        try:
            import winreg
            reg_candidates = [
                (winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam", "SteamPath"),
                (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Valve\Steam", "InstallPath"),
            ]
            for hive, key_name, value_name in reg_candidates:
                try:
                    with winreg.OpenKey(hive, key_name) as key:
                        value, _ = winreg.QueryValueEx(key, value_name)
                        if value:
                            steam_root = Path(value)
                            candidates.append(steam_root / "steamapps" / "common" / "Brawlhalla" / "audio" / "pc")
                            vdf = steam_root / "steamapps" / "libraryfolders.vdf"
                            if vdf.is_file():
                                text = vdf.read_text(encoding="utf-8", errors="ignore")
                                for match in re.finditer(r'"path"\s+"([^"]+)"', text, re.I):
                                    lib = Path(match.group(1).replace('\\\\', '\\'))
                                    candidates.append(lib / "steamapps" / "common" / "Brawlhalla" / "audio" / "pc")
                except OSError:
                    pass
        except Exception:
            pass

    seen: set[str] = set()
    for path in candidates:
        try:
            key = str(path.resolve()).lower()
        except OSError:
            key = str(path).lower()
        if key in seen:
            continue
        seen.add(key)
        if (path / "Init.bnk").is_file():
            return path.resolve()
    return Path(preferred) if preferred else GAME_AUDIO_DIR

def cleanup_temporary_source_downloads(paths: KitPaths) -> None:
    """Remove downloaded replacement media that is only needed during a run.

    Replacement URLs are downloaded into these private staging folders. They are not
    user exports and should never accumulate after processing finishes.
    """
    for root in (
        paths.processed_audio / "url_prefetch",
        paths.processed_audio / "batch_sources",
    ):
        with contextlib.suppress(OSError):
            shutil.rmtree(root, ignore_errors=True)


def cleanup_old_workspace(paths: KitPaths) -> None:

    for root in (
        paths.wems / "inspect",
        paths.processed_audio / "preview_cache",
        paths.processed_audio / "runs",
        paths.processed_audio / "url_prefetch",
        paths.processed_audio / "batch_sources",
    ):
        try:
            if root.is_file():
                root.unlink()
                continue
            if not root.is_dir():
                continue
            children = list(root.iterdir())
        except OSError:
            continue
        for child in children:
            try:
                if child.is_dir():
                    shutil.rmtree(child, ignore_errors=True)
                else:
                    child.unlink()
            except OSError:
                pass

    paths.cleanup_generated_bank_artifacts()


class UpdateUnavailable(RuntimeError):
    """Raised when the update feed is valid but does not advertise a newer version."""

