    def _install_responsive_ux(self) -> None:
        """Premium UX layer: hover states, busy feedback, and live readiness cues."""
        try:
            self._ux_busy = False
            self._ux_original_status = None
            self._ux_bind_widgets(self.root)
            self.root.bind("<Motion>", self._ux_pointer_motion, add="+")
            self._start_hover_polling()
        except Exception as exc:
            self.log.debug("Responsive UX install skipped: %s", exc)

    def _ux_palette(self):
        return getattr(self, "_theme_colors", {}) or {}

    def _ux_bind_widgets(self, widget):
        try:
            if isinstance(widget, (ttk.Button, tk.Button)):
                widget.bind("<Enter>", lambda e, w=widget: self._ux_hover(w, True), add="+")
                widget.bind("<Leave>", lambda e, w=widget: self._ux_hover(w, False), add="+")
                widget.bind("<ButtonPress-1>", lambda e, w=widget: self._ux_press(w), add="+")
                widget.bind("<ButtonRelease-1>", lambda e, w=widget: self._ux_release(w), add="+")
            elif isinstance(widget, tk.Label):
                widget.bind("<Enter>", lambda e, w=widget: self._ux_text_hover(w, True), add="+")
                widget.bind("<Leave>", lambda e, w=widget: self._ux_text_hover(w, False), add="+")
            elif isinstance(widget, ttk.Treeview):
                widget.bind("<Motion>", self._ux_tree_hover, add="+")
                widget.bind("<Enter>", self._ux_tree_hover, add="+")
                widget.bind("<Leave>", lambda _e, w=widget: self._ux_tree_clear_hover(w), add="+")
            for child in widget.winfo_children():
                self._ux_bind_widgets(child)
        except Exception:
            pass

    def _ux_hover(self, widget, active):
        try:
            p = self._ux_palette()
            accent = p.get("accent", "#c65d91")
            accent_active = p.get("accent_active", accent)
            accent_pressed = p.get("accent_pressed", accent)
            fg = p.get("fg", "#332c34")
            sel = p.get("sel", "#efc7db")
            
            if isinstance(widget, tk.Button):
                widget.configure(activebackground=accent_active if active else accent)
                widget.configure(cursor="hand2" if active else "")
            elif isinstance(widget, ttk.Button):
                style_name = widget.cget("style") or "TButton"
                style = ttk.Style()
                
                # Ensure the base style has proper active/pressed mappings
                # The theme already sets these up in _configure_style
                # We just need to make sure cursor changes
                widget.configure(cursor="hand2" if active else "")
                
                # For a subtle glow effect, we can tweak the style's active state
                if active:
                    # Create a one-time hover enhancement
                    hover_style = f"{style_name}.Hover"
                    try:
                        style.configure(hover_style, **style.configure(style_name))
                        style.map(hover_style,
                            background=[("active", accent_active), ("pressed", accent_pressed), ("!disabled", accent_active)],
                            foreground=[("active", "#ffffff"), ("pressed", "#ffffff"), ("!disabled", fg)],
                            relief=[("active", "raised"), ("pressed", "sunken")]
                        )
                        widget.configure(style=hover_style)
                    except Exception:
                        pass
                else:
                    # Restore original style
                    widget.configure(style=style_name)
        except Exception:
            pass

    def _ux_press(self, widget):
        try:
            p = self._ux_palette()
            accent_pressed = p.get("accent_pressed", p.get("accent", "#c65d91"))
            if isinstance(widget, tk.Button):
                widget.configure(bg=accent_pressed)
            elif isinstance(widget, ttk.Button):
                style_name = widget.cget("style") or "TButton"
                # The theme's style.map already handles pressed state
                # Just ensure we're using the base style
                if style_name.endswith(".Hover"):
                    style_name = style_name[:-6]
                widget.configure(style=style_name)
        except Exception:
            pass

    def _ux_release(self, widget):
        try:
            p = self._ux_palette()
            accent = p.get("accent", "#c65d91")
            if isinstance(widget, tk.Button):
                widget.configure(bg=accent)
            elif isinstance(widget, ttk.Button):
                style_name = widget.cget("style") or "TButton"
                # Restore to base style
                if style_name.endswith(".Hover") or style_name.endswith(".Pressed"):
                    style_name = style_name.replace(".Hover", "").replace(".Pressed", "")
                widget.configure(style=style_name)
        except Exception:
            pass

    def _ux_text_hover(self, widget, active):
        try:
            if getattr(widget, "_no_ux_hover", False):
                return
            p = self._ux_palette()
            widget.configure(
                fg=p.get("accent_active" if active else "fg", p.get("fg")),
                cursor="hand2" if active else ""
            )
        except Exception:
            pass

    def _ux_tree_hover(self, event):
        try:
            tree = event.widget
            row = tree.identify_row(event.y)
            if not hasattr(self, "_ux_tree_hover_row"):
                self._ux_tree_hover_row = {}
            if not hasattr(self, "_ux_tree_original_tags"):
                self._ux_tree_original_tags = {}
            previous = self._ux_tree_hover_row.get(tree)
            if previous and previous != row:
                try:
                    orig_tags = self._ux_tree_original_tags.get(tree, {}).get(previous)
                    if orig_tags is not None:
                        tree.item(previous, tags=orig_tags)
                    else:
                        tree.item(previous, tags=())
                except Exception:
                    pass  # Previous item may no longer exist after tree rebuild
            if row:
                if row not in self._ux_tree_original_tags.get(tree, {}):
                    self._ux_tree_original_tags.setdefault(tree, {})[row] = tree.item(row, "tags")
                tree.item(row, tags=("ux_hover",))
                p = self._ux_palette()
                hover_bg = p.get("accent", "#c65d91")
                tree.tag_configure("ux_hover", background=hover_bg, foreground="#ffffff")
            self._ux_tree_hover_row[tree] = row
        except Exception:
            pass

    def _ux_tree_clear_hover(self, tree):
        try:
            row = getattr(self, "_ux_tree_hover_row", {}).get(tree)
            if row:
                orig_tags = getattr(self, "_ux_tree_original_tags", {}).get(tree, {}).get(row)
                if orig_tags is not None:
                    tree.item(row, tags=orig_tags)
                else:
                    tree.item(row, tags=())
            getattr(self, "_ux_tree_hover_row", {}).pop(tree, None)
        except Exception:
            pass

    def _refresh_tree_hover(self, tree):
        """Force refresh hover state for a tree - call after tree rebuild."""
        try:
            # Get mouse position relative to tree
            x = self.root.winfo_pointerx() - tree.winfo_rootx()
            y = self.root.winfo_pointery() - tree.winfo_rooty()
            # Check if mouse is over tree
            if 0 <= x <= tree.winfo_width() and 0 <= y <= tree.winfo_height():
                event = type('Event', (), {
                    'widget': tree,
                    'x': x,
                    'y': y,
                    'x_root': self.root.winfo_pointerx(),
                    'y_root': self.root.winfo_pointery()
                })()
                self._ux_tree_hover(event)
        except Exception:
            pass

    def _start_hover_polling(self):
        """Start periodic hover check to ensure glow persists."""
        def poll_hover():
            try:
                if not self._destroyed:
                    for tree in [self.bank_tree, self.wem_tree]:
                        if tree and tree.winfo_exists():
                            self._refresh_tree_hover(tree)
            except Exception:
                pass
            if not self._destroyed:
                self.root.after(100, poll_hover)
        self.root.after(100, poll_hover)

    def set_busy_state(self, busy: bool, message: str = "") -> None:
        """Call this before/after expensive BNK/WEM operations."""
        try:
            self._ux_busy = busy
            if hasattr(self, "status_var") and message:
                self.status_var.set(("⏳ " if busy else "♡ ") + message)
            self.root.configure(cursor="watch" if busy else "")
            if getattr(self, "process_button", None) is not None:
                if busy:
                    self.process_button.configure(state="disabled")
                else:
                    self._refresh_process_button()
        except Exception:
            pass

    def ux_ready(self, message: str = "Ready") -> None:
        self.set_busy_state(False, message)

    def _load_wem_descriptions(self) -> dict[str, str]:
        """Load persistent WEM descriptions with crash-safe fallbacks."""
        primary = self.wem_descriptions_path
        backup = primary.with_suffix(primary.suffix + ".bak")
        temp = primary.with_suffix(primary.suffix + ".tmp")

        # Prefer the normal file. If it is damaged by an interrupted write, fall back to
        # the last known-good backup, then to a complete temp file left by a crash.
        for candidate in (primary, backup, temp):
            try:
                if not candidate.is_file():
                    continue
                data = json.loads(candidate.read_text(encoding="utf-8"))
                if not isinstance(data, dict):
                    continue
                # Current format stores metadata beside a nested `descriptions` map.
                # Accept a legacy flat map too so an older hand-edited file is not lost.
                raw_map = data.get("descriptions") if isinstance(data.get("descriptions"), dict) else data
                out: dict[str, str] = {}
                for key, value in raw_map.items():
                    if isinstance(key, str) and isinstance(value, str):
                        text = value.strip()
                        if text:
                            out[key] = text
                return out
            except Exception as exc:
                self.log.debug("Could not read WEM descriptions from %s: %s", candidate, exc)
        return {}

    def _save_wem_descriptions(self) -> None:
        """Persist descriptions immediately using atomic replacement and a backup."""
        path = self.wem_descriptions_path
        tmp = path.with_suffix(path.suffix + ".tmp")
        bak = path.with_suffix(path.suffix + ".bak")
        payload = {
            "version": 1,
            "updated_at": _dt.datetime.now().isoformat(timespec="seconds"),
            "descriptions": dict(sorted(self.wem_descriptions.items())),
        }
        # Keep the JSON easy for users to inspect/edit manually.
        encoded = json.dumps(payload, indent=2, ensure_ascii=False)
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with tmp.open("w", encoding="utf-8", newline="\n") as fh:
                fh.write(encoded)
                fh.flush()
                with contextlib.suppress(OSError):
                    os.fsync(fh.fileno())
            if path.is_file():
                with contextlib.suppress(OSError):
                    shutil.copy2(path, bak)
            os.replace(tmp, path)
        except Exception:
            with contextlib.suppress(OSError):
                tmp.unlink()
            raise

    def _description_for_info(self, info: WemInfo) -> str:
        return str(self.wem_descriptions.get(info.key, "")).strip()

    def _update_wem_description_panel_theme(self) -> None:
        label = getattr(self, "_wem_description_label", None)
        card = getattr(self, "_wem_description_card", None)
        if label is None:
            return
        colors = getattr(self, "_theme_colors", {})
        field = colors.get("field", "#fffafd")
        fg = colors.get("fg", "#3e3640")
        muted = colors.get("muted", "#7b707b")
        accent = colors.get("accent", "#c35d91")
        for widget in (card, label):
            try:
                widget.configure(background=field)
            except Exception:
                pass
        try:
            label.configure(foreground=fg if self._wem_description_text_value else muted)
        except Exception:
            pass
        title = getattr(self, "_wem_description_title_label", None)
        if title is not None:
            try:
                title.configure(background=field, foreground=accent)
            except Exception:
                pass

    def _refresh_wem_description_panel(self) -> None:
        label = getattr(self, "_wem_description_label", None)
        if label is None:
            return
        selected = self._selected_infos()
        self._wem_description_text_value = ""
        if not selected:
            self._wem_description_title_text = "♡ Description"
            self._wem_description_text_value = "Select a WEM to see its description here.\nRight-click a selected WEM to add or edit a description."
        elif len(selected) == 1:
            info = selected[0]
            desc = self._description_for_info(info)
            self._wem_description_title_text = f"♡ Description · {self._friendly_sound_label(info)}"
            self._wem_description_text_value = desc or "No description yet. Right-click this WEM and choose ‘Add / Edit Description…’ to add one."
        else:
            descriptions = [(info, self._description_for_info(info)) for info in selected]
            nonempty = [d for _i, d in descriptions if d]
            if nonempty and len(set(nonempty)) == 1:
                self._wem_description_title_text = f"♡ Description · {len(selected)} sounds selected"
                self._wem_description_text_value = nonempty[0]
            else:
                self._wem_description_title_text = f"♡ Descriptions · {len(selected)} sounds selected"
                lines: list[str] = []
                for info, desc in descriptions:
                    label_text = self._friendly_sound_label(info)
                    lines.append(f"• {label_text}: {desc or 'No description yet.'}")
                self._wem_description_text_value = "\n".join(lines)
        try:
            label.configure(text=self._wem_description_text_value)
            label.update_idletasks()
        except Exception:
            pass
        title = getattr(self, "_wem_description_title_label", None)
        if title is not None:
            try:
                title.configure(text=self._wem_description_title_text)
            except Exception:
                pass
        self._update_wem_description_panel_theme()

    def _edit_selected_wem_description(self) -> None:
        infos = self._selected_infos()
        if not infos:
            cute_warning("WEM description", "Select one or more WEMs first.", parent=self.root)
            return

        existing = [self._description_for_info(info) for info in infos]
        shared = existing[0] if existing and all(text == existing[0] for text in existing) else ""
        count_text = "this WEM" if len(infos) == 1 else f"these {len(infos)} WEMs"

        win = tk.Toplevel(self.root)
        self._windowed_lightweight(win, "WEM description", 720, 430)
        try:
            win.transient(self.root)
            win.grab_set()
        except Exception:
            pass
        body = ttk.Frame(win, padding=18)
        body.pack(fill="both", expand=True)
        ttk.Label(body, text="♡ Add a little note", style="EditorTitle.TLabel").pack(anchor="w")
        ttk.Label(
            body,
            text=f"Write a description for {count_text}. It is saved immediately and will still be here after a restart.",
            style="EditorSub.TLabel", wraplength=660, justify="left"
        ).pack(anchor="w", pady=(5, 12))

        field_card = ttk.Frame(body, style="Card.TFrame", padding=8)
        field_card.pack(fill="both", expand=True)
        text_widget = tk.Text(
            field_card, wrap="word", height=10, undo=True,
            bg=self._theme_colors.get("field", "#fffafd"),
            fg=self._theme_colors.get("fg", "#3e3640"),
            insertbackground=self._theme_colors.get("fg", "#3e3640"),
            selectbackground=self._theme_colors.get("accent", "#c35d91"),
            selectforeground="#ffffff", relief="flat", borderwidth=0,
            font=("Segoe UI", 10), padx=10, pady=9
        )
        text_widget.pack(fill="both", expand=True)
        if shared:
            text_widget.insert("1.0", shared)
        text_widget.focus_set()

        footer = ttk.Frame(body)
        footer.pack(fill="x", pady=(12, 0))
        hint = ttk.Label(footer, text="Tip: short, useful notes work best — the full text is shown in the WEM panel.", style="EditorHint.TLabel")
        hint.pack(side="left", fill="x", expand=True)

        def close_save() -> None:
            value = text_widget.get("1.0", "end-1c").strip()
            changed = False
            for info in infos:
                old = self._description_for_info(info)
                if old == value:
                    continue
                if value:
                    self.wem_descriptions[info.key] = value
                else:
                    self.wem_descriptions.pop(info.key, None)
                changed = True
            if changed:
                try:
                    self._save_wem_descriptions()
                except Exception as exc:
                    cute_error(
                        "Could not save description",
                        f"I couldn't safely save the description.\n\n{exc}",
                        parent=win,
                        hint="The existing saved descriptions were left untouched where possible."
                    )
                    return
            self._render_wems()
            self.status_var.set(
                f"♡ Description {'saved' if value else 'cleared'} for {len(infos)} WEM(s)"
            )
            win.destroy()

        def cancel() -> None:
            win.destroy()

        ttk.Button(footer, text="Cancel", style="Tool.TButton", command=cancel).pack(side="right", padx=(6, 0))
        ttk.Button(footer, text="Save description ♡", style="Big.TButton", command=close_save).pack(side="right")
        win.bind("<Escape>", lambda _e: cancel())
        win.bind("<Control-Return>", lambda _e: close_save())
        self._raise_child(win)

    def _clear_selected_wem_description(self) -> None:
        infos = self._selected_infos()
        if not infos:
            cute_warning("WEM description", "Select one or more WEMs first.", parent=self.root)
            return
        changed = False
        for info in infos:
            if info.key in self.wem_descriptions:
                self.wem_descriptions.pop(info.key, None)
                changed = True
        if not changed:
            self.status_var.set("♡ No saved descriptions to clear")
            return
        try:
            self._save_wem_descriptions()
        except Exception as exc:
            cute_error("Could not save description", f"I couldn't safely save the change.\n\n{exc}", parent=self.root)
            return
        self._render_wems()
        self.status_var.set(f"♡ Cleared descriptions for {len(infos)} WEM(s)")

    def _load_ui_settings(self) -> dict[str, Any]:
        defaults = {
            "show_technical_names": False, "show_advanced_details": False,
            "theme": "Cute Pastel", "density": "Comfortable", "confirm_install": False,
            "fullscreen": True, "wem_sort": "Sound #", "wem_sort_order": "Ascending",
            "favorite_wem_keys": [], "recent_sources": [],
            "first_run_complete": False, "wwise_root": "", "wwise_console_path": "",
            "tutorial_seen": False,
            "last_update_prompt_version": "", "last_app_version": "",
            "update_manifest_url": "", "auto_update_check": True,        }
        try:
            data = json.loads(self.settings_path.read_text(encoding="utf-8")) if self.settings_path.is_file() else {}
            if isinstance(data, dict):
                defaults.update(data)
        except Exception:
            pass
        if not isinstance(defaults.get("favorite_wem_keys"), list):
            defaults["favorite_wem_keys"] = []
        if not isinstance(defaults.get("recent_sources"), list):
            defaults["recent_sources"] = []
        defaults["last_app_version"] = APP_VERSION
        return defaults

    def _save_ui_settings(self) -> None:
        self.settings.update({
            "show_technical_names": bool(self.show_technical_names_var.get()),
            "show_advanced_details": bool(self.show_advanced_details_var.get()),
            "theme": self.theme_var.get(), "density": self.density_var.get(),
            "custom_theme_colors": dict(self.custom_theme_colors),
            "workspace": dict(self.workspace_custom),
            "visual_looks": dict(self.settings.get("visual_looks", {})),
            "confirm_install": bool(self.confirm_install_var.get()),
            "show_terminal": bool(self.show_terminal_var.get()),
            "game_audio_dir": str(self.game_target_var.get()),
            "fullscreen": bool(self.fullscreen_var.get()),
            "wem_sort": self.wem_sort_var.get(),
            "wem_sort_order": self.wem_sort_order_var.get(),
            "favorite_wem_keys": sorted(self.favorite_wem_keys),
            "recent_sources": list(self.recent_sources[:10]),
            "first_run_complete": bool(self.settings.get("first_run_complete", False)),
            "tutorial_seen": bool(self.settings.get("tutorial_seen", False)),
            "wwise_root": str(self.settings.get("wwise_root", "")),
            "wwise_console_path": str(self.settings.get("wwise_console_path", "")),
            "last_app_version": APP_VERSION,
            "update_manifest_url": str(self.settings.get("update_manifest_url", "")),
            "auto_update_check": bool(self.settings.get("auto_update_check", True)),
        })
        try:
            self.settings_path.write_text(json.dumps(self.settings, indent=2), encoding="utf-8")
        except Exception as exc:
            self.log.debug("Could not save UI settings: %s", exc)

    @staticmethod
    def _valid_hex_color(value: Any) -> bool:
        text = str(value or "").strip()
        if not text.startswith("#") or len(text) not in (4, 7):
            return False
        digits = text[1:]
        return all(ch in "0123456789abcdefABCDEF" for ch in digits)

    def _sanitize_custom_theme_colors(self, value: Any) -> dict[str, str]:
        allowed = {
            "bg", "fg", "field", "panel", "sel", "accent", "border",
            "muted", "success", "warning", "canvas", "soft_accent", "soft_glow",
            "accent_active", "accent_pressed",
        }
        source = value if isinstance(value, dict) else {}
        return {k: str(source[k]).strip() for k in allowed if k in source and self._valid_hex_color(source[k])}

    def _sanitize_workspace_custom(self, value: Any) -> dict[str, Any]:
        source = value if isinstance(value, dict) else {}
        try:
            ratio = float(source.get("left_ratio", 0.34))
        except Exception:
            ratio = 0.34
        ratio = max(0.25, min(0.55, ratio))
        try:
            preview_height = int(source.get("preview_height", 72))
        except Exception:
            preview_height = 72
        preview_height = max(56, min(150, preview_height))
        return {
            "left_ratio": ratio,
            "preview_height": preview_height,
            "show_flow": bool(source.get("show_flow", True)),
        }

    def _refresh_target_path_label(self) -> None:
        try:
            label = getattr(self, "_target_path_label", None)
            if label is not None and label.winfo_exists():
                label.configure(text=self._friendly_target_label())
        except (tk.TclError, RuntimeError):
            pass

    def _friendly_target_label(self) -> str:
        try:
            path = Path(self.game_target_var.get()).expanduser()
            parts = [part for part in path.parts if part not in (path.anchor or "")]
            if len(parts) > 3:
                return "…\\" + "\\".join(parts[-3:])
            return str(path)
        except Exception:
            return str(self.game_target_var.get())

    def _friendly_bank_label(self, bank: Path) -> str:
        if bank.suffix.lower() == ".wem":
            return bank.name if self.show_technical_names_var.get() else f"Sound: {bank.stem}"
        category, label = self.bank_categories.get(str(bank), categorise_brawlhalla_bnk(bank))
        if category == "Sound Effects":
            category = "Other / Uncategorized"
        if category == "Other / Uncategorized" or not label or label == bank.stem:
            try:
                n = self.discovered_banks.index(bank) + 1
            except ValueError:
                n = 1
            label = f"Other sound group {n}"
        if self.show_technical_names_var.get():
            return f"{label}  [{bank.name}]"
        return label

    def _friendly_sound_label(self, info: WemInfo) -> str:
        return f"Sound {info.index}  [{info.display_name}]" if self.show_technical_names_var.get() else f"Sound {info.index}"

