        colors.update(self.custom_theme_colors)
        # Derived action states stay visually tied to the user's accent. Explicit
        # overrides are still honored when present in settings.
        if "accent_active" not in self.custom_theme_colors:
            colors["accent_active"] = colors["accent"]
        if "accent_pressed" not in self.custom_theme_colors:
            colors["accent_pressed"] = colors["accent"]
        colors.update({"button_text": "#ffffff", "selected_text": "#ffffff"})
        self._theme_colors = colors

        # ttk's native Windows theme can ignore custom button backgrounds. Force
        # a styleable theme and make the action hierarchy visually explicit.
        try:
            if style.theme_use() != "clam":
                style.theme_use("clam")
        except tk.TclError:
            pass
        bg, fg, field, sel = colors["bg"], colors["fg"], colors["field"], colors["sel"]
        accent, border = colors["accent"], colors["border"]
        muted, disabled = colors["muted"], colors["disabled"]

