    def _cute_log_message(self, message: str) -> str:
        text = message
        lower = text.lower()
        replacements = (
            ("starting scan", "♡ Warming up and checking your Brawlhalla sounds…"),
            ("scanning brawlhalla bnks", "♡ Looking for your sound groups…"),
            ("unpacking", "✿ Opening a sound group…"),
            ("repacking", "✿ Putting your new sound back together…"),
            ("backup created", "♡ Temporary safety copy created during the install…"),
            ("downloading", "♡ Fetching your audio…"),
            ("temporary processing files cleaned up", "♡ Little work files tidied away!"),
            ("matched wav duration", "♪ Matching the sound length…"),
            ("audio effects applied", "♪ Polishing the audio…"),
            ("replacing", "♡ Swapping the sound…"),
            ("installed", "♡ Your new sound is in the game!"),
            ("verification", "✓ Giving everything a quick safety check…"),
            ("could not find", "♡ I could not find that yet…"),
            ("failed", "♡ Something needs another little try…"),
            ("success", "♡ Success!"),
            ("complete", "♡ Finished!"),
            ("loading", "✿ Loading your sounds…"),
            ("opening", "✿ Opening it up…"),
            ("closing", "♡ Tucking that away…"),
            ("done", "♡ All done!"),
            ("ready", "♡ Ready when you are!"),
        )
        for needle, friendly in replacements:
            if needle in lower:
                return friendly
        if " | " in text:
            text = text.split(" | ", 2)[-1]
        if any(marker in text.lower() for marker in ("\\", "/authoring/", "\\authoring\\")):
            return "♡ Working behind the scenes…"
        return ("♡ " + text) if text and not text.startswith(("♡", "✿", "♪", "✓")) else text

    def _configure_screen_scaling(self) -> None:

        try:
            sw = max(1, self.root.winfo_screenwidth())
            sh = max(1, self.root.winfo_screenheight())
            base = min(sw / 1920.0, sh / 1080.0)
            scale = max(0.88, min(1.18, base))

            current = float(self.root.tk.call("tk", "scaling"))
            self.root.tk.call("tk", "scaling", max(current, 1.333 * scale))
        except Exception:
            pass

    def toggle_fullscreen(self) -> None:
        self.fullscreen_var.set(not bool(self.fullscreen_var.get()))
        self._apply_fullscreen_state()

    def _apply_fullscreen_state(self) -> None:
        try:
            active = bool(self.fullscreen_var.get())
            self.root.attributes("-fullscreen", active)
            if not active:
                self._maximize_window(self.root)
            else:
                self.root.state("normal")
                self.root.attributes("-fullscreen", True)
                self.root.lift()
            self.status_var.set("⛶ Full screen on" if active else "⛶ Full screen off")
        except Exception as exc:
            self.log.debug("Could not toggle full screen: %s", exc)

    def _terminal_flag_path(self) -> Path:
        try:
            return Path(__file__).resolve().parent / "show_terminal.flag"
        except Exception:
            return Path.cwd() / "show_terminal.flag"

    def _sync_terminal_flag_file(self) -> None:
        try:
            flag = self._terminal_flag_path()
            if bool(self.show_terminal_var.get()):
                with contextlib.suppress(Exception):
                    flag.write_text("1", encoding="utf-8")
            else:
                with contextlib.suppress(Exception):
                    if flag.is_file():
                        flag.unlink()
        except Exception:
            pass

    def _apply_terminal_state(self) -> None:
        if bool(self.show_terminal_var.get()):
            ensure_console_window(getattr(self, "log", None))
        else:
            release_console_window(getattr(self, "log", None))
        self._sync_terminal_flag_file()

    def _child_focus_in(self, win: tk.Misc, _event=None) -> None:
        try:
            if win.winfo_exists():
                self._active_child = win
                self._last_child_title = str(win.title())
                self._child_windows.add(win)
        except Exception:
            pass

    def _restore_last_child(self, _event=None) -> None:

        win = self._active_child
        try:
            if win is not None and win.winfo_exists() and str(win.state()) != "withdrawn":
                self.root.after_idle(lambda w=win: self._raise_child(w))
        except Exception:
            self._active_child = None

    def reopen_last_workspace(self) -> None:

        win = self._active_child
        try:
            if win is not None and win.winfo_exists():
                self._raise_child(win)
                return
        except Exception:
            pass
        self._active_child = None

        title = (self._last_child_title or "").lower()
        try:
            if "replace sound" in title or "replace sounds" in title:
                self.quick_replace()
            elif "preview" in title:
                self.preview_selected_wems()
            elif "how to use" in title:
                self.show_quick_guide()
            elif "settings" in title:
                self.show_settings()
            elif "categor" in title:
                self.show_category_chooser()
            else:
                self.root.lift()
                self.root.focus_force()
        except Exception as exc:
            self.log.debug("Could not reopen last workspace: %s", exc)
            self.root.lift(); self.root.focus_force()

    def _raise_child(self, win: tk.Misc) -> None:
        try:
            if not win.winfo_exists():
                return
            win.deiconify()
            win.lift(self.root)

            win.attributes("-topmost", True)
            win.after(180, lambda w=win: w.attributes("-topmost", False) if w.winfo_exists() else None)
            win.focus_force()
        except Exception:
            pass

    def _windowed_lightweight(self, win: tk.Misc, title: str = "", width: int = 860, height: int = 620) -> tk.Misc:

        try:
            if title:
                win.title(title)
            self._child_windows.add(win)
            self._active_child = win
            self._last_child_title = str(win.title())
            win.transient(self.root)
            win.resizable(True, True)
            win.protocol("WM_DELETE_WINDOW", win.destroy)
            win.bind("<FocusIn>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Map>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Destroy>", lambda e, w=win: self._cleanup_child(w) if e.widget is w else None, add="+")
            self._fit_dialog(win, width=width, height=height, margin=28)
            self._schedule_chrome_paint(win)
            win.lift(self.root)
            win.focus_force()
            return win
        except Exception:
            try:
                win.lift(); win.focus_force()
            except Exception:
                pass
            return win

    def _replacement_dialog(self, win: tk.Misc, title: str = "") -> tk.Misc:
        """Create a replacement editor window that survives Alt-Tab/activation cleanly.

        The replacement editor used to be an overrideredirect window. On Windows,
        borderless transient Toplevels can lose normal keyboard/mouse activation
        after the application is Alt-Tabbed away and back, making Entry widgets
        appear visible but stop accepting clicks. Keep the same work-area sizing
        and taskbar-safe geometry, but use a normal managed Toplevel for reliable
        activation and focus.
        """
        try:
            if title:
                win.title(title)
            self._child_windows.add(win)
            self._active_child = win
            self._last_child_title = str(win.title())
            win.transient(self.root)
            win.resizable(True, True)
            win.protocol("WM_DELETE_WINDOW", win.destroy)
            win.bind("<FocusIn>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Map>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Destroy>", lambda e, w=win: self._cleanup_child(w) if e.widget is w else None, add="+")
            win.bind("<Alt-KeyRelease>", lambda e, w=win: self._raise_child(w), add="+")
            self._fit_dialog(win, 1280, 780, margin=8)
            self._schedule_chrome_paint(win)
            win.lift(self.root)

                                                                                  

            win.after_idle(lambda w=win: w.focus_force() if w.winfo_exists() else None)
            return win
        except Exception:
            try:
                win.overrideredirect(False)
                win.lift()
                win.focus_force()
            except Exception:
                pass
            return win

    def _group_replacement_dialog(self, win: tk.Misc, title: str = "") -> tk.Misc:
        """Open the multi-sound replacement editor across the usable screen area."""
        try:
            if title:
                win.title(title)
            self._child_windows.add(win)
            self._active_child = win
            self._last_child_title = str(win.title())
            win.transient(self.root)
            win.resizable(True, True)
            try:
                win.configure(bg=self._theme_colors.get("bg", "#fff7fb"))
            except Exception:
                pass
            win.protocol("WM_DELETE_WINDOW", win.destroy)
            win.bind("<FocusIn>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Map>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Destroy>", lambda e, w=win: self._cleanup_child(w) if e.widget is w else None, add="+")
            win.bind("<Alt-KeyRelease>", lambda e, w=win: self._raise_child(w), add="+")
            win.minsize(960, 600)
            win.update_idletasks()
            try:
                win.attributes("-fullscreen", False)
                win.overrideredirect(False)
                win.state("zoomed")
            except Exception:
                left, top, right, bottom = self._windows_work_area(win)
                win.geometry(f"{max(960, right-left)}x{max(600, bottom-top)}+{left}+{top}")
            win.update_idletasks()
            if win.state() != "zoomed":
                left, top, right, bottom = self._windows_work_area(win)
                win.geometry(f"{max(960, right-left)}x{max(600, bottom-top)}+{left}+{top}")
            win.update_idletasks()
            win.lift(self.root)
            win.after(80, lambda w=win: (w.lift(), w.focus_force()) if w.winfo_exists() else None)
            return win
        except Exception:
            try:
                win.overrideredirect(False)
                win.state("zoomed")
                win.lift()
                win.focus_force()
            except Exception:
                pass
            return win

    def _borderless_fullscreen(self, win: tk.Misc, title: str = "") -> tk.Misc:

        try:
            if title:
                win.title(title)
            self._child_windows.add(win)
            self._active_child = win
            self._last_child_title = str(win.title())
            win.transient(self.root)
            win.resizable(True, True)
            win.protocol("WM_DELETE_WINDOW", win.destroy)
            win.bind("<FocusIn>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Map>", lambda e, w=win: self._child_focus_in(w, e), add="+")
            win.bind("<Destroy>", lambda e, w=win: self._cleanup_child(w) if e.widget is w else None, add="+")
            win.bind("<Alt-KeyRelease>", lambda e, w=win: self._raise_child(w), add="+")

                                                                                 

            win.overrideredirect(True)
            win.attributes("-fullscreen", False)
            win.state("normal")
            win.update_idletasks()
            left, top, right, bottom = self._windows_work_area(win)
            margin = 8
            width = max(640, right - left - margin * 2)
            height = max(420, bottom - top - margin * 2)
            win.geometry(f"{width}x{height}+{left + margin}+{top + margin}")
            win.update_idletasks()
            self._clamp_window_to_work_area(win, margin=8)
            win.bind("<Configure>", lambda _e, w=win: self._clamp_window_to_work_area(w, margin=8), add="+")
            win.lift()
            win.focus_force()
            return win
        except Exception:

            try:
                win.overrideredirect(False)
                win.attributes("-fullscreen", False)
                win.state("zoomed")
                win.lift()
                win.focus_force()
            except Exception:
                pass
            return win

    def _cleanup_child(self, win: tk.Misc) -> None:
        try:
            self._child_windows.discard(win)
        except Exception:
            pass
        try:
            if self._active_child is win:
                self._active_child = None
                self.root.after_idle(lambda: self.root.lift())
        except Exception:
            pass

    def _windowed_window(self, win: tk.Misc, width: int = 920, height: int = 620) -> None:

        try:
            win.resizable(True, True)
            win.update_idletasks()
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            width = min(max(720, width), max(720, sw - 120))
            height = min(max(480, height), max(480, sh - 140))
            x = max(0, (sw - width) // 2)
            y = max(0, (sh - height) // 2)
            win.geometry(f"{width}x{height}+{x}+{y}")
        except Exception:
            pass

    def _maximize_window(self, win: tk.Misc) -> None:

        try:

            if win is self.root:
                win.resizable(True, True)
                win.attributes("-fullscreen", False)
                win.state("normal")
            win.update_idletasks()
            left, top, right, bottom = self._windows_work_area(win)

            margin = 8
            width = max(760, right - left - margin * 2)
            height = max(560, bottom - top - margin * 2)
            x = left + margin
            y = top + margin
            win.geometry(f"{width}x{height}+{x}+{y}")
            win.update_idletasks()

            self._clamp_window_to_work_area(win, margin=4)
            win.lift()
        except Exception:

            try:
                sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
                win.geometry(f"{max(760, sw-32)}x{max(560, sh-110)}+16+16")
            except Exception:
                pass

    def _windows_work_area(self, win: tk.Misc) -> tuple[int, int, int, int]:

        if os.name != "nt":
            return (0, 0, win.winfo_screenwidth(), win.winfo_screenheight())
        import ctypes
        from ctypes import wintypes
        class RECT(ctypes.Structure):
            _fields_ = [("left", wintypes.LONG), ("top", wintypes.LONG),
                        ("right", wintypes.LONG), ("bottom", wintypes.LONG)]
        class MONITORINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", RECT),
                        ("rcWork", RECT), ("dwFlags", wintypes.DWORD)]
        user32 = ctypes.windll.user32
        hwnd = wintypes.HWND(int(win.winfo_id()))
        monitor = user32.MonitorFromWindow(hwnd, 2)
        mi = MONITORINFO(); mi.cbSize = ctypes.sizeof(MONITORINFO)
        if monitor and user32.GetMonitorInfoW(monitor, ctypes.byref(mi)):
            rc = mi.rcWork
            left, top, right, bottom = int(rc.left), int(rc.top), int(rc.right), int(rc.bottom)
        else:
            left, top, right, bottom = 0, 0, win.winfo_screenwidth(), win.winfo_screenheight()

        taskbar = user32.FindWindowW("Shell_TrayWnd", None)
        if taskbar:
            tr = RECT()
            if user32.GetWindowRect(taskbar, ctypes.byref(tr)):
                tl, tt, tright, tb = int(tr.left), int(tr.top), int(tr.right), int(tr.bottom)
                if tl <= right and tright >= left and tt >= top:

                    if tb >= bottom - 4 and tt < bottom:
                        bottom = min(bottom, tt)

                    elif tt <= top + 4 and tb > top:
                        top = max(top, tb)

                    elif tright <= left + 4:
                        left = max(left, tright)
                    elif tl >= right - 4:
                        right = min(right, tl)
        return (left, top, right, bottom)

    def _clamp_window_to_work_area(self, win: tk.Misc, margin: int = 4) -> None:

        try:
            win.update_idletasks()
            left, top, right, bottom = self._windows_work_area(win)
            wr = win.winfo_rootx(), win.winfo_rooty(), win.winfo_rootx() + win.winfo_width(), win.winfo_rooty() + win.winfo_height()
            x0, y0, x1, y1 = wr
            dx = 0
            dy = 0
            if x0 < left + margin:
                dx = (left + margin) - x0
            elif x1 > right - margin:
                dx = (right - margin) - x1
            if y0 < top + margin:
                dy = (top + margin) - y0
            elif y1 > bottom - margin:
                dy = (bottom - margin) - y1
            new_w = max(760, min(win.winfo_width(), (right - left) - margin * 2))
            new_h = max(560, min(win.winfo_height(), (bottom - top) - margin * 2))
            new_x = x0 + dx
            new_y = y0 + dy

            if x1 - x0 > (right - left) - margin * 2:
                new_w = max(760, (right - left) - margin * 2)
            if y1 - y0 > (bottom - top) - margin * 2:
                new_h = max(560, (bottom - top) - margin * 2)
            if new_w != win.winfo_width() or new_h != win.winfo_height() or dx or dy:
                win.geometry(f"{new_w}x{new_h}+{new_x}+{new_y}")
                win.update_idletasks()
        except Exception:
            pass

    def _fit_dialog(self, win: tk.Misc, width: int, height: int, margin: int = 18) -> None:

        try:

            if win is self.root:
                win.resizable(True, True)
                win.attributes("-fullscreen", False)
                win.state("normal")
            win.update_idletasks()
            left, top, right, bottom = self._windows_work_area(win)
            avail_w = max(640, right - left - margin * 2)
            avail_h = max(420, bottom - top - margin * 2)
            ww = min(max(640, width), avail_w)
            wh = min(max(420, height), avail_h)
            x = left + max(margin, (right - left - ww) // 2)
            y = top + max(margin, (bottom - top - wh) // 2)
            win.geometry(f"{ww}x{wh}+{x}+{y}")
            win.update_idletasks()
            self._clamp_window_to_work_area(win, margin=margin)
        except Exception:
            pass

    _STATUS_KINDS = {
        "info": ("♡ ", "StatusInfo.TLabel"),
        "progress": ("✿ ", "StatusProgress.TLabel"),
        "success": ("✓ ", "StatusSuccess.TLabel"),
        "warning": ("⚠ ", "StatusWarning.TLabel"),
        "error": ("✗ ", "StatusError.TLabel"),
    }

    def _set_status(self, text: str, kind: str = "info") -> None:
        """Set the footer status text with a cute but meaningful severity style."""
        try:
            prefix, style_name = self._STATUS_KINDS.get(kind, self._STATUS_KINDS["info"])
            label = getattr(self, "_status_label", None)
            if label is not None:
                label.configure(style=style_name)
            self.status_var.set(text if (text and text.startswith(prefix)) else f"{prefix}{text}")
        except Exception:
            try:
                self.status_var.set(text)
            except Exception:
                pass

    def _friendly_error(self, exc: BaseException, title: Optional[str] = None, parent=None) -> None:
        """Show an error with a friendly title, understandable message, and a fix hint."""
        auto_title, friendly_message, hint = explain_error(exc)
        cute_error(title or auto_title, friendly_message, parent=parent, hint=hint, copy_text=str(exc))

    def _set_loading(self, active: bool, text: Optional[str] = None) -> None:
        self._loading_active = active
        if text:
            self.status_var.set(text)
        if self.loading_bar is None:
            return
        try:
            if active:
                self.loading_bar.configure(mode="indeterminate")
                self.loading_bar.start(12)
            else:
                self.loading_bar.stop()
                self.loading_bar.configure(mode="determinate", value=0)
        except Exception:
            pass

    def _apply_density(self) -> None:
        compact = self.density_var.get() == "Compact"
        style = ttk.Style(self.root)
        style.configure("Treeview", rowheight=23 if compact else 27)
        style.configure("TButton", padding=(8, 4) if compact else (10, 6))
        style.configure("Tool.TButton", padding=(9, 5) if compact else (10, 6))
        style.configure("Big.TButton", padding=(13, 7) if compact else (16, 9))
        style.configure("Action.TButton", padding=(11, 6) if compact else (14, 8))
        style.configure("Subsection.TLabel", font=("Segoe UI", 9, "bold") if compact else ("Segoe UI", 10, "bold"))
        style.configure("Section.TLabel", font=("Segoe UI", 12, "bold") if compact else ("Segoe UI", 13, "bold"))
        if compact:
            self.root.minsize(900, 560)
        else:
            self.root.minsize(1040, 700)

    def _configure_style(self) -> None:
        style = ttk.Style(self.root)
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure("App.TFrame", padding=0)
        style.configure("Hero.TLabel", font=("Segoe UI", 23, "bold"))
        style.configure("HeroSub.TLabel", font=("Segoe UI", 10))
        style.configure("Big.TButton", font=("Segoe UI", 10, "bold"), padding=(13, 7))
        style.configure("Action.TButton", font=("Segoe UI", 10, "bold"), padding=(9, 5))
        style.configure("Tool.TButton", font=("Segoe UI", 9, "bold"), padding=(8, 4))
        style.configure("Help.TButton", font=("Segoe UI", 10, "bold"), padding=(12, 6))
        style.configure("Category.TButton", font=("Segoe UI", 10, "bold"), padding=(10, 7))
        style.configure("Small.TLabel", font=("Segoe UI", 9))
        style.configure("Error.TLabel", font=("Segoe UI", 9), foreground=self._theme_colors.get("accent_pressed", "#a74774"))
        style.configure("Treeview", rowheight=30, font=("Segoe UI", 10))
        style.configure("Treeview.Heading", font=("Segoe UI", 9, "bold"), padding=5)

    def _add_tooltip(self, widget: tk.Misc, text: str) -> None:
        """Lightweight delayed tooltip for dense controls; no extra windows until needed."""
        tip_id = {"value": None}
        bubble = {"win": None}
        def hide(_event=None) -> None:
            after = tip_id.get("value")
            if after is not None:
                with contextlib.suppress(Exception):
                    widget.after_cancel(after)
                tip_id["value"] = None
            win = bubble.get("win")
            if win is not None:
                with contextlib.suppress(Exception):
                    win.destroy()
                bubble["win"] = None
        def show(_event=None) -> None:
            hide()
            def create() -> None:
                try:
                    if not widget.winfo_exists() or not widget.winfo_viewable():
                        return
                    x = widget.winfo_rootx() + max(0, widget.winfo_width() // 2 - 120)
                    y = widget.winfo_rooty() + widget.winfo_height() + 6
                    win = tk.Toplevel(widget)
                    bubble["win"] = win
                    win.overrideredirect(True)
                    win.attributes("-topmost", True)
                    frame = tk.Frame(win, bg=self._theme_colors.get("field", "#ffffff"),
                                     highlightthickness=1, highlightbackground=self._theme_colors.get("border", "#cccccc"))
                    frame.pack()
                    tk.Label(frame, text=text, bg=self._theme_colors.get("field", "#ffffff"),
                             fg=self._theme_colors.get("fg", "#333333"), font=("Segoe UI", 9),
                             wraplength=280, justify="left", padx=9, pady=6).pack()
                    win.geometry(f"+{x}+{y}")
                except Exception:
                    pass
            tip_id["value"] = widget.after(650, create)
        widget.bind("<Enter>", show, add="+")
        widget.bind("<Leave>", hide, add="+")
        widget.bind("<ButtonPress>", hide, add="+")

    def _make_overflow_menu(self, owner: tk.Misc, items: list[tuple[str, Callable[[], Any]]]) -> tk.Menu:
        menu = tk.Menu(owner, tearoff=False)
        for label, command in items:
            if label == "-":
                menu.add_separator()
            else:
                menu.add_command(label=label, command=command)
        return menu

    def _open_dir(self, path: Path) -> None:
        try:
            path.mkdir(parents=True, exist_ok=True)
            os.startfile(path)
        except Exception as exc:
            cute_error("Open folder failed", str(exc))

    def open_game_folder(self) -> None:
        self._open_dir(Path(self.game_target_var.get()))

    def _pick_game_folder(self) -> None:
        try:
            cur = str(self.game_target_var.get() or "")
            start = cur if cur and Path(os.path.expandvars(os.path.expanduser(cur))).is_dir() else str(Path.home())
        except Exception:
            start = str(Path.home())
        try:
            chosen = filedialog.askdirectory(title="Select your Brawlhalla audio folder (the one with the .bnk files)", initialdir=start, parent=self.root)
        except Exception:
            chosen = ""
        if not chosen:
            return
        try:
            self.game_target_var.set(chosen)
            self.settings["game_audio_dir"] = chosen
            self._save_ui_settings()
        except Exception:
            pass
        self.auto_scan_game_banks()

    def _enqueue_log(self, message: str) -> None:
        self.queue.put(message)

    def _drain_log(self) -> None:

        latest = None
        try:
            while True:
                latest = self.queue.get_nowait()
        except queue.Empty:
            pass
        if latest and not self._destroyed:

            if " | DEBUG" not in latest:
                upper = latest.upper()
                if " | ERROR" in upper or " | CRITICAL" in upper:
                    message = latest.split(" | ", 2)[-1].strip()
                    self._set_status(f"I could not finish that: {message}", "error")
                elif " | WARNING" in upper:
                    message = latest.split(" | ", 2)[-1].strip()
                    self._set_status(f"Heads-up: {message}", "warning")
                else:
                    self._set_status(self._cute_log_message(latest), "progress")
        if not self._destroyed:
            self.root.after(100, self._drain_log)

    def _install_global_wheel(self) -> None:

        self.root.bind_all("<MouseWheel>", self._wheel_global, add="+")
        self.root.bind_all("<Shift-MouseWheel>", self._wheel_shift, add="+")

    # ------------------------------------------------------------------
    # Keyboard accessibility
    # ------------------------------------------------------------------
    def _install_keyboard_navigation(self) -> None:
        """Make the complete GUI usable from the keyboard without changing mouse behavior.

        A dedicated bindtag runs before widget/class bindings, so global shortcuts keep
        working even after the user clicks an Entry, Combobox, button, or other control.
        """
        self._keyboard_bindtag = "CutieKeyboard"
        try:
            self.root.bind_class(self._keyboard_bindtag, "<Control-b>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self.bank_search_entry)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-B>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self.bank_search_entry)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-l>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self._main_wem_search)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-L>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self._main_wem_search)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-f>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self._main_wem_search)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-F>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self._focus_widget(self._main_wem_search)))
            self.root.bind_class(self._keyboard_bindtag, "<Control-k>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self.show_category_chooser()))
            self.root.bind_class(self._keyboard_bindtag, "<Control-K>", lambda e: self._main_shortcut_dispatch(e, lambda _e: self.show_category_chooser()))
            self.root.bind_class(self._keyboard_bindtag, "<F1>", self._keyboard_guide)
            self.root.bind_class(self._keyboard_bindtag, "<Escape>", self._keyboard_escape)
            self.root.bind_class(self._keyboard_bindtag, "<Control-r>", lambda e: self._text_safe_root_action(e, self.quick_replace))
            self.root.bind_class(self._keyboard_bindtag, "<Control-p>", lambda e: self._text_safe_root_action(e, self.preview_selected_wems))
        except Exception:
            pass
        self.root.bind_all("<FocusIn>", self._ensure_keyboard_bindtag, add="+")
        self._ensure_keyboard_bindtag(type("_E", (), {"widget": self.root})())
        # Fast focus targets in the main workspace.
        shortcuts = self._get_customizable_shortcuts()
        # Install the full shortcut set on the priority bindtag too. This is what
        # keeps shortcuts reliable after clicking Entries/Comboboxes/buttons whose
        # normal Tk class bindings would otherwise consume combinations such as
        # Ctrl+Left, Ctrl+Right, Ctrl+E, or Ctrl+S.
        for sequence, callback in shortcuts.items():
            try:
                self.root.bind_class(
                    self._keyboard_bindtag, sequence,
                    lambda e, cb=callback: self._main_shortcut_dispatch(e, cb),
                )
            except Exception:
                pass
        for sequence, callback in (
            ("<Control-e>", lambda _e: self.export_selected_wems()),
            ("<F5>", lambda _e: self.auto_scan_game_banks()),
            ("<F6>", lambda _e: self.reopen_last_workspace()),
            ("<F11>", lambda _e: self.toggle_fullscreen()),
        ):
            try:
                self.root.bind_class(
                    self._keyboard_bindtag, sequence,
                    lambda e, cb=callback: self._main_shortcut_dispatch(e, cb),
                )
            except Exception:
                pass

        for sequence, callback in shortcuts.items():
            self.root.bind_all(sequence, lambda e, cb=callback: self._main_shortcut_dispatch(e, cb), add="+")

        # Make the standard tree navigation behave like a normal multi-select list.
        for tree, kind in ((getattr(self, "bank_tree", None), "bank"), (getattr(self, "wem_tree", None), "wem")):
            if tree is None:
                continue
            tree.configure(takefocus=True)
            for sequence, handler in (
                ("<Up>", lambda e, t=tree, k=kind: self._tree_keyboard_move(t, k, -1, e)),
                ("<Down>", lambda e, t=tree, k=kind: self._tree_keyboard_move(t, k, 1, e)),
                ("<Prior>", lambda e, t=tree, k=kind: self._tree_keyboard_page(t, k, -1, e)),
                ("<Next>", lambda e, t=tree, k=kind: self._tree_keyboard_page(t, k, 1, e)),
                ("<Home>", lambda e, t=tree, k=kind: self._tree_keyboard_home_end(t, k, False, e)),
                ("<End>", lambda e, t=tree, k=kind: self._tree_keyboard_home_end(t, k, True, e)),
                ("<Control-a>", lambda e, t=tree, k=kind: self._tree_keyboard_select_all(t, k, e)),
                ("<Control-A>", lambda e, t=tree, k=kind: self._tree_keyboard_select_all(t, k, e)),
                ("<Shift-Home>", lambda e, t=tree, k=kind: self._tree_keyboard_home_end(t, k, False, e)),
                ("<Shift-End>", lambda e, t=tree, k=kind: self._tree_keyboard_home_end(t, k, True, e)),
            ):
                tree.bind(sequence, handler, add="+")
            tree.bind("<space>", lambda e, t=tree, k=kind: self._tree_keyboard_activate(t, k, e), add="+")

            if kind == "bank":
                tree.bind("<Return>", lambda e, t=tree: self._tree_keyboard_activate(t, "bank", e), add="+")
                # Delete is already part of the original bank-tree behavior; do not
                # add a second handler because that would unload twice.
        # Search/filter controls should be obvious focus destinations.
        for attr in ("bank_search_entry", "_main_wem_search", "category_view_button"):
            widget = getattr(self, attr, None)
            if widget is not None:
                try:
                    widget.configure(takefocus=True)
                except Exception:
                    pass

        # Do not rely on a FocusIn event to install the priority tag. Mouse users can
        # click directly into any control before Tk delivers the focus event, so make
        # the ordering explicit for the complete main-window widget tree now.
        self._install_keyboard_bindtag_tree(self.root)


    def _install_keyboard_bindtag_tree(self, parent: tk.Misc) -> None:
        tag = getattr(self, "_keyboard_bindtag", None)
        if not tag:
            return
        try:
            widgets = list(parent.winfo_children())
        except Exception:
            widgets = []
        for widget in widgets:
            try:
                tags = list(widget.bindtags())
                if tag in tags:
                    tags.remove(tag)
                tags.insert(0, tag)
                widget.bindtags(tuple(tags))
            except Exception:
                pass
            self._install_keyboard_bindtag_tree(widget)


    def _ensure_keyboard_bindtag(self, event: Any) -> str:
        """Put the app keyboard dispatcher ahead of widget/class bindings for the focused widget."""
        tag = getattr(self, "_keyboard_bindtag", None)
        widget = getattr(event, "widget", None)
        if not tag or widget is None:
            return "continue"
        try:
            tags = list(widget.bindtags())
            if tag in tags:
                tags.remove(tag)
            tags.insert(0, tag)
            widget.bindtags(tuple(tags))
        except Exception:
            pass
        return "continue"


    def _keyboard_focus_next_action(self) -> None:
        """Cycle focus through the primary workflow controls without requiring a mouse."""
        order = [
            getattr(self, "category_view_button", None),
            getattr(self, "bank_search_entry", None),
            getattr(self, "bank_tree", None),
            getattr(self, "_main_wem_search", None),
            getattr(self, "wem_tree", None),
            getattr(self, "process_button", None),
        ]
        current = self.root.focus_get()
        valid = [w for w in order if w is not None and w.winfo_exists()]
        if not valid:
            return
        try:
            idx = valid.index(current)
        except ValueError:
            idx = -1
        valid[(idx + 1) % len(valid)].focus_set()

    def _main_shortcut_dispatch(self, event: Any, callback: Callable[[Any], Any]) -> str:
        """Run a global shortcut only when focus belongs to the main workspace."""
        try:
            top = event.widget.winfo_toplevel()
            if top is not self.root:
                return "continue"
        except Exception:
            return "continue"
        result = callback(event)
        return str(result) if result else "break"

    def _keyboard_main_action(self, action: Callable[[], Any]) -> str:
        action()
        return "break"

    def _focus_widget(self, widget: Any) -> str:
        if widget is None:
            return "break"
        try:
            widget.focus_set()
            if isinstance(widget, (tk.Entry, ttk.Entry)):
                widget.select_range(0, "end")
        except Exception:
            pass
        return "break"

    def _keyboard_guide(self, _event: Any = None) -> str:
        try:
            top = _event.widget.winfo_toplevel() if _event is not None else self.root
            if top is not self.root:
                return "continue"
        except Exception:
            pass
        self.show_quick_guide()
        return "break"

    def _text_safe_root_action(self, event: Any, action: Callable[[], Any]) -> str:
        """Run a root-level action unless the user is typing into an input."""
        if self._widget_is_text_input(getattr(event, "widget", None)):
            return "continue"
        action()
        return "break"

    def _keyboard_escape(self, event: Any) -> str:
        """Esc stops playback; child dialogs get first refusal through their own bindings."""
        widget = getattr(event, "widget", None)
        # In the main window, Esc exits search/edit focus so keyboard users are never
        # trapped in an input. Child dialogs keep their own Escape behavior.
        try:
            top = widget.winfo_toplevel() if widget is not None else self.root
            if top is not self.root:
                return "continue"
        except Exception:
            pass
        if self._widget_is_text_input(widget):
            target = None
            if widget is getattr(self, "bank_search_entry", None):
                target = getattr(self, "bank_tree", None)
            elif widget is getattr(self, "_main_wem_search", None):
                target = getattr(self, "wem_tree", None)
            else:
                target = getattr(self, "wem_tree", None) or getattr(self, "bank_tree", None)
            if target is not None:
                target.focus_set()
                try:
                    iid = self._tree_current_iid(target)
                    if iid:
                        target.see(iid)
                except Exception:
                    pass
            return "break"
        self.stop_preview()
        return "break"

    def _tree_current_iid(self, tree: ttk.Treeview) -> Optional[str]:
        focus = tree.focus()
        if focus and focus in tree.get_children(""):
            return focus
        selection = tree.selection()
        return selection[-1] if selection else None

    def _tree_set_keyboard_anchor(self, tree: ttk.Treeview, kind: str, iid: Optional[str]) -> None:
        if not iid:
            return
        tree.focus(iid)
        if kind == "bank":
            self._bank_anchor_iid = iid
            self._bank_anchor_path = self._bank_path_by_item.get(iid)
        else:
            self._wem_anchor_iid = iid

    def _tree_keyboard_select_range(self, tree: ttk.Treeview, kind: str, anchor: str, current: str, add: bool = False) -> None:
        items = list(tree.get_children(""))
        if anchor not in items or current not in items:
            return
        a, b = items.index(anchor), items.index(current)
        lo, hi = sorted((a, b))
        rng = items[lo:hi + 1]
        if add:
            tree.selection_add(rng)
        else:
            tree.selection_set(rng)

    def _tree_keyboard_move(self, tree: ttk.Treeview, kind: str, direction: int, event: Any) -> str:
        items = list(tree.get_children(""))
        if not items:
            return "break"
        current = self._tree_current_iid(tree) or items[0]
        try:
            index = items.index(current)
        except ValueError:
            index = 0
        new_index = max(0, min(len(items) - 1, index + direction))
        target = items[new_index]
        state = int(getattr(event, "state", 0) or 0)
        shift = bool(state & 0x0001)
        ctrl = bool(state & 0x0004)

        # Without modifiers, move focus and select one row. Ctrl moves focus only;
        # Shift extends from the anchor. Ctrl+Shift extends while preserving prior selection.
        if ctrl and shift:
            anchor = (self._bank_anchor_iid if kind == "bank" else self._wem_anchor_iid) or current
            self._tree_keyboard_select_range(tree, kind, anchor, target, add=True)
            tree.focus(target)
        elif shift:
            anchor = (self._bank_anchor_iid if kind == "bank" else self._wem_anchor_iid) or current
            self._tree_keyboard_select_range(tree, kind, anchor, target, add=False)
            tree.focus(target)
        elif ctrl:
            tree.focus(target)
        else:
            tree.selection_set(target)
            tree.focus(target)
            self._tree_set_keyboard_anchor(tree, kind, target)
        tree.see(target)
        if kind == "wem":
            self._wem_selection_changed()
        return "break"

    def _tree_keyboard_page(self, tree: ttk.Treeview, kind: str, direction: int, event: Any) -> str:
        try:
            height = max(1, int(tree.winfo_height()))
            row_height = max(18, int(tree.cget("height") and 30))
            page = max(1, height // row_height - 1)
        except Exception:
            page = 8
        # Page selection is intentionally routed through repeated movement so Shift
        # keeps the same contiguous-range semantics as Up/Down.
        target_event = dict(event=event) if False else event
        result = "break"
        for _ in range(page):
            result = self._tree_keyboard_move(tree, kind, direction, target_event)
        return result

    def _tree_keyboard_home_end(self, tree: ttk.Treeview, kind: str, end: bool, event: Any) -> str:
        items = list(tree.get_children(""))
        if not items:
            return "break"
        target = items[-1] if end else items[0]
        current = self._tree_current_iid(tree) or target
        state = int(getattr(event, "state", 0) or 0)
        shift = bool(state & 0x0001)
        ctrl = bool(state & 0x0004)
        if shift:
            anchor = (self._bank_anchor_iid if kind == "bank" else self._wem_anchor_iid) or current
            self._tree_keyboard_select_range(tree, kind, anchor, target, add=ctrl)
            tree.focus(target)
        elif ctrl:
            tree.focus(target)
        else:
            tree.selection_set(target)
            tree.focus(target)
            self._tree_set_keyboard_anchor(tree, kind, target)
        tree.see(target)
        if kind == "wem":
            self._wem_selection_changed()
        return "break"

    def _tree_keyboard_select_all(self, tree: ttk.Treeview, kind: str, _event: Any) -> str:
        items = tree.get_children("")
        if items:
            tree.selection_set(items)
            tree.focus(items[0])
            if kind == "bank":
                self._bank_anchor_iid = items[0]
                self._bank_anchor_path = self._bank_path_by_item.get(items[0])
            else:
                self._wem_anchor_iid = items[0]
                self._wem_selection_changed()
        return "break"

    def _tree_keyboard_activate(self, tree: ttk.Treeview, kind: str, _event: Any) -> str:
        iid = self._tree_current_iid(tree)
        if not iid:
            return "break"
        if kind == "bank":
            selected = [self._bank_path_by_item[i] for i in tree.selection() if i in self._bank_path_by_item]
            if len(selected) <= 1:
                self._bank_activate(iid, 0)
            else:
                loaded = [p for p in selected if p in self.loaded_banks]
                unloaded = [p for p in selected if p not in self.loaded_banks]
                for path in loaded:
                    self._unload_bank_immediately(path)
                if unloaded:
                    self._load_banks_bulk(unloaded)
                self.status_var.set(f"Toggled {len(selected)} selected sound group(s)")
        else:
            self.preview_selected_wems()
        return "break"

    def _widget_under_pointer(self, event: Any) -> Optional[tk.Widget]:
        try:
            return self.root.winfo_containing(event.x_root, event.y_root)
        except Exception:
            return None

    def _wheel_global(self, event: Any) -> str:
        widget = self._widget_under_pointer(event)
        if widget is None:
            return "continue"
        tree = self._nearest_tree(widget)
        if tree is not None:
            delta = int(-1 * (event.delta / 120))
            if delta == 0:
                delta = -1 if event.delta < 0 else 1
            tree.yview_scroll(delta * 3, "units")
            return "break"
        canvas = self._nearest_canvas(widget)
        if canvas is not None:
            delta = int(-1 * (event.delta / 120)) or (-1 if event.delta < 0 else 1)
            canvas.yview_scroll(delta * 3, "units")
            return "break"
        return "continue"

    def _wheel_shift(self, event: Any) -> str:
        widget = self._widget_under_pointer(event)
        tree = self._nearest_tree(widget) if widget else None
        if tree is not None:
            delta = int(-1 * (event.delta / 120)) or (-1 if event.delta < 0 else 1)
            tree.xview_scroll(delta * 3, "units")
            return "break"
        canvas = self._nearest_canvas(widget) if widget else None
        if canvas is not None:
            delta = int(-1 * (event.delta / 120)) or (-1 if event.delta < 0 else 1)
            canvas.xview_scroll(delta * 3, "units")
            return "break"
        return "continue"

    @staticmethod
    def _nearest_tree(widget: Optional[tk.Widget]) -> Optional[ttk.Treeview]:
        current = widget
        while current is not None:
            if isinstance(current, ttk.Treeview):
                return current
            try:
                current = current.master
            except Exception:
                return None
        return None

    @staticmethod
    def _nearest_canvas(widget: Optional[tk.Widget]) -> Optional[tk.Canvas]:
        current = widget
        while current is not None:
            if isinstance(current, tk.Canvas):
                return current
            try:
                current = current.master
            except Exception:
                return None
        return None

    def _apply_workspace_customization(self) -> None:
        """Apply safe, layout-only workspace preferences without touching audio logic."""
        try:
            flow = getattr(self, "_flow_frame", None)
            if flow is not None and flow.winfo_exists():
                packed = bool(flow.pack_info()) if flow.winfo_manager() == "pack" else False
                if bool(self.workspace_custom.get("show_flow", True)):
                    if not packed:
                        flow.pack(fill="x", pady=(0, 8), before=getattr(self, "_main_paned", None))
                elif packed:
                    flow.pack_forget()
        except Exception:
            pass
        try:
            canvas = getattr(self, "preview_player_canvas", None)
            if canvas is not None and canvas.winfo_exists():
                canvas.configure(height=int(self.workspace_custom.get("preview_height", 72)))
                self._draw_preview_player()
        except Exception:
            pass
        try:
            self.root.after_idle(self._set_initial_main_sash)
        except Exception:
            pass

