        ttk.Label(parent, text=label + ":").grid(row=row, column=0, sticky="w", padx=(0, 6), pady=2)
        if values:
            ttk.Combobox(parent, textvariable=var, values=list(values), state="readonly", width=18).grid(row=row, column=1, sticky="ew", pady=2)
