    def _preset_file(self) -> Path:
        try:
            override = str((self.settings or {}).get("preset_file", "") or "").strip()
        except Exception:
            override = ""
        if override:
            cand = Path(os.path.expandvars(os.path.expanduser(override)))
            try:
                if cand.is_file():
                    return cand
            except Exception:
                pass
        return self.preset_path

    @staticmethod
    def _merge_preset_data(first: dict[str, Any], second: dict[str, Any]) -> dict[str, Any]:
        banks = first.setdefault("banks", {})
        if not isinstance(banks, dict):
            banks = {}
            first["banks"] = banks
        for name, entry in ((second.get("banks") or {}) if isinstance(second, dict) else {}).items():
            if not isinstance(entry, dict):
                continue
            current = banks.get(name)
            if not isinstance(current, dict):
                banks[name] = entry
                continue
            merged: dict[int, dict[str, Any]] = {}
            for item in current.get("recipe") or []:
                if isinstance(item, dict):
                    try:
                        merged[int(item.get("wem_index"))] = dict(item)
                    except (TypeError, ValueError):
                        pass
            for item in entry.get("recipe") or []:
                if isinstance(item, dict):
                    try:
                        key = int(item.get("wem_index"))
                    except (TypeError, ValueError):
                        continue
                    merged.setdefault(key, dict(item))
            current["recipe"] = [merged[k] for k in sorted(merged)]
        return first

    def _journal_snapshot_rows(self, mod_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        covered: dict[str, set[int]] = {}
        for row in mod_rows:
            if not isinstance(row, dict):
                continue
            idxs: set[int] = set()
            for e in row.get("recipe") or []:
                if isinstance(e, dict):
                    try:
                        idxs.add(int(e.get("wem_index")))
                    except (TypeError, ValueError):
                        pass
            covered.setdefault(str(row.get("bank_name", "")).lower(), set()).update(idxs)
        pairs: list[tuple[Path, Path]] = []
        try:
            journal = UndoManager(self.paths, self.log).read()
            for e in journal.get("entries") or []:
                if isinstance(e, dict) and e.get("installed_path") and e.get("backup_path"):
                    pairs.append((Path(str(e["installed_path"])), Path(str(e["backup_path"]))))
        except Exception as exc:
            self.log.debug("No undo journal to scan for mods: %s", exc)
        try:
            undo_root = self.paths.processed_audio / "undo"
            live_by_safe: dict[str, Path] = {}
            for b in self.discovered_banks or []:
                live_by_safe.setdefault(safe_name(Path(b).name).lower(), Path(b))
            if undo_root.is_dir():
                for bak in undo_root.rglob("*"):
                    if not bak.is_file() or bak.suffix.lower() != ".bnk":
                        continue
                    rest = bak.name[18:] if len(bak.name) > 18 and bak.name[16:18] == "__" else bak.name
                    live = live_by_safe.get(rest.lower())
                    if live is not None and live.is_file() and (live, bak) not in pairs:
                        pairs.append((live, bak))
        except Exception as exc:
            self.log.debug("Could not scan undo backups for mods: %s", exc)
        out: list[dict[str, Any]] = []
        for live, ref in pairs:
            try:
                if not live.is_file() or not ref.is_file():
                    continue
                live_media = extract_embedded_wems_from_snapshot(parse_bnk_snapshot(live))
                ref_media = extract_embedded_wems_from_snapshot(parse_bnk_snapshot(ref))
            except Exception:
                continue
            key = live.name.lower()
            fresh = [i for i, payload in live_media.items() if ref_media.get(i) != payload and i not in covered.get(key, set())]
            if not fresh:
                continue
            covered.setdefault(key, set()).update(fresh)
            out.append({"bank_name": live.name, "recipe": [{"wem_index": i, "wem_name": f"WEM {i}", "_live": True} for i in sorted(fresh)], "_snap_bank": str(live)})
        return out

    def _import_preset_file(self, parent, reopen) -> None:
        src = filedialog.askopenfilename(parent=parent, title="Locate backup file \u2014 mod_presets.txt", filetypes=[("Backup text", "*.txt"), ("All files", "*.*")])
        if not src:
            return
        try:
            data = json.loads(Path(src).read_text(encoding="utf-8"))
        except Exception as exc:
            cute_error("Locate backup file", f"Could not read that file:\n{exc}", parent=parent)
            return
        if not isinstance(data, dict) or not isinstance(data.get("banks"), dict):
            cute_error("Locate backup file", "That file is not a mod backup (no saved sound groups inside).", parent=parent)
            return
        self.settings["preset_file"] = str(Path(src))
        with contextlib.suppress(Exception):
            self._save_ui_settings()
        cute_info("Backup linked \u2661", f"I will read your saved mods from:\n{src}", parent=parent, hint="Your list should fill in right away.")
        try:
            reopen()
        except Exception:
            pass

    def _load_mod_presets(self) -> dict[str, Any]:
        data: dict[str, Any] = {"version": 1, "banks": {}}
        try:
            if self.preset_path.is_file():
                loaded = json.loads(self.preset_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict) and isinstance(loaded.get("banks"), dict):
                    data = loaded
        except Exception as exc:
            self.log.warning("Could not read mod preset database: %s", exc)
        try:
            extra = self._preset_file()
            if extra != self.preset_path and extra.is_file():
                other = json.loads(extra.read_text(encoding="utf-8"))
                if isinstance(other, dict) and isinstance(other.get("banks"), dict):
                    data = self._merge_preset_data(data, other)
        except Exception as exc:
            self.log.warning("Could not read linked backup file: %s", exc)
        data.setdefault("version", 1)
        if not isinstance(data.get("banks"), dict):
            data["banks"] = {}
        return data

    def _save_mod_presets(self, data: dict[str, Any]) -> None:
        payload = json.dumps(data, indent=2, ensure_ascii=False)
        tmp = self.preset_path.with_name(self.preset_path.name + ".tmp")
        last_exc: Optional[BaseException] = None
        for attempt in range(1, 4):
            try:
                self.preset_path.parent.mkdir(parents=True, exist_ok=True)
                tmp.write_text(payload, encoding="utf-8")
                try:
                    os.replace(tmp, self.preset_path)
                except OSError as exc:
                    last_exc = exc
                    if attempt < 3:
                        time.sleep(0.35 * attempt)
                        continue
                    shutil.copy2(tmp, self.preset_path)
                    tmp.unlink(missing_ok=True)
                return
            except Exception as exc:
                last_exc = exc
                if attempt < 3:
                    time.sleep(0.35 * attempt)
        if last_exc is not None:
            self.log.error("Could not save mod preset database: %s", last_exc)

    @staticmethod
    def _effective_selection(sel: Selection, options: ProcessOptions) -> dict[str, Any]:
        return {
            "wem_index": int(sel.wem.index),
            "wem_name": sel.wem.display_name,
            "source": str(sel.source),
            "source_kind": str(sel.source_kind),
            "source_playlist_urls": list(sel.source_playlist_urls),
            "offset_ms": float(sel.source_offset_ms or 0.0),
            "source_end_ms": None if sel.source_end_ms is None else float(sel.source_end_ms),
            "auto_match_duration": bool(options.auto_match_duration if sel.auto_match_duration is None else sel.auto_match_duration),
            "playback_rate": float(options.playback_rate if sel.playback_rate is None else sel.playback_rate),
            "volume_db": float(options.volume_db if sel.volume_db is None else sel.volume_db),
            "fade_in_ms": int(options.fade_in_ms if sel.fade_in_ms is None else sel.fade_in_ms),
            "fade_out_ms": int(options.fade_out_ms if sel.fade_out_ms is None else sel.fade_out_ms),
            "normalize_loudness": bool(options.normalize_loudness if sel.normalize_loudness is None else sel.normalize_loudness),
            "combine_original": bool(options.combine_original if sel.combine_original is None else sel.combine_original),
            "overlay_gain_db": float(options.overlay_gain_db if sel.overlay_gain_db is None else sel.overlay_gain_db),
            "short_source_policy": str(options.short_source_policy if sel.short_source_policy is None else sel.short_source_policy),
            "duration_tolerance_ms": float(options.duration_tolerance_ms),
            "sample_rate_policy": str(options.sample_rate_policy),
            "channel_policy": str(options.channel_policy),
            "conversion_preset": str(options.conversion_preset),
            "map_mode": bool(sel.map_mode),
            "map_transition_ms": None if sel.map_transition_ms is None else float(sel.map_transition_ms),
        }

    def _save_presets_for_success(self, selections: list[Selection], options: ProcessOptions, records: list[JobRecord]) -> None:

        data = self._load_mod_presets()
        banks = data.setdefault("banks", {})
        grouped: dict[Path, list[Selection]] = {}
        for sel in selections:
            grouped.setdefault(sel.wem.bank_path.resolve(), []).append(sel)
        for bank, sels in grouped.items():
            rec = next((r for r in records if Path(r.source_bank).resolve() == bank), None)
            if rec is None or rec.status != "success" or not bank.is_file():
                continue

            previous = banks.get(bank.name) if isinstance(banks.get(bank.name), dict) else {}
            previous_recipe = previous.get("recipe", []) if isinstance(previous, dict) else []
            merged: dict[int, dict[str, Any]] = {}
            if isinstance(previous_recipe, list):
                for item in previous_recipe:
                    if isinstance(item, dict) and item.get("wem_index") is not None:
                        try:
                            merged[int(item["wem_index"])] = dict(item)
                        except (TypeError, ValueError):
                            continue
            for sel in sels:
                recipe_item = self._effective_selection(sel, options)
                merged[int(recipe_item["wem_index"])] = recipe_item

            original_hash = str(previous.get("original_sha256", "")) if isinstance(previous, dict) else ""
            original_path = str(previous.get("original_bank_path", "")) if isinstance(previous, dict) else ""
            rec_original_hash = str(getattr(rec, "original_sha256", ""))
            if not original_hash:
                original_hash = rec_original_hash or sha256_file(bank)
            if not original_path:
                original_path = str(bank)

            banks[bank.name] = {
                "bank_name": bank.name,
                "original_bank_path": original_path,
                "original_sha256": original_hash,
                "saved_at": _dt.datetime.now().isoformat(timespec="seconds"),
                "recipe": [merged[idx] for idx in sorted(merged)],
            }
        self._save_mod_presets(data)

    def _friendly_backup_bank(self, bank_name: Any) -> str:
        try:
            _cat, label = categorise_brawlhalla_bnk(Path(str(bank_name)))
            if label and str(label).strip():
                return str(label)
        except Exception:
            pass
        return str(bank_name)

    def _preset_rows(self) -> list[dict[str, Any]]:
        data = self._load_mod_presets()
        rows = []
        for _name, entry in sorted(data.get("banks", {}).items(), key=lambda kv: kv[0].lower()):
            if isinstance(entry, dict):
                rows.append(entry)
        return rows

    def _restore_selected_presets(self, listbox: tk.Listbox, win: tk.Toplevel) -> None:
        indexes = listbox.curselection()
        preset_rows = self._preset_rows()
        rows = [preset_rows[i] for i in indexes if 0 <= i < len(preset_rows)]
        if not rows:
            cute_warning("Restore", "Select one or more backed up BNKs first.", parent=win)
            return

        names = [self._friendly_backup_bank(r.get("bank_name", "Unknown BNK")) for r in rows]
        if not cute_ask(
            "Restore original sounds",
            "I'll rebuild the sound groups you picked from their saved recipes:\n\n"
            + "\n".join("• " + n for n in names),
            parent=win,
            hint="Use your ORIGINAL, unmodified sound groups — restoring over an already-modded group can stack changes.",
            yes="Restore ♡",
        ):
            return

        selector = tk.Toplevel(win)
        self._borderless_fullscreen(selector, "Choose WEMs to Restore")
        body = ttk.Frame(selector, padding=16)
        body.pack(fill="both", expand=True)
        ttk.Label(body, text="Choose WEMs to Restore", font=("Segoe UI", 18, "bold")).pack(anchor="w")
        ttk.Label(
            body,
            text="Everything is selected by default. Uncheck any WEMs you want to leave completely untouched.",
            style="Small.TLabel",
            wraplength=820,
        ).pack(anchor="w", pady=(2, 12))

        outer = ttk.Frame(body)
        outer.pack(fill="both", expand=True)
        canvas = tk.Canvas(outer, highlightthickness=0, bd=0, bg=self.root.cget("bg"))
        scroll = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        content = ttk.Frame(canvas)
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        window_id = canvas.create_window((0, 0), window=content, anchor="nw")

        def refresh_scroll(_event=None) -> None:
            try:
                canvas.itemconfigure(window_id, width=max(1, canvas.winfo_width()))
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                pass

        content.bind("<Configure>", refresh_scroll)
        canvas.bind("<Configure>", refresh_scroll)

        choices: list[tuple[dict[str, Any], dict[str, tk.BooleanVar]]] = []
        for row in rows:
            bank_name = str(row.get("bank_name", "Unknown BNK"))
            recipe = row.get("recipe", [])
            if not isinstance(recipe, list):
                recipe = []
            card = ttk.LabelFrame(content, text=f"  {self._friendly_backup_bank(bank_name)}  •  {len(recipe)} saved WEM change(s)  ", padding=10)
            card.pack(fill="x", padx=4, pady=5)
            vars_by_key: dict[str, tk.BooleanVar] = {}
            if not recipe:
                ttk.Label(card, text="No saved WEM changes.", style="Small.TLabel").pack(anchor="w")
            for item in sorted((x for x in recipe if isinstance(x, dict)), key=lambda x: int(x.get("wem_index", 0))):
                idx = int(item.get("wem_index", 0))
                var = tk.BooleanVar(value=True)
                key = str(idx)
                vars_by_key[key] = var
                source = str(item.get("source", ""))
                speed = float(item.get("playback_rate", 1.0))
                gain = float(item.get("volume_db", 0.0))
                offset = float(item.get("offset_ms", 0.0))
                combine = bool(item.get("combine_original", False))
                description = (
                    f"WEM {idx}  •  {source}\n"
                    f"Offset: {offset:g} ms  •  Speed: {speed:g}x  •  Gain: {gain:g} dB  •  "
                    f"Combine: {'ON' if combine else 'OFF'}"
                )
                ttk.Checkbutton(card, text=description, variable=var).pack(anchor="w", fill="x", pady=2)
            choices.append((row, vars_by_key))

        controls = ttk.Frame(body)
        controls.pack(fill="x", pady=(10, 0))

        def set_all(value: bool) -> None:
            for _row, mapping in choices:
                for var in mapping.values():
                    var.set(value)

        ttk.Button(controls, text="Select All", style="Tool.TButton", command=lambda: set_all(True)).pack(side="left")
        ttk.Button(controls, text="Clear All", style="Tool.TButton", command=lambda: set_all(False)).pack(side="left", padx=(6, 0))

        def begin_restore() -> None:
            try:
                all_selections: list[Selection] = []
                selected_recipe_count = 0
                banks_to_restore = []
                for row, mapping in choices:
                    chosen_items = []
                    recipe = row.get("recipe", [])
                    if isinstance(recipe, list):
                        for item in recipe:
                            if not isinstance(item, dict):
                                continue
                            idx = int(item.get("wem_index"))
                            if mapping.get(str(idx), tk.BooleanVar(value=False)).get():
                                chosen_items.append(item)
                    if chosen_items:
                        selected_recipe_count += len(chosen_items)
                    if chosen_items:
                        banks_to_restore.append((row, chosen_items))

                if selected_recipe_count == 0:
                    cute_warning("Restore", "Select at least one WEM to restore.", parent=selector)
                    return

                for row, recipe_items in banks_to_restore:
                    bank_name = str(row.get("bank_name", ""))
                    bank = self._resolve_restore_bank(bank_name)
                    if bank is None:
                        raise FileNotFoundError(
                            f"Could not find {bank_name} in the current Brawlhalla audio folder or discovered BNKs."
                        )
                    expected = str(row.get("original_sha256", ""))
                    if expected and sha256_file(bank) != expected:
                        ok = cute_ask(
                            "This doesn't look original",
                            f"{bank.name} doesn't match the original file saved with this preset — it may already be modded or changed by a game update.",
                            parent=selector,
                            hint="Restoring on top of a changed file can stack changes.",
                            yes="Restore anyway ♡",
                        )
                        if not ok:
                            return

                    replacer = BNKReplacer(
                        self.paths,
                        self.tools,
                        ProcessOptions(game_audio_dir=Path(self.game_target_var.get()), install_to_game=True),
                        self.log,
                        self.bus,
                    )
                    generation = self._loading_generation
                    infos = replacer.inspect_bank(
                        bank,
                        progress_callback=lambda d, t, w, b=bank, g=generation: self._ui_after(
                            0, lambda d=d, t=t, w=w, bank_path=b, gen=g:
                                self._update_bank_probe_status(bank_path, d, t, w, gen)
                        ),
                    )
                    by_index = {info.index: info for info in infos}
                    for item in recipe_items:
                        idx = int(item.get("wem_index"))
                        info = by_index.get(idx)
                        if info is None:
                            raise RuntimeError(f"{bank_name}: saved WEM {idx} is missing from the current BNK")
                        source = str(item.get("source", "")).strip()
                        if not source:
                            raise RuntimeError(f"{bank_name} WEM {idx}: saved audio source is empty")
                        if not looks_like_url(source) and not Path(os.path.expandvars(os.path.expanduser(source))).is_file():
                            raise FileNotFoundError(f"{bank_name} WEM {idx}: source is missing:\n{source}")
                        all_selections.append(Selection(
                            info,
                            source,
                            str(item.get("source_kind", "url" if looks_like_url(source) else "file")),
                            source_offset_ms=float(item.get("offset_ms", 0.0)),
                            source_end_ms=(None if item.get("source_end_ms") in (None, "") else float(item.get("source_end_ms"))),
                            auto_match_duration=bool(item.get("auto_match_duration", False)),
                            playback_rate=float(item.get("playback_rate", 1.0)),
                            volume_db=float(item.get("volume_db", 0.0)),
                            fade_in_ms=int(item.get("fade_in_ms", 0)),
                            fade_out_ms=int(item.get("fade_out_ms", 0)),
                            normalize_loudness=bool(item.get("normalize_loudness", False)),
                            combine_original=bool(item.get("combine_original", False)),
                            overlay_gain_db=float(item.get("overlay_gain_db", 0.0)),
                            short_source_policy=str(item.get("short_source_policy", "loop")),
                            map_mode=bool(item.get("map_mode", False)),
                            map_transition_ms=item.get("map_transition_ms"),
                        ))

                restore_options = ProcessOptions(
                    short_source_policy="loop",
                    duration_tolerance_ms=2.0,
                    sample_rate_policy="original",
                    channel_policy="original",
                    conversion_preset="Vorbis Quality High",
                    backup_inputs=False,
                    verify_output=True,
                    game_audio_dir=Path(self.game_target_var.get()),
                    install_to_game=True,
                )
                selector.destroy()
                self._start_processing(
                    all_selections,
                    restore_options,
                    quick=False,
                    save_preset=True,
                    operation_label="Restoring your selected WEMs",
                )
            except Exception as exc:
                cute_error("Restore could not start", str(exc), parent=selector)

        ttk.Button(controls, text="Cancel", style="Tool.TButton", command=selector.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(controls, text="Restore Selected", style="Big.TButton", command=begin_restore).pack(side="right")
        selector.bind("<Escape>", lambda _e: selector.destroy())

    def _resolve_restore_bank(self, bank_name: str) -> Optional[Path]:
        game_dir = Path(self.game_target_var.get())
        candidate = game_dir / bank_name
        if candidate.is_file():
            return candidate.resolve()
        for p in self.discovered_banks:
            if p.name.lower() == bank_name.lower() and p.is_file():
                return p.resolve()
        return None

    def show_backed_up(self, parent: tk.Toplevel) -> None:
        """Show a dedicated, scrollable Backed Up window for managing restoration."""
        win = tk.Toplevel(parent)
        self._windowed_lightweight(win, "Backed Up — Automatic Reconstruction", 1000, 780)
        win.transient(parent)
        win.grab_set()

        outer = ttk.Frame(win, padding=16)
        outer.pack(fill="both", expand=True)

        # Header
        header = ttk.Frame(outer)
        header.pack(fill="x", pady=(0, 12))
        ttk.Label(header, text="💾  Backed Up — Automatic Reconstruction", font=("Segoe UI", 18, "bold")).pack(side="left", anchor="w")
        ttk.Label(header, text="Your safety net after game updates. Every successful replacement saves a recipe.", style="Small.TLabel").pack(side="left", padx=(12, 0))

        # Description card
        desc_card = ttk.Frame(outer, style="Card.TFrame", padding=14)
        desc_card.pack(fill="x", pady=(0, 12))
        ttk.Label(desc_card, text="How it works", style="Subsection.TLabel").pack(anchor="w")
        ttk.Label(
            desc_card,
            text=(
                "• Each successful replace saves a tiny text recipe: which BNK, which WEM, what audio, what settings.\n"
                "• When Brawlhalla updates or Steam verifies files, your original BNKs are restored.\n"
                "• Backed Up re-applies your changes automatically — expand a BNK, check the WEMs you want, click Restore.\n"
                "• Source files matter: recipes remember where audio came from. Don't delete/move them if you want to reconstruct later."
            ),
            style="Small.TLabel",
            wraplength=920,
            justify="left",
        ).pack(anchor="w", pady=(6, 0))

        # Main tree area with scroll
        tree_frame = ttk.LabelFrame(outer, text="Saved Modifications", padding=10)
        tree_frame.pack(fill="both", expand=True)

        tree = ttk.Treeview(
            tree_frame,
            columns=("check", "info"),
            show="tree headings",
            selectmode="none",
            height=14
        )
        tree.heading("#0", text="BNK / WEM")
        tree.heading("check", text="✓")
        tree.heading("info", text="SAVED MODIFICATION")
        tree.column("#0", width=380, minwidth=280, stretch=True)
        tree.column("check", width=50, minwidth=50, stretch=False, anchor="center")
        tree.column("info", width=520, minwidth=300, stretch=True)

        # Scrollbars
        vscroll = ttk.Scrollbar(tree_frame, orient="vertical", command=tree.yview)
        hscroll = ttk.Scrollbar(tree_frame, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vscroll.set, xscrollcommand=hscroll.set)

        tree.grid(row=0, column=0, sticky="nsew")
        vscroll.grid(row=0, column=1, sticky="ns")
        hscroll.grid(row=1, column=0, sticky="ew")
        tree_frame.grid_rowconfigure(0, weight=1)
        tree_frame.grid_columnconfigure(0, weight=1)

        # Configure tags for visual feedback
        tree.tag_configure("bank", font=("Segoe UI", 9, "bold"), foreground=self._theme_colors.get("fg", "#332c34"))
        tree.tag_configure("wem", font=("Segoe UI", 9), foreground=self._theme_colors.get("fg", "#332c34"))
        tree.tag_configure("wem_checked", font=("Segoe UI", 9, "bold"), foreground=self._theme_colors.get("accent", "#c65d91"))
        tree.tag_configure("empty", font=("Segoe UI", 9, "italic"), foreground=self._theme_colors.get("muted", "#8c7d87"))

        # Bind hover effects
        self._ux_bind_widgets(tree_frame)

        # Load data
        rows = self._preset_rows()
        checked: dict[str, bool] = {}
        item_meta: dict[str, tuple[str, int]] = {}
        bank_nodes: dict[str, str] = {}

        if not rows:
            tree.insert("", "end", iid="empty", text="No modded BNKs have been saved yet.", values=("", ""), tags=("empty",))
        else:
            for bank_no, row in enumerate(rows):
                bank_name = str(row.get("bank_name", "Unknown BNK"))
                recipe = row.get("recipe", [])
                if not isinstance(recipe, list):
                    recipe = []
                bank_iid = f"bank::{bank_no}"
                bank_nodes[bank_iid] = bank_name
                tree.insert("", "end", iid=bank_iid, text=self._friendly_backup_bank(bank_name),
                            values=("—", f"{len(recipe)} saved WEM change(s)"), open=True, tags=("bank",))
                for wem_no, item in enumerate(sorted((x for x in recipe if isinstance(x, dict)), key=lambda x: int(x.get("wem_index", 0)))):
                    idx = int(item.get("wem_index", 0))
                    child_iid = f"wem::{bank_no}::{wem_no}"
                    checked[child_iid] = True
                    item_meta[child_iid] = (bank_name, idx)
                    source = str(item.get("source", ""))
                    speed = float(item.get("playback_rate", 1.0))
                    gain = float(item.get("volume_db", 0.0))
                    offset = float(item.get("offset_ms", 0.0))
                    combine = bool(item.get("combine_original", False))
                    info = (
                        f"{source}  •  Offset {offset:g} ms  •  Speed {speed:g}x  •  "
                        f"Gain {gain:g} dB  •  Combine {'ON' if combine else 'OFF'}"
                    )
                    tree.insert(bank_iid, "end", iid=child_iid, text=f"WEM {idx}",
                                values=("☑", info), tags=("wem",))

        def set_bank_children(bank_iid: str, value: bool) -> None:
            for child in tree.get_children(bank_iid):
                if child in checked:
                    checked[child] = value
                    tree.set(child, "check", "☑" if value else "☐")
                    if value:
                        tree.item(child, tags=("wem_checked",))
                    else:
                        tree.item(child, tags=("wem",))

        def update_bank_visual(bank_iid: str) -> None:
            children = [c for c in tree.get_children(bank_iid) if c in checked]
            if not children:
                tree.set(bank_iid, "check", "—")
                return
            states = [checked[c] for c in children]
            if all(states):
                tree.set(bank_iid, "check", "☑")
            elif not any(states):
                tree.set(bank_iid, "check", "☐")
            else:
                tree.set(bank_iid, "check", "◩")

        for bank_iid in bank_nodes:
            update_bank_visual(bank_iid)

        def toggle_item(event: Any) -> str:
            iid = tree.identify_row(event.y)
            if not iid or iid == "empty":
                return "break"
            column = tree.identify_column(event.x)
            if iid in checked:
                if column in ("#0", "#2", "#3"):
                    checked[iid] = not checked[iid]
                    tree.set(iid, "check", "☑" if checked[iid] else "☐")
                    if checked[iid]:
                        tree.item(iid, tags=("wem_checked",))
                    else:
                        tree.item(iid, tags=("wem",))
                    parent_iid = tree.parent(iid)
                    if parent_iid:
                        update_bank_visual(parent_iid)
                    return "break"
            elif iid in bank_nodes:
                if column in ("#0", "#2", "#3"):
                    children = [c for c in tree.get_children(iid) if c in checked]
                    target = not all(checked[c] for c in children) if children else True
                    set_bank_children(iid, target)
                    update_bank_visual(iid)
                    return "break"
            return "break"

        tree.bind("<Button-1>", toggle_item, add="+")
        tree.bind("<space>", lambda e: (tree.focus_set(), toggle_item(type('Event', (), {'x': e.x, 'y': e.y})())), add="+")

        buttons = ttk.Frame(outer)
        buttons.pack(fill="x", pady=(12, 0))

        def select_all() -> None:
            for iid in list(checked):
                checked[iid] = True
                tree.set(iid, "check", "☑")
                tree.item(iid, tags=("wem_checked",))
            for bank_iid in bank_nodes:
                update_bank_visual(bank_iid)

        def clear_all() -> None:
            for iid in list(checked):
                checked[iid] = False
                tree.set(iid, "check", "☐")
                tree.item(iid, tags=("wem",))
            for bank_iid in bank_nodes:
                update_bank_visual(bank_iid)

        def refresh_tree() -> None:
            win.destroy()
            self.show_backed_up(parent)

        ttk.Button(buttons, text="✓ Select All WEMs", style="Tool.TButton", command=select_all).pack(side="left")
        ttk.Button(buttons, text="☐ Clear All WEMs", style="Tool.TButton", command=clear_all).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="↻ Refresh", style="Tool.TButton", command=refresh_tree).pack(side="left", padx=(8, 0))

        def restore_checked() -> None:
            selected_keys = {item_meta[iid] for iid, is_checked in checked.items() if is_checked and iid in item_meta}
            if not selected_keys:
                cute_warning("Restore", "Select at least one WEM to restore.", parent=win)
                return
            preset_rows = self._preset_rows()
            selected_by_bank: dict[str, set[int]] = {}
            for bank_name, idx in selected_keys:
                selected_by_bank.setdefault(bank_name.lower(), set()).add(idx)
            filtered_rows = []
            for row in preset_rows:
                name = str(row.get("bank_name", ""))
                if name.lower() not in selected_by_bank:
                    continue
                wanted = selected_by_bank[name.lower()]
                recipe = row.get("recipe", [])
                kept = [item for item in recipe if isinstance(item, dict) and int(item.get("wem_index", -1)) in wanted]
                if kept:
                    clone = dict(row)
                    clone["recipe"] = kept
                    filtered_rows.append(clone)
            win.destroy()
            self._restore_selected_preset_rows(filtered_rows, parent)

        ttk.Button(buttons, text="Restore", style="Big.TButton", command=restore_checked).pack(side="right")
        ttk.Button(buttons, text="Close", style="Tool.TButton", command=win.destroy).pack(side="right", padx=(8, 0))

        if not rows:
            for b in buttons.winfo_children():
                if b.cget("text") in {"✓ Select All WEMs", "☐ Clear All WEMs", "🔧 Restore Selected"}:
                    b.configure(state="disabled")

    def _refresh_backed_up_tree(self, tree: ttk.Treeview, checked: dict[str, bool],
                                item_meta: dict[str, tuple[str, int]], bank_nodes: dict[str, str]) -> None:
        for iid in tree.get_children(""):
            tree.delete(iid)
        checked.clear(); item_meta.clear(); bank_nodes.clear()
        rows = self._preset_rows()
        for bank_no, row in enumerate(rows):
            bank_name = str(row.get("bank_name", "Unknown BNK"))
            recipe = row.get("recipe", [])
            if not isinstance(recipe, list): recipe = []
            bank_iid = f"bank::{bank_no}"
            bank_nodes[bank_iid] = bank_name
            tree.insert("", "end", iid=bank_iid, text=self._friendly_backup_bank(bank_name),
                        values=("—", f"{len(recipe)} saved WEM change(s)"), open=True)
            for wem_no, item in enumerate(sorted((x for x in recipe if isinstance(x, dict)), key=lambda x: int(x.get("wem_index", 0)))):
                idx = int(item.get("wem_index", 0))
                child_iid = f"wem::{bank_no}::{wem_no}"
                checked[child_iid] = True
                item_meta[child_iid] = (bank_name, idx)
                source = str(item.get("source", ""))
                speed = float(item.get("playback_rate", 1.0)); gain = float(item.get("volume_db", 0.0))
                offset = float(item.get("offset_ms", 0.0)); combine = bool(item.get("combine_original", False))
                info = f"{source}  •  Offset {offset:g} ms  •  Speed {speed:g}x  •  Gain {gain:g} dB  •  Combine {'ON' if combine else 'OFF'}"
                tree.insert(bank_iid, "end", iid=child_iid, text=f"WEM {idx}", values=("☑", info))

    def _restore_selected_preset_rows(self, rows: list[dict[str, Any]], parent: tk.Toplevel) -> None:
        if not rows:
            cute_warning("Restore", "Select at least one WEM to restore.", parent=parent)
            return
        names = [self._friendly_backup_bank(r.get("bank_name", "Unknown BNK")) for r in rows]
        if not cute_ask(
            "Restore original sounds",
            "I'll rebuild only the checked sounds from their saved recipes:\n\n"
            + "\n".join("• " + n for n in names),
            parent=parent,
            hint="Use your ORIGINAL, unmodified sound groups — restoring over an already-modded group can stack changes.",
            yes="Restore ♡",
        ):
            return

        selector_parent = parent
        all_selections: list[Selection] = []
        try:
            for row in rows:
                bank_name = str(row.get("bank_name", ""))
                bank = self._resolve_restore_bank(bank_name)
                if bank is None:
                    raise FileNotFoundError(
                        f"Could not find {bank_name} in the current Brawlhalla audio folder or discovered BNKs."
                    )
                expected = str(row.get("original_sha256", ""))
                if expected and sha256_file(bank) != expected:
                    ok = cute_ask(
                        "This doesn't look original",
                        f"{bank.name} doesn't match the original file saved with this preset — it may already be modded or changed by a game update.",
                        parent=selector_parent,
                        hint="Restoring on top of a changed file can stack changes.",
                        yes="Restore anyway ♡",
                    )
                    if not ok:
                        return
                replacer = BNKReplacer(
                    self.paths, self.tools,
                    ProcessOptions(game_audio_dir=Path(self.game_target_var.get()), install_to_game=True),
                    self.log, self.bus,
                )
                generation = self._loading_generation
                infos = replacer.inspect_bank(
                    bank,
                    progress_callback=lambda d, t, w, b=bank, g=generation: self._ui_after(
                        0, lambda d=d, t=t, w=w, bank_path=b, gen=g:
                            self._update_bank_probe_status(bank_path, d, t, w, gen)
                    ),
                )
                by_index = {info.index: info for info in infos}
                for item in row.get("recipe", []):
                    if not isinstance(item, dict):
                        continue
                    idx = int(item.get("wem_index"))
                    info = by_index.get(idx)
                    if info is None:
                        raise RuntimeError(f"{bank_name}: saved WEM {idx} is missing from the current BNK")
                    source = str(item.get("source", "")).strip()
                    if not source:
                        raise RuntimeError(f"{bank_name} WEM {idx}: saved audio source is empty")
                    if not looks_like_url(source) and not Path(os.path.expandvars(os.path.expanduser(source))).is_file():
                        raise FileNotFoundError(f"{bank_name} WEM {idx}: source is missing:\n{source}")
                    all_selections.append(Selection(
                        info, source,
                        str(item.get("source_kind", "url" if looks_like_url(source) else "file")),
                        source_playlist_urls=tuple(str(u) for u in (item.get("source_playlist_urls") or []) if is_youtube_playlist_url(str(u))),
                        source_offset_ms=float(item.get("offset_ms", 0.0)),
                        source_end_ms=(None if item.get("source_end_ms") in (None, "") else float(item.get("source_end_ms"))),
                        auto_match_duration=bool(item.get("auto_match_duration", False)),
                        playback_rate=float(item.get("playback_rate", 1.0)),
                        volume_db=float(item.get("volume_db", 0.0)),
                        fade_in_ms=int(item.get("fade_in_ms", 0)),
                        fade_out_ms=int(item.get("fade_out_ms", 0)),
                        normalize_loudness=bool(item.get("normalize_loudness", False)),
                        combine_original=bool(item.get("combine_original", False)),
                        overlay_gain_db=float(item.get("overlay_gain_db", 0.0)),
                        short_source_policy=str(item.get("short_source_policy", "loop")),
                        map_mode=bool(item.get("map_mode", False)),
                        map_transition_ms=item.get("map_transition_ms"),
                    ))
            restore_options = ProcessOptions(
                short_source_policy="loop", duration_tolerance_ms=2.0,
                sample_rate_policy="original", channel_policy="original",
                conversion_preset="Vorbis Quality High", backup_inputs=False,
                verify_output=True, game_audio_dir=Path(self.game_target_var.get()), install_to_game=True,
            )
            self._start_processing(
                all_selections, restore_options, quick=False, save_preset=True,
                operation_label="Restoring your selected WEMs",
            )
        except Exception as exc:
            cute_error("Restore could not start", str(exc), parent=selector_parent)

    def _user_preset_files(self) -> list[Path]:
        try:
            self.user_presets_dir.mkdir(parents=True, exist_ok=True)
            return sorted(
                (p for p in self.user_presets_dir.glob("*.txt") if p.is_file()),
                key=lambda p: p.stem.lower(),
            )
        except OSError:
            return []

    def _read_user_preset(self, path: Path) -> Optional[dict[str, Any]]:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return None
            banks = data.get("banks")
            if not isinstance(banks, list):
                return None
            return data
        except Exception as exc:
            self.log.warning("Could not read user preset %s: %s", path, exc)
            return None

    def _user_preset_entries(self) -> list[tuple[Path, dict[str, Any]]]:
        out: list[tuple[Path, dict[str, Any]]] = []
        for path in self._user_preset_files():
            data = self._read_user_preset(path)
            if data is not None:
                out.append((path, data))
        return out

    def _create_user_preset(self, parent: tk.Toplevel) -> None:
        source_rows = self._preset_rows()
        if not source_rows:
            cute_info(
                "Nothing saved yet",
                "There are no backed-up sound changes yet.",
                parent=parent,
                hint="Change at least one sound first, then you can save a preset from it.",
            )
            return

        win = tk.Toplevel(parent)
        self._windowed_lightweight(win, "Create Preset", 1050, 760)
        body = ttk.Frame(win, padding=16)
        body.pack(fill="both", expand=True)
        ttk.Label(body, text="Create Preset", font=("Segoe UI", 18, "bold")).pack(anchor="w")
        ttk.Label(
            body,
            text=("Presets are snapshots of selected backed-up WEM modifications. "
                  "Each preset is saved as its own TXT file and never changes when the automatic Backed up recipes change later."),
            style="Small.TLabel", wraplength=980,
        ).pack(anchor="w", pady=(2, 10))

        info = ttk.Frame(body); info.pack(fill="x", pady=(0, 8))
        ttk.Label(info, text="Preset name:").pack(side="left")
        name_var = tk.StringVar()
        ttk.Entry(info, textvariable=name_var, width=40).pack(side="left", padx=(8, 18))
        ttk.Label(info, text="Description:").pack(side="left")
        desc_var = tk.StringVar()
        ttk.Entry(info, textvariable=desc_var).pack(side="left", fill="x", expand=True, padx=(8, 0))

        ttk.Label(body, text="Changes to include:", font=("Segoe UI", 10, "bold")).pack(anchor="w", pady=(4, 6))
        outer = ttk.Frame(body); outer.pack(fill="both", expand=True)
        tree = ttk.Treeview(outer, columns=("check", "info"), show="tree headings", selectmode="browse")
        tree.heading("#0", text="BNK / WEM")
        tree.heading("check", text="INCLUDE")
        tree.heading("info", text="SAVED MODIFICATION")
        tree.column("#0", width=330, minwidth=230, stretch=True)
        tree.column("check", width=90, minwidth=80, stretch=False, anchor="center")
        tree.column("info", width=600, minwidth=320, stretch=True)
        scroll=ttk.Scrollbar(outer, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.pack(side="left", fill="both", expand=True); scroll.pack(side="right", fill="y")
        checked: dict[str, bool] = {}
        meta: dict[str, tuple[str, int]] = {}
        bank_nodes: dict[str, str] = {}

        def render_rows() -> None:
            for iid in tree.get_children(""): tree.delete(iid)
            checked.clear(); meta.clear(); bank_nodes.clear()
            for bank_no, row in enumerate(source_rows):
                bank_name=str(row.get("bank_name", "Unknown BNK"))
                recipe=row.get("recipe", [])
                recipe=[x for x in recipe if isinstance(x, dict)] if isinstance(recipe, list) else []
                bid=f"bank::{bank_no}"; bank_nodes[bid]=bank_name
                tree.insert("", "end", iid=bid, text=self._friendly_backup_bank(bank_name), values=("—", f"{len(recipe)} saved WEM change(s)"), open=True)
                for wem_no,item in enumerate(sorted(recipe,key=lambda x:int(x.get("wem_index",0)))):
                    idx=int(item.get("wem_index",0)); iid=f"wem::{bank_no}::{wem_no}"
                    checked[iid]=True; meta[iid]=(bank_name,idx)
                    source=str(item.get("source","")); speed=float(item.get("playback_rate",1.0)); gain=float(item.get("volume_db",0.0))
                    info=f"{source}  •  Offset {float(item.get('offset_ms',0.0)):g} ms  •  Speed {speed:g}x  •  Gain {gain:g} dB"
                    tree.insert(bid,"end",iid=iid,text=f"WEM {idx}",values=("☑",info))
        render_rows()

        def update_bank(bid: str) -> None:
            kids=[c for c in tree.get_children(bid) if c in checked]
            if not kids: tree.set(bid,"check","—"); return
            vals=[checked[c] for c in kids]
            tree.set(bid,"check","☑" if all(vals) else ("☐" if not any(vals) else "◩"))

        def toggle(_event: Any=None) -> str:
            iid=tree.identify_row(_event.y) if _event is not None else ""
            if iid in checked:
                checked[iid]=not checked[iid]; tree.set(iid,"check","☑" if checked[iid] else "☐")
                par=tree.parent(iid)
                if par: update_bank(par)
                return "break"
            if iid in bank_nodes:
                kids=[c for c in tree.get_children(iid) if c in checked]
                target=not all(checked[c] for c in kids) if kids else True
                for c in kids:
                    checked[c]=target; tree.set(c,"check","☑" if target else "☐")
                update_bank(iid)
            return "break"
        tree.bind("<Button-1>", toggle, add="+")
        for bid in bank_nodes: update_bank(bid)

        actions=ttk.Frame(body); actions.pack(fill="x", pady=(8,0))
        def all_on():
            for iid in checked: checked[iid]=True; tree.set(iid,"check","☑")
            for bid in bank_nodes: update_bank(bid)
        def all_off():
            for iid in checked: checked[iid]=False; tree.set(iid,"check","☐")
            for bid in bank_nodes: update_bank(bid)
        ttk.Button(actions,text="Select All",style="Tool.TButton",command=all_on).pack(side="left")
        ttk.Button(actions,text="Clear All",style="Tool.TButton",command=all_off).pack(side="left",padx=(6,0))
        def save():
            name=name_var.get().strip()
            if not name:
                cute_error("Create Preset","Enter a preset name.",parent=win); return
            selected={(b,i) for iid,(b,i) in meta.items() if checked.get(iid,False)}
            if not selected:
                cute_warning("Create Preset","Select at least one saved WEM change.",parent=win); return
            filename=safe_name(name)
            if not filename or filename in {".",".."}: filename="Preset"
            path=self.user_presets_dir / f"{filename}.txt"
            if path.exists() and not cute_ask("Replace preset?",f"A preset named {name!r} already exists.",parent=win,yes="Replace ♡"): return
            banks=[]
            for row in source_rows:
                bank_name=str(row.get("bank_name",""))
                recipe=row.get("recipe",[])
                if not isinstance(recipe,list): continue
                kept=[dict(item) for item in recipe if isinstance(item,dict) and (bank_name,int(item.get("wem_index",-1))) in selected]
                if kept:
                    entry={k:v for k,v in row.items() if k != "recipe"}
                    entry["recipe"]=kept; banks.append(entry)
            payload={"version":1,"preset_name":name,"description":desc_var.get().strip(),"created_at":_dt.datetime.now().isoformat(timespec="seconds"),"updated_at":_dt.datetime.now().isoformat(timespec="seconds"),"banks":banks}
            errors=self._preset_validation_errors(payload)
            if errors:
                cute_error("Create Preset","The preset could not be validated:\n\n"+"\n".join(errors[:12]),parent=win); return
            try:
                self.user_presets_dir.mkdir(parents=True,exist_ok=True)
                tmp=path.with_name(path.name+".tmp")
                tmp.write_text(json.dumps(payload,indent=2,ensure_ascii=False),encoding="utf-8")
                os.replace(tmp,path)
            except Exception as exc:
                cute_error("Create Preset",f"Could not save preset:\n{exc}",parent=win); return
            cute_info("Preset saved ♡", f"Saved “{name}” with {len(banks)} sound group(s).", parent=win)
            win.destroy()
            self._refresh_user_preset_listbox()
        ttk.Button(actions,text="Cancel",style="Tool.TButton",command=win.destroy).pack(side="right",padx=(6,0))
        ttk.Button(actions,text="Save Preset",style="Big.TButton",command=save).pack(side="right")
        win.bind("<Escape>",lambda _e:win.destroy()); win.bind("<Return>",lambda _e:save())

    def _refresh_user_preset_listbox(self) -> None:
        lb = self._user_preset_listbox
        if lb is None:
            return
        try:
            query = str(getattr(self, "_user_preset_filter_var", tk.StringVar(value="")).get()).strip().lower()
            previous = list(lb.curselection())
            previous_name = None
            entries = getattr(self, "_user_preset_display", [])
            if previous and previous[0] < len(entries):
                previous_name = str(entries[previous[0]][1].get("preset_name", entries[previous[0]][0].stem))

            lb.delete(0, "end")
            self._user_preset_display = []
            all_entries = self._user_preset_entries()
            for path, data in all_entries:
                banks = data.get("banks", [])
                total = sum(
                    len(r.get("recipe", []))
                    for r in banks
                    if isinstance(r, dict) and isinstance(r.get("recipe", []), list)
                )
                name = str(data.get("preset_name", path.stem))
                desc = str(data.get("description", "")).strip()
                haystack = f"{name} {desc}".lower()
                if query and query not in haystack:
                    continue
                line = f"♡  {name}   ·   {len(banks)} BNK{'s' if len(banks) != 1 else ''}   ·   {total} change{'s' if total != 1 else ''}"
                self._user_preset_display.append((path, data))
                lb.insert("end", line)

            if previous_name:
                for i, (_path, data) in enumerate(self._user_preset_display):
                    if str(data.get("preset_name", "")) == previous_name:
                        lb.selection_set(i)
                        lb.see(i)
                        break
            elif self._user_preset_display:
                lb.selection_set(0)
                lb.see(0)
            self._update_user_preset_details()
            if hasattr(self, "_user_preset_count_var"):
                total_count = len(all_entries)
                visible_count = len(self._user_preset_display)
                self._user_preset_count_var.set(
                    f"{visible_count} shown / {total_count} preset{'s' if total_count != 1 else ''}"
                )
        except Exception:
            pass

    def _selected_user_preset_entry(self) -> Optional[tuple[Path, dict[str, Any]]]:
        lb = self._user_preset_listbox
        entries = getattr(self, "_user_preset_display", [])
        if lb is None:
            return None
        sel = list(lb.curselection())
        if not sel or sel[0] >= len(entries):
            return None
        return entries[sel[0]]

    def _update_user_preset_details(self, _event: Any = None) -> None:
        details = getattr(self, "_user_preset_details_var", None)
        if details is None:
            return
        entry = self._selected_user_preset_entry()
        if not entry:
            details.set("Select a preset to see what it contains.  Double-click a preset to apply it.")
            return
        path, data = entry
        name = str(data.get("preset_name", path.stem))
        desc = str(data.get("description", "")).strip()
        banks = [b for b in data.get("banks", []) if isinstance(b, dict)]
        total = sum(len(b.get("recipe", [])) for b in banks if isinstance(b.get("recipe", []), list))
        bank_names = [str(b.get("bank_name", "Unknown BNK")) for b in banks[:4]]
        line = f"{name}  •  {len(banks)} BNK{'s' if len(banks) != 1 else ''}  •  {total} WEM change{'s' if total != 1 else ''}"
        if bank_names:
            line += "\n" + "  ·  " + "   ·   ".join(bank_names)
        if desc:
            line += f"\n\n{desc}"
        details.set(line)

    def _filter_user_presets(self, _event: Any = None) -> None:
        self._refresh_user_preset_listbox()

    def _apply_selected_user_preset(self, parent: tk.Toplevel) -> None:
        entry = self._selected_user_preset_entry()
        if not entry:
            cute_warning("Apply Preset", "Pick a preset first — then press Apply or double-click it.", parent=parent)
            return
        _path, data = entry
        rows = [
            r for r in data.get("banks", [])
            if isinstance(r, dict) and isinstance(r.get("recipe", []), list) and r.get("recipe")
        ]
        if not rows:
            cute_warning("Apply Preset", "This preset contains no usable BNK changes.", parent=parent)
            return
        name = str(data.get("preset_name", "Preset"))
        self._restore_selected_preset_rows(rows, parent)

    def _delete_selected_user_preset(self, parent: tk.Toplevel) -> None:
        entry = self._selected_user_preset_entry()
        if not entry:
            cute_warning("Delete Preset", "Pick a preset first.", parent=parent)
            return
        path, data = entry
        name = str(data.get("preset_name", path.stem))
        if not cute_ask(
            "Delete preset?",
            f"Delete “{name}”?",
            parent=parent,
            hint="This does not change your saved backups or installed game files.",
            yes="Delete",
        ):
            return
        try:
            path.unlink()
        except Exception as exc:
            cute_error("Delete Preset", f"Could not delete preset:\n{exc}", parent=parent)
            return
        self._refresh_user_preset_listbox()

    def _rename_selected_user_preset(self, parent: tk.Toplevel) -> None:
        entry = self._selected_user_preset_entry()
        if not entry:
            cute_warning("Rename Preset", "Pick a preset first.", parent=parent)
            return
        path, data = entry
        old_name = str(data.get("preset_name", path.stem))
        new_name = simpledialog.askstring("Rename Preset", "New preset name:", initialvalue=old_name, parent=parent)
        if new_name is None:
            return
        new_name = new_name.strip()
        if not new_name:
            cute_warning("Rename Preset", "Preset name cannot be empty.", parent=parent)
            return
        target = self.user_presets_dir / f"{safe_name(new_name) or 'Preset'}.txt"
        if target != path and target.exists():
            if not cute_ask("Replace preset?", f"A preset named {new_name!r} already exists.", parent=parent, yes="Replace ♡"):
                return
        try:
            updated = dict(data)
            updated["preset_name"] = new_name
            updated["updated_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            tmp = target.with_name(target.name + ".tmp")
            tmp.write_text(json.dumps(updated, indent=2, ensure_ascii=False), encoding="utf-8")
            os.replace(tmp, target)
            if target != path:
                path.unlink(missing_ok=True)
            self._refresh_user_preset_listbox()
        except Exception as exc:
            cute_error("Rename Preset", f"Could not rename preset:\n{exc}", parent=parent)

    def _duplicate_selected_user_preset(self, parent: tk.Toplevel) -> None:
        entry = self._selected_user_preset_entry()
        if not entry:
            cute_warning("Duplicate Preset", "Pick a preset first.", parent=parent)
            return
        _path, data = entry
        base = str(data.get("preset_name", "Preset")).strip() or "Preset"
        name = simpledialog.askstring("Duplicate Preset", "Name for the copy:", initialvalue=f"{base} Copy", parent=parent)
        if name is None:
            return
        name = name.strip()
        if not name:
            cute_warning("Duplicate Preset", "Preset name cannot be empty.", parent=parent)
            return
        target = self.user_presets_dir / f"{safe_name(name) or 'Preset'}.txt"
        if target.exists() and not cute_ask("Replace preset?", f"A preset named {name!r} already exists.", parent=parent, yes="Replace ♡"):
            return
        try:
            copied = json.loads(json.dumps(data))
            copied["preset_name"] = name
            copied["created_at"] = _dt.datetime.now().isoformat(timespec="seconds")
            copied["updated_at"] = copied["created_at"]
            tmp = target.with_name(target.name + ".tmp")
            tmp.write_text(json.dumps(copied, indent=2, ensure_ascii=False), encoding="utf-8")
            os.replace(tmp, target)
            self._refresh_user_preset_listbox()
        except Exception as exc:
            cute_error("Duplicate Preset", f"Could not duplicate preset:\n{exc}", parent=parent)

    def _preset_validation_errors(self, data: dict[str, Any]) -> list[str]:
        errors: list[str] = []
        if not isinstance(data, dict):
            return ["Preset root must be an object."]
        if not str(data.get("preset_name", "")).strip():
            errors.append("Preset name is missing.")
        banks = data.get("banks")
        if not isinstance(banks, list) or not banks:
            errors.append("Preset contains no BNK entries.")
            return errors
        for bi, bank in enumerate(banks, 1):
            if not isinstance(bank, dict):
                errors.append(f"BNK entry {bi} is invalid.")
                continue
            if not str(bank.get("bank_name", "")).strip():
                errors.append(f"BNK entry {bi} has no bank name.")
            recipe = bank.get("recipe")
            if not isinstance(recipe, list) or not recipe:
                errors.append(f"BNK entry {bi} has no WEM recipe entries.")
                continue
            for wi, item in enumerate(recipe, 1):
                if not isinstance(item, dict):
                    errors.append(f"BNK entry {bi}, WEM entry {wi} is invalid.")
                    continue
                try:
                    int(item.get("wem_index"))
                except Exception:
                    errors.append(f"BNK entry {bi}, WEM entry {wi} has an invalid WEM index.")
                if not str(item.get("source", "")).strip():
                    errors.append(f"BNK entry {bi}, WEM entry {wi} has no source.")
        return errors

    def _export_selected_user_preset(self, parent: tk.Toplevel) -> None:
        lb = self._user_preset_listbox
        entries = getattr(self, "_user_preset_display", [])
        if lb is None:
            return
        sel = list(lb.curselection())
        if not sel or sel[0] >= len(entries):
            cute_warning("Export Preset", "Select a preset first.", parent=parent)
            return
        src, data = entries[sel[0]]
        name = str(data.get("preset_name", src.stem))
        target = filedialog.asksaveasfilename(parent=parent, title="Export Preset", initialfile=f"{safe_name(name)}.txt", defaultextension=".txt", filetypes=[("Preset TXT", "*.txt")])
        if not target:
            return
        try:
            Path(target).write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
            cute_info("Preset exported ♡", f"Saved “{name}” to:\n{target}", parent=parent)
        except Exception as exc:
            cute_error("Export Preset", f"Could not export preset:\n{exc}", parent=parent)

    def _import_user_preset(self, parent: tk.Toplevel) -> None:
        source = filedialog.askopenfilename(parent=parent, title="Import Preset", filetypes=[("Preset TXT", "*.txt"), ("All files", "*.*")])
        if not source:
            return
        path = Path(source)
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            errors = self._preset_validation_errors(data)
            if errors:
                raise ValueError("\n".join(errors[:12]))
            name = str(data.get("preset_name", path.stem)).strip() or path.stem
            filename = safe_name(name) or "Preset"
            target = self.user_presets_dir / f"{filename}.txt"
            if target.exists() and not cute_ask("Replace preset?", f"A preset named {name!r} already exists.", parent=parent, yes="Replace ♡"):
                return
            data = dict(data)
            data["preset_name"] = name
            target.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
            self._refresh_user_preset_listbox()
            cute_info("Preset imported ♡", f"Imported “{name}”.", parent=parent)
        except Exception as exc:
            cute_error("Import Preset", f"Could not import that preset:\n{exc}", parent=parent)

    # ---- Mod packs (.cutie) ----
    @staticmethod
    def _app_base_dir() -> Path:
        try:
            if getattr(sys, "frozen", False):
                return Path(sys.executable).resolve().parent
        except Exception:
            pass
        return Path(__file__).resolve().parent

    def _packs_dir(self) -> Path:
        d = self._app_base_dir() / "Packs"
        with contextlib.suppress(Exception):
            d.mkdir(parents=True, exist_ok=True)
        return d

    def _read_pack(self, path: Path) -> Optional[dict[str, Any]]:
        try:
            data = json.loads(Path(path).read_text(encoding="utf-8"))
        except Exception as exc:
            self.log.warning("Could not read pack %s: %s", path, exc)
            return None
        if isinstance(data, dict) and isinstance(data.get("pack"), dict):
            data = data["pack"]
        if not isinstance(data, dict) or not isinstance(data.get("items"), list):
            return None
        return data

    def _pack_files(self) -> list[Path]:
        d = self._packs_dir()
        found: list[Path] = []
        try:
            for pat in ("*.cutie", "*.cutie.json", "*.json"):
                for p in d.glob(pat):
                    if p.is_file() and self._read_pack(p) is not None:
                        found.append(p)
        except OSError:
            return []
        return sorted(found, key=lambda p: p.stem.lower())

    def _pack_display(self, path: Path) -> str:
        data = self._read_pack(path) or {}
        name = str(data.get("name", path.stem))
        items = data.get("items", [])
        return f"{name} ({len(items) if isinstance(items, list) else 0})"

    def _add_pack_from_file(self, parent) -> None:
        src = filedialog.askopenfilename(parent=parent, title="Add pack \u2014 select a .cutie file", filetypes=[("Cutie packs", "*.cutie;*.cutie.json;*.json"), ("All files", "*.*")])
        if not src:
            return
        data = self._read_pack(Path(src))
        if data is None:
            cute_error("Add pack", "That file is not a .cutie pack.", parent=parent)
            return
        dest = self._packs_dir() / Path(src).name
        i = 2
        while dest.exists():
            dest = self._packs_dir() / f"{Path(src).stem}_{i}{Path(src).suffix or '.cutie'}"
            i += 1
        try:
            shutil.copy2(src, dest)
        except Exception as exc:
            cute_error("Add pack", f"Could not copy pack into Packs:\n{exc}", parent=parent)
            return
        self.log.info("Pack added: %s", dest.name)
        refresh_win = getattr(self, "_refresh_packs_window", None)
        if callable(refresh_win):
            with contextlib.suppress(Exception):
                refresh_win()
        cute_info("Pack added ♡", f"\u201c{data.get('name', dest.stem)}\u201d is now in the Packs folder.", parent=parent)

    def _export_pack(self, parent, path: Path) -> None:
        data = self._read_pack(path)
        name = str((data or {}).get("name", path.stem))
        dest = filedialog.asksaveasfilename(parent=parent, title="Share pack ♡", initialfile=f"{safe_name(name)}.cutie", defaultextension=".cutie", filetypes=[("Cutie pack", "*.cutie"), ("All files", "*.*")])
        if not dest:
            return
        try:
            shutil.copy2(path, dest)
        except Exception as exc:
            cute_error("Share pack", f"Could not export pack:\n{exc}", parent=parent)
            return
        cute_info("Pack shared ♡", f"\u201c{name}\u201d exported. Send the .cutie file \u2014 the other person presses Add pack.", parent=parent)

    def _embed_source_audio(self, raw: str, _cache: Optional[dict[str, Any]] = None) -> dict[str, Any]:
        s = (raw or "").strip()
        if not s:
            return {"kind": "empty", "ref": ""}
        if looks_like_url(s):
            return {"kind": "url", "ref": s}
        if _cache is not None and s in _cache:
            return _cache[s]
        cand = Path(os.path.expandvars(os.path.expanduser(s)))
        result: dict[str, Any] = {"kind": "missing", "ref": s}
        try:
            data = cand.read_bytes() if cand.is_file() else b""
        except Exception:
            data = b""
        if data:
            orig_ext = cand.suffix.lower() or ".wav"
            payload, codec, ext = data, "raw", orig_ext
            ff = getattr(self.tools, "ffmpeg", None)
            if ff and len(data) > 256 * 1024:
                try:
                    with tempfile.TemporaryDirectory(prefix="cutie_pack_") as td:
                        tdp = Path(td)
                        src_tmp = tdp / ("in" + orig_ext)
                        out_tmp = tdp / "pack.ogg"
                        src_tmp.write_bytes(data)
                        cp = subprocess.run(
                            [os.fspath(ff), "-y", "-v", "error", "-i", os.fspath(src_tmp),
                             "-c:a", "libopus", "-b:a", "64k", "-vn", os.fspath(out_tmp)],
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
                        if cp.returncode == 0 and out_tmp.is_file() and out_tmp.stat().st_size > 0:
                            enc = out_tmp.read_bytes()
                            if len(enc) < len(data):
                                payload, codec, ext = enc, "opus", ".ogg"
                except Exception as exc:
                    self.log.warning("Pack audio compression fell back to raw for %s: %s", cand.name, exc)
            result = {"kind": "file", "name": cand.name, "codec": codec, "ext": ext,
                      "sha256": hashlib.sha256(payload).hexdigest(), "bytes": len(payload),
                      "data_b64": base64.b64encode(payload).decode("ascii")}
        if _cache is not None:
            _cache[s] = result
        return result

    def _extract_pack_audio(self, item: dict[str, Any]) -> tuple[Optional[str], Optional[str], Optional[str]]:
        audio = item.get("audio")
        if not isinstance(audio, dict):
            return None, None, "legacy"
        kind = audio.get("kind")
        if kind == "url":
            return str(audio.get("ref", "")), "url", None
        if kind in ("empty", "missing"):
            return None, None, str(audio.get("ref") or "no source")
        if kind == "file":
            try:
                payload = base64.b64decode(audio.get("data_b64", ""))
            except Exception:
                return None, None, "embedded audio is corrupt"
            if not payload or hashlib.sha256(payload).hexdigest() != audio.get("sha256"):
                return None, None, "embedded audio failed its checksum"
            cache = self.paths.processed_audio / "pack_audio"
            with contextlib.suppress(Exception):
                cache.mkdir(parents=True, exist_ok=True)
            fname = f"{str(audio.get('sha256', 'pack'))[:16]}_{safe_name(str(audio.get('name', 'audio')))}{audio.get('ext', '.ogg')}"
            dest = cache / fname
            try:
                if not dest.is_file():
                    dest.write_bytes(payload)
            except Exception as exc:
                return None, None, f"could not stage audio ({exc})"
            return str(dest), "file", None
        return None, None, "unknown audio entry"

    def _resolve_pack_source(self, raw: str, pack_path: Path) -> Optional[Path]:
        s = (raw or "").strip()
        if not s:
            return None
        if looks_like_url(s):
            return None
        cand = Path(os.path.expandvars(os.path.expanduser(s)))
        if cand.is_file():
            return cand
        base = cand.name
        for alt in (pack_path.parent / base, self._packs_dir() / base):
            try:
                if alt.is_file():
                    return alt
            except Exception:
                pass
        return None

    def _bake_url_audio(self, url: str, cache: dict[str, Any]) -> Optional[dict[str, Any]]:
        def note(msg: str) -> None:
            with contextlib.suppress(Exception):
                self._last_bake_error = msg
        cached = cache.get(url)
        if isinstance(cached, dict) and cached.get("kind") == "file":
            return cached
        if not getattr(getattr(self, "tools", None), "yt_dlp", None):
            note("yt-dlp.exe was not found (check Tool status)")
            return None
        try:
            tmp = Path(tempfile.mkdtemp(prefix="cutie_bake_"))
            try:
                local = self.source_manager.materialize(url, tmp / "dl", "pack_audio")
                if local is None or not Path(local).is_file():
                    note("downloader returned no file")
                    return None
                emb = self._embed_source_audio(str(Path(local)), cache)
                if isinstance(emb, dict) and emb.get("kind") == "file":
                    cache[url] = emb
                    return emb
                note("downloaded audio could not be read")
                return None
            finally:
                with contextlib.suppress(Exception):
                    shutil.rmtree(tmp, ignore_errors=True)
        except Exception as exc:
            self.log.warning("Could not bake pack audio for %s: %s", url, exc)
            note(str(exc)[:160] or "download failed")
            return None

    def _embed_live_wem(self, bank_name: str, idx: int, media_cache: dict[str, Any]) -> Optional[dict[str, Any]]:
        try:
            key = str(bank_name or "").lower()
            stem = Path(bank_name).stem.lower() if bank_name else ""
            live = None
            for b in self.discovered_banks or []:
                try:
                    if Path(b).name.lower() == key or (stem and Path(b).stem.lower() == stem):
                        live = Path(b)
                        break
                except Exception:
                    continue
            if live is None or not live.is_file():
                return None
            ck = str(live)
            if ck not in media_cache:
                try:
                    media_cache[ck] = extract_embedded_wems_from_snapshot(parse_bnk_snapshot(live))
                except Exception:
                    return None
            want_idx = int(idx)
            payload = media_cache[ck].get(want_idx)
            if not payload:
                return None
            digest = hashlib.sha256(payload).hexdigest()
            return {"kind": "file", "name": f"{safe_name(live.stem)}_{want_idx}.wem", "codec": "raw", "ext": ".wem",
                    "sha256": digest, "bytes": len(payload), "data_b64": base64.b64encode(payload).decode("ascii")}
        except Exception as exc:
            self.log.debug("Live WEM embed skipped for %s #%s: %s", bank_name, idx, exc)
            return None

    def _install_snapshot_groups(self, parent, groups: dict[str, dict[int, bytes]], pack_name: str, stem_to_bank: dict[str, Path], after=None) -> None:
        total = sum(len(v) for v in groups.values())
        if not total:
            return
        if self._brawlhalla_is_running():
            cute_warning("Close Brawlhalla first", "Brawlhalla is currently running. Please close Brawlhalla, then install the pack again.", parent=parent)
            return
        if bool(self.confirm_install_var.get()):
            if not cute_ask("Apply to Brawlhalla?", f"I'll change {total} sound{'s' if total != 1 else ''} in your live Brawlhalla files.", parent=parent, hint="Temporary files are cleaned up automatically, and you can Undo this afterwards.", yes="Apply \u2661"):
                return
        wu = getattr(self.tools, "wwiseutil", None)
        if not wu:
            cute_error("Tool missing", "wwiseutil was not found. Open More \u25be \u2192 Tool Status and press Re-scan Tools, then try again.", parent=parent)
            return
        try:
            game_root = Path(self.game_target_var.get()).resolve()
        except Exception:
            cute_error("Install pack", "The game folder is not set. Load your game folder first.", parent=parent)
            return
        self._set_loading(True, "Installing snapshot sounds\u2026")
        with contextlib.suppress(Exception):
            self._show_processing_window(total)

        def worker() -> None:
            run_id = timestamp() + "_" + uuid.uuid4().hex[:6]
            undo = UndoManager(self.paths, self.log)
            adapter = WwiseUtilAdapter(Path(wu), self.runner, self.log)
            ok_names: list[str] = []
            problems: list[str] = []
            journal_entries: list[dict[str, Any]] = []
            tmp = Path(tempfile.mkdtemp(prefix="cutie_snap_"))
            try:
                for order, (stem, idx_map) in enumerate(sorted(groups.items())):
                    bank = stem_to_bank.get(stem)
                    if bank is None:
                        problems.append(f"{stem} \u2014 sound group not found")
                        continue
                    self._ui_after(0, lambda o=order, s=stem: self._set_process_progress(f"Installing {s}\u2026 \u2661", o, len(groups)))
                    try:
                        src = Path(bank).resolve()
                        try:
                            rel = src.relative_to(game_root)
                        except ValueError:
                            rel = Path(src.name)
                        target = game_root / rel
                        if not target.is_file():
                            raise FileNotFoundError(f"Game file not found: {target}")
                        stage = tmp / safe_name(stem)
                        stage.mkdir(parents=True, exist_ok=True)
                        files = adapter.unpack(target, stage / "extracted")
                        wem_map: dict[int, Path] = {}
                        for pos, path in enumerate(files, 1):
                            key = int(path.stem) if path.stem.isdigit() else pos
                            wem_map[key] = path
                        for idx in sorted(idx_map):
                            dest = wem_map.get(int(idx))
                            if dest is None:
                                raise RuntimeError(f"WEM {idx} is no longer inside {target.name}")
                            dest.write_bytes(idx_map[idx])
                        out_bank = stage / f"{safe_name(stem)}_snapshot.bnk"
                        adapter.replace(target, stage / "extracted", out_bank)
                        verify = extract_embedded_wems_from_snapshot(parse_bnk_snapshot(out_bank))
                        for idx, payload in idx_map.items():
                            if verify.get(int(idx)) != payload:
                                raise RuntimeError(f"Verification failed for WEM {idx} in {target.name}")
                        backup = undo.create_backup(run_id, target, target)
                        install_tmp = target.with_name(target.name + f".{run_id}.install.tmp")
                        try:
                            if install_tmp.exists():
                                install_tmp.unlink()
                            shutil.copy2(out_bank, install_tmp)
                            with open(install_tmp, "r+b") as fh:
                                fh.flush()
                                try:
                                    os.fsync(fh.fileno())
                                except OSError:
                                    pass
                            os.replace(install_tmp, target)
                        finally:
                            with contextlib.suppress(OSError):
                                install_tmp.unlink()
                        journal_entries.append({"installed_path": str(target), "backup_path": str(backup), "installed_sha256": sha256_file(target), "source_bank": str(bank)})
                        ok_names.append(f"{target.name} ({len(idx_map)})")
                    except Exception as exc:
                        self.log.error("Snapshot install failed for %s: %s", stem, exc)
                        first = str(exc).strip().splitlines()[0] if str(exc).strip() else "failed"
                        problems.append(f"{stem} \u2014 {first}")
            finally:
                with contextlib.suppress(Exception):
                    shutil.rmtree(tmp, ignore_errors=True)
            if journal_entries:
                try:
                    undo._write_journal(run_id, _dt.datetime.now().isoformat(timespec="seconds"), journal_entries)
                    undo.prune()
                except Exception as exc:
                    self.log.warning("Could not write snapshot undo record: %s", exc)
            self._ui_after(0, lambda: self._finish_snapshot_install(pack_name, ok_names, problems, after))

        threading.Thread(target=worker, daemon=True, name="CutieSnapshot").start()

    def _finish_snapshot_install(self, pack_name: str, ok_names: list[str], problems: list[str], after=None) -> None:
        with contextlib.suppress(Exception):
            self._close_processing_window()
        if ok_names:
            self._set_loading(False, "\u2661 Pack installed \u2014 refreshing sound groups\u2026")
            with contextlib.suppress(Exception):
                self.status_var.set("\u2661 Pack installed \u2014 refreshing sound groups\u2026")
            with contextlib.suppress(Exception):
                self.root.after(100, self.auto_scan_game_banks)
            cute_info("Pack installed \u2661", f"\u201c{pack_name}\u201d is live in Brawlhalla.\n\n" + "\n".join(ok_names[:12]), parent=self.root, hint="You can Undo this afterwards. The sound list refreshes automatically.")
        else:
            self._set_loading(False, "\u2661 Finished with a few hiccups.")
            with contextlib.suppress(Exception):
                self.status_var.set("\u2661 Snapshot install finished with errors.")
        if problems:
            cute_error("Some snapshot sounds didn't install", "\n".join(problems[:12]), parent=self.root)
        if after is not None:
            try:
                after()
            except Exception as exc:
                self.log.warning("Could not continue pack install: %s", exc)

    def _reapply_pack(self, parent, path: Optional[Path] = None) -> None:
        target = path
        if target is None:
            files = self._pack_files()
            if not files:
                cute_warning("Install pack", "No packs yet \u2014 make one above, or press Add pack.", parent=parent)
                return
            target = files[0]
        data = self._read_pack(target)
        if not data or not isinstance(data.get("items"), list) or not data["items"]:
            cute_warning("Re-apply pack", "This pack contains no usable sounds.", parent=parent)
            return
        stem_map: dict[str, Path] = {}
        for b in self.discovered_banks:
            try:
                stem_map.setdefault(Path(b).stem.lower(), Path(b))
            except Exception:
                pass
        need: list[Path] = []
        seen_need: set[Path] = set()
        for it in data["items"]:
            if not isinstance(it, dict) or it.get("snapshot"):
                continue
            bank = stem_map.get(str(it.get("bank_stem", "")).lower())
            if bank is not None and bank not in seen_need:
                seen_need.add(bank)
                if not self.bank_infos.get(str(bank)):
                    need.append(bank)
        if need:
            self._set_loading(True, f"Opening {len(need)} sound group(s) for the pack\u2026")
            threading.Thread(target=lambda: self._ensure_pack_banks(parent, target, data, stem_map, need), daemon=True, name="CutiePackLoad").start()
            return
        self._reapply_pack_build(parent, target, data, stem_map)

    def _ensure_pack_banks(self, parent, target, data, stem_map, need: list[Path]) -> None:
        for bank in need:
            start = time.time()
            requested = False
            while time.time() - start < 900:
                if bank in self.loaded_banks:
                    break
                has = bool(self.bank_infos.get(str(bank)))
                if bank not in self._loading_banks and (has or (requested and time.time() - start > 5)):
                    break
                if bank not in self._loading_banks and not has and not requested:
                    self._ui_after(0, lambda b=bank: self._load_bank_immediately(b))
                    requested = True
                time.sleep(0.5)
        self._ui_after(0, lambda: self._reapply_pack_build(parent, target, data, stem_map))

    def _reapply_pack_build(self, parent, target, data, stem_map) -> None:
        selections: list[Selection] = []
        problems: list[str] = []
        snap_groups: dict[str, dict[int, bytes]] = {}
        snap_problems: list[str] = []
        for it in data["items"]:
            if not isinstance(it, dict):
                continue
            if it.get("snapshot"):
                snap_label = str(it.get("label", it.get("wem_index", "?")))
                snap_stem = str(it.get("bank_stem", "")).lower()
                try:
                    snap_idx = int(it.get("wem_index", -1))
                except (TypeError, ValueError):
                    snap_idx = -1
                if not snap_stem or snap_stem not in stem_map:
                    snap_problems.append(f"{snap_label} \u2014 sound group not found (press Refresh first)")
                    continue
                staged, staged_kind, staged_err = self._extract_pack_audio(it)
                if staged_err or staged_kind != "file" or not staged:
                    snap_problems.append(f"{snap_label} \u2014 audio missing ({staged_err or 'no audio'})")
                    continue
                try:
                    snap_payload = Path(staged).read_bytes()
                except Exception as exc:
                    snap_problems.append(f"{snap_label} \u2014 audio unreadable ({exc})")
                    continue
                if not snap_payload:
                    snap_problems.append(f"{snap_label} \u2014 audio is empty")
                    continue
                snap_groups.setdefault(snap_stem, {})[snap_idx] = snap_payload
                continue
            label = str(it.get("label", it.get("wem_index", "?")))
            stem = str(it.get("bank_stem", "")).lower()
            bank = stem_map.get(stem)
            if bank is None:
                problems.append(f"{label} \u2014 sound group not found (press Refresh first)")
                continue
            infos = self.bank_infos.get(str(bank), [])
            if not infos:
                problems.append(f"{label} \u2014 group has no readable sounds (open it in the main list first)")
                continue
            try:
                want = int(it.get("wem_index", -1))
            except Exception:
                want = -1
            info = next((w for w in infos if int(w.index) == want), None)
            if info is None:
                problems.append(f"{label} \u2014 sound no longer in group")
                continue
            source, kind, audio_err = self._extract_pack_audio(it)
            if audio_err == "legacy":
                raw_src = str(it.get("src", ""))
                if looks_like_url(raw_src):
                    source, kind, audio_err = raw_src, "url", None
                else:
                    resolved = self._resolve_pack_source(raw_src, target)
                    if resolved is None:
                        problems.append(f"{label} \u2014 audio missing ({raw_src or 'no source'}; put it next to the .cutie file)")
                        continue
                    source, kind, audio_err = str(resolved), "file", None
            if audio_err:
                problems.append(f"{label} \u2014 audio missing ({audio_err})")
                continue
            try:
                rate = float(it.get("rate", 1.0) or 1.0)
            except Exception:
                rate = 1.0
            try:
                gain = float(it.get("gain_db", 0.0) or 0.0)
            except Exception:
                gain = 0.0
            try:
                fin = float(it.get("fade_in_s", 0.0) or 0.0)
            except Exception:
                fin = 0.0
            try:
                fout = float(it.get("fade_out_s", 0.0) or 0.0)
            except Exception:
                fout = 0.0
            try:
                off = float(it.get("offset_s", 0.0) or 0.0)
            except Exception:
                off = 0.0
            end_cut = it.get("end_cut_s")
            try:
                end_ms = None if end_cut in (None, "") else float(end_cut) * 1000.0
            except Exception:
                end_ms = None
            selections.append(Selection(
                info, source, kind,
                source_offset_ms=off * 1000.0, source_end_ms=end_ms,
                auto_match_duration=bool(it.get("auto_match", False)), playback_rate=rate,
                volume_db=gain, fade_in_ms=int(round(fin * 1000)), fade_out_ms=int(round(fout * 1000)),
                normalize_loudness=bool(it.get("normalize", False)), combine_original=bool(it.get("combine", False)),
                overlay_gain_db=gain,
                short_source_policy=str(it.get("short_policy", "loop") or "loop"),
            ))
        if problems or snap_problems:
            cute_error("Re-apply pack", "Some pack sounds could not be rebuilt:\n\n" + "\n".join((problems + snap_problems)[:12]), parent=parent)
            if not selections and not snap_groups:
                self._set_loading(False, "\u2661 Pack checked \u2014 nothing to install.")
                return
        if not selections and not snap_groups:
            self._set_loading(False, "\u2661 Pack checked \u2014 nothing to install.")
            cute_warning("Re-apply pack", "Nothing to re-apply.", parent=parent)
            return
        options = ProcessOptions(
            short_source_policy="loop", duration_tolerance_ms=2.0,
            conversion_preset="Vorbis Quality High", backup_inputs=False, verify_output=True,
            game_audio_dir=Path(self.game_target_var.get()), install_to_game=True,
        )
        self.log.info("Re-applying pack \u201c%s\u201d (%d sounds)", data.get("name", target.stem), len(selections))
        if snap_groups:
            after = (lambda: self._start_processing(selections, options, quick=True)) if selections else None
            self._install_snapshot_groups(parent, snap_groups, str(data.get("name", target.stem)), stem_map, after=after)
            return
        self._start_processing(selections, options, quick=True)

    def _open_pending_pack(self) -> None:
        try:
            with contextlib.suppress(Exception):
                self.root.deiconify()
                self.root.lift()
            self._open_pending_pack_inner()
        except Exception as exc:
            try:
                self.log.exception("Could not open pack on launch")
            except Exception:
                pass
            try:
                cute_error("Open pack", f"The app opened, but the pack would not:\n{exc}", parent=self.root)
            except Exception:
                pass

    def _check_cutie_assoc(self) -> None:
        if os.name != "nt":
            return
        try:
            if getattr(self, "_pending_pack_open", None):
                return
        except Exception:
            pass
        try:
            ok, current = cutie_association_state()
        except Exception:
            return
        if ok:
            return
        if self._cutie_target_missing(current):
            with contextlib.suppress(Exception):
                register_cutie_association()
                self.log.info("Repaired stale .cutie association")
            return
        try:
            if self.settings.get("cutie_assoc_prompted"):
                return
            self.settings["cutie_assoc_prompted"] = True
            with contextlib.suppress(Exception):
                self._save_ui_settings()
        except Exception:
            pass
        try:
            if current:
                if cute_ask("Fix .cutie files?", "Your .cutie files point at an old copy of the app. Point them here instead?", parent=self.root, hint="One click, no admin needed.", yes="Fix them ♡"):
                    self._register_cutie_here(self.root)
            else:
                if cute_ask("Clickable .cutie files?", "Want double-clicking a .cutie file to open it here, ready to install?", parent=self.root, hint="One click, no admin needed. Changeable anytime in Mod packs.", yes="Make it so ♡"):
                    self._register_cutie_here(self.root)
        except Exception:
            pass

    @staticmethod
    def _cutie_target_missing(current: str) -> bool:
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Classes\CutieSumoPack\shell\open\command") as k:
                cmd = str(winreg.QueryValueEx(k, "")[0])
            import re as _re
            parts = _re.findall(r'"([^"]+)"', cmd)
            if getattr(sys, "frozen", False):
                return not (len(parts) >= 1 and Path(parts[0]).is_file())
            return not (len(parts) >= 2 and Path(parts[0]).is_file() and Path(parts[1]).is_file())
        except Exception:
            return False

    def _open_pending_pack_inner(self) -> None:
        raw = getattr(self, "_pending_pack_open", None)
        self._pending_pack_open = None
        if not raw:
            return
        p = Path(str(raw))
        if not p.is_file():
            cute_error("Open pack", f"Pack file not found:\n{p}", parent=self.root)
            return
        data = self._read_pack(p)
        if data is None:
            cute_error("Open pack", "That file is not a .cutie pack.", parent=self.root)
            return
        dest = self._packs_dir() / p.name
        try:
            if p.resolve() != dest.resolve():
                i = 2
                while dest.exists():
                    other = self._read_pack(dest)
                    if other is not None and other == data:
                        break
                    dest = self._packs_dir() / f"{p.stem}_{i}{p.suffix or '.cutie'}"
                    i += 1
                if not dest.exists():
                    shutil.copy2(p, dest)
        except Exception as exc:
            cute_error("Open pack", f"Could not copy pack into Packs:\n{exc}", parent=self.root)
            return
        self._pack_to_open = dest
        self.show_packs(self.root)
        self._set_status(f"Opened pack \u2014 {data.get('name', dest.stem)} \u2661", kind="success")

    def _register_cutie_here(self, parent) -> None:
        try:
            msg = register_cutie_association()
        except Exception as exc:
            cute_error("Clickable .cutie files", f"Could not register:\n{exc}", parent=parent)
            return
        with contextlib.suppress(Exception):
            for _cp in self._packs_dir().glob("*.cutie"):
                try:
                    os.utime(_cp, None)
                except Exception:
                    continue
        with contextlib.suppress(Exception):
            refresh_cutie_icon()
        cute_info("Clickable .cutie files \u2661", msg + "\n\nNow double-click any .cutie file and the app opens it \u2014 with a cute little icon \u2661", parent=parent)

    def show_packs(self, parent=None) -> None:
        parent = parent or self.root
        win = tk.Toplevel(parent)
        self._windowed_lightweight(win, "Mod packs \u2661 \u00b7 v" + APP_VERSION, 1120, 880)
        win.transient(parent)
        win.grab_set()

        def reopen_packs() -> None:
            try:
                win.destroy()
            except Exception:
                pass
            self.show_packs(parent)

        outer = ttk.Frame(win, padding=16)
        outer.pack(fill="both", expand=True)
        hero = ttk.Frame(outer)
        try:
            _psty = ttk.Style()
            _pacc = self._theme_colors.get("accent", "#c35d91")
            _psty.configure("PackBank.TLabel", foreground=_pacc, font=("Segoe UI", 10, "bold"))
            _psty.configure("PackChip.TLabel", foreground=_pacc, font=("Segoe UI", 9, "bold"))
        except Exception:
            pass
        hero.pack(fill="x", pady=(0, 10))
        brand = ttk.Frame(hero)
        brand.pack(anchor="w")
        ttk.Label(brand, text="Mod packs", style="Hero.TLabel").pack(side="left")
        ttk.Label(brand, text="\u2661", style="BrandMark.TLabel").pack(side="left", padx=(7, 0), pady=(5, 0))
        ttk.Label(hero, text="Pick your modded sounds below, press Make pack, and share one .cutie file with the audio baked in. Install any pack back with one click \u2014 even after a Brawlhalla update.", style="HeroSub.TLabel", wraplength=960, justify="left").pack(anchor="w", pady=(4, 0))
        bar = ttk.Frame(outer)
        bar.pack(fill="x", pady=(0, 8))
        ttk.Button(bar, text="Add pack", style="Tool.TButton", command=lambda: (self._add_pack_from_file(win), refresh_packs())).pack(side="left")
        ttk.Button(bar, text="Open Folder", style="Tool.TButton", command=lambda: self._open_path(self._packs_dir())).pack(side="left", padx=(6, 0))
        ttk.Button(bar, text="Close", style="Tool.TButton", command=win.destroy).pack(side="right")

        tabs = ttk.Notebook(outer)
        tabs.pack(fill="both", expand=True)
        make_frame = ttk.Frame(tabs, padding=10)
        tabs.add(make_frame, text="\u2661 1 \u00b7 Make a pack")
        ttk.Label(make_frame, text="Pick a group on the left, tick its sounds on the right, then press Make pack ♡. Double-click a group for its whole set.", wraplength=1000, justify="left").pack(anchor="w", pady=(2, 6))
        filter_row = ttk.Frame(make_frame, style="Toolbar.TFrame", padding=(6, 5))
        filter_row.pack(fill="x", pady=(0, 7))
        ttk.Label(filter_row, text="Find a sound:", style="ToolbarSmall.TLabel").pack(side="left")
        filter_var = tk.StringVar(value="")
        find_entry = ttk.Entry(filter_row, textvariable=filter_var, width=40)
        find_entry.pack(side="left", padx=(8, 0), fill="x", expand=True)
        self._add_tooltip(find_entry, "Search your modded sounds by group, number, or source.")
        ttk.Button(filter_row, text="\u00d7", width=2, style="Tool.TButton", command=lambda: filter_var.set("")).pack(side="left", padx=(6, 0))
        picked_var = tk.StringVar(value="0/0 picked")
        gcount_var = tk.StringVar(value="0 groups")
        checked: set[str] = set()
        child_of: dict[str, tuple[int, int]] = {}
        children_of_bank: dict[str, list[str]] = {}
        parent_of: dict[str, str] = {}
        row_widgets: dict[str, dict[str, Any]] = {}
        bank_ids: list[str] = []
        bank_meta: dict[str, tuple[str, int, list[tuple[int, dict[str, Any]]]]] = {}
        sel_bank: list = [None]
        filling = {"on": False}
        bar_w = {"w": 120}
        try:
            mod_rows = self._preset_rows()
        except Exception as exc:
            self.log.warning("Could not load saved recipes: %s", exc)
            mod_rows = []
        try:
            mod_rows = list(mod_rows) + self._journal_snapshot_rows(mod_rows)
        except Exception as exc:
            self.log.warning("Could not scan backups for mods: %s", exc)
        try:
            _pack_live_stems = {Path(b).stem.lower() for b in (self.discovered_banks or [])}
        except Exception:
            _pack_live_stems = set()
        def _pack_row_live(bank_no: int) -> bool:
            try:
                crow = mod_rows[bank_no]
            except Exception:
                return True
            if not isinstance(crow, dict):
                return True
            cands: set[str] = set()
            bn = str(crow.get("bank_name", "") or "")
            if bn:
                cands.add(Path(bn).stem.lower())
            for e in (crow.get("recipe", []) or []):
                if isinstance(e, dict):
                    for k in ("bank_stem", "bank_name"):
                        v = str(e.get(k, "") or "")
                        if v:
                            cands.add(Path(v).stem.lower())
            if not cands:
                return True
            return any(c in _pack_live_stems for c in cands)

        split = ttk.Frame(make_frame)
        split.pack(fill="both", expand=True)
        gcard = ttk.Frame(split, style="Workspace.TFrame")
        gcard.pack(side="left", fill="y", padx=(0, 6))
        ghead = ttk.Frame(gcard, style="Workspace.TFrame")
        ghead.pack(fill="x", pady=(0, 7))
        ttk.Label(ghead, text="\u2661 1 \u00b7 Pick a group", style="Section.TLabel").pack(side="left")
        ttk.Label(ghead, textvariable=gcount_var, style="Count.TLabel").pack(side="left", padx=(7, 0))
        glist = ttk.Frame(gcard, style="Card.TFrame", padding=4)
        glist.pack(fill="both", expand=True)
        gscroll = ttk.Scrollbar(glist, orient="vertical")
        gscroll.pack(side="right", fill="y")
        groups_lb = tk.Listbox(glist, width=32, relief="flat", borderwidth=0, highlightthickness=0, activestyle="none", font=("Segoe UI", 10))
        try:
            groups_lb.configure(bg=self._theme_colors.get("field", "#ffffff"), fg=self._theme_colors.get("fg", "#222222"), selectbackground=self._theme_colors.get("accent", "#c35d91"), selectforeground="#ffffff")
        except Exception:
            pass
        groups_lb.pack(side="left", fill="y", expand=True)
        gscroll.config(command=groups_lb.yview)
        groups_lb.configure(yscrollcommand=gscroll.set)
        rcard = ttk.Frame(split, style="Workspace.TFrame")
        rcard.pack(side="left", fill="both", expand=True)
        rhead = ttk.Frame(rcard, style="Workspace.TFrame")
        rhead.pack(fill="x", pady=(0, 7))
        ttk.Label(rhead, text="\u2661 2 \u00b7 Pick sounds", style="Section.TLabel").pack(side="left")
        rname = ttk.Label(rhead, text="Pick a group on the left", style="Small.TLabel")
        rname.pack(side="left", padx=(7, 0))
        rall = ttk.Button(rhead, text="All", width=6, style="Tool.TButton", command=lambda: toggle_bank(sel_bank[0]) if sel_bank[0] else None)
        rall.pack(side="right")
        rlist = ttk.Frame(rcard, style="Card.TFrame", padding=4)
        rlist.pack(fill="both", expand=True)
        rbar = tk.Canvas(rlist, height=4, highlightthickness=0, bd=0, bg=self._theme_colors.get("canvas", "#fff7fb"))
        rbar.pack(fill="x", pady=(4, 2))
        rcanvas = tk.Canvas(rlist, highlightthickness=0, bd=0, bg=self._theme_colors.get("canvas", "#fff7fb"))
        rscroll = ttk.Scrollbar(rlist, orient="vertical", command=rcanvas.yview)
        rcanvas.configure(yscrollcommand=rscroll.set)
        rscroll.pack(side="right", fill="y")
        rcanvas.pack(side="left", fill="both", expand=True)
        rbody = ttk.Frame(rcanvas, padding=2)
        rwin = rcanvas.create_window((0, 0), window=rbody, anchor="nw")
        if not self.discovered_banks:
            ttk.Label(make_frame, text="Tip: load your game folder (Refresh in the main window) so packs copy audio straight from your game \u2661", wraplength=1000, justify="left").pack(anchor="w", pady=(0, 4), before=split)

        def sync_right(_e: Any = None) -> None:
            try:
                rcanvas.configure(scrollregion=rcanvas.bbox("all"))
                rcanvas.itemconfigure(rwin, width=int(rcanvas.winfo_width() or 1))
            except Exception:
                pass
        rbody.bind("<Configure>", lambda _e: sync_right())
        rcanvas.bind("<Configure>", sync_right)

        def short_domain(src: str, live: bool) -> str:
            if live:
                return "from game backup"
            s = (src or "").strip()
            if looks_like_url(s):
                try:
                    host = s.split("://", 1)[1].split("/", 1)[0].split("?", 1)[0]
                    if host.lower().startswith("www."):
                        host = host[4:]
                    return host[:22]
                except Exception:
                    return "link"
            base = os.path.basename(s.strip().strip('"').strip("'"))
            return base[:28] if base else "link"

        def update_picked_label() -> None:
            try:
                n = sum(1 for i in checked if i in child_of)
                picked_var.set(f"{n}/{len(child_of)} picked")
            except Exception:
                pass

        def draw_bar(picked: int, total: int) -> None:
            try:
                rbar.delete("all")
                w = int(rbar.winfo_width() or 0)
                if w < 10:
                    w = int(bar_w["w"])
                else:
                    bar_w["w"] = w
                if total > 0 and picked > 0:
                    rbar.create_rectangle(0, 0, max(2, int(w * picked / total)), 6, fill=self._theme_colors.get("accent", "#c35d91"), outline="")
            except Exception:
                pass

        def group_line(b: str) -> str:
            bank_name, bank_no, _ = bank_meta[b]
            kids = children_of_bank.get(b, [])
            p = sum(1 for k in kids if k in checked)
            nm = bank_name if len(bank_name) <= 26 else bank_name[:24] + "\u2026"
            mark = "\u2713" if kids and p == len(kids) else ("\u25cf" if p else "\u25cb")
            try:
                live = _pack_row_live(bank_no)
            except Exception:
                live = True
            tail = "" if live else "  \u2717 not in game folder"
            return f"{mark} {nm} \u00b7 {p}/{len(kids)}{tail}"

        def paint_row(iid: str) -> None:
            refs = row_widgets.get(iid)
            if not refs:
                return
            try:
                refs["box"].configure(text="\u25cf" if iid in checked else "\u25cb")
                refs["title"].configure(font=("Segoe UI", 10, "bold") if iid in checked else ("Segoe UI", 10))
            except Exception:
                pass

        def paint_head(b: Any) -> None:
            if b != sel_bank[0] or b not in bank_meta:
                return
            try:
                kids = children_of_bank.get(b, [])
                p = sum(1 for k in kids if k in checked)
                bank_name, _, _ = bank_meta[b]
                shown = bank_name if len(bank_name) <= 34 else bank_name[:32] + "\u2026"
                rname.configure(text=f"{shown} \u00b7 {p}/{len(kids)}")
                rall.configure(text="\u2713 All" if kids and p == len(kids) else "All")
                draw_bar(p, len(kids))
            except Exception:
                pass

        def refresh_group_line(b: str) -> None:
            try:
                i = bank_ids.index(b)
            except ValueError:
                return
            try:
                if groups_lb.get(i) != group_line(b):
                    sel = i in groups_lb.curselection()
                    groups_lb.delete(i)
                    groups_lb.insert(i, group_line(b))
                    if sel:
                        groups_lb.selection_set(i)
            except Exception:
                pass

        def refresh_all() -> None:
            for b in list(bank_ids):
                refresh_group_line(b)
            paint_head(sel_bank[0])
            update_picked_label()

        def invert_picks() -> None:
            for iid in list(child_of.keys()):
                if iid in checked:
                    checked.discard(iid)
                else:
                    checked.add(iid)
            for k in list(row_widgets.keys()):
                paint_row(k)
            refresh_all()

        def toggle_row(iid: str) -> None:
            if iid in checked:
                checked.discard(iid)
            else:
                checked.add(iid)
            paint_row(iid)
            owner = parent_of.get(iid)
            if owner is not None:
                refresh_group_line(owner)
                paint_head(owner)
            update_picked_label()

        def toggle_bank(bank_iid: Any) -> None:
            if not bank_iid or bank_iid not in bank_meta:
                return
            kids = children_of_bank.get(bank_iid, [])
            if kids and all(k in checked for k in kids):
                for k in kids:
                    checked.discard(k)
            else:
                for k in kids:
                    checked.add(k)
            if bank_iid == sel_bank[0]:
                for k in kids:
                    paint_row(k)
                paint_head(bank_iid)
            refresh_group_line(bank_iid)
            update_picked_label()

        def wheel_scroll(e: Any) -> str:
            try:
                delta = int(getattr(e, "delta", 0) or 0)
                step = -1 * (delta // 120) if delta else 0
                if step:
                    rcanvas.yview_scroll(step, "units")
            except Exception:
                pass
            return "break"

        def wheel_up(_e: Any) -> str:
            try:
                rcanvas.yview_scroll(-3, "units")
            except Exception:
                pass
            return "break"

        def wheel_down(_e: Any) -> str:
            try:
                rcanvas.yview_scroll(3, "units")
            except Exception:
                pass
            return "break"

        def wheel_bind(w: Any) -> None:
            try:
                w.bind("<MouseWheel>", wheel_scroll, add="+")
                w.bind("<Button-4>", wheel_up, add="+")
                w.bind("<Button-5>", wheel_down, add="+")
            except Exception:
                pass
            try:
                for ch in w.winfo_children():
                    wheel_bind(ch)
            except Exception:
                pass

        try:
            rcanvas.bind("<MouseWheel>", wheel_scroll)
            rcanvas.bind("<Button-4>", wheel_up)
            rcanvas.bind("<Button-5>", wheel_down)
        except Exception:
            pass

        def build_right() -> None:
            q = filter_var.get().strip().lower()
            for ch in rbody.winfo_children():
                ch.destroy()
            for k in list(row_widgets.keys()):
                row_widgets.pop(k, None)
            b = sel_bank[0]
            if not b or b not in bank_meta:
                try:
                    rname.configure(text="Pick a group on the left")
                    rall.configure(text="All")
                    draw_bar(0, 0)
                except Exception:
                    pass
                return
            paint_head(b)
            _, bank_no, indexed = bank_meta[b]
            n = 0
            for idx, item in indexed:
                child_iid = f"mpack::wem::{bank_no}::{idx}"
                if q and q not in f"wem {idx} \u00b7 {item.get('wem_name', '')}".lower() and q not in str(item.get("source", "")).lower():
                    continue
                live = bool(item.get("_live"))
                r = ttk.Frame(rbody)
                r.pack(fill="x", pady=1)
                box = ttk.Button(r, text="\u25cb", width=3, style="Tool.TButton", command=lambda i=child_iid: toggle_row(i))
                box.pack(side="left")
                label = f"WEM {idx} \u00b7 {item.get('wem_name', '')} \u00b7 {short_domain(str(item.get('source', '')), live)}"
                if len(label) > 64:
                    label = label[:62] + "\u2026"
                title = ttk.Label(r, text=label, font=("Segoe UI", 10))
                title.pack(side="left", padx=(6, 0))
                row_widgets[child_iid] = {"box": box, "title": title}
                for w in (r, title):
                    w.bind("<Button-1>", lambda _e, i=child_iid: toggle_row(i))
                paint_row(child_iid)
                n += 1
            if not n:
                ttk.Label(rbody, text="Nothing matches \u2014 clear the search \u2661", style="Small.TLabel").pack(anchor="w", padx=6, pady=10)
            wheel_bind(rbody)
            sync_right()

        def on_group_select(_e: Any = None) -> None:
            if filling["on"]:
                return
            try:
                s = groups_lb.curselection()
            except Exception:
                return
            if not s:
                return
            try:
                b = bank_ids[s[0]]
            except IndexError:
                return
            if b and b != sel_bank[0]:
                sel_bank[0] = b
                build_right()

        groups_lb.bind("<<ListboxSelect>>", on_group_select)
        groups_lb.bind("<Double-Button-1>", lambda _e: toggle_bank(sel_bank[0]))

        def rebuild_make_cards(*_a: Any) -> None:
            try:
                if not split.winfo_exists():
                    return
            except Exception:
                return
            q = filter_var.get().strip().lower()
            bank_ids.clear()
            bank_meta.clear()
            child_of.clear()
            children_of_bank.clear()
            parent_of.clear()
            row_widgets.clear()
            banks: list[tuple[str, int, list[tuple[int, dict[str, Any]]]]] = []
            for bank_no, crow in enumerate(mod_rows):
                if not isinstance(crow, dict):
                    continue
                bank_name = str(crow.get("bank_name", "Unknown BNK"))
                recipe = crow.get("recipe", [])
                if not isinstance(recipe, list):
                    recipe = []
                indexed: list[tuple[int, dict[str, Any]]] = []
                for entry in recipe:
                    if not isinstance(entry, dict):
                        continue
                    try:
                        number = int(entry.get("wem_index", 0))
                    except (TypeError, ValueError):
                        try:
                            number = int(float(str(entry.get("wem_index", 0))))
                        except (TypeError, ValueError):
                            continue
                    indexed.append((number, entry))
                indexed.sort(key=lambda pair: pair[0])
                if q and q not in bank_name.lower():
                    indexed = [(n, e) for n, e in indexed if q in f"wem {n} \u00b7 {e.get('wem_name', '')}".lower() or q in str(e.get("source", "")).lower()]
                if not indexed:
                    continue
                banks.append((bank_name, bank_no, indexed))
            for bank_name, bank_no, indexed in banks:
                bank_iid = f"mpack::bank::{bank_no}"
                children_of_bank[bank_iid] = []
                bank_meta[bank_iid] = (bank_name, bank_no, indexed)
                bank_ids.append(bank_iid)
                for idx, _item in indexed:
                    child_iid = f"mpack::wem::{bank_no}::{idx}"
                    if child_iid in child_of:
                        continue
                    child_of[child_iid] = (bank_no, idx)
                    parent_of[child_iid] = bank_iid
                    children_of_bank[bank_iid].append(child_iid)
            if sel_bank[0] not in bank_meta:
                sel_bank[0] = bank_ids[0] if bank_ids else None
            filling["on"] = True
            try:
                groups_lb.delete(0, "end")
                for b in bank_ids:
                    groups_lb.insert("end", group_line(b))
                if sel_bank[0] in bank_meta:
                    i = bank_ids.index(sel_bank[0])
                    groups_lb.selection_set(i)
                    groups_lb.see(i)
                elif bank_ids:
                    groups_lb.selection_set(0)
            except Exception:
                pass
            filling["on"] = False
            gcount_var.set(f"{len(bank_ids)} group{'s' if len(bank_ids) != 1 else ''}")
            if not bank_ids:
                try:
                    rname.configure(text="Nothing here yet")
                    rall.configure(text="All")
                    draw_bar(0, 0)
                except Exception:
                    pass
                msg = f'Nothing matches "{filter_var.get().strip()}" \u2014 clear the search \u2661' if q else ("Nothing here yet \u2014 press Refresh in the main window, then replace a sound \u2661" if not mod_rows else "No saved recipes yet \u2014 new mods save here automatically \u2661")
                ttk.Label(rbody, text=msg, style="Small.TLabel").pack(anchor="w", padx=6, pady=12)
                update_picked_label()
                return
            build_right()
            update_picked_label()

        search_after = {"id": None}

        def on_filter_type(*_a: Any) -> None:
            try:
                if search_after["id"] is not None:
                    win.after_cancel(search_after["id"])
            except Exception:
                pass
            try:
                search_after["id"] = win.after(150, rebuild_make_cards)
            except Exception:
                rebuild_make_cards()

        filter_var.trace_add("write", on_filter_type)
        rebuild_make_cards()

        make_btns = ttk.Frame(make_frame)
        make_btns.pack(side="bottom", fill="x", pady=(8, 0))
        ttk.Label(make_btns, textvariable=picked_var, style="Count.TLabel", font=("Segoe UI", 9, "bold")).pack(side="left", padx=(2, 8))
        ttk.Button(make_btns, text="All groups", style="Tool.TButton", command=lambda: (checked.update(child_of.keys()), refresh_all())).pack(side="left")
        ttk.Button(make_btns, text="Invert", style="Tool.TButton", command=invert_picks).pack(side="left", padx=(6, 0))
        ttk.Button(make_btns, text="Clear", style="Tool.TButton", command=lambda: (checked.clear(), refresh_all())).pack(side="left", padx=(6, 0))
        ttk.Button(make_btns, text="Make pack \u2661", style="Big.TButton", command=lambda: make_pack()).pack(side="right")
        n_snap = sum(1 for r in mod_rows if isinstance(r, dict) and r.get("_snap_bank"))
        n_recipe = sum(1 for r in mod_rows if isinstance(r, dict) and not r.get("_snap_bank"))
        try:
            n_missing = sum(1 for n in range(len(mod_rows)) if isinstance(mod_rows[n], dict) and not _pack_row_live(n))
        except Exception:
            n_missing = 0
        ctx_row = ttk.Frame(make_frame)
        ctx_row.pack(fill="x", pady=(0, 4), before=filter_row)
        ctx_text = f"Recipes: {n_recipe} \u00b7 Traces: {n_snap} \u00b7 {self._preset_file().name}"
        if n_missing:
            ctx_text += f" \u00b7 {n_missing} group(s) not in game folder \u2014 press Refresh in the main window; removed game files can't come back"
        ttk.Label(ctx_row, text=ctx_text, style="Small.TLabel", wraplength=1000, justify="left").pack(side="left")
        ttk.Button(ctx_row, text="Locate\u2026", width=9, style="Tool.TButton", command=lambda: self._import_preset_file(win, reopen_packs)).pack(side="left", padx=(8, 0))
        ttk.Button(ctx_row, text="Data folder", width=11, style="Tool.TButton", command=lambda: self._open_path(self._preset_file().parent)).pack(side="left", padx=(4, 0))

        def recipe_item(bank_no: int, idx: int) -> Optional[dict[str, Any]]:
            if not (0 <= bank_no < len(mod_rows)):
                return None
            for x in mod_rows[bank_no].get("recipe", []):
                if isinstance(x, dict):
                    try:
                        if int(x.get("wem_index", -1)) == idx:
                            return x
                    except (TypeError, ValueError):
                        pass
            return None

        def make_pack() -> None:
            picks = sorted(child_of[i] for i in checked if i in child_of)
            if not picks:
                cute_warning("Make pack", "Check one or more modded sounds first.", parent=win)
                return
            needs_net = False
            for bno, idx in picks:
                src_item = recipe_item(bno, idx) or {}
                if not src_item.get("_live") and looks_like_url(str(src_item.get("source", ""))):
                    needs_net = True
                    break
            with contextlib.suppress(Exception):
                self.tools = ToolLocator(self.paths).locate()
            if not needs_net:
                items, missing, skipped, unbaked = bake_all(picks, None)
                finish_make(items, missing, skipped, unbaked)
                return
            self._set_loading(True, "Baking pack audio\u2026 \u2661")
            with contextlib.suppress(Exception):
                self._show_processing_window(len(picks))

            def bake_worker() -> None:
                items, missing, skipped, unbaked = bake_all(picks, True)
                self._ui_after(0, lambda: finish_make(items, missing, skipped, unbaked))

            threading.Thread(target=bake_worker, daemon=True, name="CutiePackBake").start()

        def bake_all(picks: list[tuple[int, int]], progress: bool = False) -> tuple[list[dict[str, Any]], list[str], set[int], list[str]]:
            audio_cache: dict[str, Any] = {}
            live_cache: dict[str, Any] = {}
            items: list[dict[str, Any]] = []
            missing: list[str] = []
            skipped: set[int] = set()
            unbaked: list[str] = []
            for pos, (bno, idx) in enumerate(picks):
                src_item = recipe_item(bno, idx) or {}
                bank_name = str((mod_rows[bno] or {}).get("bank_name", ""))
                from_live = False
                if src_item.get("_live"):
                    live_bank = Path(str((mod_rows[bno] or {}).get("_snap_bank", "")))
                    snap_payload = None
                    try:
                        if live_bank.is_file():
                            snap_payload = extract_embedded_wems_from_snapshot(parse_bnk_snapshot(live_bank)).get(int(idx))
                    except Exception:
                        snap_payload = None
                    raw_src = ""
                    if snap_payload:
                        digest = hashlib.sha256(snap_payload).hexdigest()
                        emb = {"kind": "file", "name": f"{safe_name(live_bank.stem)}_{int(idx)}.wem", "codec": "raw", "ext": ".wem", "sha256": digest, "bytes": len(snap_payload), "data_b64": base64.b64encode(snap_payload).decode("ascii")}
                    else:
                        emb = {"kind": "missing", "ref": f"{live_bank.name} WEM {idx}"}
                else:
                    raw_src = str(src_item.get("source", ""))
                    live_emb = self._embed_live_wem(bank_name, idx, live_cache)
                    if live_emb is not None:
                        emb = live_emb
                        from_live = True
                    else:
                        emb = self._embed_source_audio(raw_src, audio_cache)
                    if emb.get("kind") == "url":
                        with contextlib.suppress(Exception):
                            self._last_bake_error = ""
                        baked = self._bake_url_audio(raw_src, audio_cache)
                        if baked is not None:
                            emb = baked
                        else:
                            with contextlib.suppress(Exception):
                                reason = str(getattr(self, "_last_bake_error", "") or "download failed").strip()
                            unbaked.append(f"WEM {idx} ({raw_src}) \u2014 {reason}")
                if progress:
                    self._ui_after(0, lambda p=pos: self._set_process_progress(f"Baking audio {p + 1}/{len(picks)}\u2026 \u2661", p + 1, len(picks)))
                if emb.get("kind") in ("missing", "empty"):
                    missing.append(f"WEM {idx} ({raw_src or 'no source'})")
                    skipped.add(pos)
                end_raw = src_item.get("source_end_ms")
                try:
                    end_cut = None if end_raw in (None, "") else float(end_raw) / 1000.0
                except (TypeError, ValueError):
                    end_cut = None
                items.append({
                    "bank_stem": Path(bank_name).stem, "bank_name": bank_name,
                    "wem_index": idx, "label": str(src_item.get("wem_name", f"WEM {idx}")),
                    "src": raw_src, "audio": emb, "snapshot": bool(src_item.get("_live")) or from_live,
                    "offset_s": float(src_item.get("offset_ms", 0.0) or 0.0) / 1000.0,
                    "end_cut_s": end_cut,
                    "auto_match": bool(src_item.get("auto_match_duration", False)),
                    "rate": float(src_item.get("playback_rate", 1.0) or 1.0),
                    "gain_db": float(src_item.get("volume_db", 0.0) or 0.0),
                    "fade_in_s": int(src_item.get("fade_in_ms", 0) or 0) / 1000.0,
                    "fade_out_s": int(src_item.get("fade_out_ms", 0) or 0) / 1000.0,
                    "normalize": bool(src_item.get("normalize_loudness", False)),
                    "combine": bool(src_item.get("combine_original", False)),
                    "short_policy": str(src_item.get("short_source_policy", "loop") or "loop"),
                })
            if progress:
                self._ui_after(0, lambda: self._set_process_progress("Baking audio done \u2661", len(picks), len(picks)))
            return items, missing, skipped, unbaked

        def finish_make(items: list[dict[str, Any]], missing: list[str], skipped: set[int], unbaked: list[str]) -> None:
            with contextlib.suppress(Exception):
                self._close_processing_window()
            self._set_loading(False, "\u2661 Audio baked \u2014 name your pack.")
            if unbaked:
                shown = "\n".join(unbaked[:8]) + ("\n\u2026" if len(unbaked) > 8 else "")
                if not cute_ask("Audio didn't bake in", "These sounds are saved as web links ONLY \u2014 no audio inside the pack:\n\n" + shown, parent=win, hint="Usually yt-dlp is missing or the download failed (see Tool status + Log). Local files and game sounds always bake in; link-only packs need internet at install.", yes="Keep links \u2661", no="Stop"):
                    return
            if missing:
                if not cute_ask("Some audio is missing", "These sounds have no audio file to bake in:\n\n" + "\n".join(missing[:10]) + "\n\nMake the pack without them?", parent=win, hint="Web links are kept as links; missing local files are skipped.", yes="Make it anyway \u2661"):
                    return
                items = [it for pos, it in enumerate(items) if pos not in skipped]
                if not items:
                    return
            ask_name(items)

        def ask_name(items: list[dict[str, Any]]) -> None:
            dlg = tk.Toplevel(win)
            self._windowed_lightweight(dlg, "Name your pack \u2661", 460, 300)
            dlg.transient(win)
            dlg.grab_set()
            body = ttk.Frame(dlg, padding=16)
            body.pack(fill="both", expand=True)
            ttk.Label(body, text="\u2661 Name your pack", font=("Segoe UI", 14, "bold")).pack(anchor="w")
            baked_n = sum(1 for it in items if isinstance(it, dict) and isinstance(it.get("audio"), dict) and it.get("audio", {}).get("kind") == "file")
            linked_n = len(items) - baked_n
            sub = f"{baked_n} sound(s) with audio baked in." if not linked_n else f"{baked_n} baked in \u00b7 {linked_n} linked (needs internet at install)."
            ttk.Label(body, text=sub, style="Small.TLabel").pack(anchor="w", pady=(4, 10))
            ttk.Label(body, text="Pack name:").pack(anchor="w")
            name_var = tk.StringVar(value="")
            name_entry = ttk.Entry(body, textvariable=name_var, width=44)
            name_entry.pack(fill="x", pady=(2, 8))
            name_entry.focus_set()
            ttk.Label(body, text="One-line description (optional):").pack(anchor="w")
            desc_var = tk.StringVar(value="")
            ttk.Entry(body, textvariable=desc_var, width=44).pack(fill="x", pady=(2, 12))
            btns = ttk.Frame(body)
            btns.pack(fill="x")
            ttk.Button(btns, text="Make pack \u2661", style="Big.TButton", command=lambda: finish()).pack(side="left")
            ttk.Button(btns, text="Cancel", style="Tool.TButton", command=dlg.destroy).pack(side="left", padx=(6, 0))

            def finish() -> None:
                name = name_var.get().strip() or f"My Pack {len(self._pack_files()) + 1}"
                pack = {"name": name, "desc": desc_var.get().strip() or "Custom Cutie Sumo pack.", "created": timestamp(), "items": items}
                base = safe_name(name) or "pack"
                dest = self._packs_dir() / f"{base}.cutie"
                i = 2
                while dest.exists():
                    dest = self._packs_dir() / f"{base}_{i}.cutie"
                    i += 1
                total = sum(int((it.get("audio") or {}).get("bytes", 0)) for it in items if isinstance(it.get("audio"), dict))
                if total > 80 * 1024 * 1024:
                    if not cute_ask("Big pack?", f"This pack embeds {total / 1048576:.0f} MB of audio. Save it anyway?", parent=dlg, yes="Save anyway"):
                        return
                try:
                    dest.write_text(json.dumps({"app": "cutie-sumo", "kind": "mod-pack", "version": 1, "pack": pack}, indent=2), encoding="utf-8")
                except Exception as exc:
                    cute_error("Make pack", f"Could not write pack:\n{exc}", parent=dlg)
                    return
                self.log.info("Pack made: %s (%d sounds)", name, len(items))
                dlg.destroy()
                refresh_packs()
                with contextlib.suppress(Exception):
                    tabs.select(packs_frame)
                if cute_ask("Pack ready \u2661", f"\u201c{name}\u201d is saved in Packs.\n\nWould you like to export this pack file somewhere?", parent=win, hint="Send the exported file to a friend \u2014 they press Add pack.", yes="Export \u2661", no="Keep in Packs"):
                    self._export_pack(win, dest)
                    refresh_packs()

        packs_frame = ttk.Frame(tabs, padding=10)
        tabs.add(packs_frame, text="\u2661 2 \u00b7 Install a pack")
        ttk.Label(packs_frame, text="One click puts a pack's sounds back into Brawlhalla \u2014 even after an update.").pack(anchor="w", pady=(2, 6))
        cards_outer = ttk.Frame(packs_frame, style="Card.TFrame", padding=4)
        cards_outer.pack(fill="both", expand=True)
        canvas = tk.Canvas(cards_outer, highlightthickness=0, bd=0, bg=self._theme_colors.get("canvas", "#fff7fb"))
        scroll = ttk.Scrollbar(cards_outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        cards = ttk.Frame(canvas, padding=4)
        cards_win = canvas.create_window((0, 0), window=cards, anchor="nw")

        def sync_cards(_e: Any = None) -> None:
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
                canvas.itemconfigure(cards_win, width=int(canvas.winfo_width() or 1))
            except Exception:
                pass
        cards.bind("<Configure>", lambda _e: sync_cards())
        canvas.bind("<Configure>", sync_cards)

        def refresh_packs() -> None:
            try:
                if not cards.winfo_exists():
                    return
            except Exception:
                return
            for ch in cards.winfo_children():
                ch.destroy()
            card_of.clear()
            files = self._pack_files()
            if not files:
                ttk.Label(cards, text="No packs yet \u2014 make one in the \u2661 1 tab, or press Add pack to copy a friend's .cutie file here. \u2661", style="Small.TLabel", wraplength=880).pack(anchor="w", pady=6)
            for path in files:
                data = self._read_pack(path) or {}
                pack_items = data.get("items", []) if isinstance(data.get("items"), list) else []
                card = ttk.Frame(cards, style="Card.TFrame", padding=12)
                card.pack(fill="x", pady=(0, 8))
                with contextlib.suppress(Exception):
                    card_of[str(path)] = card
                head = ttk.Frame(card)
                head.pack(fill="x")
                ttk.Label(head, text=f"\u2661 {data.get('name', path.stem)}", font=("Segoe UI", 12, "bold")).pack(side="left")
                ttk.Label(head, text=f"{len(pack_items)} sound(s)", style="Small.TLabel").pack(side="left", padx=(8, 0))
                ttk.Label(card, text=str(data.get("desc", "")), style="Small.TLabel", wraplength=880).pack(anchor="w")
                by_bank: dict[str, list[str]] = {}
                for it in pack_items:
                    if not isinstance(it, dict):
                        continue
                    by_bank.setdefault(str(it.get("bank_name", "?")), []).append(f"WEM {it.get('wem_index', '?')} \u00b7 {it.get('label', '')}")
                detail_txt = "\n".join(f"\u25b8 {b} \u2014 {', '.join(v[:6])}{' \u2026' if len(v) > 6 else ''}" for b, v in sorted(by_bank.items()))
                ttk.Label(card, text=detail_txt or "Empty pack.", style="Small.TLabel", wraplength=880, justify="left").pack(anchor="w", pady=(6, 0))
                row = ttk.Frame(card)
                row.pack(fill="x", pady=(8, 0))
                ttk.Button(row, text="Install pack \u2661", style="Big.TButton", command=lambda p=path: (win.destroy(), self._reapply_pack(self.root, p))).pack(side="left")
                ttk.Button(row, text="Export", style="Tool.TButton", command=lambda p=path: self._export_pack(win, p)).pack(side="left", padx=(6, 0))
                ttk.Button(row, text="Delete", style="Tool.TButton", command=lambda p=path: delete_pack(p)).pack(side="left", padx=(6, 0))
            sync_cards()

        def delete_pack(path: Path) -> None:
            data = self._read_pack(path) or {}
            if not cute_ask("Delete pack?", f"Delete \u201c{data.get('name', path.stem)}\u201d from Packs?", parent=win, hint="Installed game sounds stay as they are.", yes="Delete"):
                return
            try:
                path.unlink()
            except Exception as exc:
                cute_error("Delete pack", f"Could not delete pack:\n{exc}", parent=win)
                return
            refresh_packs()

        card_of: dict[str, Any] = {}
        self._refresh_packs_window = refresh_packs
        refresh_packs()
        pending = getattr(self, "_pack_to_open", None)
        if pending is not None:
            self._pack_to_open = None
            with contextlib.suppress(Exception):
                tabs.select(packs_frame)
            try:
                cards.update_idletasks()
                target = card_of.get(str(pending))
                if target is not None and target.winfo_exists():
                    total = max(1, cards.winfo_height())
                    canvas.yview_moveto(max(0.0, min(1.0, (target.winfo_y() - 60) / total)))
                    acc = self._theme_colors.get("accent", "#c35d91")
                    target.configure(highlightthickness=3, highlightbackground=acc)

                    def _unflash(t=target):
                        with contextlib.suppress(Exception):
                            t.configure(highlightthickness=0)

                    self.root.after(2600, _unflash)
            except Exception:
                pass
        self._ux_bind_widgets(outer)


