    def _open_path(self, path: Path) -> None:
        try:
            path.mkdir(parents=True, exist_ok=True)
            if os.name == "nt":
                os.startfile(str(path))
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(path)])
            else:
                subprocess.Popen(["xdg-open", str(path)])
        except Exception as exc:
            cute_error("Open Folder", f"Could not open:\n{path}\n\n{exc}", parent=self.root)

    def _tool_status_lines(self) -> list[tuple[str, Optional[Path], bool]]:
        required = (("FFmpeg", self.tools.ffmpeg), ("FFprobe", self.tools.ffprobe), ("yt-dlp", self.tools.yt_dlp), ("vgmstream", self.tools.vgmstream), ("wwiseutil", self.tools.wwiseutil), ("WwiseConsole", self.tools.wwise_console))
        return [(name, path, bool(path and Path(path).is_file())) for name, path in required]

    def show_tool_status(self, parent: Optional[tk.Misc]=None) -> None:
        owner = parent or self.root
        win = tk.Toplevel(owner)
        self._windowed_lightweight(win, "Tool Status", 760, 600)
        body=ttk.Frame(win,padding=16); body.pack(fill="both",expand=True)
        ttk.Label(body,text="Tool Status",font=("Segoe UI",18,"bold")).pack(anchor="w")
        ttk.Label(body,text="These are the external tools the program uses. Green means the program found a usable copy.",style="Small.TLabel",wraplength=700).pack(anchor="w",pady=(2,12))
        rows=ttk.LabelFrame(body,text="Required tools",padding=10); rows.pack(fill="both",expand=True)
        for name,path,ok in self._tool_status_lines():
            row=ttk.Frame(rows); row.pack(fill="x",pady=4)
            ttk.Label(row,text=("✓" if ok else "✗"),font=("Segoe UI",12,"bold")).pack(side="left",padx=(0,10))
            ttk.Label(row,text=name,font=("Segoe UI",10,"bold"),width=16).pack(side="left")
            ttk.Label(row,text=str(path) if path else "Not found",style="Small.TLabel",wraplength=560).pack(side="left",fill="x",expand=True)
        ttk.Label(body,text="Tip: WwiseConsole can be found from an installed Wwise version, so a portable package does not have to ship the entire Wwise Authoring installation.",style="Small.TLabel",wraplength=700).pack(anchor="w",pady=(10,8))
        def rescan_and_refresh() -> None:
            self.rescan_tools(); win.destroy(); self.show_tool_status(owner)
        ttk.Button(body,text="Re-scan Tools",style="Tool.TButton",command=rescan_and_refresh).pack(side="left")
        ttk.Button(body,text="Close",style="Big.TButton",command=win.destroy).pack(side="right")
        self._ux_bind_widgets(win)

    def _diagnostics_text(self) -> str:
        tool_lines=self.tools.pretty(self.tools)
        try:
            import tkinter
            tkver=tkinter.Tcl().eval("info patchlevel")
        except Exception:
            tkver="unknown"
        return (f"{APP_NAME} {APP_VERSION}\n"
                f"Python: {platform.python_version()}\n"
                f"Windows: {platform.platform()}\n"
                f"Tk: {tkver}\n"
                f"Game audio: {self.game_target_var.get()}\n\n"
                f"Tool status:\n{tool_lines}\n\n"
                f"Preset folder: {self.user_presets_dir}\n"
                f"Automatic recipe file: {self.preset_path}\n"
                f"Logs folder: {self.paths.processed_audio / 'logs'}")

    def copy_diagnostics(self) -> None:
        text=self._diagnostics_text()
        try:
            self.root.clipboard_clear(); self.root.clipboard_append(text); self.root.update()
            cute_info("Diagnostics copied ♡", "I copied the details to your clipboard.", parent=self.root, hint="Paste them into Discord when reporting a problem.")
        except Exception as exc:
            cute_error("Diagnostics", f"Could not copy diagnostics:\n{exc}", parent=self.root)

