    def _update_lib(self):
        return updater_client

    def _update_manifest_url(self) -> str:
        try:
            return str(self.settings.get("update_manifest_url", "") or "").strip()
        except Exception:
            return ""

    def _silent_update_check(self) -> None:
        try:
            if self._destroyed:
                return
            if not bool(self.settings.get("auto_update_check", True)):
                return
            if not self._update_manifest_url():
                return
            if self._update_lib() is None:
                return
            threading.Thread(target=self._update_check_worker, args=(False,), daemon=True).start()
        except Exception:
            pass

    def check_for_updates(self, manual: bool = True) -> None:
        if self._update_lib() is None:
            if manual:
                cute_error("Updater needed", "Keep updater_client.py next to the app to enable updates.", parent=self.root)
            return
        if not self._update_manifest_url():
            if manual:
                cute_info("No update feed yet", "Paste the manifest URL in Settings first.", parent=self.root, hint="Your publisher prints it after every publish.")
            return
        self.status_var.set("\u2661 Checking for updates\u2026")
        threading.Thread(target=self._update_check_worker, args=(manual,), daemon=True).start()

    def _update_check_worker(self, manual: bool) -> None:
        lib = self._update_lib()
        url = self._update_manifest_url()
        if lib is None or not url:
            return
        try:
            info = lib.check_for_update(url, APP_VERSION_NUM, timeout=12)
        except Exception as exc:
            if manual:
                self._ui_after(0, lambda e=exc: cute_error("Update check failed", str(e), parent=self.root))
            else:
                self._ui_after(0, lambda: self.status_var.set("\u2661 Could not reach the update server"))
            return
        if not info.get("update"):
            if manual:
                self._ui_after(0, lambda: (cute_info("No updates \u2661", f"v{APP_VERSION_NUM} is the newest.", parent=self.root), self.status_var.set("\u2661 Up to date")))
            return
        if not manual and str(self.settings.get("last_update_prompt_version", "")) == str(info.get("latest", "")):
            return
        self._ui_after(0, lambda: self._show_update_dialog(info))

    def _remember_skipped_update(self, version: str) -> None:
        try:
            self.settings["last_update_prompt_version"] = str(version)
            self.settings_path.write_text(json.dumps(self.settings, indent=2), encoding="utf-8")
        except Exception:
            pass

    def _show_update_dialog(self, info: dict) -> None:
        try:
            lib = self._update_lib()
            if lib is None:
                return
            latest = str(info.get("latest", "?"))
            win = tk.Toplevel(self.root)
            self._windowed_lightweight(win, "Software update \u2661", 600, 480)
            body = ttk.Frame(win, padding=18)
            body.pack(fill="both", expand=True)
            ttk.Label(body, text=f"\U0001f389 v{latest} is available", font=("Segoe UI", 16, "bold")).pack(anchor="w")
            ttk.Label(body, text=f"You have v{APP_VERSION_NUM}.", style="Small.TLabel").pack(anchor="w", pady=(2, 8))
            notes = [str(n) for n in (info.get("notes") or [])][:8]
            ttk.Label(body, text="What's new:", font=("Segoe UI", 10, "bold")).pack(anchor="w")
            ttk.Label(body, text="\n".join(f"\u2022 {n}" for n in notes) or "Bug fixes and polish.", wraplength=540, justify="left").pack(anchor="w", pady=(2, 6))
            size = info.get("size_mb") or 0
            sha = str(info.get("sha256", ""))
            ttk.Label(body, text=f"SHA-256 checked \u00b7 {size} MB \u00b7 keeps a backup of your file.", style="Small.TLabel", wraplength=540, justify="left").pack(anchor="w", pady=(0, 8))
            pct_var = tk.IntVar(value=0)
            bar = ttk.Progressbar(body, mode="determinate", maximum=100, variable=pct_var)
            bar.pack(fill="x", pady=(0, 4))
            state_var = tk.StringVar(value="")
            ttk.Label(body, textvariable=state_var, style="Small.TLabel").pack(anchor="w")
            footer = ttk.Frame(body)
            footer.pack(fill="x", pady=(10, 0))
            dl_btn = ttk.Button(footer, text="Download & install \u2661", style="Big.TButton")
            dl_btn.pack(side="right")
            ttk.Button(footer, text="Skip this version", style="Tool.TButton", command=lambda: (self._remember_skipped_update(latest), win.destroy(), self.status_var.set(f"\u2661 Skipped v{latest}"))).pack(side="right", padx=(6, 0))
            ttk.Button(footer, text="Close", style="Tool.TButton", command=win.destroy).pack(side="left")
            last = {"pct": -1}

            def progress(got: int, total: int) -> None:
                try:
                    pct = int(got * 100 / total) if total else 0
                except Exception:
                    pct = 0
                if pct == last["pct"]:
                    return
                last["pct"] = pct
                self._ui_after(0, lambda p=pct, g=got, t=total: (pct_var.set(p), state_var.set(f"{g / 1048576:.1f} / {t / 1048576:.1f} MB" if t else f"{g / 1048576:.1f} MB")))

            def worker() -> None:
                try:
                    target = lib.running_file()
                    dest = target.parent / (target.stem + ".new" + target.suffix)
                    lib.download_update(str(info.get("url", "")), dest, str(info.get("sha256", "") or ""), progress=progress, timeout=60)
                except Exception as exc:
                    self._ui_after(0, lambda e=exc: (cute_error("Download failed", str(e), parent=win), dl_btn.configure(state="normal"), state_var.set("")))
                    return
                def after_download() -> None:
                    dl_btn.configure(state="normal")
                    if cute_ask("Restart now? \u2661", f"v{latest} is downloaded and verified. Restart to finish installing?", parent=win, hint="Your settings, packs and backups are untouched.", yes="Restart \u2661", no="Later"):
                        try:
                            lib.apply_update(dest)
                        except Exception as exc:
                            cute_error("Update failed", str(exc), parent=win)
                    else:
                        try:
                            dest.unlink()
                        except Exception:
                            pass
                        state_var.set("Saved for later \u2014 download again anytime.")
                self._ui_after(0, after_download)

            dl_btn.configure(command=lambda: (dl_btn.configure(state="disabled"), state_var.set("Downloading\u2026"), threading.Thread(target=worker, daemon=True).start()))
            self._ux_bind_widgets(win)
            self._raise_child(win)
        except Exception as exc:
            self.log.debug("Update dialog skipped: %s", exc)

    def _cancel_theme_fade(self) -> None:
        self._fade_run = None
        after_id = getattr(self, "_fade_after", None)
        try:
            if after_id is not None:
                self.root.after_cancel(after_id)
        except Exception:
            pass
        self._fade_after = None

    def _fade_to_theme(self, final_theme, final_custom, on_step=None, on_done=None) -> None:
        self._cancel_theme_fade()
        old = dict(getattr(self, "_theme_colors", {}) or {})
        self.theme_var.set(final_theme)
        self.custom_theme_colors = dict(final_custom)
        self._apply_theme()
        new = dict(self._theme_colors)
        keys = [k for k in new
                if isinstance(new.get(k), str) and new[k].startswith("#")
                and isinstance(old.get(k), str) and old[k].startswith("#")]
        if not keys:
            self._save_ui_settings()
            if on_step:
                on_step()
            if on_done:
                on_done()
            return
        def _hx(h: str):
            h = h.lstrip("#")
            return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))
        def _mix(a: str, b: str, t: float) -> str:
            ra, ga, ba = _hx(a)
            rb, gb, bb = _hx(b)
            return f"#{round(ra + (rb - ra) * t):02x}{round(ga + (gb - ga) * t):02x}{round(ba + (bb - ba) * t):02x}"
        run = {"alive": True}
        self._fade_run = run
        state = {"i": 0}
        steps, delay = 12, 22
        self.custom_theme_colors = {k: old[k] for k in keys}
        self._apply_theme()
        if on_step:
            on_step()
        def _step() -> None:
            if self._fade_run is not run:
                return
            state["i"] += 1
            t = min(1.0, state["i"] / steps)
            e = t * t * (3 - 2 * t)
            self.custom_theme_colors = {k: _mix(old[k], new[k], e) for k in keys}
            self._apply_theme()
            if on_step:
                on_step()
            if t < 1.0:
                self._fade_after = self.root.after(delay, _step)
            else:
                self._fade_run = None
                self._fade_after = None
                self.custom_theme_colors = dict(final_custom)
                self._apply_theme()
                self._save_ui_settings()
                if on_step:
                    on_step()
                if on_done:
                    on_done()
        self._fade_after = self.root.after(delay, _step)

