        left_scale = ttk.Scale(workspace, from_=0.25, to=0.55, variable=left_ratio_var, orient="horizontal", length=260, command=lambda _v: (self.workspace_custom.__setitem__("left_ratio", float(left_ratio_var.get())), self._set_initial_main_sash()))
        left_scale.grid(row=0, column=1, sticky="ew", pady=3)
        ttk.Label(workspace, text="Groups  25% ← → 55%", style="Small.TLabel").grid(row=0, column=2, sticky="w", padx=(8, 0))
