        preview_height_var = tk.IntVar(value=int(self.workspace_custom.get("preview_height", 72)))
        preview_scale = ttk.Scale(workspace, from_=56, to=150, variable=preview_height_var, orient="horizontal", length=260, command=lambda _v: (self.workspace_custom.__setitem__("preview_height", int(round(preview_height_var.get()))), self._apply_workspace_customization()))
        preview_scale.grid(row=1, column=1, sticky="ew", pady=3)
        ttk.Label(workspace, text="Compact 56  ← →  Tall 150", style="Small.TLabel").grid(row=1, column=2, sticky="w", padx=(8, 0))
