        workspace.columnconfigure(1, weight=1)

        display = ttk.LabelFrame(body, text="♡ Information", padding=10); display.pack(fill="x", pady=(0, 8))
        ttk.Checkbutton(display, text="Show technical file names (BNK / WEM)", variable=self.show_technical_names_var).pack(anchor="w", pady=3)
        ttk.Checkbutton(display, text="Show advanced audio details", variable=self.show_advanced_details_var).pack(anchor="w", pady=3)
        ttk.Checkbutton(display, text="Ask before installing a replacement", variable=self.confirm_install_var).pack(anchor="w", pady=3)
        ttk.Checkbutton(display, text="Immersive full screen (F11)", variable=self.fullscreen_var, command=self._apply_fullscreen_state).pack(anchor="w", pady=3)
        ttk.Checkbutton(display, text="Show terminal window (applies instantly)", variable=self.show_terminal_var, command=self._apply_terminal_state).pack(anchor="w", pady=3)

        backup_frame = ttk.Frame(display)
        backup_frame.pack(fill="x", pady=(6, 0))
        ttk.Button(backup_frame, text="💾 Backed Up — View & Restore", style="Tool.TButton", command=lambda: self.show_backed_up(self.root)).pack(side="left")
        self.show_user_presets(body)

        tutorial = ttk.LabelFrame(body, text="♡ Tutorial", padding=10); tutorial.pack(fill="x", pady=(0, 8))

        updates = ttk.LabelFrame(body, text="♡ Software updates", padding=10); updates.pack(fill="x", pady=(0, 8))
        auto_update_var = tk.BooleanVar(value=bool(self.settings.get("auto_update_check", True)))
        manifest_var = tk.StringVar(value=str(self.settings.get("update_manifest_url", "")))
        ttk.Checkbutton(updates, text="Check for updates on startup (silent when offline)", variable=auto_update_var).pack(anchor="w", pady=3)
        urow = ttk.Frame(updates); urow.pack(fill="x", pady=3)
        ttk.Label(urow, text="Manifest URL:").pack(side="left")
        ttk.Entry(urow, textvariable=manifest_var).pack(side="left", fill="x", expand=True, padx=(8, 0))
        ttk.Button(urow, text="Check now", style="Tool.TButton", command=lambda: self.check_for_updates(True)).pack(side="left", padx=(6, 0))
        ttk.Label(updates, text="Paste the manifest URL from the Update Publisher. The app only ever replaces its own file, verifies SHA-256 first, and keeps a backup.", style="Small.TLabel", wraplength=1100).pack(anchor="w", pady=(3, 0))
        ttk.Label(tutorial, text="Brand-new here? A 60-second guided tour starts automatically on first launch.", style="Small.TLabel", wraplength=1100).pack(anchor="w", pady=(0, 7))
        tut_row = ttk.Frame(tutorial); tut_row.pack(fill="x")
        ttk.Button(tut_row, text="Replay tutorial ♡", style="Tool.TButton", command=lambda: (win.destroy(), self._reset_tutorial())).pack(side="left")
        ttk.Label(tut_row, text="Replaying also resets it, so it will show again on next launch until finished.", style="Small.TLabel").pack(side="left", padx=(8, 0))

