    def _category_label(self) -> str:
        if self.active_categories == set(self.category_names):
            return "Show All"
        if len(self.active_categories) == 1:
            full = next(iter(self.active_categories))
            compact = {
                "Menu & Lobby Music": "Menu",
                "Map Music": "Maps",
                "Weapon Sounds": "Weapons",
                "Legend Signatures": "Legends",
                "Movement & UI": "Move / UI",
                "Announcer & Voice": "Voice",
                "Cinematics & Cutscenes": "Cinema",
                "Other / Uncategorized": "Other",
            }
            return compact.get(full, full)
        return f"{len(self.active_categories)} Categories"

    def _sync_category_view(self) -> None:
        if not hasattr(self, "category_view_var"):
            self.category_view_var = tk.StringVar(master=self.root, value=self._category_label())
        else:
            self.category_view_var.set(self._category_label())

    def _category_counts(self) -> dict[str, int]:
        counts = {name: 0 for name in self.category_names}
        for p in self.discovered_banks:
            top, _sub = self.bank_categories.get(str(p), categorise_brawlhalla_bnk(p))
            if top == "Sound Effects":
                top = "Other / Uncategorized"
            if top in counts:
                counts[top] += 1
        return counts

    @staticmethod
    def _wasapi_vcall(obj, index: int, restype, argtypes: list[Any], *args):
        """Call a COM interface method by vtable index."""
        if not obj:
            raise RuntimeError("Invalid WASAPI COM interface pointer")
        vtbl = ctypes.cast(obj, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
        fn_addr = vtbl[index]
        fn = ctypes.WINFUNCTYPE(restype, ctypes.c_void_p, *argtypes)(fn_addr)
        return fn(obj, *args)

    def show_category_chooser(self) -> None:
        if not self.discovered_banks:
            self.status_var.set("♡ Looking for your sound groups…")
            return

        win = tk.Toplevel(self.root)
        self._windowed_lightweight(win, "Choose categories", 900, 680)
        body = ttk.Frame(win, padding=22, style="Chooser.TFrame")
        body.pack(fill="both", expand=True)

        ttk.Label(body, text="★ SELECT YOUR STAGE ★", style="ChooserHint.TLabel", justify="center").pack(anchor="center")
        ttk.Label(body, text="Choose sound groups", style="ChooserTitle.TLabel", justify="center").pack(anchor="center")
        ttk.Label(
            body,
            text="1–8 toggles categories · 0 selects all · press START when ready.",
            style="ChooserSub.TLabel",
            justify="center",
        ).pack(anchor="center", pady=(2, 12))

        counts = self._category_counts()
        descriptions = {
            "Menu & Lobby Music": "Main menu, events, crossovers and Battle Pass music.",
            "Map Music": "Stage and map music.",
            "Weapon Sounds": "Weapon attacks and combat sounds.",
            "Legend Signatures": "Legend signature attacks and related sounds.",
            "Movement & UI": "Movement, emotes and interface sounds.",
            "Announcer & Voice": "Announcer and character voice sounds.",
            "Cinematics & Cutscenes": "Cutscene and cinematic audio.",
            "Other / Uncategorized": "Sounds that do not match another category.",
        }
        options = [(name, descriptions[name]) for name in self.category_names if name != "Sound Effects"]
        vars_local: dict[str, tk.BooleanVar] = {
            name: tk.BooleanVar(value=name in self.active_categories) for name, _ in options
        }
        row_widgets: list[tk.Widget] = []

        chooser = ttk.Frame(body, style="Chooser.TFrame")
        chooser.pack(fill="both", expand=True)

        def set_all(value: bool) -> None:
            for var in vars_local.values():
                var.set(value)

        p = self._ux_palette()
        arcade_accent = p.get("accent", "#c65d91")
        arcade_bg = p.get("bg", "#f5efe9")
        arcade_field = p.get("field", "#ffffff")
        arcade_sel = p.get("soft_accent", p.get("sel", "#efc7db"))
        arcade_border = p.get("border", "#d8c9d2")
        arcade_muted = p.get("muted", "#756872")
        arcade_fg = p.get("fg", "#332c34")
        arcade_cards: dict[str, dict[str, tk.Widget]] = {}

        def arcade_toggle(name: str) -> None:
            vars_local[name].set(not vars_local[name].get())

        def arcade_paint(*_args: Any) -> None:
            for key, var in list(vars_local.items()) + [("__all__", None)]:
                refs = arcade_cards.get(key)
                if not refs:
                    continue
                on = all(v.get() for v in vars_local.values()) if key == "__all__" else bool(vars_local[key].get())
                lit = arcade_sel if on else arcade_field
                refs["frame"].configure(highlightbackground=arcade_accent if on else arcade_border, bg=lit)
                refs["mid"].configure(bg=lit)
                refs["title"].configure(bg=lit, fg=arcade_fg)
                refs["desc"].configure(bg=lit, fg=arcade_muted)
                refs["pill"].configure(bg=arcade_accent if on else arcade_border, fg="#ffffff" if on else arcade_fg)
                refs["state"].configure(text="ON" if on else "OFF", bg=lit, fg=arcade_accent if on else arcade_muted)

        def arcade_build_card(key: str, num: str, title: str, desc: str, group_count: int, is_all: bool) -> None:
            card = tk.Frame(chooser, highlightthickness=2, highlightbackground=arcade_border, highlightcolor=arcade_accent, bd=0, takefocus=True, bg=arcade_field)
            card.pack(fill="x", pady=2)
            badge = tk.Label(card, text=num, font=("Segoe UI", 10, "bold"), bg=arcade_fg, fg=arcade_bg, width=3, pady=2)
            badge.pack(side="left", padx=(6, 8), pady=4)
            mid = tk.Frame(card, bd=0, bg=arcade_field)
            mid.pack(side="left", fill="x", expand=True, pady=2)
            title_lbl = tk.Label(mid, text=title, font=("Segoe UI", 10, "bold"), bg=arcade_field, fg=arcade_fg, anchor="w", justify="left")
            title_lbl.pack(anchor="w")
            desc_lbl = tk.Label(mid, text=desc, font=("Segoe UI", 9), bg=arcade_field, fg=arcade_muted, anchor="w", justify="left", wraplength=520)
            desc_lbl.pack(anchor="w")
            pill = tk.Label(card, text=f"x{group_count}", font=("Segoe UI", 9, "bold"), bg=arcade_border, fg=arcade_fg, padx=10, pady=2)
            pill.pack(side="right", padx=(4, 4))
            state = tk.Label(card, text="OFF", font=("Segoe UI", 9, "bold"), bg=arcade_field, fg=arcade_muted, width=4)
            state.pack(side="right", padx=(0, 6))
            arcade_cards[key] = {"frame": card, "mid": mid, "title": title_lbl, "desc": desc_lbl, "pill": pill, "state": state}
            for w in (badge, mid, title_lbl, desc_lbl, pill, state):
                w._no_ux_hover = True
            if is_all:
                card.bind("<Button-1>", lambda _e: set_all(not all(v.get() for v in vars_local.values())))
                for w in (badge, mid, title_lbl, desc_lbl, pill, state):
                    w.bind("<Button-1>", lambda _e: set_all(not all(v.get() for v in vars_local.values())))
            else:
                card.bind("<Button-1>", lambda _e, n=key: arcade_toggle(n))
                for w in (badge, mid, title_lbl, desc_lbl, pill, state):
                    w.bind("<Button-1>", lambda _e, n=key: arcade_toggle(n))
            card.bind("<space>", lambda _e, n=key, a=is_all: (set_all(not all(v.get() for v in vars_local.values())) if a else arcade_toggle(n), "break")[1])
            def hover_on(_e, c=card, k=key, a=is_all) -> None:
                c.configure(cursor="hand2")
                on = all(v.get() for v in vars_local.values()) if a else bool(vars_local[k].get())
                if not on:
                    c.configure(highlightbackground=arcade_accent)
            def hover_off(_e, c=card) -> None:
                c.configure(cursor="")
                arcade_paint()
            for w in (card, badge, mid, title_lbl, desc_lbl, pill, state):
                w.bind("<Enter>", hover_on)
                w.bind("<Leave>", hover_off)
            row_widgets.append(card)

        for idx, (name, desc) in enumerate(options, start=1):
            arcade_build_card(name, str(idx), f"{idx}. {name}", desc, counts.get(name, 0), False)

        all_check_var = tk.BooleanVar(value=self.active_categories == set(self.category_names))
        arcade_build_card("__all__", "0", "SHOW ALL", "Browse every sound group in Brawlhalla.", len(self.discovered_banks), True)
        for var in vars_local.values():
            var.trace_add("write", arcade_paint)
        arcade_paint()

        def sync_all_flag(*_args: Any) -> None:
            all_check_var.set(all(var.get() for var in vars_local.values()))

        for var in vars_local.values():
            var.trace_add("write", sync_all_flag)

        buttons = ttk.Frame(body)
        buttons.pack(fill="x", pady=(16, 0))
        selected_count_var = tk.StringVar(value="")
        ttk.Label(buttons, textvariable=selected_count_var, style="Small.TLabel").pack(side="left")
        back_btn = tk.Button(buttons, text="B · Back", command=win.destroy, bg=arcade_field, fg=arcade_fg, activebackground=arcade_sel, activeforeground=arcade_fg, font=("Segoe UI", 9, "bold"), relief="raised", bd=1, padx=16, pady=6, cursor="hand2")
        back_btn.pack(side="right", padx=(6, 0))

        def refresh_selected_count(*_args: Any) -> None:
            picked = [name for name, var in vars_local.items() if var.get()]
            groups = sum(counts.get(name, 0) for name in picked)
            selected_count_var.set(f"{len(picked)} selected · ~{groups} groups" if picked else "pick at least 1")
        for var in vars_local.values():
            var.trace_add("write", refresh_selected_count)
        refresh_selected_count()

        def apply() -> None:
            selected = {name for name, var in vars_local.items() if var.get()}
            if not selected:
                cute_warning("Categories", "Choose at least one category.", parent=win)
                return
            self.active_categories = selected
            self._sync_category_view()
            self._render_banks()
            win.destroy()
            self.status_var.set(f"Categories: {self._category_label()}")

        start_btn = tk.Button(buttons, text="START", command=apply, bg=arcade_accent, fg="#ffffff", activebackground=arcade_accent, activeforeground="#ffffff", font=("Segoe UI", 10, "bold"), relief="raised", bd=1, padx=28, pady=6, cursor="hand2")
        start_btn.pack(side="right")

        self._ux_bind_widgets(win)

        def toggle_index(index: int) -> str:
            if 0 <= index < len(options):
                name = options[index][0]
                vars_local[name].set(not vars_local[name].get())
            return "break"

        for key_index in range(1, min(9, len(options) + 1)):
            win.bind(str(key_index), lambda _e, i=key_index - 1: toggle_index(i))
        win.bind("0", lambda _e: (set_all(True), all_check_var.set(True), "break")[2])
        win.bind("<Return>", lambda _e: (apply(), "break")[1])
        win.bind("<Escape>", lambda _e: (win.destroy(), "break")[1])
        win.bind("<space>", lambda _e: (win.focus_get().invoke() if hasattr(win.focus_get(), "invoke") else None, "break")[1])

        self._raise_child(win)
        try:
            win.after(900, lambda w=win: self._paint_one_window_chrome(w))
        except Exception:
            pass
        try:
            (row_widgets[0] if row_widgets else win).focus_set()
        except Exception:
            pass

    def _ui_after(self, delay_ms: int, callback: Callable[[], Any]) -> Optional[str]:
        """Schedule a Tk callback without letting worker threads crash during window close."""
        if self._destroyed:
            return None
        try:
            return self.root.after(delay_ms, callback)
        except (tk.TclError, RuntimeError):
            return None

    def _cleanup_replacement_source_files(self) -> None:
        """Delete downloaded URL/playlist media once replacement work is finished."""
        with contextlib.suppress(Exception):
            self._url_prefetch.cleanup_all()
        with contextlib.suppress(Exception):
            cleanup_temporary_source_downloads(self.paths)

    def _play_background_completion_sound(
        self, ok: bool, cancelled: bool = False, error: Optional[BaseException] = None
    ) -> None:
        """Play a short native Windows notification sound when hidden processing ends."""
        if winsound is None:
            return
        try:
            if error is not None or (not ok and not cancelled):
                winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
            elif cancelled:
                winsound.MessageBeep(winsound.MB_ICONASTERISK)
            else:
                winsound.MessageBeep(winsound.MB_OK)
        except Exception as exc:
            self.log.debug("Could not play background completion sound: %s", exc)

    def _background_operation_status(self, message: str) -> None:
        """Show background download/preparation status in both the status bar and process card."""
        try:
            self.status_var.set(str(message))
        except Exception:
            pass
        try:
            win = getattr(self, "_processing_window", None)
            if win is not None and win.winfo_exists():
                self._set_process_progress(str(message), 0, 0)
        except Exception:
            pass

    def _selected_categories(self) -> set[str]:
        return set(self.active_categories) or set(self.category_names)

    def auto_scan_game_banks(self) -> None:
        game_dir = Path(self.game_target_var.get())
        if not game_dir.is_dir():
            self.status_var.set(f"Brawlhalla audio folder not found: {game_dir}")
            return

        # Refresh must not keep showing the WEM files extracted before a BNK was
        # modified.  Those extracted files are what Preview reads, so retaining
        # the old loaded bank would make Refresh appear to do nothing.  Preserve
        # which groups were open, fully drop their extraction caches, then reopen
        # them from the current on-disk game banks after the rescan finishes.
        self.stop_preview()
        self._stop_modified_wem_preview()
        self._refresh_reload_paths = set(self.loaded_banks)
        self._loading_generation += 1
        self._loading_banks.clear()
        for bank in list(self.loaded_banks):
            infos = self.bank_infos.pop(str(bank), [])
            cache_dirs = {info.file_path.parent for info in infos if info.file_path.parent.exists()}
            for cache_dir in cache_dirs:
                with contextlib.suppress(OSError):
                    shutil.rmtree(cache_dir, ignore_errors=True)
        self.loaded_banks.clear()
        self._render_banks()
        self._render_wems()
        self.selected_bank_hint_var.set("Refreshing sound groups…")
        self.loaded_count_var.set("")
        self._set_loading(True, "♡ Refreshing your sound groups…")
        threading.Thread(target=self._scan_banks_thread, args=(game_dir,), daemon=True).start()

    def _scan_banks_thread(self, game_dir: Path) -> None:
        try:
            all_bnks = sorted(
                (p.resolve() for p in game_dir.rglob("*.bnk") if p.is_file()),
                key=lambda p: (str(p.parent).lower(), p.name.lower()),
            )
            skipped = [p for p in all_bnks if not is_live_game_bank(p)]
            for p in skipped:
                self.log.info("Scan skipping non-live bank file: %s", p.name)
            bnk_paths = [p for p in all_bnks if is_live_game_bank(p)]
            self.log.info("Scan found %d live BNKs (%d skipped) under %s", len(bnk_paths), len(skipped), game_dir)

            # VOX_Announcer.bnk is a single logical announcer bank.  Some installs can
            # contain an extra root-level copy left behind by an older version of the
            # tool (or by a previous manual install).  Keep the most specific/live copy
            # instead of showing two identical "Announcer" rows, without assuming a
            # particular language such as English(US).
            announcer_candidates = [
                p for p in bnk_paths if p.name.lower() == "vox_announcer.bnk"
            ]
            if len(announcer_candidates) > 1:
                announcer_candidates.sort(
                    key=lambda p: (len(p.relative_to(game_dir.resolve()).parts), str(p).lower()),
                    reverse=True,
                )
                announcer_keep = announcer_candidates[0]
                bnk_paths = [
                    p for p in bnk_paths
                    if p.name.lower() != "vox_announcer.bnk" or p == announcer_keep
                ]

            loose_wems = sorted(
                (p.resolve() for p in game_dir.rglob("*.wem") if p.is_file()),
                key=lambda p: (str(p.parent).lower(), p.name.lower()),
            )

            unique = bnk_paths + loose_wems
            categories = {str(p): categorise_brawlhalla_bnk(p) for p in bnk_paths}
            categories.update({str(p): ("Other / Uncategorized", "Loose WEM") for p in loose_wems})
            self._ui_after(0, lambda: self._apply_scan(unique, categories))
        except Exception as exc:
            self.log.error("BNK scan failed: %s", exc)
            self._ui_after(0, lambda: self._set_loading(False, "✗ I could not finish scanning — see Details below."))
            self._ui_after(50, lambda e=exc: self._friendly_error(e, title="Could not scan sound groups"))

    def _apply_scan(self, banks: list[Path], categories: dict[str, tuple[str, str]]) -> None:
        reload_paths = {p.resolve() for p in self._refresh_reload_paths if p.exists()}
        self._refresh_reload_paths.clear()
        self.discovered_banks = banks
        self.bank_categories = {k: v for k, v in categories.items()}
        self.loaded_banks.clear()
        self.bank_infos.clear()
        self._render_banks()
        self._render_wems()
        self.bank_count_var.set(f"{len(banks)} groups")
        self.loaded_count_var.set("")
        self._sync_category_view()
        # The category picker only opens when the user clicks it.

        # Re-open exactly the groups that were open before Refresh, but only when
        # they still exist in the freshly scanned tree. This forces wwiseutil to
        # inspect the current bank contents rather than an obsolete extraction.
        to_reload = [p for p in banks if p in reload_paths]
        if to_reload:
            self._load_banks_bulk(to_reload)
        else:
            self._set_loading(False, f"♡ Found {len(banks)} sound group(s) ready to explore!")

    def _bank_search_changed(self, _event: Any = None) -> None:
        if self._search_after_id:
            try:
                self.root.after_cancel(self._search_after_id)
            except Exception:
                pass
        self._search_after_id = self.root.after(80, self._render_banks)

    def _saved_modded_bank_info(self) -> dict[str, dict[str, Any]]:
        info: dict[str, dict[str, Any]] = {}
        for row in self._preset_rows():
            name = str(row.get("bank_name", "")).strip().lower()
            if not name:
                continue
            recipe = row.get("recipe", [])
            count = len(recipe) if isinstance(recipe, list) else 0
            info[name] = {"wem_count": count, "saved_at": str(row.get("saved_at", ""))}
        return info

    def _render_banks(self) -> None:
        selected_paths = {self._bank_path_by_item.get(i) for i in self.bank_tree.selection()}
        for iid in self.bank_tree.get_children(""):
            self.bank_tree.delete(iid)
        self._bank_item_by_path.clear()
        self._bank_path_by_item.clear()
        query = self.bank_search_var.get().strip().lower()
        allowed = self._selected_categories()
        shown = 0
        modded_info = self._saved_modded_bank_info()
        for p in self.discovered_banks:
            top, sub = self.bank_categories.get(str(p), ("SFX", "Other SFX"))
            if top not in allowed:
                continue
            label_for_search = self._friendly_bank_label(p).lower()
            if query and query not in p.name.lower() and query not in label_for_search and query not in top.lower() and query not in sub.lower():
                continue
            loaded = p in self.loaded_banks
            modinfo = modded_info.get(p.name.lower())
            label = self._friendly_bank_label(p)
            iid = self.bank_tree.insert("", "end", values=("☑" if loaded else "☐", f"{top} / {sub}", label))
            self._bank_item_by_path[p] = iid
            self._bank_path_by_item[iid] = p
            shown += 1
        if shown == 0:
            if query:
                empty_msg = f"No sound groups match “{query}” — try another word."
            elif not self.discovered_banks:
                empty_msg = "No sound groups found. Check your Brawlhalla folder in Settings."
            else:
                empty_msg = "No sound groups in the categories you picked. Adjust the category filter."
            self.bank_tree.insert("", "end", values=("—", "", empty_msg), tags=("empty",))
        self.bank_count_var.set(f"{shown} shown · {len(self.discovered_banks)} total")
        self.loaded_count_var.set("")
        if selected_paths:
            for p in selected_paths:
                iid = self._bank_item_by_path.get(p)
                if iid:
                    self.bank_tree.selection_add(iid)

        self._ux_bind_widgets(self.bank_tree)

        # Refresh hover state after a short delay so glow doesn't disappear
        def _refresh_tree_hover():
            try:
                event = type('Event', (), {'widget': self.bank_tree, 'y': self.root.winfo_pointery() - self.bank_tree.winfo_rooty(), 'x_root': self.root.winfo_pointerx(), 'y_root': self.root.winfo_pointery()})()
                self._ux_tree_hover(event)
            except Exception:
                pass

        # Force hover refresh after tree rebuild so glow doesn't disappear
        self.root.after(50, _refresh_tree_hover)

    def _bank_activate(self, row: str, state: int = 0) -> Optional[str]:
        p = self._bank_path_by_item.get(row)
        if not p:
            return None
        shift = bool(state & 0x0001)
        ctrl = bool(state & 0x0004)
        items = list(self.bank_tree.get_children(""))
        anchor_iid = self._bank_anchor_iid
        if self._bank_anchor_path is not None:
            anchor_iid = self._bank_item_by_path.get(self._bank_anchor_path, anchor_iid)
        if shift and anchor_iid in items:
            a, b = items.index(anchor_iid), items.index(row)
            lo, hi = sorted((a,b)); rng = items[lo:hi+1]
            if ctrl:
                self.bank_tree.selection_add(rng)
            else:
                self.bank_tree.selection_set(rng)
        elif ctrl:
            self.bank_tree.selection_toggle(row)
        else:
            self.bank_tree.selection_set(row)
        if not shift:
            self._bank_anchor_iid = row
            self._bank_anchor_path = p
        if p in self.loaded_banks:
            if not shift and not ctrl:
                self._unload_bank_immediately(p)
        else:
            if p.suffix.lower() == ".wem":
                self._load_loose_wem_immediately(p)
            else:
                self._load_bank_immediately(p)
        # Refresh hover glow after load in case mouse is still over the tree
        self.root.after(50, lambda: self._refresh_tree_hover(self.bank_tree))
        return "break"

    def _make_marquee_overlay_clickthrough(self, win: tk.Toplevel) -> None:

        if os.name != "nt":
            return
        try:
            import ctypes
            from ctypes import wintypes
            hwnd = wintypes.HWND(int(win.winfo_id()))
            user32 = ctypes.windll.user32
            GWL_EXSTYLE = -20
            WS_EX_LAYERED = 0x00080000
            WS_EX_TRANSPARENT = 0x00000020
            WS_EX_NOACTIVATE = 0x08000000
            WS_EX_TOOLWINDOW = 0x00000080
            HTTRANSPARENT = -1
            style = user32.GetWindowLongW(hwnd, GWL_EXSTYLE)
            user32.SetWindowLongW(hwnd, GWL_EXSTYLE, style | WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_NOACTIVATE | WS_EX_TOOLWINDOW)

            WNDPROC = ctypes.WINFUNCTYPE(wintypes.LRESULT, wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)
            CallWindowProc = user32.CallWindowProcW
            SetWindowLongPtr = getattr(user32, 'SetWindowLongPtrW', user32.SetWindowLongW)
            GetWindowLongPtr = getattr(user32, 'GetWindowLongPtrW', user32.GetWindowLongW)
            GWLP_WNDPROC = -4
            old_proc = GetWindowLongPtr(hwnd, GWLP_WNDPROC)

            @WNDPROC
            def proc(h, msg, wp, lp):
                if msg == 0x0084:
                    return HTTRANSPARENT
                return CallWindowProc(old_proc, h, msg, wp, lp)

            SetWindowLongPtr(hwnd, GWLP_WNDPROC, ctypes.cast(proc, ctypes.c_void_p).value)
            self._marquee_overlay_proc[str(int(hwnd))] = (proc, old_proc)
        except Exception:
            pass

    def _show_marquee(self, tree: ttk.Treeview, canvas_attr: str, rect: tuple[int,int,int,int]) -> None:
        try:
            x0, y0, x1, y1 = rect
            left, right = sorted((int(x0), int(x1)))
            top, bottom = sorted((int(y0), int(y1)))
            width = max(2, right - left)
            height = max(2, bottom - top)
            master = tree.master
            ox = int(tree.winfo_x() + left)
            oy = int(tree.winfo_y() + top)
            accent = self._theme_colors.get("accent", "#ff69b4")
            active = self._theme_colors.get("accent_active", "#ff1493")
            try:
                tbg = tree.cget("background") or self._theme_colors.get("field", "#ffffff")
            except Exception:
                tbg = self._theme_colors.get("field", "#ffffff")
            canvas = getattr(self, canvas_attr, None)
            try:
                alive = canvas is not None and canvas.winfo_exists() and canvas.master is master
            except Exception:
                alive = False
            if not alive:
                try:
                    if canvas is not None:
                        canvas.destroy()
                except Exception:
                    pass
                canvas = tk.Canvas(master, bg=tbg, bd=0, highlightthickness=0, takefocus=0)
                setattr(self, canvas_attr, canvas)
            try:
                canvas.configure(bg=tbg)
            except Exception:
                pass
            canvas.delete("all")
            canvas.create_rectangle(1, 1, width - 1, height - 1,
                                    outline=active, width=2, fill=accent, stipple="gray12")
            canvas.place(x=ox, y=oy, width=width, height=height)
            canvas.lift()
        except Exception:
            pass

    def _hide_marquee(self, canvas_attr: str) -> None:
        canvas = getattr(self, canvas_attr, None)
        if canvas is not None:
            try:
                canvas.place_forget()
            except Exception:
                pass
            try:
                canvas.destroy()
            except Exception:
                pass
            setattr(self, canvas_attr, None)

    def _stop_tree_drag_autoscroll(self, kind: str) -> None:
        attr = "_bank_drag_after" if kind == "bank" else "_wem_drag_after"
        after_id = getattr(self, attr, None)
        if after_id:
            try:
                self.root.after_cancel(after_id)
            except Exception:
                pass
            setattr(self, attr, None)

    def _tree_drag_rows(self, tree: ttk.Treeview, start_iid: Optional[str], current_y: int) -> set[str]:
        items = list(tree.get_children(""))
        if not items or not start_iid or start_iid not in items:
            return set()
        current_iid = tree.identify_row(max(0, min(tree.winfo_height() - 1, current_y)))
        if not current_iid:
            # The pointer may be in the small overscroll band at an edge. Pick the
            # nearest currently visible row, while retaining the original start row.
            visible = [iid for iid in items if tree.bbox(iid)]
            if not visible:
                return {start_iid}
            current_iid = visible[0] if current_y < 0 else visible[-1]
        try:
            a, b = items.index(start_iid), items.index(current_iid)
        except ValueError:
            return {current_iid}
        lo, hi = sorted((a, b))
        return set(items[lo:hi+1])

    def _update_tree_drag_selection(self, tree: ttk.Treeview, kind: str, pointer_root_y: int) -> None:
        start = self._bank_drag_start if kind == "bank" else self._wem_drag_start
        start_iid = self._bank_drag_start_iid if kind == "bank" else self._wem_drag_start_iid
        if not start:
            return
        sx_root, sy_root, state = start
        local_y = pointer_root_y - tree.winfo_rooty()
        # Use the same row range even when the pointer is in the small overscroll band.
        clamped_y = max(-tree.winfo_height() // 3, min(tree.winfo_height() + tree.winfo_height() // 3, local_y))
        hits = self._tree_drag_rows(tree, start_iid, clamped_y)
        if kind == "bank":
            self._bank_marquee_hits = hits
        else:
            self._wem_marquee_hits = hits
        if state & 0x0004 or state & 0x0001:
            if hits:
                tree.selection_add(tuple(hits))
        else:
            tree.selection_set(tuple(hits)) if hits else tree.selection_remove(tree.selection())

    def _tree_drag_tick(self, kind: str) -> None:
        tree = self.bank_tree if kind == "bank" else self.wem_tree
        start = self._bank_drag_start if kind == "bank" else self._wem_drag_start
        active = self._bank_drag_active if kind == "bank" else self._wem_drag_active
        pointer_root = self._bank_drag_pointer if kind == "bank" else self._wem_drag_pointer
        if not start or not active or pointer_root is None:
            self._stop_tree_drag_autoscroll(kind)
            return

        # Tk stops receiving mouse-release events when the pointer is released outside
        # the application (for example after the cursor reaches the Windows taskbar).
        # Poll the real left-button state so a completed drag is finalized instead of
        # leaving the next click to unexpectedly clear the selection.
        if os.name == "nt":
            try:
                left_down = bool(ctypes.windll.user32.GetAsyncKeyState(0x01) & 0x8000)
            except Exception:
                left_down = True
            if not left_down:
                self._stop_tree_drag_autoscroll(kind)
                if kind == "wem":
                    dragged = self._wem_drag_active
                    self._wem_drag_start = None
                    self._wem_drag_start_iid = None
                    self._wem_drag_pointer = None
                    self._wem_drag_active = False
                    self._hide_marquee("_wem_marquee_canvas")
                    self._wem_marquee_hits.clear()
                    if dragged:
                        self._wem_selection_changed()
                        self.status_var.set(f"Selected {len(self.wem_tree.selection())} sound(s)")
                else:
                    hit_iids = tuple(self._bank_marquee_hits)
                    dragged = self._bank_drag_active
                    self._bank_drag_start = None
                    self._bank_drag_start_iid = None
                    self._bank_drag_pointer = None
                    self._bank_drag_active = False
                    self._hide_marquee("_bank_marquee_canvas")
                    self._bank_marquee_hits.clear()
                    if dragged:
                        paths = []
                        seen: set[Path] = set()
                        for iid in hit_iids:
                            path = self._bank_path_by_item.get(iid)
                            if path is not None and path not in seen:
                                paths.append(path)
                                seen.add(path)
                        loaded = [p for p in paths if p in self.loaded_banks]
                        unloaded = [p for p in paths if p not in self.loaded_banks]
                        for path in loaded:
                            self._unload_bank_immediately(path)
                        if unloaded:
                            self._load_banks_bulk(unloaded)
                        self.status_var.set(f"Toggled {len(paths)} selected sound group(s)")
                return

        local_y = pointer_root[1] - tree.winfo_rooty()
        edge = max(28, min(64, tree.winfo_height() // 8))
        direction = -1 if local_y < edge else (1 if local_y > tree.winfo_height() - edge else 0)
        if direction:
            units = 3 if abs(local_y - (0 if direction < 0 else tree.winfo_height())) < edge // 2 else 2
            try:
                tree.yview_scroll(direction * units, "units")
            except Exception:
                pass
        self._update_tree_drag_selection(tree, kind, pointer_root[1])
        attr = "_bank_drag_after" if kind == "bank" else "_wem_drag_after"
        setattr(self, attr, self.root.after(55, lambda k=kind: self._tree_drag_tick(k)))

    def _bank_press(self, event: Any) -> str:
        row = self.bank_tree.identify_row(event.y)
        self._stop_tree_drag_autoscroll("bank")
        self._bank_drag_pointer = (event.x_root, event.y_root)
        if not row:
            self._bank_drag_start = None
            self._bank_drag_start_iid = None
            self._bank_drag_active = False
            self._bank_marquee_hits.clear()
            self._hide_marquee("_bank_marquee_canvas")
            return "break"
        self._bank_drag_start = (event.x_root, event.y_root, int(event.state or 0))
        self._bank_drag_start_iid = row
        self._bank_drag_active = False
        self._bank_marquee_hits.clear()
        self._hide_marquee("_bank_marquee_canvas")
        return "break"

    def _bank_drag_motion(self, event: Any) -> str:
        if not self._bank_drag_start:
            return "break"
        self._bank_drag_pointer = (event.x_root, event.y_root)
        sx_root, sy_root, state = self._bank_drag_start
        sx = sx_root - self.bank_tree.winfo_rootx()
        sy = sy_root - self.bank_tree.winfo_rooty()
        ex, ey = event.x, event.y
        dx, dy = ex - sx, ey - sy
        if not self._bank_drag_active and (dx * dx + dy * dy) >= 36:
            self._bank_drag_active = True
            self._bank_marquee_hits.clear()
            self.status_var.set("Selecting sound groups…")
            self._stop_tree_drag_autoscroll("bank")
            self._bank_drag_after = self.root.after(55, lambda: self._tree_drag_tick("bank"))
        if not self._bank_drag_active:
            return "break"
        rx0, rx1 = sorted((sx, ex))
        ry0, ry1 = sorted((sy, ey))
        self._show_marquee(self.bank_tree, "_bank_marquee_canvas", (rx0, ry0, rx1, ry1))
        self._update_tree_drag_selection(self.bank_tree, "bank", event.y_root)
        return "break"

    def _bank_release(self, event: Any) -> str:
        if not self._bank_drag_start:
            return "continue"
        sx_root, sy_root, state = self._bank_drag_start
        dragged = self._bank_drag_active
        hit_iids = tuple(self._bank_marquee_hits)
        self._stop_tree_drag_autoscroll("bank")
        self._bank_drag_start = None
        self._bank_drag_start_iid = None
        self._bank_drag_pointer = None
        self._bank_drag_active = False
        self._bank_marquee_hits.clear()
        self._hide_marquee("_bank_marquee_canvas")

        if dragged:

            paths = []
            seen: set[Path] = set()
            for iid in hit_iids:
                path = self._bank_path_by_item.get(iid)
                if path is not None and path not in seen:
                    paths.append(path)
                    seen.add(path)

            loaded = [p for p in paths if p in self.loaded_banks]
            unloaded = [p for p in paths if p not in self.loaded_banks]

            for path in loaded:
                self._unload_bank_immediately(path)
            if unloaded:
                self._load_banks_bulk(unloaded)
            self.status_var.set(f"Toggled {len(paths)} selected sound group(s)")
            return "break"

        ty = self.bank_tree.winfo_rooty()
        row = self.bank_tree.identify_row(event.y_root - ty)
        if row:
            return self._bank_activate(row, state)
        return "break"

    def _bank_click(self, event: Any) -> Optional[str]:

        row = self.bank_tree.identify_row(event.y)
        return self._bank_activate(row, int(event.state or 0)) if row else None

    def _bank_double(self, event: Any) -> Optional[str]:

        return "break"

    def _load_banks_bulk(self, banks: Sequence[Path]) -> None:

        pending = []
        seen: set[Path] = set()
        for bank in banks:
            bank = Path(bank).resolve()
            if bank in seen or bank in self.loaded_banks:
                continue
            seen.add(bank)
            pending.append(bank)
        if not pending:
            return

        self._loading_generation += 1
        generation = self._loading_generation
        self._loading_banks.clear()
        self._loading_banks.update(pending)
        for bank in pending:
            self.bank_infos[str(bank)] = []
        self._render_banks()
        self._render_wems()
        self._set_loading(True, f"✿ Opening {len(pending)} selected sound groups…")
        threading.Thread(
            target=self._load_banks_bulk_thread,
            args=(pending, generation),
            daemon=True,
        ).start()

    def _load_banks_bulk_thread(self, banks: list[Path], generation: int) -> None:
        failures: list[tuple[Path, str]] = []
        for bank in banks:
            if generation != self._loading_generation or self._destroyed:
                return
            try:
                if bank.suffix.lower() == ".wem":
                    if not self.tools.vgmstream:
                        raise ToolNotFound("vgmstream-cli.exe not found")
                    infos = make_wem_info_list(self.runner, self.tools.vgmstream, bank, [bank], 180.0)
                else:
                    options = ProcessOptions(game_audio_dir=Path(self.game_target_var.get()), install_to_game=True)
                    replacer = BNKReplacer(self.paths, self.tools, options, self.log, self.bus)
                    self.log.info("Automatically loading BNK (bulk selection): %s", bank)
                    infos = replacer.inspect_bank(
                        bank,
                        progress_callback=lambda d, t, w, b=bank, g=generation: self._ui_after(
                            0, lambda d=d, t=t, w=w, bank_path=b, gen=g:
                                self._update_bank_probe_status(bank_path, d, t, w, gen)
                        ),
                    )
                self._ui_after(0, lambda b=bank, i=infos, g=generation: self._finish_bulk_bank_load(b, i, g))
            except Exception as exc:
                msg = str(exc)
                failures.append((bank, msg))
                self.log.error("Failed to load %s: %s", bank, exc)
                self._ui_after(0, lambda b=bank, g=generation: self._fail_bulk_bank_load(b, g))
        self._ui_after(0, lambda g=generation, f=failures: self._finish_bulk_bank_load_batch(g, f))

    def _update_bank_probe_status(self, bank: Path, done: int, total: int, wem: Path, generation: int) -> None:
        if generation != self._loading_generation or self._destroyed:
            return
        try:
            self.status_var.set(f"✿ Reading {self._friendly_bank_label(bank)} — WEM {done}/{total}: {wem.name}")
        except Exception:
            pass

    def _finish_bulk_bank_load(self, bank: Path, infos: list[WemInfo], generation: int) -> None:
        if generation != self._loading_generation or self._destroyed:
            return
        self.loaded_banks.add(bank)
        self._loading_banks.discard(bank)
        self.bank_infos[str(bank)] = infos
        self._render_banks()
        self._render_wems()

    def _fail_bulk_bank_load(self, bank: Path, generation: int) -> None:
        if generation != self._loading_generation or self._destroyed:
            return
        self.loaded_banks.discard(bank)
        self._loading_banks.discard(bank)
        self.bank_infos.pop(str(bank), None)
        self._render_banks()
        self._render_wems()

    def _finish_bulk_bank_load_batch(self, generation: int, failures: list[tuple[Path, str]]) -> None:
        if generation != self._loading_generation or self._destroyed:
            return
        self._loading_banks.clear()
        self._set_loading(False)
        self._render_wems()
        if failures:
            summary = "\n\n".join(f"{self._friendly_bank_label(bank)}\n{msg}" for bank, msg in failures[:8])
            self.status_var.set(f"Loaded selected groups with {len(failures)} failure(s)")
            cute_error(
                "Some sound groups could not be opened",
                f"{len(failures)} selected BNK(s) could not be loaded.\n\n{summary}",
                parent=self.root,
            )
        else:
            self.status_var.set("♡ All selected sound groups loaded")

    def _load_loose_wem_thread(self, wem: Path, generation: int) -> None:
        try:
            if not self.tools.vgmstream:
                raise ToolNotFound("vgmstream-cli.exe not found")
            infos = make_wem_info_list(
                self.runner, self.tools.vgmstream, wem, [wem], 180.0
            )
            self._ui_after(0, lambda: self._finish_bank_load(wem, infos, generation))
        except Exception as exc:
            self.log.error("Failed to load loose WEM %s: %s", wem, exc)
            def fail_ui(msg=str(exc), b=wem):
                self._loading_banks.discard(b)
                self.bank_infos.pop(str(b), None)
                self.loaded_banks.discard(b)
                self._render_banks()
                self._render_wems()
                self._set_loading(False, f"Could not load {b.name}: {msg}")
            self._ui_after(0, fail_ui)

    def _load_loose_wem_immediately(self, wem: Path) -> None:
        if wem in self.loaded_banks or wem in self._loading_banks:
            return
        self._loading_generation += 1
        generation = self._loading_generation
        self._loading_banks.clear()
        self._loading_banks.add(wem)
        self._set_loading(True, f"✿ Opening {self._friendly_bank_label(wem)}…")
        self.bank_infos[str(wem)] = []
        self._render_wems()
        self.loaded_count_var.set("")
        self.status_var.set(f"Opening {self._friendly_bank_label(wem)}…")
        threading.Thread(target=self._load_loose_wem_thread, args=(wem, generation), daemon=True).start()

    def _load_bank_immediately(self, bank: Path) -> None:
        if bank in self.loaded_banks or bank in self._loading_banks:
            return
        self._loading_generation += 1
        generation = self._loading_generation
        self._loading_banks.clear()
        self._loading_banks.add(bank)
        self._set_loading(True, f"✿ Opening {self._friendly_bank_label(bank)}…")

        self.bank_infos[str(bank)] = []
        self._render_wems()
        self.loaded_count_var.set("")
        self.status_var.set(f"Opening {self._friendly_bank_label(bank)}…")
        threading.Thread(target=self._load_bank_thread, args=(bank, generation), daemon=True).start()

    def _load_bank_thread(self, bank: Path, generation: int) -> None:
        try:
            if bank.suffix.lower() == ".wem":
                if not self.tools.vgmstream:
                    raise ToolNotFound("vgmstream-cli.exe not found")
                infos = make_wem_info_list(self.runner, self.tools.vgmstream, bank, [bank], 180.0)
            else:
                options = ProcessOptions(game_audio_dir=Path(self.game_target_var.get()), install_to_game=True)
                replacer = BNKReplacer(self.paths, self.tools, options, self.log, self.bus)
                self.log.info("Automatically loading BNK: %s", bank)
                infos = replacer.inspect_bank(bank)
            self._ui_after(0, lambda: self._finish_bank_load(bank, infos, generation))
        except Exception as exc:
            self.log.error("Failed to load %s: %s", bank, exc)
            def fail_ui(msg=str(exc), b=bank):
                self._loading_banks.discard(b)
                self.bank_infos.pop(str(b), None)
                self.loaded_banks.discard(b)
                self._render_banks()
                self._render_wems()
                self._set_loading(False, f"✗ Could not open {self._friendly_bank_label(b)}")
                cute_error(
                    "Could not open sound group",
                    f"Could not open {self._friendly_bank_label(b)}.",
                    hint="The file may be locked by Brawlhalla or damaged. Close the game if it "
                         "is open, make sure the file is not read-only, then try again.",
                    copy_text=msg,
                )
            self._ui_after(0, fail_ui)

    def _finish_bank_load(self, bank: Path, infos: list[WemInfo], generation: int) -> None:
        if generation != self._loading_generation:
            return
        self.loaded_banks.add(bank)
        self._loading_banks.discard(bank)
        self.bank_infos[str(bank)] = infos
        self._render_banks()
        self._render_wems()
        self.selected_bank_hint_var.set(f"✿ {self._friendly_bank_label(bank)} — {len(infos)} sounds. Pick one below ♡")
        self._set_flow_hint("Now pick a sound, then press “Listen” to hear the original ♡", mark=True)
        self._set_loading(False, f"♡ Loaded {self._friendly_bank_label(bank)}: {len(infos)} sounds")

    def _unload_bank_immediately(self, bank: Path) -> None:

        if bank.suffix.lower() == ".wem":
            self._loading_generation += 1
            self._loading_banks.discard(bank)
            self.bank_infos.pop(str(bank), None)
            self.loaded_banks.discard(bank)
            self._render_banks()
            self._render_wems()
            self.status_var.set(f"Closed {self._friendly_bank_label(bank)}")
            return

        self._loading_generation += 1
        self._loading_banks.discard(bank)
        infos = self.bank_infos.get(str(bank), [])
        cache_dirs = {info.file_path.parent for info in infos if info.file_path.parent.exists()}
        self.loaded_banks.discard(bank)
        self.bank_infos.pop(str(bank), None)
        for cache_dir in cache_dirs:
            _LIVE_BNK_STAGING_DIRS.discard(cache_dir)
            with contextlib.suppress(OSError):
                shutil.rmtree(cache_dir, ignore_errors=True)
        self._render_banks()
        self._render_wems()
        self.status_var.set(f"Closed {self._friendly_bank_label(bank)}")

    def _unload_selected_banks(self) -> None:
        for iid in self.bank_tree.selection():
            p = self._bank_path_by_item.get(iid)
            if p:
                self._unload_bank_immediately(p)

    def select_banks(self) -> None:
        files = filedialog.askopenfilenames(title="Add BNK files", filetypes=[("Wwise SoundBank", "*.bnk"), ("All files", "*.*")])
        if not files:
            return
        for value in files:
            p = Path(value).resolve()
            if p not in self.discovered_banks:
                self.discovered_banks.append(p)
                self.bank_categories[str(p)] = categorise_brawlhalla_bnk(p)
        self.discovered_banks.sort(key=lambda p: p.name.lower())
        self._render_banks()
        for p in files:
            iid = self._bank_item_by_path.get(Path(p).resolve())
            if iid:
                self.bank_tree.selection_add(iid)

    def select_all_banks(self) -> None:
        for iid in self.bank_tree.get_children(""):
            p = self._bank_path_by_item.get(iid)
            if p and p not in self.loaded_banks:
                self._load_bank_immediately(p)
        self.status_var.set("✿ Opening the visible sound groups…")

    def clear_bank_selection(self) -> None:
        # Clear means remove loaded BNKs and clear the current selection/search.
        self._loading_generation += 1
        self._loading_banks.clear()

        selected = []
        for iid in self.bank_tree.selection():
            bank = self._bank_path_by_item.get(iid)
            if bank is not None:
                selected.append(bank)

        targets = [bank for bank in selected if bank in self.loaded_banks]
        if not targets:
            targets = list(self.loaded_banks)

        for bank in targets:
            infos = self.bank_infos.pop(str(bank), [])
            self.loaded_banks.discard(bank)
            cache_dirs = {info.file_path.parent for info in infos if info.file_path.parent.exists()}
            for cache_dir in cache_dirs:
                _LIVE_BNK_STAGING_DIRS.discard(cache_dir)
                with contextlib.suppress(OSError):
                    shutil.rmtree(cache_dir, ignore_errors=True)

        self.bank_tree.selection_remove(self.bank_tree.selection())
        self.bank_search_var.set("")
        self.wem_search_var.set("")
        self.loaded_count_var.set("")
        self._render_banks()
        self._render_wems()
        if targets:
            self.status_var.set(f"♡ Cleared {len(targets)} loaded sound group(s)")
        else:
            self.status_var.set("♡ Cleared selection")

    def _all_loaded_infos(self) -> list[WemInfo]:
        out: list[WemInfo] = []
        for bank in self.discovered_banks:
            if bank in self.loaded_banks:
                out.extend(self.bank_infos.get(str(bank), []))
        return out

    def _refresh_detail_columns(self) -> None:
        advanced = bool(self.show_advanced_details_var.get())
        technical = bool(self.show_technical_names_var.get())

        # Normal view deliberately prioritizes the human-readable description.
        # This keeps the right pane narrow enough that it cannot squeeze the BNK pane.
        if advanced:
            self.wem_tree.configure(
                displaycolumns=("wem", "bank", "description", "duration", "rate", "channels", "encoding")
            )
            self.wem_tree.column("wem", width=135, minwidth=110, stretch=False)
            self.wem_tree.column("bank", width=145, minwidth=110, stretch=False)
            self.wem_tree.column("description", width=250, minwidth=140, stretch=True)
            self.wem_tree.column("duration", width=78, minwidth=68, anchor="e", stretch=False)
            self.wem_tree.column("rate", width=78, minwidth=0, anchor="e", stretch=False)
            self.wem_tree.column("channels", width=44, minwidth=0, anchor="center", stretch=False)
            self.wem_tree.column("encoding", width=108, minwidth=0, anchor="center", stretch=False)
        else:
            # Keep the original compact layout, but always show the BNK that owns
            # each WEM. This makes similarly-numbered sounds immediately traceable
            # when multiple BNKs are loaded at once.
            self.wem_tree.configure(displaycolumns=("wem", "bank", "description", "duration"))
            self.wem_tree.column("wem", width=128, minwidth=105, anchor="center", stretch=False)
            self.wem_tree.column("bank", width=190, minwidth=140, anchor="w", stretch=False)
            self.wem_tree.column("description", width=245, minwidth=140, stretch=True)
            self.wem_tree.column("duration", width=78, minwidth=68, anchor="e", stretch=False)
            self.wem_tree.column("rate", width=0, minwidth=0, stretch=False)
            self.wem_tree.column("channels", width=0, minwidth=0, stretch=False)
            self.wem_tree.column("encoding", width=0, minwidth=0, stretch=False)

        self.wem_tree.heading("wem", text="WEM" if technical else "SOUND")
        self.wem_tree.heading("bank", text="SOUND GROUP")
        self.wem_tree.heading("description", text="DESCRIPTION")
        self.wem_tree.heading("duration", text="LENGTH")
        self.bank_tree.heading("name", text="BNK FILE" if technical else "SOUND GROUP")

    def _render_wems(self) -> None:
        selected_paths = {self.wem_by_item[i].key for i in self.wem_tree.selection() if i in self.wem_by_item}
        for iid in self.wem_tree.get_children(""):
            self.wem_tree.delete(iid)
        self.wem_by_item.clear()
        query = self.wem_search_var.get().strip().lower()
        infos = [i for i in self._all_loaded_infos()
                 if (not self.favorite_only_var.get() or i.key in self.favorite_wem_keys)
                 and (not query or query in i.display_name.lower() or query in i.bank_path.name.lower() or str(i.index) == query)]
        sort_mode = self.wem_sort_var.get()
        if sort_mode == "Name":
            infos.sort(key=lambda i: (i.display_name.lower(), i.bank_path.name.lower(), i.index))
        elif sort_mode in ("Duration", "Length"):
            infos.sort(key=lambda i: (i.duration_seconds, i.bank_path.name.lower(), i.index))
        else:
            infos.sort(key=lambda i: (i.bank_path.name.lower(), i.index))
        if self.wem_sort_order_var.get() == "Descending":
            infos.reverse()

        loading_banks = [p for p in self._loading_banks if not self.bank_infos.get(str(p)) and query == ""]

        for bank in sorted(loading_banks, key=lambda p: p.name.lower()):
            iid = f"loading::{safe_name(bank.stem)}"
            self.wem_tree.insert("", "end", iid=iid, values=("…", self._friendly_bank_label(bank), "", "Loading…", "", "", ""), tags=("loading",))

        if not infos and not loading_banks:
            loaded_names = [self._friendly_bank_label(p) for p in sorted(self.loaded_banks, key=lambda p: p.name.lower())]
            if loaded_names:
                self.wem_tree.insert("", "end", values=("—", ", ".join(loaded_names[:2]), "", "No sounds", "", "", "This group has no playable sounds"), tags=("empty",))
            else:
                self.wem_tree.insert("", "end", values=("—", "Nothing picked yet", "", "", "", "", "Pick a sound group on the left"), tags=("empty",))

        for info in infos:
            iid = f"{safe_name(info.bank_path.stem)}::{info.index}::{uuid.uuid4().hex[:5]}"
            row_number = len(self.wem_by_item) + 1
            star = "★ " if info.key in self.favorite_wem_keys else "☆ "
            description = self._description_for_info(info).replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
            self.wem_tree.insert("", "end", iid=iid, values=(
                f"{row_number} · {star}{self._friendly_sound_label(info)}",
                self._friendly_bank_label(info.bank_path).split("  [", 1)[0],
                description,
                f"{info.duration_seconds:.4f}s", f"{info.sample_rate} Hz", info.channels, info.encoding
            ))
            self.wem_by_item[iid] = info
        self.wem_count_var.set(f"{len(infos)} sounds")
        self._refresh_detail_columns()
        self._wem_selection_changed()
        for iid, info in self.wem_by_item.items():
            if info.key in selected_paths:
                self.wem_tree.selection_add(iid)

        self._ux_bind_widgets(self.wem_tree)

    def _wem_selection_changed(self) -> None:
        self.selected_wem_var.set(f"{len(self.wem_tree.selection())} selected" if self.wem_tree.selection() else "")
        selected = self._selected_infos()
        if selected:
            count = len(selected)
            self.selected_bank_hint_var.set(
                f"Ready: {self._friendly_sound_label(selected[0])}"
                + (f"  +{count - 1} more" if count > 1 else "")
            )
            self._set_flow_hint("Now listen to it, then press “Replace this sound ♡”", mark=False)
        elif self.wem_by_item:
            self.selected_bank_hint_var.set("Pick a sound from the list")
            self._set_flow_hint("Now pick a sound, then press “Listen” to hear the original ♡", mark=True)
        else:
            self.selected_bank_hint_var.set("Choose a group on the left to see its sounds")
            self._set_flow_hint("Start on the left — pick a sound group ♡", mark=True)
        self._refresh_process_button()
        self._refresh_wem_description_panel()

    def _set_flow_hint(self, text: str, mark: bool = False) -> None:
        try:
            self._flow_hint_var.set(text)
        except Exception:
            pass
        try:
            if mark:
                if not self.sounds_step_mark.winfo_ismapped():
                    self.sounds_step_mark.pack(side="left", padx=(8, 0))
            else:
                self.sounds_step_mark.pack_forget()
        except Exception:
            pass

    def _refresh_process_button(self) -> None:
        button = getattr(self, "process_button", None)
        if button is None:
            return
        busy = getattr(self, "_ux_busy", False) or getattr(self, "_process_worker", None) is not None
        try:
            button.state(["disabled"] if busy or not self._selected_infos() else ["!disabled"])
        except Exception:
            pass

    def _selected_infos(self) -> list[WemInfo]:
        return [self.wem_by_item[i] for i in self.wem_tree.selection() if i in self.wem_by_item]

    def _wem_press(self, event: Any) -> str:
        row = self.wem_tree.identify_row(event.y)
        self._stop_tree_drag_autoscroll("wem")
        self._wem_drag_pointer = (event.x_root, event.y_root)
        if not row or row not in self.wem_by_item:
            self._wem_drag_start = None
            self._wem_drag_start_iid = None
            self._wem_drag_active = False
            self._wem_marquee_hits.clear()
            self._hide_marquee("_wem_marquee_canvas")
            return "break"
        self._wem_drag_start = (event.x_root, event.y_root, int(event.state or 0))
        self._wem_drag_start_iid = row
        self._wem_anchor_iid = row
        self._wem_drag_active = False
        self._wem_marquee_hits.clear()
        self._hide_marquee("_wem_marquee_canvas")
        return "break"

    def _wem_drag_motion(self, event: Any) -> str:
        if not self._wem_drag_start:
            return "break"
        self._wem_drag_pointer = (event.x_root, event.y_root)
        sx_root, sy_root, state = self._wem_drag_start
        sx = sx_root - self.wem_tree.winfo_rootx(); sy = sy_root - self.wem_tree.winfo_rooty()
        ex, ey = event.x, event.y
        dx, dy = ex - sx, ey - sy
        if not self._wem_drag_active and (dx * dx + dy * dy) >= 36:
            self._wem_drag_active = True
            self._wem_marquee_hits.clear()
            self.status_var.set("Selecting sounds…")
            self._stop_tree_drag_autoscroll("wem")
            self._wem_drag_after = self.root.after(55, lambda: self._tree_drag_tick("wem"))
        if not self._wem_drag_active:
            return "break"
        rx0, rx1 = sorted((sx, ex)); ry0, ry1 = sorted((sy, ey))
        self._show_marquee(self.wem_tree, "_wem_marquee_canvas", (rx0, ry0, rx1, ry1))
        self._update_tree_drag_selection(self.wem_tree, "wem", event.y_root)
        return "break"

    def _wem_release(self, event: Any) -> str:
        if not self._wem_drag_start:
            return "continue"
        dragged = self._wem_drag_active
        self._stop_tree_drag_autoscroll("wem")
        self._wem_drag_start = None
        self._wem_drag_start_iid = None
        self._wem_drag_pointer = None
        self._wem_drag_active = False
        self._wem_marquee_hits.clear()
        self._hide_marquee("_wem_marquee_canvas")
        if dragged:
            self._wem_selection_changed()
            self.status_var.set(f"Selected {len(self.wem_tree.selection())} sound(s)")
            return "break"
        row = self.wem_tree.identify_row(event.y)
        if row and row in self.wem_by_item:
            state = int(event.state or 0)
            if state & 0x0004:
                self.wem_tree.selection_toggle(row)
            elif state & 0x0001:
                self.wem_tree.selection_add(row)
            else:
                self.wem_tree.selection_set(row)
            self._wem_anchor_iid = row
            self._wem_selection_changed()
        return "break"

    def clear_wem_selection(self) -> None:
        self.wem_tree.selection_remove(self.wem_tree.selection())
        self._wem_selection_changed()

    def select_all_wems(self) -> None:
        children = self.wem_tree.get_children("")
        if children:
            self.wem_tree.selection_set(children)
        self._wem_selection_changed()

    def _copy_selected_wem_paths(self) -> None:
        infos = self._selected_infos()
        if not infos:
            return
        text = "\n".join(str(i.file_path) for i in infos)
        self.root.clipboard_clear(); self.root.clipboard_append(text)
        self.status_var.set(f"Copied {len(infos)} WEM path(s).")

    def _reveal_selected_wem(self) -> None:
        infos = self._selected_infos()
        if not infos:
            return
        p = infos[0].file_path
        try:
            subprocess.Popen(["explorer.exe", "/select,", os.fspath(p)])
        except Exception as exc:
            cute_error("Reveal failed", str(exc))

