    def _watch_url_prefetch(self, variable: tk.StringVar, context: str, label: str) -> None:
        """Watch an audio source entry without queueing no-op Tk callbacks.

        Empty/local-file values are ignored immediately. URL work is still coalesced by
        URLPrefetchManager and executed on its background worker, so changing several WEM
        rows cannot turn the replacement dialog into a burst of main-thread callbacks.
        """
        pending = {"id": None}
        def changed(*_args: Any) -> None:
            if pending["id"] is not None:
                with contextlib.suppress(Exception):
                    self.root.after_cancel(pending["id"])
                pending["id"] = None
            raw = variable.get().strip()
            if not looks_like_url(raw) or is_youtube_playlist_url(raw):
                return
            def start() -> None:
                pending["id"] = None
                try:
                    self._url_prefetch.activate(context, raw, label)
                except Exception as exc:
                    self.log.debug("URL prefetch change handler failed: %s", exc)
            pending["id"] = self.root.after(250, start)
        variable.trace_add("write", changed)
        changed()

    def _prefetched_source_for(self, source: str, label: str) -> Optional[Path]:
        raw = source.strip().strip('"')
        if not looks_like_url(raw) or is_youtube_playlist_url(raw):
            return None
        return self._url_prefetch.wait_for(raw, label)

    def _request_additional_playlist(self, remaining: int, collected: int, used_playlist_ids: set[str]) -> str:
        """Ask on the Tk thread for another playlist when the current queue is short."""
        result: dict[str, Any] = {"url": None, "cancel": False}
        ready = threading.Event()
        prompt_box: dict[str, Any] = {"win": None}

        def close_prompt(cancelled: bool = False) -> None:
            result["cancel"] = bool(cancelled)
            win = prompt_box.get("win")
            if win is not None:
                with contextlib.suppress(Exception):
                    if win.winfo_exists():
                        win.grab_release()
                        win.destroy()
            ready.set()

        def show() -> None:
            if self._destroyed:
                result["cancel"] = True
                ready.set()
                return
            parent = getattr(self, "_processing_window", None)
            if parent is None or not parent.winfo_exists():
                parent = self.root
            win = tk.Toplevel(parent)
            prompt_box["win"] = win
            self._windowed_lightweight(win, "Add another playlist", 650, 280)
            try:
                win.transient(parent)
                win.grab_set()
            except Exception:
                pass
            body = ttk.Frame(win, padding=18); body.pack(fill="both", expand=True)
            ttk.Label(body, text="♡ This playlist needs a little help", style="EditorTitle.TLabel").pack(anchor="w")
            ttk.Label(
                body,
                text=f"The playlist supplied {collected} distinct track(s), but {remaining} more track(s) are still needed. Add another YouTube playlist and its unused tracks will continue the queue in order.",
                style="EditorSub.TLabel", wraplength=600, justify="left",
            ).pack(anchor="w", pady=(6, 14))
            entry = tk.StringVar()
            row = ttk.Frame(body); row.pack(fill="x")
            ttk.Label(row, text="Playlist URL:", width=15, style="EditorField.TLabel").pack(side="left")
            ent = ttk.Entry(row, textvariable=entry); ent.pack(side="left", fill="x", expand=True, padx=(6, 0))
            ttk.Label(body, text="Duplicate songs across playlists are skipped automatically.", style="EditorHint.TLabel", wraplength=600).pack(anchor="w", pady=(9, 0))
            ttk.Label(body, text="Choose Stop to cancel the whole replacement; nothing further will be processed.", style="EditorHint.TLabel", wraplength=600).pack(anchor="w", pady=(3, 0))
            footer = ttk.Frame(body); footer.pack(fill="x", side="bottom", pady=(18, 0))

            def submit() -> None:
                url = entry.get().strip().strip('"')
                if not is_youtube_playlist_url(url):
                    cute_warning("Playlist needed", "Enter a valid YouTube playlist URL containing a list= ID.", parent=win)
                    ent.focus_set(); return
                playlist_id = self._playlist_id(url)
                if playlist_id and playlist_id in used_playlist_ids:
                    cute_warning("Playlist already used", "That playlist has already been added to this replacement queue. Choose a different playlist.", parent=win)
                    ent.focus_set(); return
                result["url"] = url
                close_prompt(False)

            ttk.Button(footer, text="Stop", style="Tool.TButton", command=lambda: close_prompt(True)).pack(side="right", padx=(6, 0))
            ttk.Button(footer, text="Add playlist ♡", style="Big.TButton", command=submit).pack(side="right")
            win.protocol("WM_DELETE_WINDOW", lambda: close_prompt(True))
            win.bind("<Return>", lambda _e: submit())
            win.bind("<Escape>", lambda _e: close_prompt(True))
            ent.focus_set()
            self._raise_child(win)

        self._ui_after(0, show)
        cancel_event = getattr(self, "_process_cancel", None)
        while not ready.wait(0.20):
            if cancel_event is not None and cancel_event.is_set():
                self._ui_after(0, lambda: close_prompt(True))
                raise ProcessingCancelled("Replacement cancelled while waiting for an additional playlist")
        if result.get("cancel") or not result.get("url"):
            raise ProcessingCancelled("Replacement cancelled while choosing playlist sources")
        return str(result["url"])

    def _request_playlist_shortage_action(self, playlist_name: str, available: int, required: int) -> tuple[str, str]:
        """Prompt safely from a worker thread; never block Tk while creating the prompt."""
        result: dict[str, str] = {"action": "stop", "url": ""}
        ready = threading.Event()
        box: dict[str, Any] = {"win": None}

        def close(action: str, url: str = "") -> None:
            result["action"] = action
            result["url"] = url
            win = box.get("win")
            if win is not None:
                with contextlib.suppress(Exception):
                    if win.winfo_exists():
                        win.grab_release(); win.destroy()
            ready.set()

        def show() -> None:
            if self._destroyed:
                ready.set(); return
            parent = getattr(self, "_processing_window", None)
            if parent is None or not parent.winfo_exists():
                parent = self.root
            win = tk.Toplevel(parent); box["win"] = win
            self._windowed_lightweight(win, "Playlist is shorter", 680, 315)
            try:
                win.transient(parent); win.grab_set()
            except Exception:
                pass
            body = ttk.Frame(win, padding=18); body.pack(fill="both", expand=True)
            ttk.Label(body, text="♡ Playlist is shorter than your WEM selection", style="EditorTitle.TLabel").pack(anchor="w")
            ttk.Label(body, text=(f"The playlist has {available} usable track(s), but {required} WEMs are selected.\n\n"
                                  "Reuse the first playlist from the beginning, or paste another playlist to fill the remaining WEMs."),
                      style="EditorSub.TLabel", wraplength=640, justify="left").pack(anchor="w", pady=(6, 12))
            ttk.Label(body, text=f"Current playlist: {playlist_name}", style="EditorHint.TLabel", wraplength=640).pack(anchor="w", pady=(0, 8))
            entry = tk.StringVar()
            row = ttk.Frame(body); row.pack(fill="x")
            ttk.Label(row, text="Another playlist:", width=16, style="EditorField.TLabel").pack(side="left")
            ent = ttk.Entry(row, textvariable=entry); ent.pack(side="left", fill="x", expand=True, padx=(6, 0))
            footer = ttk.Frame(body); footer.pack(fill="x", side="bottom", pady=(16, 0))
            def add() -> None:
                url = entry.get().strip().strip('"')
                if not is_youtube_playlist_url(url):
                    cute_warning("Playlist needed", "Enter a valid YouTube playlist URL containing a list= ID.", parent=win); ent.focus_set(); return
                close("add", url)
            ttk.Button(footer, text="Cancel", style="Tool.TButton", command=lambda: close("stop")).pack(side="right", padx=(6, 0))
            ttk.Button(footer, text="Reuse first playlist ♡", style="Tool.TButton", command=lambda: close("reuse")).pack(side="right", padx=(6, 0))
            ttk.Button(footer, text="Add another playlist ♡", style="Big.TButton", command=add).pack(side="right")
            win.protocol("WM_DELETE_WINDOW", lambda: close("stop")); win.bind("<Escape>", lambda _e: close("stop"))
            ent.focus_set(); self._raise_child(win)

        self._ui_after(0, show)
        cancel_event = getattr(self, "_process_cancel", None)
        while not ready.wait(0.10):
            if cancel_event is not None and cancel_event.is_set():
                self._ui_after(0, lambda: close("stop")); return "stop", ""
        return result["action"], result["url"]

    @staticmethod
    def _playlist_id(url: str) -> str:
        try:
            parsed = urllib.parse.urlparse(str(url).strip().strip('"'))
            return str((urllib.parse.parse_qs(parsed.query).get("list") or [""])[0]).strip().lower()
        except Exception:
            return ""

    def _prepare_url_sources(self, selections: list[Selection]) -> None:
        """Prepare sources for replacement. Playlist work is intentionally lean and staged."""
        single_url_groups: dict[str, list[Selection]] = {}
        playlist_groups: dict[str, list[Selection]] = {}
        for selection in selections:
            # Playlist batch mode pre-downloads every exact playlist track and stores
            # it on the Selection. Do not throw that work away by resolving the URL again.
            cached = selection.local_source_path
            if cached is not None:
                try:
                    if cached.is_file() and cached.stat().st_size > 4096:
                        continue
                except OSError:
                    pass
            raw = selection.source.strip().strip('"')
            if not looks_like_url(raw):
                continue
            if is_youtube_playlist_url(raw):
                playlist_groups.setdefault(raw, []).append(selection)
            else:
                single_url_groups.setdefault(raw, []).append(selection)

        if single_url_groups:
            # Every distinct URL gets its own worker immediately.  This is the critical bulk
            # path: 40 different WEMs with 40 different replacement URLs create 40 simultaneous
            # downloads instead of making the network wait behind a four-job queue.
            requested_workers = int(getattr(self, "_download_worker_limit", 0) or 0)
            max_workers = len(single_url_groups) if requested_workers <= 0 else max(1, min(requested_workers, len(single_url_groups)))

            def resolve_one(item: tuple[str, list[Selection]]) -> tuple[str, Path]:
                raw, group = item
                path = self._prefetched_source_for(raw, group[0].wem.display_name)
                if path is None:
                    raise RuntimeError(f"Could not prepare replacement URL: {raw}")
                return raw, path

            self._ui_after(0, lambda n=len(single_url_groups), w=max_workers: self._set_process_progress(
                f"Downloading all {n} replacement sound(s) at once — {w} active download(s)… ♫", 0, n
            ))
            with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix="sourcewait") as pool:
                futures = [pool.submit(resolve_one, item) for item in single_url_groups.items()]
                completed = 0
                for future in concurrent.futures.as_completed(futures):
                    raw, path = future.result()
                    completed += 1
                    self._ui_after(0, lambda d=completed, n=len(single_url_groups): self._set_process_progress(
                        f"✓ Replacement downloads ready — {d}/{n}… ♫", d, n
                    ))
                    for selection in single_url_groups[raw]:
                        selection.local_source_path = path

        for raw_url, group in playlist_groups.items():
            required = len(group)
            cancel_event = getattr(self, "_process_cancel", None)
            runner = Runner(self.log, self.bus, cancel_event=cancel_event)
            batch_options = ProcessOptions(
                install_to_game=False,
                download_timeout=600.0,
                # Start every required playlist download together.
                download_workers=max(1, required),
            )
            source_manager = SourceManager(self.tools, runner, self.paths, self.log, batch_options, fast_preview=True)

            with self._playlist_batch_metadata_lock:
                chain = list(self._playlist_batch_chains.get(raw_url, [raw_url]))
                first_cached = self._playlist_batch_metadata.get(raw_url)
                first_reuse = bool(self._playlist_batch_reuse_decisions.get(raw_url, False))

            all_tracks: list[PlaylistTrack] = []
            playlist_track_groups: list[tuple[str, list[PlaylistTrack]]] = []
            used_ids: set[str] = set()
            remaining = required
            for chain_index, playlist_url in enumerate(chain):
                if remaining <= 0:
                    break
                with self._playlist_batch_metadata_lock:
                    cached = self._playlist_batch_metadata.get(playlist_url)
                if cached is not None and cached[2]:
                    declared_count, playlist_title, tracks = cached
                    tracks = list(tracks)
                elif chain_index == 0 and first_cached is not None:
                    declared_count, playlist_title, tracks = first_cached
                    tracks = list(tracks)
                else:
                    if source_manager.fast_preview:
                        requested = max(1, remaining)
                        playlist_title, tracks = source_manager.playlist_entries_limited(
                            playlist_url, requested
                        )
                        declared_count = max(requested, len(tracks))
                    else:
                        declared_count = source_manager.playlist_count_fast(playlist_url, timeout=8.0)
                        playlist_title, tracks = source_manager.playlist_entries_limited(
                            playlist_url, min(remaining, max(1, int(declared_count)))
                        )
                    with self._playlist_batch_metadata_lock:
                        self._playlist_batch_metadata[playlist_url] = (declared_count, playlist_title, list(tracks))
                chosen: list[PlaylistTrack] = []
                for track in tracks:
                    if not remaining:
                        break
                    key = source_manager._playlist_track_key(track)
                    if key in used_ids:
                        continue
                    used_ids.add(key)
                    chosen.append(track)
                    all_tracks.append(track)
                    remaining -= 1
                if chosen:
                    playlist_track_groups.append((playlist_url, chosen))

            if not all_tracks:
                raise RuntimeError("The YouTube playlist returned no usable tracks.")
            if len(all_tracks) < required and not first_reuse:
                raise ProcessingCancelled(
                    f"Only {len(all_tracks)} distinct usable track(s) could be prepared for {required} selected WEMs."
                )

            self._ui_after(0, lambda t=len(all_tracks), r=required: self._set_process_progress(
                f"Downloading {t} playlist track(s) for {r} WEM(s) in bulk… ♫", 0, t
            ))
            base_batch_dir = self.paths.processed_audio / "batch_sources" / hashlib.sha256(raw_url.encode("utf-8")).hexdigest()[:20]
            downloaded: list[PlaylistTrack] = []
            for playlist_url, playlist_tracks in playlist_track_groups:
                playlist_dir = base_batch_dir / hashlib.sha256(playlist_url.encode("utf-8")).hexdigest()[:12]
                done_before = len(downloaded)
                part = source_manager.download_playlist_bulk(
                    playlist_url, playlist_tracks, playlist_dir, cancel_event=cancel_event,
                    progress=lambda message, done, total, base=done_before, all_total=len(all_tracks): self._ui_after(
                        0, lambda m=message, d=done, b=base, a=all_total: self._set_process_progress(m, min(a, b + d), a)
                    ),
                )
                downloaded.extend(part)
            if not downloaded:
                raise RuntimeError("The playlist downloads completed without usable audio.")
            if len(downloaded) < required and not first_reuse:
                raise ProcessingCancelled("The playlist download produced fewer tracks than required and reuse was not approved.")
            mapping = [downloaded[i % len(downloaded)] for i in range(required)]
            for selection, track in zip(group, mapping):
                selection.local_source_path = track.path
                selection.source_kind = "playlist"
                selection.source_playlist_index = track.playlist_index
                selection.source_playlist_title = track.title
                selection.source_playlist_urls = tuple(chain)

    def _stop_source_preview(self) -> None:
        self._source_preview_generation += 1
        cancel = getattr(self, "_source_preview_cancel", None)
        if cancel is not None:
            cancel.set()
        with contextlib.suppress(Exception):
            winsound.PlaySound(None, winsound.SND_PURGE) if winsound is not None else None
        directory = getattr(self, "_source_preview_dir", None)
        self._source_preview_dir = None
        if directory:
            threading.Thread(target=lambda d=directory: shutil.rmtree(d, ignore_errors=True), daemon=True).start()

    def _preview_source_audio(self, source: str, parent=None, label: str = "Source audio") -> None:
        parent = parent or self.root
        if winsound is None or not self.tools.ffmpeg:
            cute_error("Source preview unavailable", "Source preview needs Windows audio playback and FFmpeg.", parent=parent)
            return
        raw = str(source).strip().strip('"')
        if not raw:
            cute_warning("Source preview", "Choose replacement audio first.", parent=parent); return
        self._stop_source_preview()
        preview_generation = self._source_preview_generation
        cancel = threading.Event(); self._source_preview_cancel = cancel
        root_dir = self.paths.processed_audio / "source_preview"; root_dir.mkdir(parents=True, exist_ok=True)
        run_dir = Path(tempfile.mkdtemp(prefix="source_", dir=root_dir))
        self._source_preview_dir = run_dir
        def worker():
            try:
                src = raw
                if looks_like_url(raw):
                    cached = self._prefetched_source_for(raw, label)
                    if not cached:
                        raise RuntimeError("The URL could not be downloaded for preview.")
                    src = str(cached)
                src_path = Path(os.path.expandvars(os.path.expanduser(src)))
                if not src_path.is_file():
                    raise FileNotFoundError(f"Audio file does not exist: {src_path}")
                wav = run_dir / "preview.wav"
                self.runner.run([self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", src_path, "-vn", "-ac", "2", "-ar", "48000", "-c:a", "pcm_s16le", wav], timeout=180)
                if cancel.is_set(): return
                with wave.open(str(wav), "rb") as wf:
                    channels, rate, width, frames = wf.getnchannels(), wf.getframerate(), wf.getsampwidth(), wf.getnframes()
                    if channels < 1 or rate < 1 or width != 2 or frames < 1:
                        raise RuntimeError("FFmpeg produced an invalid preview WAV.")
                    duration = frames / float(rate)
                winsound.PlaySound(str(wav), winsound.SND_FILENAME | winsound.SND_NODEFAULT | winsound.SND_ASYNC)
                if preview_generation != self._source_preview_generation or cancel.is_set():
                    return
                self._ui_after(0, lambda: self.preview_status_var.set(f"▶ Previewing {label}…") if not self._destroyed and preview_generation == self._source_preview_generation else None)
                end_at = time.monotonic() + duration + 0.15
                while not cancel.is_set() and winsound is not None and time.monotonic() < end_at:
                    time.sleep(0.08)
            except Exception as exc:
                if not cancel.is_set(): self._ui_after(0, lambda msg=str(exc): cute_error("Source preview", msg, parent=parent))
            finally:
                if preview_generation == self._source_preview_generation:
                    with contextlib.suppress(Exception):
                        winsound.PlaySound(None, winsound.SND_PURGE) if winsound is not None else None
                    if getattr(self, "_source_preview_dir", None) == run_dir: self._source_preview_dir = None
                shutil.rmtree(run_dir, ignore_errors=True)
        self._source_preview_thread = threading.Thread(target=worker, daemon=True, name="SourceAudioPreview")
        self._source_preview_thread.start()

    def _preview_modified_selection(self, selection: Selection, parent=None, label: str = "Modified WEM",
                                    progress: Optional[ttk.Progressbar] = None,
                                    button: Optional[ttk.Button] = None) -> None:
        preview_thread = getattr(self, "_modified_preview_thread", None)
        if preview_thread is not None and preview_thread.is_alive():
            cute_warning("Preview already running", "A modified-WEM preview is already being prepared. Stop it before starting another.", parent=parent or self.root)
            return
        if not self.tools.vgmstream or not self.tools.ffmpeg or not self.tools.ffprobe:
            cute_error("Preview unavailable", "Modified WEM preview needs vgmstream, FFmpeg, and FFprobe.", parent=parent or self.root)
            return
        if winsound is None:
            cute_error("Preview unavailable", "This preview requires Windows Python with winsound support.", parent=parent or self.root)
            return

        self._stop_modified_wem_preview()
        self._modified_preview_generation += 1
        preview_generation = self._modified_preview_generation
        cancel_event = threading.Event()
        self._modified_preview_cancel = cancel_event
        status_target = parent or self.root
        self.preview_temp_root.mkdir(parents=True, exist_ok=True)
        self._modified_preview_progress = progress
        self._modified_preview_progress_button = button
        if progress is not None:
            try:
                progress.configure(mode="indeterminate")
                if not progress.winfo_ismapped():
                    progress.pack(side="right", padx=(6, 0))
                progress.start(12)
            except Exception:
                pass
        if button is not None:
            try:
                button.configure(state="disabled", text="⏳ Preparing…")
            except Exception:
                pass
        try:
            self.status_var.set(f"Preparing modified preview: {label}…")
        except Exception:
            pass

        def worker() -> None:
            run_dir: Optional[Path] = None
            try:
                run_dir = self.preview_temp_root / ("modified_" + timestamp() + "_" + uuid.uuid4().hex[:6])
                run_dir.mkdir(parents=True, exist_ok=True)
                source_work = run_dir / "source"
                audio_work = run_dir / "audio"
                wem_work = run_dir / "wem"
                source_work.mkdir(parents=True, exist_ok=True)
                audio_work.mkdir(parents=True, exist_ok=True)
                wem_work.mkdir(parents=True, exist_ok=True)
                preview_runner = Runner(self.log, self.bus, cancel_event=cancel_event)
                source_options = ProcessOptions(
                    short_source_policy=selection.short_source_policy or "loop",
                    duration_tolerance_ms=2.0,
                    conversion_preset="Vorbis Quality High",
                    backup_inputs=False,
                    verify_output=True,
                    game_audio_dir=Path(self.game_target_var.get()),
                    install_to_game=False,
                    playback_rate=float(selection.playback_rate or 1.0),
                    volume_db=float(selection.volume_db or 0.0),
                    fade_in_ms=int(selection.fade_in_ms or 0),
                    fade_out_ms=int(selection.fade_out_ms or 0),
                    normalize_loudness=bool(selection.normalize_loudness),
                    combine_original=bool(selection.combine_original),
                    overlay_gain_db=float(selection.overlay_gain_db or 0.0),
                    source_end_ms=selection.source_end_ms,
                    auto_match_duration=False if selection.auto_match_duration is None else bool(selection.auto_match_duration),
                )
                source_manager = SourceManager(self.tools, preview_runner, self.paths, self.log, source_options, fast_preview=True)
                raw_source = selection.source.strip().strip('"')
                if looks_like_url(raw_source):
                    source_path = selection.local_source_path or self._prefetched_source_for(raw_source, selection.wem.display_name)
                    if source_path is None:
                        raise RuntimeError("The URL source could not be prepared for preview.")
                    cache_key = hashlib.sha256(raw_source.encode("utf-8")).hexdigest()[:32]
                    self._modified_preview_source_cache[cache_key] = source_path
                else:
                    source_path = source_manager.materialize(raw_source, source_work / "download", selection.wem.display_name)
                if not Path(source_path).is_file():
                    raise FileNotFoundError(f"Preview source is unavailable: {source_path}")

                processor = AudioProcessor(self.tools, preview_runner, self.log, source_options)
                matched = processor.decode_and_match(source_path, selection.wem, audio_work, extra_offset_ms=float(selection.source_offset_ms or 0.0))
                preview_encoder = WwiseEncoder(self.tools, preview_runner, self.paths.root, self.log, source_options)
                encoded = preview_encoder.encode(matched, selection.wem.file_path.name, wem_work)
                decoded = run_dir / "preview.wav"
                result = preview_runner.run([self.tools.vgmstream, "-o", decoded, encoded], timeout=180, check=False)
                if result.returncode != 0 or not decoded.is_file() or decoded.stat().st_size < 44:
                    detail = (result.stderr or result.stdout or "unknown vgmstream error").strip()
                    raise RuntimeError(detail[-1500:])
                with wave.open(str(decoded), "rb") as wf:
                    duration = wf.getnframes() / float(max(1, wf.getframerate()))
                if cancel_event.is_set() or self._modified_preview_generation != preview_generation or self._destroyed:
                    raise PreviewCancelled("Preview stopped")
                self._modified_preview_temp_dir = run_dir
                self._modified_preview_wav = decoded
                try:
                    _ph_so = float(getattr(selection, "source_offset_ms", 0.0) or 0.0) / 1000.0
                except Exception:
                    _ph_so = 0.0
                try:
                    _ph_rate = float(getattr(selection, "playback_rate", 1.0) or 1.0)
                    if not math.isfinite(_ph_rate) or _ph_rate <= 0:
                        _ph_rate = 1.0
                except Exception:
                    _ph_rate = 1.0
                self._ui_after(0, lambda g=preview_generation, p=decoded, d=duration, l=label, s=_ph_so, r=_ph_rate: self._play_modified_wem_preview(p, d, l, s, r) if g == self._modified_preview_generation and not self._destroyed else None)
            except PreviewCancelled:
                if hasattr(self, "status_var") and not self._destroyed:
                    self._ui_after(0, lambda: self.status_var.set("Preview stopped"))
            except Exception as exc:
                if not cancel_event.is_set() and not self._destroyed:
                    self._ui_after(0, lambda msg=str(exc): cute_error("Modified preview failed", msg, parent=status_target))
                    self._ui_after(0, lambda: getattr(self, "status_var", None) is not None and self.status_var.set("Ready"))
            finally:
                def clear_indicator() -> None:
                    if self._modified_preview_progress is progress:
                        if progress is not None:
                            try:
                                progress.stop()
                                progress.pack_forget()
                            except Exception:
                                pass
                        if button is not None:
                            try:
                                button.configure(state="normal", text="▶  Preview modified WEM")
                            except Exception:
                                pass
                        self._modified_preview_progress = None
                        self._modified_preview_progress_button = None
                if not self._destroyed:
                    with contextlib.suppress(Exception):
                        self.root.after(0, clear_indicator)
                if run_dir is not None and run_dir != getattr(self, "_modified_preview_temp_dir", None):
                    with contextlib.suppress(OSError):
                        shutil.rmtree(run_dir, ignore_errors=True)

        self._modified_preview_thread = threading.Thread(target=worker, daemon=True, name="ModifiedWEMPreview")
        self._modified_preview_thread.start()

    def _play_modified_wem_preview(self, wav_path: Path, duration: float, label: str, source_offset_s: float = 0.0, playback_rate: float = 1.0) -> None:
        try:
            if winsound is not None:
                winsound.PlaySound(None, winsound.SND_PURGE)
            winsound.PlaySound(str(wav_path), winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT)
            self._modified_preview_playing = True
            try:
                self._trim_playhead = {"t0": time.monotonic(), "dur": float(duration or 0.0),
                                       "so": max(0.0, float(source_offset_s or 0.0)),
                                       "rate": float(playback_rate or 1.0) or 1.0}
            except Exception:
                self._trim_playhead = None
            try:
                _draw = getattr(self, "_trim_wave_redraw", None)
                if _draw is not None:
                    _draw()
            except Exception:
                pass
            try:
                self.root.after(50, lambda g=self._modified_preview_generation: self._trim_playhead_tick(g))
            except Exception:
                pass
            if hasattr(self, "status_var"):
                self.status_var.set(f"▶ Modified preview playing: {label}")
            self.root.after(max(100, int(max(0.1, duration) * 1000) + 150), self._finish_modified_wem_preview)
        except Exception as exc:
            cute_error("Modified preview failed", str(exc), parent=self.root)

    def _finish_modified_wem_preview(self) -> None:
        if not getattr(self, "_modified_preview_playing", False):
            return
        self._stop_modified_wem_preview()
        if hasattr(self, "status_var"):
            self.status_var.set("Ready")

    def _trim_playhead_tick(self, generation: int) -> None:
        if self._destroyed or generation != getattr(self, "_modified_preview_generation", -1):
            return
        ph = getattr(self, "_trim_playhead", None)
        if ph is None:
            return
        try:
            el = time.monotonic() - float(ph.get("t0", 0.0))
            dur = float(ph.get("dur", 0.0))
        except Exception:
            return
        if el > dur + 0.3:
            self._trim_playhead = None
            try:
                _draw = getattr(self, "_trim_wave_redraw", None)
                if _draw is not None:
                    _draw()
            except Exception:
                pass
            return
        try:
            _move = getattr(self, "_trim_playhead_move", None)
            if _move is not None and _move():
                pass
            else:
                _draw = getattr(self, "_trim_wave_redraw", None)
                if _draw is not None:
                    _draw()
        except Exception:
            pass
        try:
            self.root.after(50, lambda g=generation: self._trim_playhead_tick(g))
        except Exception:
            pass

    def _stop_modified_wem_preview(self, keep_temp: bool = False) -> None:
        cancel_event = getattr(self, "_modified_preview_cancel", None)
        if cancel_event is not None:
            cancel_event.set()
        self._modified_preview_cancel = None
        self._modified_preview_generation += 1
        try:
            if winsound is not None:
                winsound.PlaySound(None, winsound.SND_PURGE)
        except Exception:
            pass
        self._modified_preview_playing = False
        self._trim_playhead = None
        try:
            _draw = getattr(self, "_trim_wave_redraw", None)
            if _draw is not None:
                _draw()
        except Exception:
            pass
        progress = getattr(self, "_modified_preview_progress", None)
        if progress is not None:
            with contextlib.suppress(Exception):
                progress.stop()
                progress.pack_forget()
        button = getattr(self, "_modified_preview_progress_button", None)
        if button is not None:
            with contextlib.suppress(Exception):
                button.configure(state="normal", text="▶  Preview modified WEM")
        self._modified_preview_progress = None
        self._modified_preview_progress_button = None
        run_dir = getattr(self, "_modified_preview_temp_dir", None)
        self._modified_preview_wav = None
        self._modified_preview_temp_dir = None
        if run_dir is not None and not keep_temp:
            with contextlib.suppress(OSError):
                shutil.rmtree(run_dir, ignore_errors=True)

    def _close_replacement_dialog(self, win: tk.Toplevel) -> None:
        """Stop replacement previews and cancel any embedded playlist batch worker."""
        self._stop_modified_wem_preview()
        self._trim_wave_redraw = None
        self._close_playlist_download_progress()
        cancel_event = getattr(self, "_batch_mode_cancel", None)
        if cancel_event is not None:
            with contextlib.suppress(Exception):
                cancel_event.set()
        self._batch_mode_cancel = None
        self._batch_mode_window = None
        with contextlib.suppress(Exception):
            if win.winfo_exists():
                win.destroy()
        mode = getattr(self, "_replace_add_mode", None)
        if mode and mode.get("win") is win:
            self._exit_replace_add_mode()

    def _begin_replace_add_mode(self, win: tk.Toplevel, add, has=None) -> None:
        try:
            _zoomed = (win.state() == "zoomed")
        except Exception:
            _zoomed = False
        try:
            _geom = win.geometry()
        except Exception:
            _geom = ""
        self._replace_add_mode = {"win": win, "add": add, "has": has or (lambda _k: False),
                                  "zoomed": _zoomed, "geometry": _geom}
        btn = getattr(self, "process_button", None)
        try:
            btn.configure(text="Add +")
            btn.state(["!disabled"])
        except Exception:
            pass
        try:
            win.withdraw()
        except Exception:
            pass
        try:
            self.status_var.set("♡ Pick more sounds in the main list, then press Add +.")
        except Exception:
            pass
        try:
            self.root.lift()
        except Exception:
            pass

    def _show_add_win(self, win, saved=None) -> None:
        try:
            if win is None or not win.winfo_exists():
                return
        except Exception:
            return
        mode = saved if isinstance(saved, dict) else (getattr(self, "_replace_add_mode", None) or {})
        try:
            win.deiconify()
        except Exception:
            return
        def restore() -> None:
            try:
                if not win.winfo_exists():
                    return
                if mode.get("zoomed"):
                    with contextlib.suppress(Exception):
                        win.state("zoomed")
                elif mode.get("geometry"):
                    with contextlib.suppress(Exception):
                        win.geometry(mode["geometry"])
                win.lift()
                with contextlib.suppress(Exception):
                    win.focus_force()
            except Exception:
                pass
        try:
            win.after(60, restore)
        except Exception:
            restore()

    def _exit_replace_add_mode(self) -> None:
        mode = getattr(self, "_replace_add_mode", None)
        self._replace_add_mode = None
        if mode:
            self._show_add_win(mode.get("win"), mode)
        btn = getattr(self, "process_button", None)
        try:
            btn.configure(text="Replace this sound ♡")
        except Exception:
            pass
        try:
            self._refresh_process_button()
        except Exception:
            pass

    def _finish_replace_add_mode(self) -> None:
        mode = getattr(self, "_replace_add_mode", None)
        if not mode:
            return
        win = mode.get("win")
        add = mode.get("add")
        has = mode.get("has", lambda _k: False)
        try:
            win_ok = bool(win is not None and win.winfo_exists())
        except Exception:
            win_ok = False
        if not win_ok or add is None:
            self._exit_replace_add_mode()
            return
        picks = [i for i in self._selected_infos() if not has(i.key)]
        if not picks:
            self._exit_replace_add_mode()
            try:
                win.lift()
            except Exception:
                pass
            cute_info("Add sounds", "No new sounds picked — back to the replacement list.", parent=self.root)
            return
        self._exit_replace_add_mode()
        try:
            add(picks)
        except Exception as exc:
            cute_error("Add sounds", f"Could not add the picked sounds:\n{exc}", parent=self.root)
            return
        try:
            win.lift()
        except Exception:
            pass

    def _request_batch_playlist_shortage(
        self,
        available: int,
        required: int,
        playlist_title: str,
        can_add_playlist: bool = True,
    ) -> tuple[str, str]:
        """Prompt from a worker when the current playlist cannot fill the WEM queue."""
        result: dict[str, str] = {"action": "cancel", "url": ""}
        ready = threading.Event()
        box: dict[str, Any] = {"win": None}
        cancel_event = getattr(self, "_batch_mode_cancel", None)

        def close(action: str, url: str = "") -> None:
            result["action"] = action
            result["url"] = url
            win = box.get("win")
            if win is not None:
                with contextlib.suppress(Exception):
                    if win.winfo_exists():
                        win.grab_release()
                        win.destroy()
            ready.set()

        def show() -> None:
            if self._destroyed:
                ready.set()
                return
            parent = getattr(self, "_active_child", None)
            if parent is None or not parent.winfo_exists():
                parent = self.root
            win = tk.Toplevel(parent)
            box["win"] = win
            self._windowed_lightweight(win, "Playlist is shorter", 700, 350)
            try:
                win.transient(parent)
                win.grab_set()
            except Exception:
                pass
            body = ttk.Frame(win, padding=18)
            body.pack(fill="both", expand=True)
            ttk.Label(body, text="♡ Not enough unique songs", style="EditorTitle.TLabel").pack(anchor="w")
            ttk.Label(
                body,
                text=(
                    f"{playlist_title or 'This playlist'} currently provides {available} unique song(s), "
                    f"but {required} WEMs need assignments.\n\n"
                    "You can add another playlist to keep filling the queue, or reuse the current "
                    "playlist from the beginning. Reuse is the only option that allows a song to repeat."
                ),
                style="EditorSub.TLabel",
                wraplength=650,
                justify="left",
            ).pack(anchor="w", pady=(6, 14))

            entry_var = tk.StringVar()
            row = ttk.Frame(body)
            row.pack(fill="x")
            ttk.Label(row, text="Another playlist:", width=17, style="EditorField.TLabel").pack(side="left")
            entry = ttk.Entry(row, textvariable=entry_var)
            entry.pack(side="left", fill="x", expand=True, padx=(7, 0))
            ttk.Label(
                body,
                text="Songs already present in the queue are skipped automatically when another playlist is added.",
                style="EditorHint.TLabel",
                wraplength=650,
            ).pack(anchor="w", pady=(9, 0))

            footer = ttk.Frame(body)
            footer.pack(fill="x", side="bottom", pady=(18, 0))
            ttk.Button(footer, text="Cancel", style="Tool.TButton", command=lambda: close("cancel")).pack(side="right", padx=(7, 0))
            ttk.Button(footer, text="Reuse current playlist ♡", style="Tool.TButton", command=lambda: close("reuse")).pack(side="right", padx=(7, 0))

            def add() -> None:
                url = entry_var.get().strip().strip('"')
                try:
                    url = normalize_youtube_playlist_url(url)
                except ValueError as exc:
                    cute_warning("Playlist needed", str(exc), parent=win)
                    entry.focus_set()
                    return
                if not is_youtube_playlist_url(url):
                    cute_warning("Playlist needed", "Enter a valid YouTube playlist or Mix URL.", parent=win)
                    entry.focus_set()
                    return
                close("add", url)

            add_button = ttk.Button(footer, text="Add playlist ♡", style="Big.TButton", command=add)
            if can_add_playlist:
                add_button.pack(side="right")
            else:
                add_button.configure(state="disabled")
                add_button.pack(side="right")
            win.protocol("WM_DELETE_WINDOW", lambda: close("cancel"))
            win.bind("<Escape>", lambda _e: close("cancel"))
            win.bind("<Return>", lambda _e: add())
            entry.focus_set()
            self._raise_child(win)

        self._ui_after(0, show)
        while not ready.wait(0.15):
            if cancel_event is not None and cancel_event.is_set():
                self._ui_after(0, lambda: close("cancel"))
                break
        return result["action"], result["url"]

    def _request_playlist_download_failure_action(
        self,
        wem_label: str,
        failed_title: str,
        replacement_title: str,
    ) -> str:
        """Ask what to do with one failed playlist source without blocking Tk's main loop."""
        result: dict[str, str] = {"action": "skip"}
        ready = threading.Event()
        box: dict[str, Any] = {"win": None}
        cancel_event = getattr(self, "_batch_mode_cancel", None)

        def close(action: str) -> None:
            result["action"] = action
            win = box.get("win")
            if win is not None:
                with contextlib.suppress(Exception):
                    if win.winfo_exists():
                        win.grab_release()
                        win.destroy()
            ready.set()

        def show() -> None:
            if self._destroyed:
                ready.set()
                return
            parent = getattr(self, "_batch_mode_window", None)
            if parent is None or not parent.winfo_exists():
                parent = getattr(self, "_active_child", None)
            if parent is None or not parent.winfo_exists():
                parent = self.root

            win = tk.Toplevel(parent)
            box["win"] = win
            self._windowed_lightweight(win, "One playlist sound failed", 720, 340)
            try:
                win.transient(parent)
                win.grab_set()
            except Exception:
                pass

            body = ttk.Frame(win, padding=18)
            body.pack(fill="both", expand=True)

            ttk.Label(
                body,
                text="♡ One playlist sound could not be downloaded",
                style="EditorTitle.TLabel",
            ).pack(anchor="w")

            ttk.Label(
                body,
                text=(
                    f"Sound: {failed_title}\n"
                    f"Target: {wem_label}\n\n"
                    "The rest of the playlist can continue normally. "
                    f"The next working downloaded song is “{replacement_title}”."
                ),
                style="EditorSub.TLabel",
                wraplength=680,
                justify="left",
            ).pack(anchor="w", pady=(7, 10))

            ttk.Label(
                body,
                text=(
                    "Choose Switch sound to automatically use that working song for this WEM. "
                    "Choose Leave unchanged to skip this WEM and keep every other replacement moving."
                ),
                style="EditorHint.TLabel",
                wraplength=680,
                justify="left",
            ).pack(anchor="w", pady=(0, 14))

            footer = ttk.Frame(body)
            footer.pack(fill="x", side="bottom")

            ttk.Button(
                footer,
                text="Leave unchanged",
                style="Tool.TButton",
                command=lambda: close("skip"),
            ).pack(side="right", padx=(7, 0))

            ttk.Button(
                footer,
                text="Switch sound ♡",
                style="Big.TButton",
                command=lambda: close("replace"),
            ).pack(side="right")

            win.protocol("WM_DELETE_WINDOW", lambda: close("skip"))
            win.bind("<Escape>", lambda _e: close("skip"))
            win.bind("<Return>", lambda _e: close("replace"))
            self._raise_child(win)

        self._ui_after(0, show)
        while not ready.wait(0.15):
            if cancel_event is not None and cancel_event.is_set():
                self._ui_after(0, lambda: close("skip"))
                break
        return result["action"]

    def _finder_search_commands(self, query):
        exe = self.tools.yt_dlp
        base = [exe, "--ignore-config", "--no-playlist", "--flat-playlist", "--skip-download", "--no-warnings", "--socket-timeout", "10", "--retries", "1", "--fragment-retries", "0", "--extractor-retries", "1", "--print", "%(id)s\t%(title)s\t%(duration)s\t%(channel)s"]
        target = "ytsearch8:" + query
        return [base + [target], base + ["--extractor-args", "youtube:player_client=android_vr", target]]

    def _finder_download_commands(self, url, template):
        exe = self.tools.yt_dlp
        base = [exe, "--ignore-config", "--no-playlist", "-f", "bestaudio/best", "--no-part", "--newline", "--restrict-filenames", "--socket-timeout", "15", "--retries", "3", "--fragment-retries", "3", "--extractor-retries", "2", "-o", template]
        return [base + [url], base + ["--extractor-args", "youtube:player_client=mweb", url], base + ["--extractor-args", "youtube:player_client=web_embedded", url], base + ["--extractor-args", "youtube:player_client=android_vr", url]]

    def _finder_fmt_len(self, seconds):
        try:
            s = int(float(seconds))
        except Exception:
            return "?:??"
        if s < 0:
            return "?:??"
        return str(s // 60) + ":" + str(s % 60).zfill(2)

    def show_music_finder(self, parent, audio_var) -> None:
        if not getattr(self.tools, "yt_dlp", None):
            cute_warning("Find music", "Music search needs yt-dlp, which is missing. Open Tool Status from the More menu, download the missing tools, then try again.", parent=parent)
            return
        win = tk.Toplevel(parent or self.root)
        self._windowed_lightweight(win, "Find music", 680, 730)
        try:
            music_dir = self.paths.processed_audio / "found_music"
            music_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            cute_warning("Find music", "Could not create the download folder.", parent=win)
            return
        def _tint_row(f, bg):
            try:
                f.configure(bg=bg)
                for w in f.winfo_children():
                    _tint_row(w, bg)
            except Exception:
                pass

        C = self._theme_colors
        _accent = str(C.get("accent", "#c65d91"))
        _accent_hi = str(C.get("accent_active", _accent))
        _btn_txt = str(C.get("button_text", "#ffffff"))
        _fg = str(C.get("fg", "#432f39"))
        _field = str(C.get("field", "#fdf0f6"))
        _muted = str(C.get("muted", "#8c7d87"))
        _border = str(C.get("border", "#dfb3c7"))
        _sel = str(C.get("sel", "#efc7db"))
        _ok = str(C.get("status_success", "#2e8b57"))
        _warn = str(C.get("status_warning", "#b8860b"))
        _card = str(C.get("panel", _field))
        _card_dim = _muted
        _bar_track = _sel
        _bar_fill = _accent
        st = {"seq": 0, "results": [], "rows": [], "idx": None, "busy": False, "playing": False, "fetch_idx": None, "bar_mode": "idle", "bar_frac": 0, "spin_pos": 0, "preview_busy": False, "autouse": None}
        outer = ttk.Frame(win, padding=14)
        outer.pack(fill="both", expand=True)
        ttk.Label(outer, text="Find music", font=("Segoe UI", 16, "bold")).pack(anchor="w")
        ttk.Label(outer, text="Type any song - typos welcome - and YouTube figures it out.", font=("Segoe UI", 10)).pack(anchor="w", pady=(0, 8))
        player = tk.Frame(outer, bg=_card, padx=14, pady=12, highlightthickness=1, highlightbackground=_border)
        player.pack(fill="x", pady=(0, 10))
        tk.Label(player, text="🔍  FIND MUSIC · NOW FETCHING", font=("Segoe UI", 9, "bold"), bg=_card, fg=_card_dim).pack(anchor="w")
        now_title_var = tk.StringVar(value="Ready when you are")
        tk.Label(player, textvariable=now_title_var, font=("Segoe UI", 15, "bold"), bg=_card, fg=_fg, wraplength=600, justify="left").pack(anchor="w", pady=(2, 0))
        status_var = tk.StringVar(value="Type a song below and press Enter.")
        tk.Label(player, textvariable=status_var, font=("Segoe UI", 10), bg=_card, fg=_card_dim).pack(anchor="w")
        bar_row = tk.Frame(player, bg=_card)
        bar_row.pack(fill="x", pady=(8, 2))
        bar_cv = tk.Canvas(bar_row, height=12, bg=_card, highlightthickness=0, bd=0)
        bar_cv.pack(side="left", fill="x", expand=True, padx=(0, 8))
        pct_var = tk.StringVar(value="")
        tk.Label(bar_row, textvariable=pct_var, font=("Segoe UI", 10, "bold"), bg=_card, fg=_fg, width=5, anchor="e").pack(side="left")
        try:
            _pstyle = ttk.Style()
            _pstyle.configure("FinderRow.TButton", background=_accent, foreground=_btn_txt, borderwidth=1, bordercolor=_accent_hi, padding=(10, 3), font=("Segoe UI", 9, "bold"))
            _pstyle.map("FinderRow.TButton", background=[("active", _accent_hi), ("pressed", _accent_hi)])
        except Exception:
            pass
        search_row = ttk.Frame(outer)
        search_row.pack(fill="x")
        query_var = tk.StringVar()
        query_entry = ttk.Entry(search_row, textvariable=query_var)
        query_entry.pack(side="left", fill="x", expand=True, padx=(0, 8))
        search_btn = ttk.Button(search_row, text="Fetch", style="Action.TButton")
        search_btn.pack(side="left")
        ttk.Label(outer, text="UP NEXT", font=("Segoe UI", 9, "bold")).pack(anchor="w", pady=(8, 2))
        list_outer = tk.Frame(outer, bg=_field, highlightthickness=1, highlightbackground=_border)
        list_outer.pack(fill="both", expand=True)
        list_cv = tk.Canvas(list_outer, bg=_field, highlightthickness=0, bd=0)
        list_sb = ttk.Scrollbar(list_outer, orient="vertical", command=list_cv.yview)
        list_cv.configure(yscrollcommand=list_sb.set)
        list_cv.pack(side="left", fill="both", expand=True)
        list_sb.pack(side="right", fill="y")
        list_in = tk.Frame(list_cv, bg=_field)
        list_win = list_cv.create_window((0, 0), window=list_in, anchor="nw")

        def _sync_list(_e=None):
            try:
                list_cv.configure(scrollregion=list_cv.bbox("all"))
                list_cv.itemconfigure(list_win, width=list_cv.winfo_width())
            except Exception:
                pass

        list_in.bind("<Configure>", _sync_list)
        list_cv.bind("<Configure>", _sync_list)
        ttk.Label(outer, text="Top match fetches itself — click ▶ to preview a row, Use ♡ to take it, double-click works too.", font=("Segoe UI", 9)).pack(anchor="w", pady=(4, 0))

        def alive():
            try:
                return win.winfo_exists()
            except Exception:
                return False

        def bar_draw(frac=None, slide=None):
            if not alive():
                return
            try:
                W = max(60, int(bar_cv.winfo_width()))
                H = 12
                bar_cv.delete("all")
                bar_cv.create_rectangle(0, 0, W, H, fill=_bar_track, outline="")
                if frac is not None:
                    w = max(0.0, min(1.0, frac)) * W
                    if w >= 1:
                        bar_cv.create_rectangle(0, 0, w, H, fill=_bar_fill, outline="")
                elif slide is not None:
                    bw = 70
                    x = slide % (W + bw) - bw
                    bar_cv.create_rectangle(x, 0, x + bw, H, fill=_bar_fill, outline="")
            except Exception:
                pass

        def bar_idle():
            st["bar_mode"] = "idle"
            st["bar_frac"] = 0
            if alive():
                bar_draw(0)
                pct_var.set("")

        def bar_spin():
            if not alive():
                return
            st["bar_mode"] = "spin"

            def _tick():
                if not alive() or st.get("bar_mode") != "spin":
                    return
                st["spin_pos"] = st.get("spin_pos", 0) + 10
                bar_draw(None, st["spin_pos"])
                self.root.after(60, _tick)

            _tick()

        def bar_set(v):
            if not alive():
                return
            st["bar_mode"] = "set"
            st["bar_frac"] = v / 100.0
            bar_draw(st["bar_frac"])
            pct_var.set(str(int(v)) + "%")

        def redraw_bar():
            if st.get("bar_mode") == "spin":
                bar_draw(None, st.get("spin_pos", 0))
            else:
                bar_draw(st.get("bar_frac", 0))

        bar_row.bind("<Configure>", lambda _e: redraw_bar())

        def set_status(text):
            if alive():
                status_var.set(text)

        def paint_sel():
            for i, w in enumerate(st["rows"]):
                try:
                    if st["idx"] == i:
                        w["frame"].configure(highlightthickness=2, highlightbackground=_accent)
                    else:
                        w["frame"].configure(highlightthickness=1, highlightbackground=_border)
                except Exception:
                    pass

        def see_row(i):
            try:
                list_in.update_idletasks()
                total = max(1, list_in.winfo_height())
                view = max(1, list_cv.winfo_height())
                top = max(0.0, min(1.0, (st["rows"][i]["frame"].winfo_y() - view / 2) / total))
                list_cv.yview_moveto(top)
            except Exception:
                pass

        def paint_rows():
            if not alive():
                return
            for i, w in enumerate(st["rows"]):
                try:
                    if st["playing"] and st["idx"] == i:
                        g, s, c = "⏸", "playing", _accent
                    elif st.get("fetch_idx") == i:
                        g, s, c = "⏳", "fetching…", _warn
                    elif st["results"][i].get("file"):
                        g, s, c = "▶", "ready ✓", _ok
                    else:
                        g, s, c = "·", "", _muted
                    w["play"].configure(text=g)
                    w["status"].configure(text=s, foreground=c)
                    if st["results"][i].get("file"):
                        if not w.get("showed"):
                            w["use"].pack(anchor="e", pady=(4, 0))
                            w["showed"] = True
                    elif w.get("showed"):
                        w["use"].pack_forget()
                        w["showed"] = False
                except Exception:
                    pass

        def build_rows():
            for child in list_in.winfo_children():
                try:
                    child.destroy()
                except Exception:
                    pass
            st["rows"] = []
            if not st["results"]:
                try:
                    tk.Label(list_in, text="🔍 Nothing here yet — search above and results land here.", font=("Segoe UI", 10), bg=_field, fg=_muted, pady=60).pack()
                except Exception:
                    pass
                _sync_list()
                return
            for i, r in enumerate(st["results"]):
                row = tk.Frame(list_in, bg=_field, highlightthickness=1, highlightbackground=_border, padx=6, pady=4)
                row.pack(fill="x", padx=8, pady=4)
                play = tk.Button(row, text="·", font=("Segoe UI", 11), width=3, relief="flat", bd=0, bg=_field, fg=_fg, activebackground=_sel, cursor="hand2", command=lambda i=i: click_play_btn(i))
                play.pack(side="left", padx=(0, 6))
                mid = tk.Frame(row, bg=_field)
                mid.pack(side="left", fill="x", expand=True)
                title_l = tk.Label(mid, text=r["title"], font=("Segoe UI", 11, "bold"), bg=_field, fg=_fg, anchor="w", justify="left", wraplength=430)
                title_l.pack(anchor="w", fill="x")
                ch_l = tk.Label(mid, text=str(r.get("channel") or ""), font=("Segoe UI", 9), bg=_field, fg=_muted, anchor="w")
                ch_l.pack(anchor="w")
                right = tk.Frame(row, bg=_field)
                right.pack(side="right", padx=(6, 0))
                status_l = tk.Label(right, text="", font=("Segoe UI", 10, "bold"), bg=_field, fg=_ok)
                status_l.pack(anchor="e")
                len_l = tk.Label(right, text=self._finder_fmt_len(r["dur"]), font=("Segoe UI", 10), bg=_field, fg=_muted)
                len_l.pack(anchor="e")
                use_b = ttk.Button(right, text="Use ♡", style="FinderRow.TButton", command=lambda i=i: use_row(i))
                st["rows"].append({"frame": row, "play": play, "title": title_l, "status": status_l, "use": use_b, "showed": False})
                for widget in (row, mid, title_l, ch_l, right, status_l, len_l):
                    widget.bind("<Button-1>", lambda e, i=i: pick_row(i))
                    widget.bind("<Double-1>", lambda e, i=i: dbl_row(i))
                row.bind("<Enter>", lambda e, f=row: _tint_row(f, _sel))
                row.bind("<Leave>", lambda e, f=row: _tint_row(f, _field))
            _sync_list()

        def fill_results(seq, rows):
            if not alive() or seq != st["seq"]:
                return
            st["busy"] = False
            bar_idle()
            st["results"] = rows
            st["idx"] = None
            st["autouse"] = None
            search_btn.configure(state="normal", text="Fetch")
            if not rows:
                build_rows()
                set_status("No matches - try fewer words or check the spelling a little.")
                now_title_var.set("No matches")
                return
            for r in rows:
                r["label"] = r["title"]
            build_rows()
            paint_rows()
            now_title_var.set(rows[0]["title"])
            set_status(str(len(rows)) + " found - fetching the top match…")
            pick_row(0)

        def run_search():
            query = query_var.get().strip()
            if not query or st["busy"]:
                return
            st["seq"] += 1
            seq = st["seq"]
            st["busy"] = True
            st["fetch_idx"] = None
            st["autouse"] = None
            search_btn.configure(state="disabled", text="Searching…")
            for child in list_in.winfo_children():
                try:
                    child.destroy()
                except Exception:
                    pass
            st["rows"] = []
            st["idx"] = None
            set_status("Searching YouTube for " + query + "…")
            bar_spin()

            def worker():
                rows = []
                try:
                    for cmd in self._finder_search_commands(query):
                        try:
                            res = self.runner.run(cmd, timeout=60, check=False)
                        except Exception:
                            continue
                        for line in (res.stdout or "").splitlines():
                            parts = line.split("\t")
                            if len(parts) < 2:
                                continue
                            vid = parts[0].strip()
                            if not vid or len(vid) > 16:
                                continue
                            rows.append({"id": vid, "title": parts[1].strip() or vid, "dur": parts[2].strip() if len(parts) > 2 else "", "channel": parts[3].strip() if len(parts) > 3 else "", "file": None, "wav": None})
                            if len(rows) >= 8:
                                break
                        if rows:
                            break
                except Exception:
                    rows = []
                self.root.after(0, lambda: fill_results(seq, rows))

            threading.Thread(target=worker, daemon=True).start()

        def downloaded_file(vid):
            for ext in ("m4a", "webm", "opus", "mp3", "mp4", "aac", "wav", "flac", "ogg"):
                p = music_dir / (vid + "." + ext)
                if p.is_file() and p.stat().st_size > 4096:
                    return p
            return None

        def stop_sound():
            st["playing"] = False
            try:
                if winsound is not None:
                    winsound.PlaySound(None, winsound.SND_PURGE)
            except Exception:
                pass
            if alive():
                paint_rows()

        def mark_row(i, tag=None):
            try:
                paint_rows()
            except Exception:
                pass

        def finish_fetch(seq, idx, path):
            if not alive() or seq != st["seq"]:
                return
            st["busy"] = False
            bar_idle()
            if path is None:
                st["fetch_idx"] = None
                mark_row(idx, "")
                set_status("That one would not download - try another result.")
                search_btn.configure(state="normal", text="Fetch")
                return
            st["results"][idx]["file"] = str(path)
            st["fetch_idx"] = None
            now_title_var.set(st["results"][idx]["title"])
            mark_row(idx, "  ✓ ready")
            set_status("Ready: " + st["results"][idx]["title"])
            search_btn.configure(state="normal", text="Fetch")
            if st.get("autouse") == idx:
                st["autouse"] = None
                st["idx"] = idx
                paint_sel()
                see_row(idx)
                use_selected()

        def fetch_selected(idx):
            r = st["results"][idx]
            if r.get("file"):
                now_title_var.set(r["title"])
                paint_rows()
                set_status("Ready: " + r["title"])
                return
            st["seq"] += 1
            seq = st["seq"]
            st["busy"] = True
            search_btn.configure(state="disabled", text="Fetching…")
            st["fetch_idx"] = idx
            now_title_var.set(r["title"])
            mark_row(idx, "  ⏳ fetching…")
            set_status("Fetching audio: " + r["title"] + "… 0%")
            bar_set(0)

            def worker():
                path = downloaded_file(r["id"])
                if path is None:
                    url = "https://www.youtube.com/watch?v=" + r["id"]
                    template = music_dir / (r["id"] + ".%(ext)s")
                    last_pct = [0]

                    def on_line(_kind, line):
                        found = re.search(r"(\d+(?:\.\d+)?)%", line or "")
                        if not found:
                            return
                        v = int(float(found.group(1)))
                        if v != last_pct[0]:
                            last_pct[0] = v
                            self.root.after(0, lambda vv=v: (bar_set(vv), set_status("Fetching audio: " + r["title"] + " … " + str(vv) + "%")))

                    for cmd in self._finder_download_commands(url, template):
                        try:
                            self.runner.run(cmd, timeout=300, check=False, output_callback=on_line)
                        except Exception:
                            pass
                        path = downloaded_file(r["id"])
                        if path is not None:
                            break
                self.root.after(0, lambda: finish_fetch(seq, idx, path))

            threading.Thread(target=worker, daemon=True).start()

        def pick_row(i):
            if not alive() or st["busy"]:
                return
            if i < 0 or i >= len(st["results"]):
                return
            stop_sound()
            st["idx"] = i
            paint_sel()
            see_row(i)
            fetch_selected(i)

        def start_play(idx, was_playing):
            if not alive() or idx < 0 or idx >= len(st["results"]):
                return
            if was_playing:
                return
            r = st["results"][idx]
            if not r.get("file") or st["busy"]:
                return
            if st["playing"]:
                stop_sound()
            st["idx"] = idx
            paint_sel()
            toggle_preview()

        def click_play_btn(i):
            if not alive() or i < 0 or i >= len(st["results"]):
                return
            was = bool(st["playing"] and st["idx"] == i)
            st["idx"] = i
            paint_sel()
            see_row(i)
            if not st["busy"]:
                stop_sound()
                fetch_selected(i)
            if st["results"][i].get("file"):
                self.root.after(0, lambda i=i, w=was: start_play(i, w))

        def dbl_row(i):
            if not alive() or i < 0 or i >= len(st["results"]):
                return
            st["idx"] = i
            paint_sel()
            see_row(i)
            if st["results"][i].get("file"):
                stop_sound()
                use_selected()
            else:
                st["autouse"] = i
                if not st["busy"]:
                    stop_sound()
                    fetch_selected(i)

        def use_row(i):
            if not alive() or i < 0 or i >= len(st["results"]):
                return
            if not st["results"][i].get("file"):
                return
            st["idx"] = i
            paint_sel()
            see_row(i)
            stop_sound()
            use_selected()

        def toggle_preview():
            if st["idx"] is None:
                return
            if st["playing"]:
                stop_sound()
                set_status("Ready: " + st["results"][st["idx"]]["title"])
                return
            r = st["results"][st["idx"]]
            src = r.get("file")
            if not src:
                return
            if not getattr(self.tools, "ffmpeg", None):
                set_status("Preview needs ffmpeg, which is missing - but Use as replacement still works.")
                return
            if st.get("preview_busy"):
                return
            st["preview_busy"] = True
            set_status("Preparing preview…")
            bar_spin()

            def worker():
                wav = music_dir / (r["id"] + "_preview.wav")
                ok = True
                if not (wav.is_file() and wav.stat().st_size > 4096):
                    try:
                        res = self.runner.run([self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", src, "-vn", "-c:a", "pcm_s16le", wav], timeout=180, check=False)
                        ok = res.returncode == 0 and wav.is_file()
                    except Exception:
                        ok = False
                def done():
                    if not alive():
                        return
                    st["preview_busy"] = False
                    bar_idle()
                    if not ok:
                        set_status("Preview failed - but Use as replacement still works.")
                        return
                    r["wav"] = str(wav)
                    try:
                        winsound.PlaySound(str(wav), winsound.SND_FILENAME | winsound.SND_NODEFAULT | winsound.SND_ASYNC)
                        st["playing"] = True
                        set_status("Playing: " + r["title"])
                        paint_rows()
                    except Exception:
                        set_status("Preview failed - but Use as replacement still works.")
                self.root.after(0, done)

            threading.Thread(target=worker, daemon=True).start()

        def place_pick(pick, drop):
            if drop and drop != pick:
                with contextlib.suppress(OSError):
                    Path(drop).unlink()
            try:
                audio_var.set(pick)
            except Exception:
                return
            st["picked"] = pick
            stop_sound()
            try:
                win.destroy()
            except Exception:
                pass

        def ensure_wav_then(r, after):
            wav = r.get("wav")
            if wav and Path(wav).is_file():
                after(wav)
                return
            if not getattr(self.tools, "ffmpeg", None):
                after(None)
                return
            set_status("Converting for the game…")
            bar_spin()

            def worker():
                out = music_dir / (r["id"] + "_preview.wav")
                ok = False
                try:
                    res = self.runner.run([self.tools.ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", r["file"], "-vn", "-c:a", "pcm_s16le", out], timeout=180, check=False)
                    ok = res.returncode == 0 and out.is_file()
                except Exception:
                    ok = False
                self.root.after(0, lambda: (bar_idle(), after(str(out) if ok else None)))

            threading.Thread(target=worker, daemon=True).start()

        def use_selected():
            if st["idx"] is None or st["busy"]:
                return
            r = st["results"][st["idx"]]
            src = r.get("file")
            if not src:
                return
            ext = os.path.splitext(src)[1].lower().lstrip(".")
            if ext in ("wav", "mp3", "flac", "ogg", "m4a", "aac", "opus"):
                place_pick(src, r.get("wav"))
                return
            st["busy"] = True

            def after(wav):
                st["busy"] = False
                if not alive():
                    return
                if not wav:
                    set_status("That format would not convert - try another result.")
                    return
                place_pick(wav, src)

            ensure_wav_then(r, after)

        build_rows()
        search_btn.configure(command=run_search)
        query_entry.bind("<Return>", lambda _e: run_search())
        def close_finder():
            stop_sound()
            keep = st.get("picked")
            for r in st["results"]:
                for key in ("file", "wav"):
                    p = r.get(key)
                    if p and p != keep:
                        with contextlib.suppress(OSError):
                            Path(p).unlink()
            try:
                win.destroy()
            except Exception:
                pass

        win.protocol("WM_DELETE_WINDOW", close_finder)
        query_entry.focus_set()

    def quick_replace(self) -> None:
        if getattr(self, "_replace_add_mode", None):
            self._finish_replace_add_mode()
            return
        # Leaving the main replacement flow should never leave the normal preview playing.
        self.stop_preview()
        selected = self._selected_infos()
        if not selected:
            cute_warning("Replace Sound", "Select one or more sounds first.")
            return

        # Map Mode is available for any two-sound group you create manually.
        # Select two sounds, press + New group, Bind them, then enable Map Mode.
        auto_map_pair = False

        # One editor for every selection size. The group editor scales down to a
        # single sound cleanly and keeps the whole app consistent.
        self.stop_preview()
        win = tk.Toplevel(self.root)
        self._group_replacement_dialog(win, "Replace Sounds")
        win.protocol("WM_DELETE_WINDOW", lambda w=win: self._close_replacement_dialog(w))

        shell = ttk.Frame(win)
        shell.pack(fill="both", expand=True)
        canvas = tk.Canvas(shell, highlightthickness=0, bd=0, bg=self._theme_colors.get("canvas", "#fff7fb"))
        scroll = ttk.Scrollbar(shell, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        body = ttk.Frame(canvas, padding=14)
        body_window = canvas.create_window((0, 0), window=body, anchor="nw")

        def _sync_group_scroll(_event=None) -> None:
            canvas.update_idletasks()
            viewport_w = max(1, int(canvas.winfo_width() or 1))
            viewport_h = max(1, int(canvas.winfo_height() or 1))
            req_h = max(body.winfo_reqheight(), viewport_h)
            # Keep the outer editor body locked to the visible viewport width.
            # The sound table owns its own horizontal scrollbar, so wide table
            # columns must never push the right-side editor panel off-screen.
            canvas.configure(scrollregion=(0, 0, viewport_w, req_h))
            canvas.itemconfigure(body_window, width=viewport_w, height=req_h)

        body.bind("<Configure>", _sync_group_scroll, add="+")
        canvas.bind("<Configure>", _sync_group_scroll, add="+")
        canvas.bind("<MouseWheel>", lambda e: (canvas.yview_scroll(int(-e.delta / 120), "units"), "break")[1])
        canvas.bind("<Button-4>", lambda e: (canvas.yview_scroll(-3, "units"), "break")[1])
        canvas.bind("<Button-5>", lambda e: (canvas.yview_scroll(3, "units"), "break")[1])
        win.after_idle(_sync_group_scroll)
        def _fit_replace_window():
            try:
                if not win.winfo_exists():
                    return
                win.update_idletasks()
                sw = max(800, int(win.winfo_screenwidth() or 1280))
                sh = max(600, int(win.winfo_screenheight() or 800))
                rw, rh = int(win.winfo_reqwidth()), int(win.winfo_reqheight())
                w = max(720, min(rw, sw - 40))
                h = max(480, min(rh, sh - 80))
                x = max(0, (sw - w) // 2)
                y = max(0, (sh - h) // 2)
                win.geometry(f"{w}x{h}+{x}+{y}")
                win.minsize(720, 480)
            except Exception:
                pass
        win.after_idle(_fit_replace_window)

        ttk.Label(body, text="♡ Replace these sounds", style="EditorTitle.TLabel").pack(anchor="w")
        subtitle_var = tk.StringVar(value=(
            f"{len(selected)} sound(s) ready. Give each its own audio below — "
            "or create a group with + New group for sounds that should share the same replacement."
        ))
        ttk.Label(body, textvariable=subtitle_var, style="EditorSub.TLabel").pack(anchor="w", pady=(4, 10))

        groups: list[str] = []
        initial_source = self.pending_source
        self.pending_source = ""
        # One playlist batch implementation lives inside the replacement editor. The older
        # "Use playlist as bulk source" path is intentionally gone; this block uses the same
        # assignment table + shortage handling + bulk yt-dlp queue as the former standalone mode.
        playlist_batch_mode_var = tk.BooleanVar(value=is_youtube_playlist_url(initial_source))
        playlist_source_var = tk.StringVar(value=initial_source if is_youtube_playlist_url(initial_source) else "")
        playlist_title_var = tk.StringVar(value="No playlist loaded yet")
        playlist_batch_status_var = tk.StringVar(
            value=("Playlist detected — press Load & assign ♡ to map songs to the selected WEMs."
                   if is_youtube_playlist_url(initial_source)
                   else "Optional: use a YouTube playlist to assign one song to each selected WEM.")
        )

        playlist_batch_state: dict[str, Any] = {
            "loading": False,
            "ready": False,
            "url": "",
            "title": "",
            "tracks": [],
            "chain": [],
            "reuse": False,
            "generation": 0,
            "cancel": threading.Event(),
        }
        self._batch_mode_cancel = playlist_batch_state["cancel"]
        self._batch_mode_window = win

        # Compact batch source bar: playlist assignment uses the normal replacement
        # table and the normal per-sound editor below. There is deliberately no second
        # assignment table and no second set of audio controls.
        playlist_batch_mode_var = tk.BooleanVar(value=is_youtube_playlist_url(initial_source))
        playlist_source_var = tk.StringVar(value=initial_source if is_youtube_playlist_url(initial_source) else "")
        playlist_title_var = tk.StringVar(value="No playlist loaded yet")
        playlist_batch_status_var = tk.StringVar(
            value=(
                "Playlist detected — load it to assign one song to each selected WEM."
                if is_youtube_playlist_url(initial_source)
                else "Optional: load a YouTube playlist to assign one song to each selected WEM."
            )
        )

        playlist_batch_state: dict[str, Any] = {
            "loading": False,
            "ready": False,
            "url": "",
            "title": "",
            "tracks": [],
            "chain": [],
            "reuse": False,
            "generation": 0,
            "cancel": threading.Event(),
        }
        playlist_track_by_key: dict[str, PlaylistTrack] = {}
        playlist_display_name_by_key: dict[str, str] = {}
        self._batch_mode_cancel = playlist_batch_state["cancel"]
        self._batch_mode_window = win

        playlist_box = ttk.LabelFrame(
            body,
            text="♡ Playlist batch source",
            style="Editor.TLabelframe",
            padding=8,
        )
        playlist_box.pack(fill="x", pady=(0, 10))

        playlist_top = ttk.Frame(playlist_box)
        playlist_top.pack(fill="x")
        playlist_mode_check = ttk.Checkbutton(
            playlist_top,
            text="Use playlist batch mode",
            variable=playlist_batch_mode_var,
        )
        playlist_mode_check.pack(side="left")
        playlist_entry = ttk.Entry(playlist_top, textvariable=playlist_source_var)
        playlist_entry.pack(side="left", fill="x", expand=True, padx=(10, 7))
        load_playlist_btn = ttk.Button(playlist_top, text="Load & assign ♡", style="Action.TButton")
        load_playlist_btn.pack(side="right")

        playlist_status_row = ttk.Frame(playlist_box)
        playlist_status_row.pack(fill="x", pady=(6, 0))
        ttk.Label(
            playlist_status_row,
            textvariable=playlist_title_var,
            style="EditorHint.TLabel",
        ).pack(side="left")
        ttk.Label(
            playlist_status_row,
            text="  •  ",
            style="EditorHint.TLabel",
        ).pack(side="left")
        ttk.Label(
            playlist_status_row,
            textvariable=playlist_batch_status_var,
            style="EditorHint.TLabel",
            wraplength=900,
        ).pack(side="left", fill="x", expand=True)

        def set_batch_status(message: str) -> None:
            with contextlib.suppress(Exception):
                if win.winfo_exists():
                    playlist_batch_status_var.set(message)

        def _widget_alive(widget: Any) -> bool:
            try:
                return bool(widget is not None and widget.winfo_exists())
            except Exception:
                return False

        def _safe_widget_configure(widget: Any, **kwargs: Any) -> None:
            if _widget_alive(widget):
                with contextlib.suppress(tk.TclError, RuntimeError):
                    widget.configure(**kwargs)

        def clear_playlist_assignment_display(message: Optional[str] = None) -> None:
            playlist_track_by_key.clear()
            playlist_display_name_by_key.clear()
            if message:
                set_batch_status(message)

        def render_playlist_assignments(tracks: list[PlaylistTrack], reuse: bool) -> None:
            if not tracks:
                return
            # Batch assignment intentionally works at the WEM level: each selected WEM
            # gets its own playlist song, so any previous manual groups are unbound.
            playlist_track_by_key.clear()
            playlist_display_name_by_key.clear()
            for index, info in enumerate(selected):
                track = tracks[index % len(tracks)] if reuse else tracks[index]
                assignments[info.key] = "Separate"
                playlist_track_by_key[info.key] = track
                playlist_display_name_by_key[info.key] = track.title or track.video_id or "Untitled"

            mode_text = (
                "reusing the playlist from the beginning"
                if reuse
                else "using unique songs only"
            )
            playlist_title_var.set(
                f"Playlist: {playlist_batch_state.get('title') or playlist_batch_state.get('url') or 'Loaded'}"
            )
            set_batch_status(
                f"✓ {len(selected)} WEMs assigned — {mode_text}. "
                "Use the normal sound settings on the right; playlist audio is downloaded when you apply."
            )
            # Refresh the original replacement table so the playlist song appears directly
            # in its normal Replacement audio column.
            build_assignment_tree(select_keys={info.key for info in selected})

        def load_playlist_batch() -> None:
            if playlist_batch_state["loading"]:
                return
            raw = playlist_source_var.get().strip().strip('"')
            try:
                raw = normalize_youtube_playlist_url(raw)
                playlist_source_var.set(raw)
            except ValueError as exc:
                cute_warning("Playlist needed", str(exc), parent=win)
                playlist_entry.focus_set()
                return
            if not is_youtube_playlist_url(raw):
                cute_warning(
                    "Playlist needed",
                    "Paste a valid YouTube playlist or YouTube Mix URL containing a list= ID.",
                    parent=win,
                )
                playlist_entry.focus_set()
                return

            playlist_batch_state["generation"] += 1
            generation = playlist_batch_state["generation"]
            playlist_batch_state["loading"] = True
            playlist_batch_state["ready"] = False
            playlist_batch_state["reuse"] = False
            playlist_batch_state["tracks"] = []
            playlist_batch_state["chain"] = []
            playlist_batch_state["cancel"].clear()
            self._batch_mode_cancel = playlist_batch_state["cancel"]
            clear_playlist_assignment_display()
            _safe_widget_configure(load_playlist_btn, state="disabled", text="Loading…")
            _safe_widget_configure(finish_btn, state="disabled")
            set_batch_status("✿ Getting songs for the WEM assignments…")

            def worker() -> None:
                try:
                    options = ProcessOptions(
                        install_to_game=False,
                        download_timeout=20.0,
                        download_workers=max(1, len(selected)),
                    )
                    manager = SourceManager(
                        self.tools,
                        Runner(self.log, self.bus, cancel_event=playlist_batch_state["cancel"]),
                        self.paths,
                        self.log,
                        options,
                        fast_preview=True,
                    )
                    required = len(selected)
                    # Batch assignment is intentionally UNIQUE by actual video/source identity.
                    # A playlist can contain duplicate occurrences of the same YouTube video;
                    # those occurrences must not consume one of the user's requested unique songs.
                    used_sources: set[str] = set()
                    chain = [raw]
                    collected: list[PlaylistTrack] = []
                    current_title = ""
                    next_url = raw
                    # Ask for a small safety margin so duplicate playlist occurrences do not
                    # immediately turn 108 requested songs into 90 assignments. If that still
                    # is not enough, the probe grows and resumes farther into the playlist.
                    probe_limit = max(required, required + 24)

                    while len(collected) < required:
                        if playlist_batch_state["cancel"].is_set():
                            raise ProcessingCancelled("Playlist batch cancelled")
                        needed_now = required - len(collected)
                        request_limit = max(1, probe_limit if next_url == raw else needed_now)
                        self._ui_after(
                            0,
                            lambda n=needed_now, q=request_limit: set_batch_status(
                                f"✿ Loading {n} more unique playlist song(s) (checking {q} entries)… ♫"
                            ),
                        )
                        title, tracks = manager.playlist_entries_limited(
                            next_url, request_limit, allow_partial=True
                        )
                        current_title = title or current_title
                        added_here = 0
                        for track in tracks:
                            source_key = manager._playlist_source_key(track)
                            if not source_key or source_key in used_sources:
                                continue
                            used_sources.add(source_key)
                            collected.append(track)
                            added_here += 1
                            if len(collected) >= required:
                                break

                        with self._playlist_batch_metadata_lock:
                            self._playlist_batch_metadata[next_url] = (
                                len(tracks), title, list(tracks)
                            )
                            self._playlist_batch_chains[raw] = list(chain)

                        if len(collected) >= required:
                            break

                        # If the current probe returned its full requested range, the playlist
                        # may contain duplicate occurrences. Expand the scan instead of asking
                        # the user to reuse those songs. This is what prevents 108 -> 90 reuse.
                        if next_url == raw and len(tracks) >= request_limit:
                            probe_limit += max(24, required // 4)
                            continue

                        if not added_here and not collected:
                            raise RuntimeError("The YouTube playlist returned no usable songs.")

                        action, extra_url = self._request_batch_playlist_shortage(
                            len(collected),
                            required, current_title or next_url, can_add_playlist=True,
                        )
                        if action == "reuse":
                            playlist_batch_state["reuse"] = True
                            break
                        if action != "add" or not extra_url:
                            raise ProcessingCancelled(
                                "Playlist batch cancelled while choosing another playlist."
                            )
                        normalized_extra = normalize_youtube_playlist_url(extra_url)
                        existing_ids = {self._playlist_id(x) for x in chain if self._playlist_id(x)}
                        if self._playlist_id(normalized_extra) in existing_ids:
                            raise RuntimeError("That playlist has already been used in this batch.")
                        next_url = normalized_extra
                        chain.append(next_url)
                        # The additional playlist is scanned from its beginning, but still only
                        # contributes source IDs that have not already been assigned.
                        probe_limit = max(required - len(collected), 24)
                        self._ui_after(
                            0,
                            lambda: set_batch_status(
                                "✿ Loading the additional playlist in one pass… ♫"
                            ),
                        )

                    def apply_loaded() -> None:
                        if (
                            playlist_batch_state["generation"] != generation
                            or not _widget_alive(win)
                        ):
                            return
                        playlist_batch_state["loading"] = False
                        playlist_batch_state["ready"] = bool(collected)
                        playlist_batch_state["url"] = raw
                        playlist_batch_state["title"] = current_title
                        playlist_batch_state["tracks"] = list(collected)
                        playlist_batch_state["chain"] = list(chain)
                        render_playlist_assignments(
                            list(collected), bool(playlist_batch_state["reuse"])
                        )
                        _safe_widget_configure(
                            load_playlist_btn,
                            state="normal",
                            text="Reload playlist ♡",
                        )
                        if playlist_batch_state["ready"]:
                            _safe_widget_configure(
                                finish_btn,
                                state="normal",
                                text="Apply to Brawlhalla ♡",
                            )

                    self._ui_after(0, apply_loaded)
                except ProcessingCancelled:
                    playlist_batch_state["loading"] = False
                    self._ui_after(0, lambda: set_batch_status("♡ Playlist batch cancelled."))
                    self._ui_after(
                        0,
                        lambda: _safe_widget_configure(
                            load_playlist_btn, state="normal", text="Load & assign ♡"
                        ),
                    )
                    self._ui_after(
                        0,
                        lambda: _safe_widget_configure(
                            finish_btn,
                            state="normal" if not playlist_batch_mode_var.get() else "disabled",
                        ),
                    )
                except Exception as exc:
                    playlist_batch_state["loading"] = False
                    self.log.error("Replacement-window batch playlist load failed: %s", exc)

                    def failed(e=exc) -> None:
                        _safe_widget_configure(
                            load_playlist_btn, state="normal", text="Load & assign ♡"
                        )
                        _safe_widget_configure(finish_btn, state="disabled")
                        set_batch_status("♡ Could not load that playlist.")
                        if _widget_alive(win):
                            self._friendly_error(
                                e, title="Could not load playlist songs", parent=win
                            )

                    self._ui_after(0, failed)

            threading.Thread(
                target=worker,
                daemon=True,
                name="ReplacementBatchPlaylistCheck",
            ).start()

        def apply_playlist_batch() -> None:
            """Download the assigned playlist songs, then let the normal editor apply settings."""
            if playlist_batch_state["loading"] or not playlist_batch_state["ready"]:
                set_batch_status("Please load the playlist first.")
                return
            if len(playlist_track_by_key) != len(selected):
                set_batch_status("Playlist assignments are incomplete — reload the playlist first.")
                return

            assigned_tracks: list[PlaylistTrack] = []
            assigned_count = 0
            # Automatic reuse is OFF. Every selected WEM gets its own downloaded playlist
            # occurrence unless the user explicitly chose the "reuse first playlist" option.
            explicit_reuse = bool(playlist_batch_state.get("reuse"))
            reused_assignments = 0
            seen_sources: set[str] = set()
            if explicit_reuse:
                # In explicit reuse mode the first playlist may intentionally wrap around.
                # Keep one copy of each source only; this is the only path where reuse is allowed.
                for info in selected:
                    track = playlist_track_by_key.get(info.key)
                    if track is None:
                        continue
                    assigned_count += 1
                    source_key = str(track.video_id or track.webpage_url or track.title or "").strip().lower()
                    if source_key and source_key in seen_sources:
                        reused_assignments += 1
                        continue
                    if source_key:
                        seen_sources.add(source_key)
                    assigned_tracks.append(track)
            else:
                for info in selected:
                    track = playlist_track_by_key.get(info.key)
                    if track is None:
                        continue
                    assigned_count += 1
                    assigned_tracks.append(track)

            if not assigned_tracks:
                set_batch_status("No usable playlist songs are assigned.")
                return

            if not explicit_reuse and len(assigned_tracks) != assigned_count:
                raise RuntimeError(
                    "Playlist assignment lost one or more songs before downloading. "
                    "The batch was stopped instead of silently reusing audio."
                )

            self.log.info(
                "Playlist batch assignments: %d WEM(s), %d downloadable track(s), %d intentional reused assignment(s)",
                assigned_count, len(assigned_tracks), reused_assignments,
            )

            # Playlist batch mode is intended to put the downloaded song into the WEM at
            # its natural length. Never inherit an unrelated per-WEM duration-matching toggle
            # here; that would trim a multi-minute playlist song to a 1-2 second character/SFX WEM.
            for info in selected:
                auto_match_duration[info.key].set(False)

            _safe_widget_configure(finish_btn, state="disabled", text="Downloading…")
            _safe_widget_configure(load_playlist_btn, state="disabled")
            _safe_widget_configure(playlist_mode_check, state="disabled")
            set_batch_status(
                f"♡ Downloading {len(assigned_tracks)} playlist song(s) for {assigned_count} WEM assignments…"
                + (f" {reused_assignments} assignment(s) intentionally reuse a playlist track." if reused_assignments else "")
            )
            self._show_playlist_download_progress(assigned_tracks, parent=win)

            batch_status_state: dict[str, Any] = {"message": "", "after_id": None}

            def queue_batch_status(message: str) -> None:
                batch_status_state["message"] = str(message)
                if batch_status_state.get("after_id") is not None:
                    return

                def flush_batch_status() -> None:
                    batch_status_state["after_id"] = None
                    if not _widget_alive(win):
                        return
                    set_batch_status(batch_status_state.get("message", ""))

                try:
                    batch_status_state["after_id"] = self.root.after(80, flush_batch_status)
                except (tk.TclError, RuntimeError):
                    batch_status_state["after_id"] = None

            def download_worker() -> None:
                try:
                    options = ProcessOptions(
                        install_to_game=False,
                        # A single hung YouTube extraction should not hold the playlist in
                        # "Downloading…" for two minutes before the fallback clients get a chance.
                        download_timeout=45.0,
                        # TURBO: use a larger bounded track pool so a few slow YouTube entries
                        # do not hold the entire playlist behind a 12-job queue.
                        download_workers=min(16, max(1, len(assigned_tracks))),
                    )
                    manager = SourceManager(
                        self.tools,
                        Runner(self.log, self.bus, cancel_event=playlist_batch_state["cancel"]),
                        self.paths,
                        self.log,
                        options,
                        fast_preview=True,
                    )
                    chain = list(playlist_batch_state["chain"])
                    digest_source = "\\n".join(chain) or str(playlist_batch_state["url"])
                    batch_dir = (
                        self.paths.processed_audio
                        / "batch_sources"
                        / hashlib.sha256(digest_source.encode("utf-8")).hexdigest()[:20]
                    )

                    batch_result = manager.download_playlist_parallel(
                        assigned_tracks,
                        batch_dir,
                        workers=min(16, max(1, len(assigned_tracks))),
                        cancel_event=playlist_batch_state["cancel"],
                        allow_partial=True,
                        progress=lambda message, _done, _total: queue_batch_status(message),
                        track_progress=lambda track, state, pct, detail: self._update_playlist_download_progress(
                            track, state, pct, detail
                        ),
                    )
                    downloaded, failures = batch_result

                    by_key = {
                        manager._playlist_track_key(track): track for track in downloaded
                    }
                    failed_by_key = {
                        manager._playlist_track_key(item.track): item for item in failures
                    }

                    # The replacement choice is made once per failed playlist source,
                    # so repeated assignment of the same failed track stays consistent.
                    failure_replacements: dict[str, PlaylistTrack] = {}

                    def choose_replacement(failed_track: PlaylistTrack) -> Optional[PlaylistTrack]:
                        candidates = [
                            item for item in downloaded
                            if item.path is not None and manager._valid_audio_file(Path(item.path))
                            and manager._playlist_track_key(item) != manager._playlist_track_key(failed_track)
                        ]
                        if not candidates:
                            return None

                        # Prefer the next successful playlist position, then wrap around.
                        after = [item for item in candidates if int(item.playlist_index) > int(failed_track.playlist_index)]
                        before = [item for item in candidates if int(item.playlist_index) < int(failed_track.playlist_index)]
                        ordered = sorted(after, key=lambda item: int(item.playlist_index))
                        ordered += sorted(before, key=lambda item: int(item.playlist_index))

                        # Avoid reusing an automatically-selected fallback until the pool
                        # is exhausted, keeping a large playlist from collapsing onto one track.
                        already_used = {
                            manager._playlist_track_key(item) for item in failure_replacements.values()
                        }
                        for candidate in ordered:
                            ckey = manager._playlist_track_key(candidate)
                            if ckey not in already_used:
                                return candidate
                        return ordered[0] if ordered else None

                    # Process every failed unique source without aborting the entire batch.
                    # A user can switch it to another working playlist sound or leave only
                    # that assigned WEM unchanged.
                    for failed_key, failure in failed_by_key.items():
                        if playlist_batch_state["cancel"].is_set():
                            raise ProcessingCancelled("Batch playlist download cancelled")

                        affected_infos = [
                            info for info in selected
                            if (
                                playlist_track_by_key.get(info.key) is not None
                                and manager._playlist_track_key(playlist_track_by_key[info.key]) == failed_key
                            )
                        ]
                        if not affected_infos:
                            continue

                        replacement = choose_replacement(failure.track)
                        target_label = self._friendly_sound_label(affected_infos[0])
                        if replacement is None:
                            self.log.warning(
                                "No downloaded replacement candidate is available for failed playlist track %s",
                                failure.track.playlist_index,
                            )
                            for info in affected_infos:
                                playlist_skip_keys.add(info.key)
                            continue

                        action = self._request_playlist_download_failure_action(
                            target_label,
                            failure.track.title or failure.track.video_id or f"Playlist item {failure.track.playlist_index}",
                            replacement.title or replacement.video_id or f"Playlist item {replacement.playlist_index}",
                        )
                        if action == "replace":
                            failure_replacements[failed_key] = replacement
                            for info in affected_infos:
                                playlist_auto_replaced[info.key] = (
                                    replacement.title or replacement.video_id or "working playlist sound"
                                )
                        else:
                            for info in affected_infos:
                                playlist_skip_keys.add(info.key)

                    local_paths: dict[str, Path] = {}
                    applied_infos: list[WemInfo] = []

                    for info in selected:
                        if info.key in playlist_skip_keys:
                            continue

                        track = playlist_track_by_key.get(info.key)
                        if track is None:
                            playlist_skip_keys.add(info.key)
                            continue

                        key = manager._playlist_track_key(track)
                        if key in failure_replacements:
                            track = failure_replacements[key]
                            playlist_track_by_key[info.key] = track
                            playlist_display_name_by_key[info.key] = (
                                "↪ " + (track.title or track.video_id or "Working playlist sound")
                            )
                            key = manager._playlist_track_key(track)

                        ready_track = by_key.get(key)
                        ready_path = Path(ready_track.path) if ready_track and ready_track.path else None

                        if ready_path is None or not manager._valid_audio_file(ready_path):
                            # This should be rare, but a successful file can disappear between
                            # the worker scan and the mapping step. Try the targeted downloader
                            # once more; that path now also includes the Piped fallback.
                            try:
                                recovered = manager._download_playlist_track(
                                    track,
                                    len(local_paths) + 1,
                                    len(selected),
                                    batch_dir,
                                    playlist_batch_state["cancel"],
                                )
                                ready_path = Path(recovered.path) if recovered.path else None
                                if ready_path is not None and manager._valid_audio_file(ready_path):
                                    by_key[key] = recovered
                            except Exception as exc:
                                self.log.error(
                                    "Final targeted recovery failed for '%s': %s",
                                    track.title,
                                    exc,
                                )

                        if ready_path is None or not manager._valid_audio_file(ready_path):
                            # A late failure can happen after the original report. Treat it
                            # exactly like the original per-track failure instead of exploding
                            # the entire batch.
                            replacement = choose_replacement(track)
                            if replacement is not None:
                                action = self._request_playlist_download_failure_action(
                                    self._friendly_sound_label(info),
                                    track.title or track.video_id or "Playlist sound",
                                    replacement.title or replacement.video_id or "working playlist sound",
                                )
                                if action == "replace":
                                    track = replacement
                                    playlist_track_by_key[info.key] = replacement
                                    playlist_display_name_by_key[info.key] = "↪ " + (
                                        replacement.title or replacement.video_id or "Working playlist sound"
                                    )
                                    ready_path = Path(replacement.path) if replacement.path else None
                                else:
                                    playlist_skip_keys.add(info.key)
                                    continue
                            else:
                                playlist_skip_keys.add(info.key)
                                continue

                        if ready_path is None or not manager._valid_audio_file(ready_path):
                            playlist_skip_keys.add(info.key)
                            continue

                        local_paths[info.key] = ready_path.resolve()
                        applied_infos.append(info)

                    if not applied_infos:
                        def nothing_to_apply() -> None:
                            _safe_widget_configure(
                                finish_btn, state="normal", text="Apply to Brawlhalla ♡"
                            )
                            _safe_widget_configure(
                                load_playlist_btn, state="normal", text="Reload playlist ♡"
                            )
                            _safe_widget_configure(playlist_mode_check, state="normal")
                            set_batch_status(
                                "♡ No playlist sounds were downloaded successfully, so nothing was changed."
                            )

                        self._ui_after(0, nothing_to_apply)
                        return

                    skipped_count = len(playlist_skip_keys)
                    switched_count = len(playlist_auto_replaced)

                    def continue_with_normal_editor() -> None:
                        self._close_playlist_download_progress()
                        if not _widget_alive(win):
                            return
                        for info in selected:
                            path = local_paths.get(info.key)
                            if path is not None:
                                separate_sources[info.key].set(os.fspath(path))
                        playlist_batch_state["loading"] = False
                        playlist_batch_state["ready"] = False
                        playlist_track_by_key.clear()
                        playlist_display_name_by_key.clear()
                        playlist_batch_mode_var.set(False)
                        build_assignment_tree(select_keys={info.key for info in applied_infos})

                        detail_text = (
                            f"✓ {len(applied_infos)} WEM(s) are ready."
                            + (f"  {switched_count} failed playlist sound(s) were switched automatically." if switched_count else "")
                            + (f"  {skipped_count} WEM(s) were left unchanged." if skipped_count else "")
                        )
                        set_batch_status(detail_text + " Applying the normal sound settings…")
                        self._ui_after(0, start)

                    with contextlib.suppress(Exception):
                        after_id = batch_status_state.get("after_id")
                        if after_id is not None:
                            self.root.after_cancel(after_id)
                            batch_status_state["after_id"] = None
                    self._ui_after(0, continue_with_normal_editor)
                except ProcessingCancelled:
                    self._ui_after(0, self._close_playlist_download_progress)
                    self._ui_after(
                        0,
                        lambda: _safe_widget_configure(
                            finish_btn, state="normal", text="Apply to Brawlhalla ♡"
                        ),
                    )
                    self._ui_after(
                        0,
                        lambda: _safe_widget_configure(
                            load_playlist_btn, state="normal", text="Reload playlist ♡"
                        ),
                    )
                    self._ui_after(
                        0,
                        lambda: _safe_widget_configure(playlist_mode_check, state="normal"),
                    )
                    self._ui_after(0, lambda: set_batch_status("♡ Playlist download cancelled."))
                except Exception as exc:
                    self.log.error(
                        "Replacement-window batch playlist download failed unexpectedly: %s", exc
                    )

                    def failed_download(e=exc) -> None:
                        self._close_playlist_download_progress()
                        _safe_widget_configure(
                            finish_btn, state="normal", text="Apply to Brawlhalla ♡"
                        )
                        _safe_widget_configure(
                            load_playlist_btn, state="normal", text="Reload playlist ♡"
                        )
                        _safe_widget_configure(playlist_mode_check, state="normal")
                        set_batch_status("♡ The playlist batch hit an unexpected problem.")
                        if _widget_alive(win):
                            self._friendly_error(e, title="Batch download problem", parent=win)

                    self._ui_after(0, failed_download)

            threading.Thread(
                target=download_worker,
                daemon=True,
                name="ReplacementBatchPlaylistDownload",
            ).start()

        def sync_playlist_batch_mode(*_args: Any) -> None:
            enabled = bool(playlist_batch_mode_var.get())
            if enabled:
                self._batch_mode_cancel = playlist_batch_state["cancel"]
                _safe_widget_configure(
                    finish_btn,
                    text="Apply to Brawlhalla ♡",
                    state=("normal" if playlist_batch_state["ready"] else "disabled"),
                )
                if playlist_batch_state["ready"]:
                    set_batch_status(playlist_batch_status_var.get())
                else:
                    set_batch_status(
                        "Load & assign a playlist to map one song to each selected WEM in order."
                    )
            else:
                playlist_batch_state["cancel"].set()
                playlist_batch_state["loading"] = False
                playlist_batch_state["ready"] = False
                self._batch_mode_cancel = None
                _safe_widget_configure(
                    finish_btn, text="Apply to Brawlhalla ♡", state="normal"
                )
                set_batch_status("Playlist batch mode is off. Manual sound/group assignments are active.")
            _safe_widget_configure(
                playlist_entry, state=("normal" if enabled else "disabled")
            )
            _safe_widget_configure(
                load_playlist_btn, state=("normal" if enabled else "disabled")
            )

        def invalidate_playlist_batch_on_edit(*_args: Any) -> None:
            # A changed URL must never reuse assignments downloaded from the previous URL.
            if playlist_batch_state["loading"]:
                playlist_batch_state["cancel"].set()
            playlist_batch_state["ready"] = False
            playlist_batch_state["tracks"] = []
            playlist_batch_state["chain"] = []
            playlist_batch_state["reuse"] = False
            playlist_track_by_key.clear()
            playlist_display_name_by_key.clear()
            if playlist_batch_mode_var.get():
                _safe_widget_configure(
                    finish_btn, state="disabled", text="Apply to Brawlhalla ♡"
                )
                playlist_title_var.set("No playlist loaded yet")
                set_batch_status(
                    "Playlist changed — press Load & assign ♡ to refresh the WEM assignments."
                )
                # Restore the normal replacement table immediately when it exists.
                with contextlib.suppress(Exception):
                    build_assignment_tree()

        playlist_batch_mode_var.trace_add("write", sync_playlist_batch_mode)
        playlist_source_var.trace_add("write", invalidate_playlist_batch_on_edit)
        load_playlist_btn.configure(command=load_playlist_batch)
        playlist_entry.bind("<Return>", lambda _e: load_playlist_batch())

        group_sources: dict[str, tk.StringVar] = {}
        assignments: dict[str, str] = {info.key: "Separate" for info in selected}
        separate_sources: dict[str, tk.StringVar] = {info.key: tk.StringVar(value=initial_source) for info in selected}

        offsets_ms: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="0") for info in selected}
        end_cutoff_s: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="") for info in selected}
        auto_match_duration: dict[str, tk.BooleanVar] = {info.key: tk.BooleanVar(value=False) for info in selected}
        playback_rates: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="1.00x") for info in selected}

        fade_in_ms: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="0") for info in selected}
        fade_out_ms: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="0") for info in selected}

        gain_db: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="0") for info in selected}
        normalize_wem: dict[str, tk.BooleanVar] = {info.key: tk.BooleanVar(value=False) for info in selected}
        overlay_gain_db: dict[str, tk.StringVar] = {info.key: tk.StringVar(value="0") for info in selected}

        combine_wem: dict[str, tk.BooleanVar] = {info.key: tk.BooleanVar(value=False) for info in selected}
        group_members_visible: dict[str, bool] = {}

        group_map_mode: dict[str, bool] = {}
        group_map_transition_s: dict[str, tk.StringVar] = {}

        # Playlist downloads can now fail per source without aborting the complete
        # replacement. These keys are skipped only for this editor run.
        playlist_skip_keys: set[str] = set()
        playlist_auto_replaced: dict[str, str] = {}

        prefetch_context_prefix = f"replace-group:{id(win)}"
        for group_name, variable in group_sources.items():
            self._watch_url_prefetch(variable, f"{prefetch_context_prefix}:group:{group_name}", group_name)
        for info in selected:
            self._watch_url_prefetch(separate_sources[info.key], f"{prefetch_context_prefix}:separate:{info.key}", self._friendly_sound_label(info))

        show_advanced_cols = tk.BooleanVar(value=False)

        toolbar = ttk.Frame(shell)
        toolbar.pack(side="top", fill="x", padx=14, pady=(14, 0), before=canvas)
        toolbar2 = ttk.Frame(shell)

        ttk.Button(toolbar, text="+ New group", style="Tool.TButton", command=lambda: add_group()).pack(side="left")
        ttk.Label(toolbar, text="Bind selected to", style="EditorField.TLabel").pack(side="left", padx=(12, 5))
        bind_choice = tk.StringVar()
        bind_combo = ttk.Combobox(toolbar, textvariable=bind_choice, state="readonly", width=13, values=tuple(groups))
        bind_combo.pack(side="left")
        ttk.Button(toolbar, text="Bind", style="Action.TButton", command=lambda: bind_selected()).pack(side="left", padx=5)
        ttk.Button(toolbar, text="Unbind", style="Tool.TButton", command=lambda: unbind_selected()).pack(side="left")
        ttk.Separator(toolbar, orient="vertical").pack(side="left", fill="y", padx=6)
        ttk.Button(toolbar, text="+ Add sounds", style="Tool.TButton", command=lambda: add_session_sounds()).pack(side="left")
        ttk.Button(toolbar, text="− Remove", style="Tool.TButton", command=lambda: remove_session_sounds()).pack(side="left", padx=(5, 0))
        ttk.Separator(toolbar, orient="vertical").pack(side="left", fill="y", padx=12)
        ttk.Checkbutton(toolbar, text="Advanced columns", variable=show_advanced_cols, command=lambda: apply_column_visibility()).pack(side="left")
        toolbar_tip = ttk.Label(toolbar, text="Tip: select a group row to edit all of its sounds at once.", style="EditorHint.TLabel")
        toolbar_tip.pack(side="left", fill="x", expand=True, padx=(12, 0))
        cancel_btn = ttk.Button(toolbar, text="Cancel", style="Tool.TButton", command=lambda w=win: self._close_replacement_dialog(w))
        cancel_btn.pack(side="right", padx=(8, 0))
        finish_btn = ttk.Button(toolbar, text="Apply to Brawlhalla ♡", style="Big.TButton", command=lambda: start())
        finish_btn.pack(side="right")
        toolbar_state = {"tip": None, "rows": None}
        def _fit_toolbar(_e=None):
            try:
                swd = shell.winfo_width()
            except Exception:
                return
            if swd < 50:
                return
            avail = swd - 28
            try:
                toolbar.update_idletasks()
                r1 = int(toolbar.winfo_reqwidth())
                tip_req = int(toolbar_tip.winfo_reqwidth())
                tip_mapped = bool(toolbar_tip.winfo_ismapped())
                cancel_req = int(cancel_btn.winfo_reqwidth())
                apply_req = int(finish_btn.winfo_reqwidth())
            except Exception:
                return
            rows = toolbar_state["rows"] or 1
            if rows == 1 and r1 > avail:
                rows = 2
            elif rows == 2 and r1 + cancel_req + apply_req + 40 <= avail:
                rows = 1
            actions = r1 - (tip_req if tip_mapped else 0)
            want_tip = avail >= actions + tip_req + 40
            if toolbar_state["rows"] == rows and toolbar_state["tip"] == want_tip:
                return
            toolbar_state["rows"] = rows
            toolbar_state["tip"] = want_tip
            try:
                if rows == 2:
                    toolbar2.pack(side="top", fill="x", padx=14, before=canvas)
                    cancel_btn.pack_forget()
                    finish_btn.pack_forget()
                    cancel_btn.pack(in_=toolbar2, side="right", padx=(8, 0))
                    finish_btn.pack(in_=toolbar2, side="right")
                else:
                    toolbar2.pack_forget()
                    cancel_btn.pack_forget()
                    finish_btn.pack_forget()
                    cancel_btn.pack(side="right", padx=(8, 0))
                    finish_btn.pack(side="right")
                if want_tip:
                    toolbar_tip.pack(side="left", fill="x", expand=True, padx=(12, 0))
                else:
                    toolbar_tip.pack_forget()
            except Exception:
                pass
        shell.bind("<Configure>", _fit_toolbar, add="+")
        _fit_toolbar()

        # Apply-button behavior follows the single batch implementation embedded above.
