        detail_offset_var = tk.StringVar(value="0")
        detail_offset_entry = ttk.Entry(detail_offset_row, textvariable=detail_offset_var, width=12); detail_offset_entry.pack(side="left", padx=7)

        detail_speed_row = ttk.Frame(detail_body); detail_speed_row.pack(fill="x", pady=(6, 0))
        ttk.Label(detail_speed_row, text="Playback speed", style="EditorField.TLabel").pack(side="left")
        detail_speed_var = tk.StringVar(value="1.00x")
        detail_speed_combo = ttk.Combobox(detail_speed_row, textvariable=detail_speed_var, state="normal", width=10, values=("0.50x", "0.75x", "1.00x", "1.25x", "1.50x", "1.75x", "2.00x", "2.50x", "3.00x")); detail_speed_combo.pack(side="left", padx=7)

        detail_end_row = ttk.Frame(detail_body); detail_end_row.pack(fill="x", pady=(6, 0))
        ttk.Label(detail_end_row, text="End cutoff (s, optional)", style="EditorField.TLabel").pack(side="left")
        detail_end_var = tk.StringVar(value="")
        detail_end_entry = ttk.Entry(detail_end_row, textvariable=detail_end_var, width=9); detail_end_entry.pack(side="left", padx=6)
        ttk.Label(detail_end_row, text="blank = full source", style="EditorHint.TLabel").pack(side="left", padx=(2, 0))

        detail_trim_frame = ttk.Frame(detail_body); detail_trim_frame.pack(fill="x", pady=(6, 0))
        detail_trim_status_var = tk.StringVar(value="Add audio above to see its length.")
        ttk.Label(detail_trim_frame, textvariable=detail_trim_status_var, style="EditorHint.TLabel", wraplength=340).pack(anchor="w")
        detail_trim_canvas = tk.Canvas(detail_trim_frame, height=64, highlightthickness=0, bd=0)
        detail_trim_canvas.pack(fill="x", expand=True, pady=(4, 0))
        detail_trim_range_var = tk.StringVar(value="")
        ttk.Label(detail_trim_frame, textvariable=detail_trim_range_var, style="EditorHint.TLabel").pack(anchor="w")
        trim_state = {"duration": None, "seq": 0, "drag": None, "peaks": None, "peaks_key": None, "cache": {}}
        def _trim_fmt(s):
            try:
                s = max(0.0, float(s))
            except Exception:
                return "--:--"
            m = int(s // 60); sec = s - m * 60
            return f"{m}:{sec:05.2f}"
        def _trim_vals():
            try:
                so = float((detail_offset_var.get() or "0").strip() or "0")
            except Exception:
                so = 0.0
            if not math.isfinite(so) or so < 0:
                so = 0.0
            raw_end = (detail_end_var.get() or "").strip()
            try:
                eo = float(raw_end) if raw_end and raw_end.lower() != "mixed" else None
            except Exception:
                eo = None
            if eo is not None and (not math.isfinite(eo) or eo < 0):
                eo = None
            d = trim_state["duration"]
            if d:
                so = min(so, d)
                eo = d if eo is None else min(eo, d)
            else:
                eo = eo if eo is not None else 0.0
            if eo is not None and eo < so:
                eo = so
            return so, eo
        def _trim_fx():
            fi = 0.0
            fo = 0.0
            gd = 0.0
            norm = False
            comb = False
            rate = 1.0
            auto = False
            try:
                fi = max(0.0, float((detail_fade_in_var.get() or "0").strip() or "0"))
            except Exception:
                fi = 0.0
            try:
                fo = max(0.0, float((detail_fade_out_var.get() or "0").strip() or "0"))
            except Exception:
                fo = 0.0
            try:
                gd = float((detail_gain_var.get() or "0").strip() or "0")
                if not math.isfinite(gd):
                    gd = 0.0
            except Exception:
                gd = 0.0
            try:
                norm = str(detail_normalize_var.get()).strip() == "1"
            except Exception:
                norm = False
            try:
                comb = str(detail_combine_var.get()).strip() == "1"
            except Exception:
                comb = False
            try:
                rate = float(str(detail_speed_var.get() or "1").strip().lower().replace("x", "") or "1")
                if not math.isfinite(rate) or rate <= 0:
                    rate = 1.0
            except Exception:
                rate = 1.0
            try:
                auto = str(detail_auto_var.get()).strip() == "1"
            except Exception:
                auto = False
            return fi, fo, gd, norm, comb, rate, auto
        def _trim_fx_label(fi, fo, gd, norm, comb, rate, auto, out_len, ctag=None):
            extra = f"  ·  out ~{_trim_fmt(out_len)}"
            if abs(gd) > 0.001:
                extra += f"  ·  {gd:+.1f} dB"
            if fi > 0 or fo > 0:
                extra += f"  ·  fade {fi:.2f}/{fo:.2f}s"
            if norm:
                extra += "  ·  norm"
            if comb:
                extra += ctag or "  ·  +original"
            if auto:
                extra += "  ·  auto"
            return extra
        trim_sched = {"id": None}
        def _trim_draw_soon(delay=30):
            try:
                if not win.winfo_exists():
                    return
            except Exception:
                return
            if trim_sched.get("id") is not None:
                return
            def _trim_go():
                trim_sched["id"] = None
                try:
                    if win.winfo_exists():
                        _trim_draw()
                except Exception:
                    pass
            try:
                trim_sched["id"] = win.after(max(0, int(delay)), _trim_go)
            except Exception:
                pass
        def _trim_draw(*_a):
            try:
                if not detail_trim_canvas.winfo_exists():
                    return
            except Exception:
                return
            pal = getattr(self, "_theme_colors", {}) or {}
            accent = pal.get("accent", "#c25f91")
            try:
                W = int(detail_trim_canvas.winfo_width() or 0)
            except Exception:
                W = 0
            if W < 40:
                detail_trim_canvas.after(120, _trim_draw)
                return
            pad = 10; top = 4; bot = 60
            detail_trim_canvas.delete("all")
            try:
                detail_trim_canvas.configure(bg=pal.get("canvas", pal.get("field", "#fffafd")))
            except Exception:
                pass
            strip = "#262932"
            dim_wave = "#5d6372"
            hot_wave = "#f4f6fb"
            try:
                detail_trim_canvas.create_rectangle(pad, top, W - pad, bot, fill=strip, outline="", width=0)
            except Exception:
                pass
            d = trim_state["duration"]
            so, eo = _trim_vals()
            raw = trim_state.get("peaks") or []
            n = len(raw)
            if d and n:
                fi, fo, gd, norm, comb, rate, auto = _trim_fx()
                cy = (top + bot) / 2.0
                half = (bot - top) / 2.0 - 5.0
                span = max(1.0, W - 2 * pad)
                colw = max(1.0, span / n)
                sel_len = max(0.0, eo - so)
                out_len = (sel_len / rate) if rate > 0 else sel_len
                xa = pad + (so / d) * span
                xb = pad + (eo / d) * span
                g = 10.0 ** (max(-36.0, min(36.0, gd)) / 20.0)
                shaped = [None] * n
                shaped_b = [0.0] * n
                peak_top = 0.0
                for i, entry in enumerate(raw):
                    t = (i / max(1, n - 1)) * d
                    if t < so - 1e-9 or t > eo + 1e-9:
                        continue
                    o = (t - so) / rate if rate > 0 else (t - so)
                    m = 1.0
                    if fi > 0 and o < fi:
                        m = min(m, max(0.0, o / fi))
                    if fo > 0 and o > out_len - fo:
                        m = min(m, max(0.0, (out_len - o) / fo))
                    try:
                        pk = float(entry[0]) if isinstance(entry, (list, tuple)) else float(entry)
                    except Exception:
                        pk = 0.0
                    try:
                        bd = float(entry[1]) if isinstance(entry, (list, tuple)) and len(entry) > 1 else pk * 0.55
                    except Exception:
                        bd = pk * 0.55
                    v = max(0.0, min(1.0, pk)) * g * m
                    shaped[i] = v
                    shaped_b[i] = max(0.0, min(1.0, bd)) * g * m
                    if v > peak_top:
                        peak_top = v
                nscale = 1.0
                if norm and peak_top > 0.001:
                    nscale = 0.891 / peak_top
                okey = None
                opeak = None
                odur = 0.0
                if comb:
                    try:
                        okey = _trim_orig_key()
                    except Exception:
                        okey = None
                    if okey:
                        if trim_state.get("orig_key") == okey:
                            opeak = trim_state.get("orig_peaks")
                        if opeak is None and trim_state.get("orig_probing") != okey:
                            try:
                                _trim_orig_probe(okey)
                            except Exception:
                                pass
                    if opeak:
                        try:
                            _oinfo = selected_by_key.get(okey)
                            odur = float(_oinfo.duration_seconds) if _oinfo else 0.0
                        except Exception:
                            odur = 0.0
                        if not (odur > 0):
                            opeak = None
                if opeak:
                    _on = len(opeak)
                    _opx = max(1, min(_on, int(span)))
                    _opool = _on / float(_opx)
                    for _p in range(_opx):
                        _a = int(_p * _opool)
                        _b = int((_p + 1) * _opool)
                        if _b <= _a:
                            _b = _a + 1
                        if _b > _on:
                            _b = _on
                        _om = 0.0
                        for _j in range(_a, _b):
                            try:
                                _ov = float(opeak[_j][0]) if isinstance(opeak[_j], (list, tuple)) else float(opeak[_j])
                            except Exception:
                                _ov = 0.0
                            if _ov > _om:
                                _om = _ov
                        ot = ((_p + 0.5) / _opx) * odur
                        if ot > d:
                            break
                        ox = pad + (ot / d) * span
                        oh = max(1.0, (min(1.0, _om) ** 0.62) * half)
                        detail_trim_canvas.create_line(ox, cy - oh, ox, cy + oh, fill="#6fd3c0", width=1)
                    try:
                        mx = pad + (min(odur, d) / d) * span
                        detail_trim_canvas.create_line(mx, top, mx, bot, fill="#6fd3c0", width=1, dash=(3, 3))
                    except Exception:
                        pass
                core = "#ffc7de" if comb else hot_wave
                core_dim = "#8a6f7e" if comb else "#4d525f"
                _pxn = max(1, min(n, int(span)))
                _pool = n / float(_pxn)
                for _p in range(_pxn):
                    _a = int(_p * _pool)
                    _b = int((_p + 1) * _pool)
                    if _b <= _a:
                        _b = _a + 1
                    if _b > n:
                        _b = n
                    sv = None
                    _bv = 0.0
                    _rpk = 0.0
                    _rbd = 0.0
                    for _i in range(_a, _b):
                        _en = raw[_i]
                        try:
                            _ep = float(_en[0]) if isinstance(_en, (list, tuple)) else float(_en)
                        except Exception:
                            _ep = 0.0
                        try:
                            _eb = float(_en[1]) if isinstance(_en, (list, tuple)) and len(_en) > 1 else _ep * 0.55
                        except Exception:
                            _eb = _ep * 0.55
                        if _ep > _rpk:
                            _rpk = _ep
                        if _eb > _rbd:
                            _rbd = _eb
                        _si = shaped[_i]
                        if _si is not None:
                            if sv is None or _si > sv:
                                sv = _si
                            _sb = shaped_b[_i]
                            if _sb > _bv:
                                _bv = _sb
                    x = pad + ((_p + 0.5) / _pxn) * span
                    if sv is None:
                        ph = max(1.0, (min(1.0, _rpk) ** 0.62) * half)
                        bh = max(1.0, (min(1.0, _rbd) ** 0.62) * half)
                        detail_trim_canvas.create_line(x, cy - ph, x, cy + ph, fill=core_dim, width=1)
                        detail_trim_canvas.create_line(x, cy - bh, x, cy + bh, fill=dim_wave, width=1)
                    else:
                        v = min(1.0, sv * nscale)
                        vb = min(1.0, _bv * nscale)
                        if v <= 0.004 and vb <= 0.004:
                            continue
                        ph = max(1.0, (v ** 0.62) * half)
                        detail_trim_canvas.create_line(x, cy - ph, x, cy + ph, fill=core_dim, width=1)
                        if vb > 0.004:
                            bh = max(1.0, (vb ** 0.62) * half)
                            detail_trim_canvas.create_line(x, cy - bh, x, cy + bh, fill=core, width=1)
                if xb > xa + 1:
                    detail_trim_canvas.create_rectangle(xa, top, xb, bot, fill=accent, outline="", stipple="gray25")
                for cx in (xa, xb):
                    detail_trim_canvas.create_oval(cx - 8, top - 1, cx + 8, top + 15, fill=accent, outline="#ffffff", width=1.5)
                detail_trim_canvas.create_line(pad, cy, W - pad, cy, fill="#3a3f4c", width=1)
                try:
                    _ph = getattr(self, "_trim_playhead", None)
                    if _ph is not None and d:
                        _el = time.monotonic() - float(_ph.get("t0", 0.0))
                        if _el < 0:
                            _el = 0.0
                        if _el <= float(_ph.get("dur", 0.0)) + 0.25:
                            _st = float(_ph.get("so", 0.0)) + _el * (float(_ph.get("rate", 1.0)) or 1.0)
                            _px = pad + (min(max(_st, 0.0), d) / d) * span
                            detail_trim_canvas.create_line(_px, top, _px, bot, fill="#ffffff", width=2, tags=("playhead",))
                except Exception:
                    pass
                ctag = "  ·  +original"
                if comb:
                    if opeak:
                        ctag = f"  ·  +original teal ends {_trim_fmt(odur)}"
                    elif okey:
                        ctag = "  ·  +original loading…"
                detail_trim_range_var.set(f"{_trim_fmt(so)} → {'' if (detail_end_var.get() or '').strip() == '' else _trim_fmt(eo)}  ·  {_trim_fmt(sel_len if d else 0)} selected" + _trim_fx_label(fi, fo, gd, norm, comb, rate, auto, out_len, ctag))
            elif d:
                cy = (top + bot) / 2.0
                detail_trim_canvas.create_line(pad, cy, W - pad, cy, fill=dim_wave, width=2)
                span = max(1.0, W - 2 * pad)
                xa = pad + (so / d) * span
                xb = pad + (eo / d) * span
                for cx in (xa, xb):
                    detail_trim_canvas.create_oval(cx - 8, top - 1, cx + 8, top + 15, fill=accent, outline="#ffffff", width=1.5)
                fi, fo, gd, norm, comb, rate, auto = _trim_fx()
                sel_len = max(0.0, eo - so)
                out_len = (sel_len / rate) if rate > 0 else sel_len
                detail_trim_range_var.set(f"{_trim_fmt(so)} → {_trim_fmt(eo)}  ·  {_trim_fmt(sel_len if d else 0)} selected" + _trim_fx_label(fi, fo, gd, norm, comb, rate, auto, out_len))
            else:
                cy = (top + bot) / 2.0
                detail_trim_canvas.create_line(pad + 6, cy, W - pad - 6, cy, fill=dim_wave, width=2, dash=(4, 4))
                detail_trim_range_var.set("")
        def _trim_pos_to_t(ev):
            try:
                W = int(detail_trim_canvas.winfo_width())
            except Exception:
                return None
            d = trim_state["duration"]
            if not d or W < 40:
                return None
            pad = 10
            frac = (ev.x - pad) / max(1.0, (W - 2 * pad))
            return min(d, max(0.0, frac * d))
        def _trim_pick(ev):
            t = _trim_pos_to_t(ev)
            if t is None:
                return None
            so, eo = _trim_vals()
            return "so" if abs(t - so) <= abs(t - eo) else "eo"
        def _trim_press(ev):
            if not trim_state["duration"]:
                return
            trim_state["drag"] = _trim_pick(ev)
        def _trim_move(ev):
            which = trim_state.get("drag")
            if not which or not trim_state["duration"]:
                return
            t = _trim_pos_to_t(ev)
            if t is None:
                return
            d = trim_state["duration"]
            if which == "so":
                detail_offset_var.set(f"{min(t, (_trim_vals()[1] if _trim_vals()[1] is not None else d)):.2f}")
            else:
                if t >= d - 0.005:
                    detail_end_var.set("")
                else:
                    detail_end_var.set(f"{max(t, _trim_vals()[0]):.2f}")
        def _trim_release(_ev=None):
            trim_state["drag"] = None
        def _trim_peaks_for(lp, dur):
            import struct as _struct
            ncols = 800
            try:
                ar = int(min(16000, max(4000, 1000000.0 / max(0.5, float(dur)))))
            except Exception:
                ar = 8000
            ff = getattr(self.tools, "ffmpeg", None)
            tmp = None
            try:
                if ff:
                    fd, tmps = tempfile.mkstemp(prefix="cutie_wave_", suffix=".wav")
                    os.close(fd)
                    tmp = Path(tmps)
                    self.runner.run([ff, "-y", "-v", "error", "-i", os.fspath(lp),
                                     "-ac", "1", "-ar", str(ar), "-c:a", "pcm_s16le", os.fspath(tmp)], timeout=120.0)
                    src = tmp
                else:
                    src = Path(lp)
                with wave.open(os.fspath(src), "rb") as wf:
                    n = wf.getnframes()
                    sw = wf.getsampwidth()
                    ch = wf.getnchannels() or 1
                    if n <= 0 or sw != 2:
                        return None
                    cols_p = [0.0] * ncols
                    cols_b = [0.0] * ncols
                    per_col = max(1, n // ncols)
                    stride = max(1, per_col // 600)
                    for i in range(ncols):
                        pos = min(n - 1, i * per_col)
                        try:
                            wf.setpos(pos)
                        except Exception:
                            break
                        chunk = wf.readframes(min(per_col, n - pos))
                        total = len(chunk) // 2
                        if total <= 0:
                            continue
                        try:
                            vals = _struct.unpack("<" + "h" * total, chunk[:total * 2])
                        except Exception:
                            continue
                        if ch > 1:
                            vals = vals[0::ch]
                        if stride > 1:
                            vals = vals[0::stride]
                        m = 0
                        s = 0.0
                        c = 0
                        for v in vals:
                            a = abs(v)
                            if a > m:
                                m = a
                            s += float(v) * float(v)
                            c += 1
                        cols_p[i] = float(m)
                        cols_b[i] = (s / c) ** 0.5 if c else 0.0
                capped = [0.0] * ncols
                for i in range(ncols):
                    cm = cols_p[i]
                    cr = cols_b[i]
                    if cr > 0.0 and cm > 3.0 * cr:
                        cm = 3.0 * cr
                    capped[i] = cm
                top = 0.0
                for cm in capped:
                    if cm > top:
                        top = cm
                if top < 1.0:
                    top = 1.0
                return [[cm / top, b / top] for cm, b in zip(capped, cols_b)]
            except Exception:
                return None
            finally:
                if tmp is not None:
                    with contextlib.suppress(Exception):
                        tmp.unlink()
        def _trim_orig_peaks_for(info):
            vg = getattr(self.tools, "vgmstream", None)
            if vg is None or info is None:
                return None
            try:
                src = Path(info.file_path)
                if not src.is_file():
                    return None
                dur = float(info.duration_seconds)
                if not (dur > 0):
                    return None
            except Exception:
                return None
            fd, tmps = tempfile.mkstemp(prefix="cutie_orig_", suffix=".wav")
            os.close(fd)
            tmp = Path(tmps)
            try:
                self.runner.run([vg, "-o", tmp, src], timeout=120.0)
                return _trim_peaks_for(tmp, dur)
            except Exception:
                return None
            finally:
                with contextlib.suppress(Exception):
                    tmp.unlink()
        def _trim_orig_key():
            try:
                if str(detail_combine_var.get()).strip() != "1":
                    return None
            except Exception:
                return None
            try:
                t = current_detail.get("type")
            except Exception:
                return None
            try:
                if t == "sound" and current_detail.get("key"):
                    return current_detail["key"]
                if t == "group" and current_detail.get("name") in groups:
                    ms = group_members_for(current_detail["name"])
                    return ms[0].key if ms else None
            except Exception:
                return None
            return None
        def _trim_orig_probe(key):
            try:
                info = selected_by_key.get(key)
            except Exception:
                info = None
            if info is None:
                return
            if trim_state.get("orig_probing") == key:
                return
            trim_state["orig_probing"] = key
            def work():
                peaks = None
                try:
                    peaks = _trim_orig_peaks_for(info)
                except Exception as exc:
                    try:
                        self.log.debug("Trim original render skipped: %s", exc)
                    except Exception:
                        pass
                    peaks = None
                def done():
                    if trim_state.get("orig_probing") != key:
                        return
                    trim_state["orig_probing"] = None
                    try:
                        want = _trim_orig_key()
                    except Exception:
                        want = None
                    if want != key:
                        _trim_draw()
                        return
                    trim_state["orig_peaks"] = peaks
                    trim_state["orig_key"] = key
                    _trim_draw()
                try:
                    win.after(0, done)
                except Exception:
                    trim_state["orig_probing"] = None
            threading.Thread(target=work, daemon=True, name="trim-orig-probe").start()
        def _trim_probe(source):
            trim_state["seq"] += 1
            seq = trim_state["seq"]
            raw = (source or "").strip().strip('"')
            cache = trim_state.get("cache")
            if not isinstance(cache, dict):
                cache = {}
                trim_state["cache"] = cache
            if not raw or raw.lower() == "mixed":
                trim_state["duration"] = None
                trim_state["peaks"] = None
                trim_state["peaks_key"] = None
                try:
                    detail_trim_status_var.set("Add audio above to see its length.")
                    _trim_draw()
                except Exception:
                    pass
                return
            trim_state["last_raw"] = raw
            fast_key = None
            try:
                _fp = Path(os.path.expandvars(os.path.expanduser(raw)))
                if _fp.is_file():
                    try:
                        _st = _fp.stat()
                        fast_key = f"{_fp}|{_st.st_size}|{_st.st_mtime_ns}"
                    except Exception:
                        fast_key = str(_fp)
            except Exception:
                fast_key = None
            if fast_key and fast_key in cache:
                hit_dur, hit_peaks = cache[fast_key]
                if seq == trim_state["seq"]:
                    trim_state["duration"] = float(hit_dur)
                    trim_state["peaks"] = hit_peaks
                    trim_state["peaks_key"] = fast_key
                    try:
                        detail_trim_status_var.set(f"Source length {_trim_fmt(hit_dur)} — drag across the waves for offset / cutoff.")
                    except Exception:
                        pass
                    _trim_draw()
                return
            trim_state["duration"] = None
            trim_state["peaks"] = None
            trim_state["peaks_key"] = None
            try:
                detail_trim_status_var.set("Reading length…")
                _trim_draw()
            except Exception:
                pass
            def work():
                dur = None
                peaks = None
                pkey = None
                try:
                    cand = None
                    try:
                        cand = self._prefetched_source_for(raw, "trim probe")
                    except Exception:
                        cand = None
                    lp = None
                    if cand is not None:
                        lp = Path(cand)
                    else:
                        with contextlib.suppress(Exception):
                            p = Path(os.path.expandvars(os.path.expanduser(raw)))
                            if p.is_file():
                                lp = p
                    if lp is not None and lp.is_file():
                        try:
                            st = lp.stat()
                            pkey = f"{lp}|{st.st_size}|{st.st_mtime_ns}"
                        except Exception:
                            pkey = str(lp)
                    if lp is not None and lp.is_file() and getattr(self.tools, "ffprobe", None):
                        try:
                            dur = ffprobe_duration(self.runner, self.tools.ffprobe, lp, timeout=60.0)
                        except Exception:
                            dur = None
                    if dur is None and lp is not None and lp.is_file():
                        try:
                            with wave.open(str(lp), "rb") as wf:
                                fr = wf.getframerate() or 44100
                                dur = (wf.getnframes() / float(fr)) if fr else None
                        except Exception:
                            dur = None
                    if lp is not None and lp.is_file() and dur and math.isfinite(dur) and dur > 0:
                        _cc = trim_state.get("cache")
                        if not isinstance(_cc, dict):
                            _cc = {}
                            trim_state["cache"] = _cc
                        if pkey and pkey in _cc:
                            peaks = _cc[pkey][1]
                        else:
                            try:
                                peaks = _trim_peaks_for(lp, dur)
                            except Exception as exc:
                                self.log.debug("Trim wave render skipped: %s", exc)
                                peaks = None
                except Exception:
                    dur = None
                    peaks = None
                def done():
                    if seq != trim_state["seq"]:
                        return
                    if dur and math.isfinite(dur) and dur > 0:
                        trim_state["duration"] = float(dur)
                        trim_state["peaks"] = peaks
                        trim_state["peaks_key"] = pkey
                        if peaks:
                            try:
                                _cc2 = trim_state.get("cache")
                                if isinstance(_cc2, dict) and pkey:
                                    _cc2[pkey] = (float(dur), peaks)
                                    while len(_cc2) > 12:
                                        _cc2.pop(next(iter(_cc2)), None)
                            except Exception:
                                pass
                            try:
                                detail_trim_status_var.set(f"Source length {_trim_fmt(dur)} — drag across the waves for offset / cutoff.")
                            except Exception:
                                pass
                        else:
                            try:
                                detail_trim_status_var.set(f"Length {_trim_fmt(dur)} is fine, but the waves would not draw. Fetch ffmpeg in Tool Status if it is missing — otherwise re-pick the file.")
                            except Exception:
                                pass
                            if trim_state.get("retried") != pkey:
                                trim_state["retried"] = pkey
                                try:
                                    win.after(2000, lambda: _trim_probe(trim_state.get("last_raw") or "") if seq == trim_state["seq"] and not trim_state.get("peaks") else None)
                                except Exception:
                                    pass
                    else:
                        trim_state["duration"] = None
                        trim_state["peaks"] = None
                        trim_state["peaks_key"] = None
                        try:
                            detail_trim_status_var.set("Could not read length yet — it will be checked at install. You can still type seconds.")
                        except Exception:
                            pass
                    _trim_draw()
                try:
                    win.after(0, done)
                except Exception:
                    pass
            threading.Thread(target=work, daemon=True, name="trim-probe").start()
