        def _trim_playhead_move():
            try:
                if not detail_trim_canvas.winfo_exists():
                    return False
                _ph = getattr(self, "_trim_playhead", None)
                _d = trim_state.get("duration")
                if _ph is None or not _d:
                    return False
                _el = time.monotonic() - float(_ph.get("t0", 0.0))
                if _el < 0:
                    _el = 0.0
                if _el > float(_ph.get("dur", 0.0)) + 0.25:
                    return False
                _W = int(detail_trim_canvas.winfo_width() or 0)
                if _W < 40:
                    return True
                _pad = 10
                _span = max(1.0, _W - 2 * _pad)
                _st = float(_ph.get("so", 0.0)) + _el * (float(_ph.get("rate", 1.0)) or 1.0)
                _px = _pad + (min(max(_st, 0.0), _d) / _d) * _span
                _ids = detail_trim_canvas.find_withtag("playhead")
                if _ids:
                    detail_trim_canvas.coords(_ids[0], _px, 4, _px, 60)
                    return True
                return False
            except Exception:
                return False
        self._trim_playhead_move = _trim_playhead_move
