    assert all("36-43" in " ".join(str(x) for x in args) for args in _range_args)
    # Resumable playlist test: first probe only yields 35/43, second probe yields 36-43.
    class _FakePlaylistRunner:
        def __init__(self):
            self.calls = []
        def run(self, args, **kwargs):
            import re as _re
            text = " ".join(str(x) for x in args)
            m = _re.search(r"1-(\\d+)|playback", text)
            # Detect the requested playlist-items range directly.
            mm = _re.search(r"--playlist-items\s*([0-9]+)-([0-9]+)", text)
            if mm:
                a, b = int(mm.group(1)), int(mm.group(2))
            else:
                a, b = 1, 43
            self.calls.append((a, b))
            class R:
                returncode = 0
                stderr = ""
                stdout = ""
            out = []
            if a == 1 and b == 24:
                for i in range(1, 16):
                    out.append(f"{i}\tid{i}\tSong {i}\thttps://www.youtube.com/watch?v=id{i}")
                R.returncode = -9
            else:
                for i in range(a, b + 1):
                    out.append(f"{i}\tid{i}\tSong {i}\thttps://www.youtube.com/watch?v=id{i}")
            R.stdout = "\n".join(out)
            return R()

